def solve(grid, start, goal):
    if start == goal:
        return [start]

    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # BFS setup
    frontier = [start]
    seen = {start}
    parents = {start: None}

    while frontier:
        # Pop from the front using list.pop(0), or advance an index
        current = frontier.pop(0)

        if current == goal:
            # Reconstruct path
            path = []
            while current:
                path.append(current)
                current = parents[current]
            return path[::-1]

        # Explore all 4 neighbors
        directions = [(-1,0), (1,0), (0,-1), (0,1)]  # up, down, left, right
        for dr, dc in directions:
            r, c = current[0] + dr, current[1] + dc
            if is_valid(r, c) and (r, c) not in seen:
                seen.add((r, c))
                parents[(r, c)] = current
                frontier.append((r, c))

    return []
