def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    if not (0 <= start[0] < rows and 0 <= start[1] < cols and grid[start[0]][start[1]] == '.'):
        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols and grid[goal[0]][goal[1]] == '.'):
        return []
    if start == goal:
        return [start]

    level = [[-1 for _ in range(cols)] for _ in range(rows)]
    parent = [[None for _ in range(cols)] for _ in range(rows)]
    level[start[0]][start[1]] = 0

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    d = 0
    while True:
        updated = False
        for r in range(rows):
            for c in range(cols):
                if level[r][c] == d:
                    for dr, dc in directions:
                        nr, nc = r + dr, c + dc
                        if (0 <= nr < rows and 0 <= nc < cols and 
                            grid[nr][nc] == '.' and level[nr][nc] == -1):
                            level[nr][nc] = d + 1
                            parent[nr][nc] = (r, c)
                            updated = True
        d += 1
        if not updated or level[goal[0]][goal[1]] != -1:
            break

    if level[goal[0]][goal[1]] == -1:
        return []

    path = [goal]
    current = goal
    while current != start:
        current = parent[current[0]][current[1]]
        path.insert(0, current)

    return path
