import heapq

def solve(grid, start, goal):
    if (
        not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])) or
        not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0]))
    ):
        return []

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    directions = [(-1,0), (1,0), (0,-1), (0,1)]
    best_steps = {}
    frontier = []
    counter = 0

    heapq.heappush(frontier, (manhattan(start, goal), counter, start[0], start[1]))
    best_steps[(start[0], start[1])] = 0
    parent = {}

    while frontier:
        key, _, r, c = heapq.heappop(frontier)

        if (r, c) == goal:
            break

        if (r, c) in best_steps and best_steps[(r, c)] < key:
            continue  # Skip if already expanded with better move count

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                new_steps = best_steps[(r, c)] + 1
                if (nr, nc) not in best_steps or new_steps < best_steps[(nr, nc)]:
                    best_steps[(nr, nc)] = new_steps
                    parent[(nr, nc)] = (r, c)
                    man_dist = manhattan((nr, nc), goal)
                    counter += 1
                    heapq.heappush(frontier, (new_steps + man_dist, counter, nr, nc))

    if goal not in parent:
        return []

    path = []
    current = goal
    while current != start:
        path.append(current)
        current = parent[current]
    path.append(start)
    return path[::-1]

def manhattan(p1, p2):
    return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])
