    if start == goal:
        return [start]
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and 0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def manhattan(r, c):
        return abs(r - goal[0]) + abs(c - goal[1])

    best_steps = { (r, c): float('inf') for r in range(rows) for c in range(cols) }
    best_steps[start] = 0
    frontier = [ (0 + manhattan(*start), 0, start[0], start[1]) ]  # (key, steps, row, col)
    came_from = {}

    while frontier:
        key = min(frontier, key=lambda x: (x[0], x[1], x[2], x[3]))
        i = frontier.index(key)
        total_key, steps, r, c = frontier.pop(i)
        if (r, c) == goal:
            break
        if best_steps[(r, c)] < steps:
            continue
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                new_steps = steps + 1
                if new_steps < best_steps[(nr, nc)]:
                    best_steps[(nr, nc)] = new_steps
                    came_from[(nr, nc)] = (r, c)
                    frontier.append( (new_steps + manhattan(nr, nc), new_steps, nr, nc) )

    if goal not in came_from:
        return []

    path = [goal]
    while path[-1] != start:
        path.append(came_from[path[-1]])
    return path[::-1]
