def solve(grid, start, goal):
    def is_free(pos):
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def manhattan(pos):
        r, c = pos
        gr, gc = goal
        return abs(r - gr) + abs(c - gc)

    if not is_free(start) or not is_free(goal):
        return []

    if start == goal:
        return [start]

    open_cells = {start}
    closed_cells = set()
    parents = {}
    steps = {start: 0}

    while open_cells:
        current = min(open_cells, key=manhattan)
        open_cells.remove(current)
        closed_cells.add(current)

        if current == goal:
            path = []
            while current:
                path.append(current)
                current = parents.get(current)
            return path[::-1]

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = current[0] + dr, current[1] + dc
            neighbor = (nr, nc)
            if is_free(neighbor) and neighbor not in closed_cells:
                if neighbor not in open_cells or steps[current] + 1 < steps.get(neighbor, float('inf')):
                    open_cells.add(neighbor)
                    steps[neighbor] = steps[current] + 1
                    parents[neighbor] = current

    return []
