def solve(grid, start, goal):
    if start == goal:
        return [start]

    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and grid[start[0]][start[1]] == '.'):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0]) and grid[goal[0]][goal[1]] == '.'):
        return []

    def manhattan(p, q):
        return abs(p[0] - q[0]) + abs(p[1] - q[1])

    open_cells = {start}
    parents = {}
    steps = {start: 0}

    while open_cells:
        current = min(open_cells, key=lambda x: manhattan(x, goal))
        if current == goal:
            path = []
            while current:
                path.append(current)
                current = parents.get(current)
            return path[::-1]

        open_cells.remove(current)

        neighbors = [
            (current[0] - 1, current[1]),
            (current[0] + 1, current[1]),
            (current[0], current[1] - 1),
            (current[0], current[1] + 1)
        ]

        for neighbor in neighbors:
            if (
                0 <= neighbor[0] < len(grid)
                and 0 <= neighbor[1] < len(grid[0])
                and grid[neighbor[0]][neighbor[1]] == '.'
            ):
                if neighbor not in steps or steps[neighbor] > steps[current] + 1:
                    steps[neighbor] = steps[current] + 1
                    parents[neighbor] = current
                    if neighbor not in open_cells:
                        open_cells.add(neighbor)

    return []
