    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])) or grid[start[0]][start[1]] == '#':
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])) or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    dist = {(r, c): float('inf') for r in range(rows) for c in range(cols) if grid[r][c] == '.'}
    dist[start] = 0
    heap = [(0, start[0], start[1])]
    parent = {}

    while heap:
        d, r, c = heapq.heappop(heap)
        if (r, c) == goal:
            break
        if d > dist[(r, c)]:
            continue
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                if dist[(nr, nc)] > d + 1:
                    dist[(nr, nc)] = d + 1
                    parent[(nr, nc)] = (r, c)
                    heapq.heappush(heap, (d + 1, nr, nc))

    if goal not in parent:
        return []

    path = [goal]
    while path[-1] != start:
        path.append(parent[path[-1]])
    return path[::-1]
