                    dist[vr][vc] = dist[u_row][u_col] + 1
                    parent[vr][vc] = (u_row, u_col)

    if dist[goal[0]][goal[1]] == float('inf'):
        return []

    path = []
    node = goal
    while node is not None:
        path.append(node)
        node = parent[node[0]][node[1]]
    return path[::-1]
