    free_cells = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '.':
                free_cells.append((r, c))
    if start not in free_cells:
        free_cells.append(start)
    if goal not in free_cells:
        free_cells.append(goal)

    # Build directed edges between adjacent free cells
    edges = []
    for r, c in free_cells:
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if (nr, nc) in free_cells:
                edges.append(( (r, c), (nr, nc) ))

    # Initialize dist and parent dicts
    dist = {point: float('inf') for point in free_cells}
    parent = {point: None for point in free_cells}
    dist[start] = 0

    # Bellman-Ford algorithm
    for _ in range(len(free_cells) - 1):
        updated = False
        for u, v in edges:
            if dist[u] + 1 < dist[v]:
                dist[v] = dist[u] + 1
                parent[v] = u
                updated = True
        if not updated:
            break

    # Reconstruct path if goal is reachable
    if dist[goal] == float('inf'):
        return []

    path = []
    current = goal
    while current:
        path.append(current)
        current = parent[current]
    path.reverse()

    return path
