def solve(grid, start, goal):
    from math import inf

    ROWS, COLS = len(grid), len(grid[0])

    # Validate start and goal
    if not (0 <= start[0] < ROWS and 0 <= start[1] < COLS and grid[start[0]][start[1]] == '.'):
        return []
    if not (0 <= goal[0] < ROWS and 0 <= goal[1] < COLS and grid[goal[0]][goal[1]] == '.'):
        return []
    if start == goal:
        return [start]

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Build a list of edges between adjacent free cells
    edges = []
    for r in range(ROWS):
        for c in range(COLS):
            if grid[r][c] == '.':
                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < ROWS and 0 <= nc < COLS and grid[nr][nc] == '.':
                        edges.append(((r, c), (nr, nc)))

    # Initialize distance and parent structures
    dist = {(r, c): inf for r in range(ROWS) for c in range(COLS) if grid[r][c] == '.'}
    parent = {(r, c): None for r in range(ROWS) for c in range(COLS) if grid[r][c] == '.'}
    dist[start] = 0

    # Bellman-Ford-like relaxation
    # The maximum number of rounds is number-of-cells - 1 to detect a path
    for _ in range(ROWS * COLS):
        updated = False
        for (u, v) in edges:
            if dist[u] + 1 < dist[v]:
                dist[v] = dist[u] + 1
                parent[v] = u
                updated = True
        if not updated:
            break

    # Reconstruct path
    path = []
    current = goal
    while current is not None:
        path.append(current)
        current = parent[current]
    path.reverse()

    # Check that path starts at start and has valid cells
    if path and path[0] == start and all(grid[r][c] == '.' for r, c in path):
        return path
    else:
        return []
