    dist = {(r, c): float('inf') for r in range(rows) for c in range(cols)}
    parent = {}

    dist[start] = 0
    heap = [(0, start[0], start[1])]

    while heap:
        d, r, c = heapq.heappop(heap)

        if d > dist[(r, c)]:
            continue

        if (r, c) == goal:
            break

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if (
                0 <= nr < rows and 0 <= nc < cols
                and grid[nr][nc] == '.'
                and dist[(nr, nc)] > d + 1
            ):
                dist[(nr, nc)] = d + 1
                parent[(nr, nc)] = (r, c)
                heapq.heappush(heap, (d + 1, nr, nc))

    if (goal[0], goal[1]) not in parent:
        return []

    path = []
    curr = (goal[0], goal[1])
    while curr != start:
        path.append(curr)
        curr = parent[curr]
    path.append(start)
    path.reverse()
    return path
