        curr = frontier.pop(min_index)

        if curr in parent:
            continue  # Already finalized

        parent[curr] = None  # Mark as finalized

        if curr == goal:
            break

        for dr, dc in directions:
            nr, nc = curr[0] + dr, curr[1] + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                next_cell = (nr, nc)
                if dist[curr] + 1 < dist[next_cell]:
