import heapq

def solve(grid, start, goal):
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows = len(grid)
    cols = len(grid[0])
    seen = set()
    parent = {}
    frontier = []
    counter = 0

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    heapq.heappush(frontier, (counter, *start))
    seen.add(start)
    counter += 1

    while frontier:
        _, r, c = heapq.heappop(frontier)

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and (nr, nc) not in seen:
                if (nr, nc) == goal:
                    parent[(nr, nc)] = (r, c)
                    return build_path(goal, parent)
                seen.add((nr, nc))
                heapq.heappush(frontier, (counter, nr, nc))
                parent[(nr, nc)] = (r, c)
                counter += 1

    return []

def build_path(goal, parent):
    path = [goal]
    while path[-1] != parent[path[-1]]:
        path.append(parent[path[-1]])
    path.reverse()
    return path
