        return []

    steps[start] = 0
    frontier.append((manhattan(*start, *goal), counter, *start))
    counter += 1

    while frontier:
        # Find the minimum key in the frontier
        min_index = 0
        for i in range(1, len(frontier)):
            if frontier[i][0] < frontier[min_index][0]:
                min_index = i
            elif frontier[i][0] == frontier[min_index][0] and frontier[i][1] < frontier[min_index][1]:
                min_index = i
        key, cnt, r, c = frontier.pop(min_index)

        if (r, c) == goal:
            # Reconstruct path
            path = []
            current = (r, c)
            while current:
                path.append(current)
                current = parents.get(current)
            return path[::-1]

        if (r, c) in steps and steps[(r, c)] < key - manhattan(r, c, *goal):
            continue  # Already expanded with a better path

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
