    if (start == goal) and grid[start[0]][start[1]] == '.':
        return [start]

    # Check if start or goal is a wall
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    # Initialize distance and parent dictionaries
    dist = {}
    parent = {}
    for i in range(rows):
        for j in range(cols):
            dist[(i, j)] = float('inf')
    dist[start] = 0

    # Initialize frontier
    frontier = [start]

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while frontier:
        # Find the cell with the smallest distance in frontier
        min_dist = float('inf')
        u_index = -1
        for i, cell in enumerate(frontier):
            if dist[cell] < min_dist:
                min_dist = dist[cell]
                u_index = i
        if u_index == -1:
