        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols and grid[goal[0]][goal[1]] == '.'):
        return []

    def bfs(from_queue, from_parent, to_parent):
        while from_queue:
            for _ in range(len(from_queue)):
                r, c = from_queue.popleft()
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r + dr, c + dc
                    if (0 <= nr < rows and 0 <= nc < cols and
                        grid[nr][nc] == '.' and (nr, nc) not in from_parent):
                        from_parent[(nr, nc)] = (r, c)
                        from_queue.append((nr, nc))
                        if (nr, nc) in to_parent:
                            return (nr, nc)
        return None

    forward_queue = deque([start])
    forward_parent = {start: None}
    backward_queue = deque([goal])
    backward_parent = {goal: None}

    while forward_queue and backward_queue:
        meet = bfs(forward_queue, forward_parent, backward_parent)
        if meet:
            return build_path(forward_parent, meet) + build_path(backward_parent, meet)[::-1][1:]
        bfs(backward_queue, backward_parent, forward_parent)

    return []

def build_path(parent, meet):
    path = [meet]
    while parent[path[-1]] is not None:
        path.append(parent[path[-1]])
    return path[::-1]
