        if not from_queue:
            return False
        for _ in range(len(from_queue)):
            x, y = from_queue.popleft()
            for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == '.' and (nx, ny) not in from_visited:
                    from_visited.add((nx, ny))
                    from_parent[(nx, ny)] = (x, y)
                    from_queue.append((nx, ny))
                    if (nx, ny) in to_visited:
