    goal_queue = deque([goal])
    start_visited = {start}
    goal_visited = {goal}
    start_parent = {}
    goal_parent = {}

    while start_queue and goal_queue:
        meet = bfs(start_queue, start_visited, goal_visited, start_parent)
        if meet:
            break
        meet = bfs(goal_queue, goal_visited, start_visited, goal_parent)
        if meet:
