    backward_queue = deque([goal])
    forward_visited = {start: 0}
    backward_visited = {goal: 0}
    forward_parents = {start: None}
    backward_parents = {goal: None}

    while forward_queue and backward_queue:
        forward_expanded = expand(forward_queue, forward_visited, forward_parents)
        if any(cell in backward_visited for cell in forward_expanded):
            meeting_cell = next(cell for cell in forward_expanded if cell in backward_visited)
            return build_path(meeting_cell, forward_parents, backward_parents)

        backward_expanded = expand(backward_queue, backward_visited, backward_parents)
        if any(cell in forward_visited for cell in backward_expanded):
            meeting_cell = next(cell for cell in backward_expanded if cell in forward_visited)
            return build_path(meeting_cell, forward_parents, backward_parents)

    return []

