from collections import deque

def solve(grid, start, goal):
    def get_neighbors(pos):
        r, c = pos
        neighbors = []
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == '.':
                neighbors.append((nr, nc))
        return neighbors

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    def bfs_step(frontier, visited, parents):
        next_frontier = []
        for pos in frontier:
            for neighbor in get_neighbors(pos):
                if neighbor not in visited:
                    visited.add(neighbor)
                    parents[neighbor] = pos
                    next_frontier.append(neighbor)
        return next_frontier

    forward_queue = deque([start])
    backward_queue = deque([goal])

    forward_visited = {start}
    backward_visited = {goal}

    forward_parents = {start: None}
    backward_parents = {goal: None}

    while forward_queue and backward_queue:
        forward_expanded = bfs_step(forward_queue, forward_visited, forward_parents)
        if set(forward_expanded) & backward_visited:
            meeting = (set(forward_expanded) & backward_visited).pop()
            return build_path(forward_parents, meeting, backward_parents, start, goal)
        forward_queue = deque(forward_expanded)

        backward_expanded = bfs_step(backward_queue, backward_visited, backward_parents)
        if set(backward_expanded) & forward_visited:
            meeting = (set(backward_expanded) & forward_visited).pop()
            return build_path(forward_parents, meeting, backward_parents, start, goal)
        backward_queue = deque(backward_expanded)

    return []

def build_path(forward_parents, meeting, backward_parents, start, goal):
    path_forward = [meeting]
    pos = meeting
    while pos != start:
        pos = forward_parents[pos]
        path_forward.append(pos)
    path_forward.reverse()

    path_backward = [meeting]
    pos = meeting
    while pos != goal:
        pos = backward_parents[pos]
        path_backward.append(pos)

    return path_forward + path_backward[1:]
