            neighbor = (nx, ny)
            if is_valid(nx, ny) and neighbor not in visited:
                visited.add(neighbor)
                new_path = path + [neighbor]
                result = dls(neighbor, limit, depth + 1, new_path, best_depth, visited)
                if result:
                    return result
                visited.remove(neighbor)
            elif neighbor in best_depth and best_depth[neighbor] <= depth + 1:
                continue

    max_depth = rows * cols
    for depth in range(max_depth + 1):
        visited = {start}
        path = dls(start, depth, 0, [start], {}, visited)
        if path:
            return path
