    cols = len(grid[0])
    dir_map = {'U': (-1, 0), 'D': (1, 0), 'L': (0, -1), 'R': (0, 1)}

    def is_in_bounds(r, c):
        return 0 <= r < rows and 0 <= c < cols

    def is_wall(r, c):
        return not is_in_bounds(r, c) or grid[r][c] == '#'

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def jump_horizontal(r, c, dr, dc):
        while True:
            r += dr
            c += dc
            if not is_in_bounds(r, c) or grid[r][c] == '#':
                return None
            if (r, c) == goal:
                return (r, c)
            # Check for forced neighbor
            for nr, nc in [(r - 1, c), (r + 1, c)]:
                if is_wall(r, c + dc) and not is_wall(nr, c):
                    return (r, c)
            # Continue if no forced neighbor
            if not jump_vertical(r, c, -1) and not jump_vertical(r, c, 1):
                return None

    def jump_vertical(r, c, dd):
        while True:
            r += dd
            if not is_in_bounds(r, c) or grid[r][c] == '#':
                return None
            if (r, c) == goal:
                return (r, c)
            for dc in [-1, 1]:
                if jump_horizontal(r, c, 0, dc) is not None:
                    return (r, c)
            return None

    def neighbors(r, c):
        res = []
        for d in dir_map:
            nr, nc = r + dir_map[d][0], c + dir_map[d][1]
            if is_in_bounds(nr, nc) and grid[nr][nc] == '.':
                jp = jump_step(r, c, d)
                if jp is not None:
                    res.append(jp)
        return res

    def jump_step(r, c, direction):
        dr, dc = dir_map[direction]
        if direction in ('L', 'R'):
            return jump_horizontal(r, c, dr, dc)
        else:
            return jump_vertical(r, c, dr)

    heap = []
    heapq.heappush(heap, (0, start, None))
    parent = {}
    g = {start: 0}
    cost = 0
    while heap:
        _, current, prev = heapq.heappop(heap)
        if current == goal:
            break
        if current in parent and parent[current] == prev:
            continue
        parent[current] = prev
        for n in neighbors(current[0], current[1]):
            if n is None or n in g:
                continue
            g[n] = g[current] + 1
            priority = g[n] + heuristic(n, goal)
            heapq.heappush(heap, (priority, n, current))

    if goal not in parent:
        return []

    path = []
    curr = goal
    while curr != start:
        path.append(curr)
        curr = parent[curr]
    path.append(start)
    path.reverse()
    return path
