                return (r, c)
            # Check horizontal jumps
            for d in (-1, 1):
                if horizontal_jump(r, c, dr, d) is not None:
                    return (r, c)
            r += dr
        return None

    came_from = {}
    g_score = {}
    f_score = {}
    closed_set = set()

    for i in range(rows):
        for j in range(cols):
            g_score[(i, j)] = float('inf')
            f_score[(i, j)] = float('inf')

