        # Check for forced neighbors
        if dx != 0:  # Horizontal move
            if not is_free(grid, x, y - 1) or not is_free(grid, x, y + 1):
                return (x, y)
            if not is_free(grid, x - dx, y - 1) or not is_free(grid, x - dx, y + 1):
                return (x, y)
        else:  # Vertical move
            for dy2 in [-1, 1]:
                jp = jump_point(grid, (x, y), dy2, 0)
                if jp is not None:
