import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]
    if not is_free(grid, start) or not is_free(grid, goal):
        return []

    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    def is_in_bounds(pos):
        r, c = pos
        return 0 <= r < rows and 0 <= c < cols

    def is_free(grid, pos):
        r, c = pos
        return is_in_bounds(pos) and grid[r][c] == '.'

    def manhattan(pos):
        return abs(pos[0] - goal[0]) + abs(pos[1] - goal[1])

    def horizontal_jump(pos, d):
        r, c = pos
        while True:
            nc = c + d
            if not is_in_bounds((r, nc)) or grid[r][nc] == '#':
                return None
            next_pos = (r, nc)
            if next_pos == goal:
                return next_pos
            # Check for forced vertical neighbors (above and below)
            if is_free(grid, (r - 1, nc)) and (
                not is_free(grid, (r - 1, nc - d)) if d != 0 else True
            ) or is_free(grid, (r + 1, nc)) and (
                not is_free(grid, (r + 1, nc - d)) if d != 0 else True
            ):
                return next_pos
            c = nc

    def vertical_jump(pos, d):
        r, c = pos
        while True:
            nr = r + d
            if not is_in_bounds((nr, c)) or grid[nr][c] == '#':
                return None
            next_pos = (nr, c)
            if next_pos == goal:
                return next_pos
            # Check for horizontal jump points
            if horizontal_jump(next_pos, 1) or horizontal_jump(next_pos, -1):
                return next_pos
            r = nr

    def jump(pos, delta, parent):
        dr, dc = delta
        if dr != 0:
            return vertical_jump(pos, dr)
        return horizontal_jump(pos, dc)

    def get_neighbors(pos):
        r, c = pos
        for d in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nr, nc = r + d[0], c + d[1]
            if is_in_bounds((nr, nc)) and grid[nr][nc] == '.':
                yield (nr, nc), d

    came_from = {}
    cost_so_far = {}
    frontier = []
    heapq.heappush(frontier, (manhattan(start), start))
    cost_so_far[start] = 0

    while frontier:
        _, pos = heapq.heappop(frontier)
        if pos == goal:
            break
        for next_pos, direction in get_neighbors(pos):
            new_g = cost_so_far[pos] + 1
            if next_pos not in cost_so_far or new_g < cost_so_far[next_pos]:
                cost_so_far[next_pos] = new_g
                came_from[next_pos] = pos
                f = new_g + manhattan(next_pos)
                heapq.heappush(frontier, (f, next_pos))
                jump_point = jump(next_pos, direction, pos)
                if jump_point:
                    cost_so_far[jump_point] = cost_so_far[next_pos] + 1
                    came_from[jump_point] = pos
                    f = cost_so_far[jump_point] + manhattan(jump_point)
                    heapq.heappush(frontier, (f, jump_point))

    if goal not in came_from:
        return []

    # Reconstruct path
    path = [goal]
    current = goal
    while current != start:
        current = came_from[current]
        path.append(current)
    path.reverse()
    return path
