    def is_valid(r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def jump_point(r, c, direction):
        orig_r, orig_c = r, c
        step_r, step_c = direction
        while True:
            r += step_r
            c += step_c
            if not (0 <= r < len(grid) and 0 <= c < len(grid[0])):
                return None
            if (r, c) == goal:
                return r, c
            if not is_valid(r, c):
                return None

            if step_r != 0:  # vertical move
                if (is_valid(r - 1, c) and not is_valid(r - 2, c)) or (is_valid(r + 1, c) and not is_valid(r + 2, c)):
                    return r, c
                if step_r == 1:  # down
                    for horizontal in [(-1, 0), (1, 0)]:
                        if jump_point(r, c, horizontal) is not None:
                            return r, c
                else:  # up
                    for horizontal in [(-1, 0), (1, 0)]:
                        if jump_point(r, c, horizontal) is not None:
                            return r, c
            else:  # horizontal move
                if (is_valid(r, c - 1) and not is_valid(r, c - 2)) or (is_valid(r, c + 1) and not is_valid(r, c + 2)):
                    return r, c
                if jump_point(r, c, (-1, 0)) is not None or jump_point(r, c, (1, 0)) is not None:
                    return r, c
        return None

    def get_neighbors(r, c):
        neighbors = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:  # up, down, left, right
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == '.':
                jump = jump_point(nr, nc, (dr, dc))
                if jump is not None:
                    neighbors.append(jump)
        return neighbors

    # A* with jump points
    open_set = []
    heapq.heappush(open_set, (manhattan(start, goal), 0, start, None, [start]))
    visited = set()

    while open_set:
        _, g, pos, parent, path = heapq.heappop(open_set)
        if pos == goal:
            return path
        if pos in visited:
            continue
        visited.add(pos)

        for neighbor in get_neighbors(*pos):
            if neighbor not in visited:
                new_g = g + manhattan(pos, neighbor)
                new_path = path + [neighbor]
                heapq.heappush(open_set, (new_g + manhattan(neighbor, goal), new_g, neighbor, pos, new_path))

