    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows = len(grid)
    cols = len(grid[0])
    open_set = []
    heapq.heappush(open_set, (0, start))
    came_from = {}
    g_score = {start: 0}
    f_score = {start: manhattan(start, goal)}

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def jump_horizontal(r, c, dr, dc):
        while True:
            nr, nc = r + dr, c + dc
            if not is_valid(nr, nc):
                return None
            if (nr, nc) == goal:
                return (nr, nc)
            if is_valid(nr, c - dc) or is_valid(nr, c + dc):
                return (nr, nc)
            r, c = nr, nc

    def jump_vertical(r, c, dr, dc):
        while True:
            nr, nc = r + dr, c + dc
            if not is_valid(nr, nc):
                return None
            if (nr, nc) == goal:
                return (nr, nc)
            if jump_horizontal(nr, nc, 1, 0) or jump_horizontal(nr, nc, -1, 0) or \
               jump_horizontal(nr, nc, 0, 1) or jump_horizontal(nr, nc, 0, -1):
                return (nr, nc)
            r, c = nr, nc

    while open_set:
        current_f, current = heapq.heappop(open_set)
        if current == goal:
            return reconstruct_path(came_from, current, start)
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            if dr != 0:
                jump_result = jump_vertical(current[0], current[1], dr, dc)
                direction = (dr, dc)
            else:
                jump_result = jump_horizontal(current[0], current[1], dc, dc)
                if dc > 0:
                    direction = (0, 1)
                else:
                    direction = (0, -1)
            if jump_result and jump_result != current:
                step_count = abs(jump_result[0] - current[0]) + abs(jump_result[1] - current[1])
                tentative_g = g_score[current] + step_count
                if jump_result not in g_score or tentative_g < g_score[jump_result]:
                    came_from[jump_result] = current
                    g_score[jump_result] = tentative_g
                    f_score[jump_result] = tentative_g + manhattan(jump_result, goal)
                    heapq.heappush(open_set, (f_score[jump_result], jump_result))
    return []

def reconstruct_path(came_from, current, start):
    path = [current]
    while current in came_from:
        current = came_from[current]
        path.insert(0, current)
        if current == start:
            break
    return path
