def solve(grid, start, goal):
    if start == goal:
        return [start] if is_free(grid, start) else []

    rows, cols = len(grid), len(grid[0])
    if not (is_free(grid, start) and is_free(grid, goal)):
        return []

    def is_free(grid, pos):
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[r]) and grid[r][c] == '.'

    def get_neighbors(pos):
        r, c = pos
        return [(r + dr, c + dc) for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)] if is_free(grid, (r + dr, c + dc))]

    def jump_horizontal(pos, dir):
        r, c = pos
        dc_dir = dir // 2 - 1  # -1 for left, +1 for right
        new_pos = (r, c + dc_dir)
        if not is_free(grid, new_pos) or new_pos == goal:
            return new_pos
        if is_free(grid, (r - 1, c)) and not is_free(grid, (r - 1, c + dc_dir)) or \
           is_free(grid, (r + 1, c)) and not is_free(grid, (r + 1, c + dc_dir)):
            return new_pos
        return jump_horizontal(new_pos, dir)

    def jump_vertical(pos, dir):
        r, c = pos
        dr_dir = -1 if dir == 0 else 1  # -1 for up, +1 for down
        new_pos = (r + dr_dir, c)
        if not is_free(grid, new_pos) or new_pos == goal:
            return new_pos
        for d in [0, 2]:  # left and right
            jump = jump_horizontal(new_pos, d)
            if jump:
                return new_pos
        return jump_vertical(new_pos, dir)

    def jump(pos, dir):
        r, c = pos
        dr, dc = [(0, -1), (0, 1), (-1, 0), (1, 0)][dir]
        new_pos = (r + dr, c + dc)
        if not is_free(grid, new_pos) or new_pos == goal:
            return new_pos
        if dir in [0, 1]:  # horizontal
            return jump_horizontal(new_pos, dir)
        else:  # vertical
            return jump_vertical(new_pos, dir)

    def reconstruct_path(came_from, goal):
        path = [goal]
        while path[-1] != start:
            path.append(came_from[path[-1]])
        return path[::-1]

    open_set = [(0, start)]
    came_from = {}
    g_score = {start: 0}
    f_score = {start: manhattan(start, goal)}

    while open_set:
        f, current = heapq.heappop(open_set)
        if current == goal:
            return reconstruct_path(came_from, current)
        for dir in [0, 1, 2, 3]:  # left, right, up, down
            j = jump(current, dir)
            if j:
                new_g = g_score[current] + manhattan(current, j)
                if j not in g_score or new_g < g_score[j]:
                    g_score[j] = new_g
                    f_score[j] = new_g + manhattan(j, goal)
                    heapq.heappush(open_set, (f_score[j], j))
                    came_from[j] = current

    return []

def manhattan(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])
