import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]
    if not is_free(grid, start) or not is_free(grid, goal):
        return []

    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    dir_map = {'^': (-1, 0), 'v': (1, 0), '<': (0, -1), '>': (0, 1)}

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def is_in_bounds(p):
        return 0 <= p[0] < rows and 0 <= p[1] < cols

    def is_free(grid, p):
        return is_in_bounds(p) and grid[p[0]][p[1]] == '.'

    def get_neighbors(p):
        r, c = p
        neighbors = []
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if is_in_bounds((nr, nc)) and is_free(grid, (nr, nc)):
                neighbors.append((nr, nc))
        return neighbors

    def jump(p, dir):
        r, c = p
        dr, dc = dir_map[dir]
        steps = 0

        while True:
            nr, nc = r + dr, c + dc
            steps += 1

            if not is_in_bounds((nr, nc)) or not is_free(grid, (nr, nc)):
                return None

            if (nr, nc) == goal:
                return (nr, nc, dir, steps)

            if dir in ['<', '>']:
                # Horizontal, check for forced vertical neighbor
                if (is_free(grid, (nr - 1, nc)) and not is_free(grid, (nr - 1, nc - dr))) or \
                   (is_free(grid, (nr + 1, nc)) and not is_free(grid, (nr + 1, nc - dr))):
                    return (nr, nc, dir, steps)
            elif dir in ['^', 'v']:
                # Vertical, check if horizontal jump from this cell finds a jump point
                for h_dir in ['<', '>']:
                    if jump((nr, nc), h_dir):
                        return (nr, nc, dir, steps)
            r, c = nr, nc

    def expand(p):
        directions = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            if 0 <= dc * 1 < 2 and dr == 0 or 0 <= dr * 1 < 2 and dc == 0:
                dir_char =('^' if dr == -1 else 'v' if dr == 1 else '<' if dc == -1 else '>')
                j_result = jump(p, dir_char)
                if j_result and j_result[0]:
                    directions.append(j_result)
        return directions

    came_from = {}
    g = {start: 0}
    f = {start: manhattan(start, goal)}
    heap = [(f[start], g[start], start)]

    while heap:
        _, current_g, current = heapq.heapop(heap)

        if current == goal:
            return reconstruct_path(came_from, current)

        for next_cell, next_dir, steps in [x[:3] for x in expand(current) if x[0]]:
            g_new = g[current] + steps
            if next_cell not in g or g_new < g[next_cell]:
                g[next_cell] = g_new
                f[next_cell] = g[next_cell] + manhattan(next_cell, goal)
                heapq.heappush(heap, (f[next_cell], g[next_cell], next_cell))
                came_from[next_cell] = (current, next_dir)

    return []

def reconstruct_path(came_from, current):
    path = [current]
    while current in came_from:
        current, _ = came_from[current]
        path.insert(0, current)
    return path
