import heapq

def solve(grid, start, goal):
    from collections import deque

    if not is_valid(grid, start) or not is_valid(grid, goal):
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])

    def is_valid(pos):
        r, c = pos
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def get_neighbors(r, c):
        return [(r + dr, c + dc) for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]]

    def jump_horizontal(r, c, dRow, dCol, parent_r, parent_c):
        if not is_valid((r, c)):
            return None
        if (r, c) == goal:
            return (r, c)
        # Check for forced vertical neighbor
        for dr2 in [-1, 1]:
            if dr2 != dRow and is_valid((r + dr2, c)):
                if not is_valid((r + dr2, c - parent_r + dr2, c - parent_c)):
                    return (r, c)
        next_r, next_c = r + dRow, c + dCol
        res = jump_horizontal(next_r, next_c, dRow, dCol, r, c)
        return res if res else None

    def jump_vertical(r, c, dRow, dCol, parent_r, parent_c):
        if not is_valid((r, c)):
            return None
        if (r, c) == goal:
            return (r, c)
        # Check for forced horizontal neighbor
        for dc2 in [-1, 1]:
            if dc2 != dCol and is_valid((r, c + dc2)):
                if jump_horizontal(r, c + dc2, -1, 0, r, c) or jump_horizontal(r, c + dc2, 1, 0, r, c):
                    return (r, c)
            elif dc2 != dCol and is_valid((r, c + dc2, -1, 0)):
                if jump_horizontal(r, c + dc2, -1, 0, r, c) or jump_horizontal(r, c + dc2, 1, 0, r, c):
                    return (r, c)
        next_r, next_c = r + dRow, c + dCol
        res = jump_vertical(next_r, next_c, dRow, dCol, r, c)
        return res if res else None

    def jump(r, c, parent_r, parent_c):
        delta = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        jumps = []
        for dr, dc in delta:
            if parent_r is not None and dr != 0 and parent_r == r + dr:
                # Moving vertically from parent, try jump vertical
                res = jump_horizontal(r, c, dr, dc, parent_r, parent_c)
            elif parent_c is not None and dc != 0 and parent_c == c + dc:
                # Moving horizontally from parent, try jump horizontal
                res = jump_vertical(r, c, dr, dc, parent_r, parent_c)
            else:
                # Moving in a new direction, try both jump types
                res = jump_horizontal(r, c, dr, dc, parent_r, parent_c)
                if not res:
                    res = jump_vertical(r, c, dr, dc, parent_r, parent_c)
            if res:
                jumps.append(res)
        return jumps

    def heuristic(r, c):
        return abs(r - goal[0]) + abs(c - goal[1])

    def neighbors(r, c, parent_r, parent_c):
        return jump(r, c, parent_r, parent_c)

    hq = [(heuristic(start[0], start[1]), 0, start, None)]
    visited = set()
    parent_map = {}
    g_scores = {start: 0}

    while hq:
        f_score, g, pos, parent_pos = heapq.heappop(hq)
        r, c = pos
        if pos == goal:
            path = get_path(parent_map, start, pos)
            return path
        if pos in visited:
            continue
        visited.add(pos)
        for next_pos in neighbors(r, c, None if parent_pos is None else parent_pos[0], None if parent_pos is None else parent_pos[1]):
            nr, nc = next_pos
            ng = g + 1
            if next_pos in g_scores and ng >= g_scores[next_pos]:
                continue
            g_scores[next_pos] = ng
            h = heuristic(nr, nc)
            heapq.heappush(hq, (ng + h, ng, next_pos, pos))
            parent_map[next_pos] = pos

    return []

def get_path(parent_map, start, goal):
    path = [goal]
    current = goal
    while current != start:
        current = parent_map.get(current)
        if current is None:
            return []
        path.insert(0, current)
    return path
