import heapq

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and grid[start[0]][start[1]] == '.'):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0]) and grid[goal[0]][goal[1]] == '.'):
        return []
    if start == goal:
        return [start]

    def heuristic(pos):
        return abs(pos[0] - goal[0]) + abs(pos[1] - goal[1])

    def is_valid(pos):
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def parent(pos):
        return [[False for _ in range(len(grid[0]))] for _ in range(len(grid))]

    def horizontalJump(pos, dr):
        r, c = pos
        while True:
            next_r, next_c = r, c + dr
            if not is_valid((next_r, next_c)):
                return None
            c += dr
            if (next_r, c) == goal:
                return (next_r, c)
            up = (next_r - 1, c)
            down = (next_r + 1, c)
            if is_valid(up) and not is_valid((next_r - 2, c)) or is_valid(down) and not is_valid((next_r + 2, c)):
                return (next_r, c)
        return None

    def verticalJump(pos, dc):
        r, c = pos
        while True:
            next_r, next_c = r + 1, c
            if dc == -1:
                next_r, next_c = r - 1, c
            if not is_valid((next_r, next_c)):
                return None
            r = next_r
            if (r, c) == goal:
                return (r, c)
            left_jump = horizontalJump((r, c), -1)
            right_jump = horizontalJump((r, c), 1)
            if left_jump or right_jump:
                return (r, c)

    def directionalJump(pos, d):
        dr, dc = d
        r, c = pos
        next_r, next_c = r + dr, c + dc
        if not is_valid((next_r, next_c)):
            return None
        if (next_r, next_c) == goal:
            return (next_r, next_c)
        if dr == 0:  # Horizontal move
            if horizontalJump((r, next_c), dc):
                return horizontalJump((r, next_c), dc)
        else:  # Vertical move
            if verticalJump((r, next_c), dr):
                return verticalJump((r, next_c), dr)
        return None

    came_from = {}
    g_score = {start: 0}
    f_score = {start: heuristic(start)}
    open_set = [(f_score[start], 0, start)]

    while open_set:
        _, cost, current = heapq.heappop(open_set)
        if current == goal:
            break
        if current in came_from.values() and g_score[current] < cost:
            continue
        for direction in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            next_cell = directionalJump(current, direction)
            if next_cell:
                new_g = g_score[current] + abs(next_cell[0] - current[0]) + abs(next_cell[1] - current[1])
                if next_cell not in g_score or new_g < g_score[next_cell]:
                    g_score[next_cell] = new_g
                    h = heuristic(next_cell)
                    f_score[next_cell] = g_score[next_cell] + h
                    heapq.heappush(open_set, (f_score[next_cell], new_g, next_cell))
                    came_from[next_cell] = current

    if goal not in g_score:
        return []

    def reconstruct_path():
        path = [goal]
        current = goal
        while current != start:
            prev = came_from.get(current)
            if not prev or prev == current:
                return []
            path.insert(0, current)
            current = prev
        return path

    path = reconstruct_path()
    full_path = []
    for i in range(len(path) - 1):
        curr, next = path[i], path[i + 1]
        dx = (next[0] - curr[0])
        dy = (next[1] - curr[1])
        for step in range(1, max(abs(dx), abs(dy)) + 1):
            if dx == 0:
                full_path.append((curr[0], curr[1] + dy * (step // abs(dy))))
            else:
                full_path.append((curr[0] + dx * (step // abs(dx)), curr[1]))
    full_path.append(path[-1])
    return [start] + [cell for cell in full_path if cell != start]
