import heapq

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and grid[start[0]][start[1]] == '.'):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0]) and grid[goal[0]][goal[1]] == '.'):
        return []
    if start == goal:
        return [start]

    rows = len(grid)
    cols = len(grid[0])

    def is_wall(r, c):
        return not (0 <= r < rows and 0 <= c < cols and grid[r][c] == '.') if grid[r][c] != ' ' else True

    def horizontal_jump(r, c, dir):
        while True:
            c += dir
            if is_wall(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            for offset in (-1, 1):
                nr, nc = r + offset, c
                if is_wall(r, c - dir) and not is_wall(nr, nc):
                    return (r, c)
            if is_wall(r, c + dir):
                return None

    def vertical_jump(r, c, dir):
        while True:
            r += dir
            if is_wall(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            for offset in (-1, 1):
                nr, nc = r, c + offset
                if is_wall(r - dir, c) and not is_wall(nr, nc):
                    return (r, c)
            if is_wall(r + dir, c):
                return None

    def jps():
        h = lambda r, c: abs(r - goal[0]) + abs(c - goal[1])
        open_set = []
        heapq.heappush(open_set, (h(start[0], start[1]), 0, start, None))
        came_from = {}
        g_score = {}
        g_score[start] = 0

        while open_set:
            f, g, current, parent = heapq.heappop(open_set)
            if current == goal:
                return reconstruct_path(came_from, current)
            if current in g_score and g_score[current] < g:
                continue
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                if parent is None or not is_aligned(current, parent, dr, dc):
                    jump = horizontal_jump(current[0], current[1], dc) if dc != 0 else vertical_jump(current[0], current[1], dr)
                    if jump:
                        if jump not in g_score or g_score[current] + manhattan(current, jump) < g_score[jump]:
                            g_score[jump] = g_score[current] + manhattan(current, jump)
                            heapq.heappush(open_set, (g_score[jump] + h(jump[0], jump[1]), g_score[jump], jump, current))
                            came_from[jump] = current

        return []

    def is_aligned(current, parent, dr, dc):
        if parent is None:
            return False
        if dc != 0:
            return (current[0] - parent[0]) != 0 or dc != (current[1] - parent[1])
        else:
            return (current[1] - parent[1]) != 0 or dr != (current[0] - parent[0])

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def reconstruct_path(came_from, current):
        path = [current]
        while current in came_from:
            current = came_from[current]
            path.insert(0, current)
        return path

    path = jps()
    if path:
        return path
    return []
