    rows = len(grid)
    cols = len(grid[0])

    if not (0 <= start[0] < rows and 0 <= start[1] < cols and grid[start[0]][start[1]] == '.'):
        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols and grid[goal[0]][goal[1]] == '.'):
        return []

    def in_bounds(r, c):
        return 0 <= r < rows and 0 <= c < cols

    def is_wall(r, c):
        return not in_bounds(r, c) or grid[r][c] == '#'

    def heur(r, c):
        return abs(r - goal[0]) + abs(c - goal[1])

    dirs = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # Right, Down, Left, Up

    def jump_horizontal(r, c, dr, dc):
        next_r, next_c = r + dc, c + dr
        if is_wall(next_r, next_c):
            return None
        while True:
            next_r += dc
            next_c += dr
            if is_wall(next_r, next_c):
                return None
            if (next_r, next_c) == goal:
                return (next_r, next_c)
            if dr == 0 and is_wall(next_r, next_c - 1) and not is_wall(next_r - 1, next_c - 1):  # Up force
                return (next_r, next_c)
            if dr == 0 and is_wall(next_r, next_c + 1) and not is_wall(next_r - 1, next_c + 1):  # Down force
                return (next_r, next_c)
            if dc == 0 and is_wall(next_r - 1, next_c) and not is_wall(next_r - 1, next_c - 1):  # Left force
                return (next_r, next_c)
            if dc == 0 and is_wall(next_r + 1, next_c) and not is_wall(next_r + 1, next_c - 1):  # Right force
                return (next_r, next_c)

    def jump_vertical(r, c, dr, dc):
        next_r, next_c = r + dc, c + dr
        if is_wall(next_r, next_c):
            return None
        while True:
            next_r += dc
            next_c += dr
            if is_wall(next_r, next_c):
                return None
            if (next_r, next_c) == goal:
                return (next_r, next_c)
            # Jump horizontally from current point
            hor1 = jump_horizontal(next_r, next_c, 1, 0)  # Down
            hor2 = jump_horizontal(next_r, next_c, -1, 0)  # Up
            if hor1 or hor2:
                return (next_r, next_c)

    def jump(r, c, dr, dc):
        if (r + dr, c + dc) == goal:
            return (r + dr, c + dc)
        if dr in (1, -1):  # Vertical movement
            return jump_vertical(r, c, dr, dc)
        else:  # Horizontal movement
            return jump_horizontal(r, c, dr, dc)

    parent = {}
    cost = {}
    open_set = []

    heapq.heappush(open_set, (heur(start[0], start[1]), 0, start[0], start[1]))
    parent[(start[0], start[1])] = None
    cost[(start[0], start[1])] = 0

    while open_set:
        _, g, r, c = heapq.heappop(open_set)
        if (r, c) == goal:
            break
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if not in_bounds(nr, nc) or is_wall(nr, nc):
                continue
            jump_cell = jump(r, c, dr, dc)
            if jump_cell is not None:
                j_r, j_c = jump_cell
                step = 0
                tmp_r, tmp_c = r + dr, c + dc
                while (tmp_r, tmp_c) != (j_r, j_c):
                    step += 1
                    tmp_r += dr
                    tmp_c += dc
                step += 1  # last cell
                new_cost = g + step
                if (j_r, j_c) not in cost or new_cost < cost[(j_r, j_c)]:
                    cost[(j_r, j_c)] = new_cost
                    parent[(j_r, j_c)] = (r, c)
                    h = heur(j_r, j_c)
                    heapq.heappush(open_set, (new_cost + h, new_cost, j_r, j_c))

    if (goal[0], goal[1]) not in parent:
        return []

    path = []
    curr = goal
    while curr is not None:
        path.append(curr)
        curr = parent[curr]
    path.reverse()

    # Fill in straight path between jump points
    final_path = []
    for i in range(len(path) - 1):
        r1, c1 = path[i]
        r2, c2 = path[i + 1]
        dr = r2 - r1
        dc = c2 - c1
        dr = (dr // abs(dr)) if dr != 0 else 0
        dc = (dc // abs(dc)) if dc != 0 else 0
        curr_r, curr_c = r1, c1
        final_path.append((curr_r, curr_c))
        while (curr_r, curr_c) != (r2, c2):
            curr_r += dr
            curr_c += dc
            final_path.append((curr_r, curr_c))

    return final_path
