                        g[(nx, ny)] = new_cost
                        heapq.heappush(heap, (new_cost + manhattan((nx, ny), to_pos), new_cost, (nx, ny), node))
        return None, float('inf')

    forward = []
    backward = []
    f_path = f_cost = None
    b_path = b_cost = None
