def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    if (start == goal and grid[start[0]][start[1]] == '.') or (goal[0] < 0 or goal[0] >= rows or goal[1] < 0 or goal[1] >= cols or grid[goal[0]][goal[1]] == '#'):
