        while True:
            nr, nc = r + dr, c + dc
            if not is_valid(nr, nc):
                return None
            if (nr, nc) == goal:
                return (nr, nc, g + 1, (r, c))
            # Check for forced vertical neighbors
            if (is_valid(nr - 1, nc) and not is_valid(nr - 2, nc)) or (is_valid(nr + 1, nc) and not is_valid(nr + 2, nc)):
                return (nr, nc, g + 1, (r, c))
            r, c = nr, nc
            g += 1

    def jump_vertical(r, c, dr, dc, g, parent):
        while True:
            nr, nc = r + dr, c + dc
            if not is_valid(nr, nc):
                return None
            if (nr, nc) == goal:
                return (nr, nc, g + 1, (r, c))
            # Check for horizontal jump from current position
            for d in [(-1, 0), (1, 0)]:
                res = jump_horizontal(nr, nc, d[0], d[1], 1, (nr, nc))
                if res:
                    return res
            r, c = nr, nc
            g += 1

    visited = set()
    heap = []

    heapq.heappush(heap, (heuristic(*start, *goal), 0, start, None))

    while heap:
        _, g, (r, c), parent = heapq.heappop(heap)
        if (r, c) == goal:
            break
        if (r, c) in visited:
            continue
        visited.add((r, c))

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if not is_valid(nr, nc):
                continue
            if dr in (-1, 1):  # horizontal
                res = jump_horizontal(r, c, dr, dc, g + 1, (r, c))
            else:  # vertical
                res = jump_vertical(r, c, dr, dc, g + 1, (r, c))
            if res:
                next_r, next_c, next_g, next_parent = res
                if (next_r, next_c) not in visited:
                    heapq.heappush(heap, (heuristic(next_r, next_c, *goal) + next_g, next_g, (next_r, next_c), (r, c)))

    if (r, c) != goal:
        return []

    # Reconstruct path
    path = []
    node = goal
    parent_map = {}
    while parent is not None and node != start:
        parent_map[node] = parent
        parent = parent_map.get(node)
        node = parent
    if node != start:
        return []

    # Get full path with all steps between jump points
    path = [goal]
    current = path[0]
    while parent:
        parent = parent_map[current]
        while parent != path[-1]:
            pr, pc = parent
            cr, cc = path[-1]
            if pr == cr:
                step = (pr, pc + (1 if pc < cc else -1))
            else:
                step = (pr + (1 if pr < cr else -1), pc)
            path.append(step)
        path.append(parent)
        current = parent

    path.reverse()
    return path
