        if f1 + f2 >= min(forward_g.values()) + min(backward_g.values()):
            return []

        for curr_heap, curr_g, curr_parents, other_g, other_start, other_goal in [
            (forward_heap, forward_g, forward_parents, backward_g, goal, start),
            (backward_heap, backward_g, backward_parents, forward_g, start, goal)
        ]:
            if not curr_heap:
                return []
            path = search(curr_heap, other_start, other_start, curr_g, curr_parents, other_goal, other_g)
            if path:
                return path

    return []

