import heapq

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    def is_wall(cell):
        r, c = cell
        return r < 0 or c < 0 or r >= rows or c >= cols or grid[r][c] == '#'

    def get_neighbors(r, c):
        return [(r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)]

    def is_forced_vertical(r, c, dir):
        # Horizontal jump: check for vertical forced neighbor
        if is_wall((r, c)):
            return False
        for dr in (1, -1):
            nr, nc = r + dr, c
            if not is_wall((nr, nc)):
                # If horizontal neighbor is free, but next is wall, we have a forced vertical
                n2r, n2c = nr + dir[0], nc + dir[1]
                if is_wall((n2r, n2c)):
                    return True
        return False

    def is_forced_horizontal(r, c):
        # Vertical jump: check if a horizontal jump in either direction leads to forced cell
        for dc in (-1, 1):
            nr, nc = r, c + dc
            if not is_wall((nr, nc)):
                n2r, n2c = nr, nc + dc
                if is_wall((n2r, n2c)):
                    return True
        return False

    def jump(r, c, d):
        dr, dc = d
        steps = 0
        while True:
            cur_r, cur_c = r + dr * steps, c + dc * steps
            if is_wall((cur_r, cur_c)):
                return None
            steps += 1
            if (cur_r, cur_c) == goal:
                return (cur_r, cur_c)
            if is_forced_vertical(cur_r, cur_c, d):
                return (cur_r, cur_c)
            if dr != 0:  # Horizontal jump
                for d2 in ((0, 1), (0, -1)):
                    if not is_wall((cur_r, cur_c)) and not is_wall((cur_r + d2[0], cur_c + d2[1])):
                        if is_forced_horizontal(cur_r + d2[0], cur_c + d2[1]):
                            return (cur_r + d2[0], cur_c + d2[1])
            elif dc != 0:  # Vertical jump
                for d2 in ((1, 0), (-1, 0)):
                    if not is_wall((cur_r + d2[0], cur_c)) and is_forced_horizontal(cur_r + d2[0], cur_c):
                        return (cur_r + d2[0], cur_c)
    return None

    if start == goal:
        return [start] if not is_wall(start) else []

    if is_wall(start) or is_wall(goal):
        return []

    parent = {}
    g_scores = {start: 0}
    f_scores = {start: manhattan(start, goal)}

    hq = [(f_scores[start], 0, start)]

    def manhattan(cell, goal):
        cr, cc = cell
        gr, gc = goal
        return abs(cr - gr) + abs(cc - gc)

    while hq:
        f, g, cell = heapq.heappop(hq)

        if cell == goal:
            break

        for d in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            next_cell = jump(*cell, d)
            if next_cell and next_cell not in f_scores or g + manhattan(next_cell, cell) < f_scores[next_cell]:
                if next_cell not in g_scores or g + manhattan(next_cell, cell) < g_scores[next_cell]:
                    g_total = g_scores[cell] + manhattan(next_cell, cell)
                    parent[next_cell] = cell
                    g_scores[next_cell] = g_total
                    f_scores[next_cell] = g_total + manhattan(next_cell, goal)
                    heapq.heappush(hq, (f_scores[next_cell], g_total, next_cell))

    if goal not in parent:
        return []

    # Reconstruct path
    path = [goal]
    while path[-1] != start:
        path.append(parent[path[-1]])
    path.reverse()

    return path
