def solve(grid, start, goal):
    if start == goal:
        return [start]
    if not is_free(grid, start) or not is_free(grid, goal):
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_free(grid, pos):
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def bfs(from_pos, to_pos, is_reversed):
        visited = {}
        frontier = []
        heapq.heappush(frontier, (manhattan(from_pos, to_pos), 0, from_pos, None, None))
        while frontier:
            f, g, pos, parent, parent_g = heapq.heappop(frontier)
            if pos in visited and g >= visited[pos][0]:
                continue
            visited[pos] = (g, parent)
            if pos == to_pos or g + manhattan(pos, to_pos) >= best_f:
                continue
            for dr, dc in directions:
                r, c = pos[0] + dr, pos[1] + dc
                next_pos = (r, c)
                if is_free(grid, next_pos) and next_pos not in visited:
                    next_g = g + 1
                    heapq.heappush(frontier, (
                        next_g + manhattan(next_pos, to_pos),
                        next_g,
                        next_pos,
                        pos,
                        g
                    ))
        return visited

    best_f = float('inf')
    forward_visited = backward_visited = None

    def meet_in_middle():
        nonlocal best_f, forward_visited, backward_visited

        forward_visited = bfs(start, goal, is_reversed=False)
        if goal in forward_visited:
            return reconstruct_path(forward_visited, start, goal)
        backward_visited = bfs(goal, start, is_reversed=True)
        if start in backward_visited:
            return reconstruct_path(backward_visited, goal, start)

        while True:
            f_g = next_g = 0
            for node in forward_visited:
                f_g = max(f_g, forward_visited[node][0] + manhattan(node, goal))
            for node in backward_visited:
                next_g = max(next_g, backward_visited[node][0] + manhattan(node, start))
            if min(f_g, next_g) >= best_f:
                break
            for node in forward_visited:
                if node in backward_visited:
                    best_f = min(best_f, forward_visited[node][0] + backward_visited[node][0])
                    meeting_point = node
            if best_f != float('inf'):
                forward_path = reconstruct_path(forward_visited, start, meeting_point)
                backward_path = reconstruct_path(backward_visited, goal, meeting_point)
                return forward_path + backward_path[::-1][1:]
            forward_visited = bfs(start, goal, is_reversed=False)
            if goal in forward_visited:
                return reconstruct_path(forward_visited, start, goal)
            backward_visited = bfs(goal, start, is_reversed=True)
            if start in backward_visited:
                return reconstruct_path(backward_visited, goal, start)
        return []

    def reconstruct_path(visited, start, end):
        path = []
        node = end
        while node is not None:
            path.append(node)
            _, node = visited[node]
        return path[::-1] if start == path[0] else path[::-1]

    return meet_in_middle()
