import heapq

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])
            and 0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def get_neighbors(r, c):
        neighbors = []
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                neighbors.append((nr, nc))
        return neighbors

    def jump_horizontal(r, c, dir):  # dir is +1 for right, -1 for left
        while 0 <= c < len(grid[0]):
            c += dir
            if not (0 <= c < len(grid[0])):
                return None
            next_cell = grid[r][c]
            if next_cell == '#':
                return None
            new_pos = (r, c)
            # Check for forced vertical
            if grid[r-1][c] == '.' and (grid[r-2][c] == '#' or r-2 < 0):
                return new_pos
            if grid[r+1][c] == '.' and (grid[r+2][c] == '#' or r+2 >= len(grid)):
                return new_pos
            # Continue otherwise
            if dir > 0:
                if c < len(grid[0]) - 1 and grid[r][c + dir] == '.' and grid[r][c - dir] == '#':
                    return new_pos
            else:
                if c > 0 and grid[r][c + dir] == '.' and grid[r][c - dir] == '#':
                    return new_pos
        return None

    def jump_vertical(r, c, dir):  # dir is +1 for down, -1 for up
        while 0 <= r < len(grid):
            r += dir
            if not (0 <= r < len(grid)):
                return None
            next_cell = grid[r][c]
            if next_cell == '#':
                return None
            new_pos = (r, c)
            # Check for jump point by horizontal jumps
            left = jump_horizontal(r, c, -1)
            right = jump_horizontal(r, c, +1)
            if left or right:
                return new_pos
        return None

    def jump_point_search():
        open_set = [(manhattan(start, goal), 0, start, None)]
        visited = set()
        parent_map = {}

        while open_set:
            _, g, pos, parent = heapq.heappop(open_set)
            if pos == goal:
                path = [pos]
                while parent:
                    path.append(parent)
                    parent = parent_map.get(parent)
                return path[::-1]
            if pos in visited:
                continue
            visited.add(pos)
            parent_map[pos] = parent

            for dr, dc, call_jump in [(-1, 0, jump_vertical), (1, 0, jump_vertical),
                                     (0, -1, jump_horizontal), (0, 1, jump_horizontal)]:
                if call_jump == jump_horizontal:
                    jump_result = call_jump(pos[0], pos[1], dc)
                else:
                    jump_result = call_jump(pos[0], pos[1], dr)
                if jump_result:
                    if jump_result not in visited:
                        new_g = g + manhattan(pos, jump_result)
                        heapq.heappush(open_set, (new_g + manhattan(jump_result, goal), new_g, jump_result, pos))

        return []

    path = jump_point_search()
    if not path or path[-1] != goal:
        return []

    # Fill in the intermediate cells between jump points
    result_path = [start]
    for i in range(1, len(path)):
        r1, c1 = path[i-1]
        r2, c2 = path[i]
        while (r1, c1) != (r2, c2):
            if r1 < r2:
                r1 += 1
            elif r1 > r2:
                r1 -= 1
            elif c1 < c2:
                c1 += 1
            else:
                c1 -= 1
            result_path.append((r1, c1))
    result_path.append(goal)
    return result_path
