                    heapq.heappush(heap, (g + 1 + h, g + 1, next_pos))
                    parent[next_pos] = current
        return float('inf'), None, parent

    if start == goal and is_valid(start):
        return [start]
    if not is_valid(start) or not is_valid(goal):
        return []

    forward_g = {start: 0}
    backward_g = {goal: 0}
    forward_parent = {}
    backward_parent = {}

    best_cost = float('inf')
    best_meet = None

    while True:
        cost_f, meet, parent_f = heuristic_search(start, goal, forward=True)
        if cost_f < best_cost and meet is not None:
            best_cost = cost_f
            best_meet = meet
            forward_parent = parent_f

        cost_b, meet, parent_b = heuristic_search(goal, start, forward=False)
        if cost_b < best_cost and meet is not None:
            best_cost = cost_b
            best_meet = meet
            backward_parent = parent_b

        if best_meet is None:
            return []

        if best_cost >= best_cost:
            break

    # Reconstruct the path
    def build_path(meet, parent, start):
        path = []
        current = meet
        while current != start:
            path.append(current)
            current = parent[current]
        path.append(start)
        return path[::-1]

    path_start = build_path(best_meet, forward_parent, start)
    path_goal = build_path(best_meet, backward_parent, goal)

    return path_start + path_goal[1:]
