import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]

    if not is_free(grid, *start) or not is_free(grid, *goal):
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1,0),(1,0),(0,-1),(0,1)]  # up, down, left, right
    parent = {}
    g_scores = {}
    f_heap = []

    def is_free(grid, r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def is_wall(r, c):
        return not (0 <= r < len(grid) and 0 <= c < len(grid[0])) or grid[r][c] == '#'

    def manhattan(p1, p2):
        return abs(p1[0]-p2[0]) + abs(p1[1]-p2[1])

    def jump_horizontal(r, c, dr, dc, parent_point):
        while True:
            r += dr
            c += dc
            if is_wall(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            # Check for forced vertical neighbors
            if is_wall(r - dr, c + dr) or is_wall(r - dr, c - dr):
                return (r, c)
            if (r, c) in g_scores:
                return None
            if parent_point is not None:
                g_scores[(r, c)] = g_scores[parent_point] + 1
            # Recursively jump in the same direction
            next_jump = jump_horizontal(r, c, dr, dc, parent_point or (r, c))
            if next_jump:
                return next_jump
        return None

    def jump_vertical(r, c, dr, dc, parent_point):
        while True:
            r += dr
            c += dc
            if is_wall(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            # Check for forced horizontal neighbors
            if jump_horizontal(r, c, 0, 1, (r, c)) or jump_horizontal(r, c, 0, -1, (r, c)):
                return (r, c)
            if (r, c) in g_scores:
                return None
            if parent_point is not None:
                g_scores[(r, c)] = g_scores[parent_point] + 1
            # Recursively jump in the same direction
            next_jump = jump_vertical(r, c, dr, dc, parent_point or (r, c))
            if next_jump:
                return next_jump
        return None

    def get_jump_points(r, c):
        jumped = []
        for dr, dc in directions:
            dir_name = (dr, dc)
            if (dir_name[0] == 0 or dir_name[1] == 0) and (dir_name[0] != dir_name[1]):
                if dir_name[0]:  # vertical
                    new_point = jump_vertical(r, c, dr, dc, (r, c))
                else:  # horizontal
                    new_point = jump_horizontal(r, c, dr, dc, (r, c))
                if new_point:
                    jumped.append(new_point)
        return jumped

    heapq.heappush(f_heap, (manhattan(start, goal), 0, start))
    g_scores[start] = 0
    parent[start] = None

    while f_heap:
        f, g, (r, c) = heapq.heappop(f_heap)

        if (r, c) == goal:
            # Reconstruct path
            path = []
            curr = (r, c)
            while curr:
                path.append(curr)
                curr = parent[curr]
            return path[::-1]

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_free(grid, nr, nc) and (nr, nc) not in g_scores:
                g_scores[(nr, nc)] = g + 1
                parent[(nr, nc)] = (r, c)
                heapq.heappush(f_heap, (g + 1 + manhattan((nr, nc), goal), g + 1, (nr, nc)))

        # Get jump points
        for point in get_jump_points(r, c):
            if point not in g_scores:
                rj, cj = point
                g_scores[point] = g + manhattan((r, c), point)
                parent[point] = (r, c)
                heapq.heappush(f_heap, (g_scores[point] + manhattan(point, goal), g_scores[point], point))

    return []
