def solve(grid, start, goal):
    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def get_neighbors(pos):
        neighbors = []
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            r, c = pos[0] + dr, pos[1] + dc
            if 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.':
                neighbors.append((r,c))
        return neighbors

    def search(from_pos, to_pos, get_next):
        g = {from_pos: 0}
        heap = [(manhattan(from_pos, to_pos), from_pos)]
        parent = {}
        while heap:
            f, pos = heapq.heappop(heap)
            if pos == to_pos or f > g[pos] + manhattan(pos, to_pos):
                continue
            for next_pos in get_next(pos):
                new_g = g[pos] + 1
                if next_pos not in g or new_g < g[next_pos]:
                    g[next_pos] = new_g
                    heapq.heappush(heap, (new_g + manhattan(next_pos, to_pos), next_pos))
                    parent[next_pos] = pos
        return g, parent

    if start == goal:
        return [start]
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    g1, parent1 = search(start, goal, lambda pos: get_neighbors(pos))
    g2, parent2 = search(goal, start, lambda pos: get_neighbors(pos))

    # Find the best meeting point
    best_cost = float('inf')
    meeting_point = None
    for pos in g1:
        if pos in g2 and g1[pos] + g2[pos] < best_cost:
            best_cost = g1[pos] + g2[pos]
            meeting_point = pos

    if not meeting_point:
        return []

    # Reconstruct path
    path1 = []
    pos = meeting_point
    while pos in parent1:
        path1.append(pos)
        pos = parent1[pos]
    path1.reverse()

    path2 = []
    pos = meeting_point
    while pos in parent2:
        pos = parent2[pos]
        if pos != goal:
            path2.append(pos)
    path = [start] + path1 + path2 + [goal]

    # Check that the full path is valid
    for i in range(len(path)-1):
        r1, c1 = path[i]
        r2, c2 = path[i+1]
        if abs(r1 - r2) + abs(c1 - c2) != 1:
            return []
        if not (0 <= r1 < len(grid) and 0 <= c1 < len(grid[0]) and grid[r1][c1] == '.' and
                0 <= r2 < len(grid) and 0 <= c2 < len(grid[0]) and grid[r2][c2] == '.'):
            return []

    return path
