def solve(grid, start, goal):
    if start == goal:
        return [start]

    rows = len(grid)
    cols = len(grid[0])
    if not (0 <= start[0] < rows and 0 <= start[1] < cols and grid[start[0]][start[1]] == '.'):
        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols and grid[goal[0]][goal[1]] == '.'):
        return []

    def neighbors(r, c):
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                yield nr, nc

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def search(from_node, other, is_forward):
        g = {from_node: 0}
        f = {from_node: manhattan(from_node, other)}
        heap = [(f[from_node], g[from_node], from_node)]
        parent = {}
        while heap:
            _, cost, node = heapq.heappop(heap)
            if g.get(node, float('inf')) < cost:
                continue
            if node in other['g']:
                return node, cost + other['g'][node]
            for next_node in neighbors(*node):
                new_cost = g[node] + 1
                if new_cost < g.get(next_node, float('inf')):
                    g[next_node] = new_cost
                    f_node = new_cost + manhattan(next_node, other['start'])
                    heapq.heappush(heap, (f_node, new_cost, next_node))
                    parent[next_node] = node
        return None, float('inf')

    forward = {'start': start, 'goal': goal, 'g': {start: 0}, 'parent': {}}
    backward = {'start': goal, 'goal': start, 'g': {goal: 0}, 'parent': {}}
    heapf = [(manhattan(start, goal), 0, start)]
    heapb = [(manhattan(goal, start), 0, goal)]
    meets = []

    while heapf and heapb:
        meet, total_cost = search(forward['start'], backward['start'], True)
        if meet:
            meets.append((meet, total_cost))
            break

        meet, total_cost = search(backward['start'], forward['start'], False)
        if meet:
            meets.append((meet, total_cost))
            break

    if not meets:
        return []

    # Pick the meeting point with lowest total cost
    meet_point, _ = min(meets, key=lambda x: x[1])

    path = [meet_point]
    node = meet_point
    while node != forward['goal']:
        node = forward['parent'][node]
        path.append(node)
    path.reverse()

    node = meet_point
    while node != backward['goal']:
        node = backward['parent'][node]
        path.append(node)

    return path
