        if not frontier:
            return None, None
        cost, pos = heapq.heappop(frontier)
        if pos in other_g:
            return pos, cost + other_g[pos]
        for dr, dc in directions:
            nr, nc = pos[0] + dr, pos[1] + dc
            next_pos = (nr, nc)
            if is_free(grid, next_pos):
                new_g = g[pos] + 1
                if next_pos not in g or new_g < g[next_pos]:
                    g[next_pos] = new_g
                    came_from[next_pos] = pos
                    priority = new_g + manhattan(next_pos, (goal if frontier is forward else start))
                    heapq.heappush(frontier, (priority, next_pos))
        return None, None

    forward_heap = [(manhattan(start, goal), start)]
    forward_g = {start: 0}
    forward_came_from = {}

    backward_heap = [(manhattan(goal, start), goal)]
    backward_g = {goal: 0}
    backward_came_from = {}

    best_meet_cost = float('inf')
    best_meet_pos = None

    while forward_heap and backward_heap and (forward_heap[0][0] + backward_heap[0][0] < best_meet_cost):
        meet_pos, meet_cost = a_star(
            forward_heap, forward_g, forward_came_from, start, backward_g, backward_heap)
        if meet_pos is not None and meet_cost < best_meet_cost:
            best_meet_cost = meet_cost
            best_meet_pos = meet_pos
        meet_pos, meet_cost = a_star(
            backward_heap, backward_g, backward_came_from, goal, forward_g, forward_heap)
        if meet_pos is not None and meet_cost < best_meet_cost:
            best_meet_cost = meet_cost
            best_meet_pos = meet_pos

    if best_meet_pos is None:
        return []

    def reconstruct_path(came_from, start, end):
        path = []
        current = end
        while current != start:
            path.append(current)
            current = came_from[current]
        path.append(start)
        path.reverse()
        return path

    forward_path = reconstruct_path(forward_came_from, start, best_meet_pos)
    backward_path = reconstruct_path(backward_came_from, goal, best_meet_pos)

    return forward_path + backward_path[1:]
