import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]

    if not is_valid(grid, start[0], start[1]) or not is_valid(grid, goal[0], goal[1]):
        return []

    # Helper to get Manhattan distance
    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    # Helper to check if cell is valid (within grid and not wall)
    def is_valid(grid, r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    # A* search from given start to given goal
    def a_star(frontier, start, goal, g, parent, is_forward):
        while frontier:
            f, state, d = heapq.heappop(frontier)
            r, c = state

            if state in g and g[state] < d:
                continue

            if is_forward and state in g_backward:
                return state
            if not is_forward and state in g_forward:
                return state

            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if is_valid(grid, nr, nc):
                    next_state = (nr, nc)
                    new_g = d + 1
                    if next_state not in g or g[next_state] > new_g:
                        g[next_state] = new_g
                        parent[next_state] = state
                        h = manhattan(next_state, goal if is_forward else start)
                        heapq.heappush(frontier, (new_g + h, next_state, new_g))
        return None

    # Build the path from parent dicts
    def build_path(parent_start, parent_goal, meeting):
        path1 = []
        curr = meeting
        while curr in parent_start:
            path1.append(curr)
            curr = parent_start[curr]
        path1.reverse()

        path2 = []
        curr = meeting
        while curr in parent_goal:
            path2.append(curr)
            curr = parent_goal[curr]

        return path1 + path2

    # Forward A* from start to goal
    frontier_forward = []
    heapq.heappush(frontier_forward, (manhattan(start, goal), start, 0))
    g_forward = {start: 0}
    parent_forward = {start: None}

    # Backward A* from goal to start
    frontier_backward = []
    heapq.heappush(frontier_backward, (manhattan(goal, start), goal, 0))
    g_backward = {goal: 0}
    parent_backward = {goal: None}

    meeting_node = None

    # Alternate expansion between forward and backward search
    dir_forward = True
    while frontier_forward and frontier_backward:
        if dir_forward:
            meeting = a_star(frontier_forward, start, goal, g_forward, parent_forward, True)
            if meeting is not None:
                meeting_node = meeting
                break
        else:
            meeting = a_star(frontier_backward, goal, start, g_backward, parent_backward, False)
            if meeting is not None:
                meeting_node = meeting
                break
        dir_forward = not dir_forward

    if meeting_node is None or meeting_node not in g_forward or meeting_node not in g_backward:
        return []

    full_path = build_path(parent_forward, parent_backward, meeting_node)
    if full_path[0] != start:
        full_path.reverse()
    if full_path[-1] != goal:
        full_path.reverse()

    if full_path[0] != start or full_path[-1] != goal:
        return []

    return full_path
