            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and (nr, nc) not in seen:
                if (nr, nc) == goal:
                    parent[(nr, nc)] = (r, c)
                    return build_path(goal, parent)
                seen.add((nr, nc))
                parent[(nr, nc)] = (r, c)
                heapq.heappush(frontier, (counter, nr, nc))
                counter += 1

    return []

def build_path(goal, parent):
    path = [goal]
    current = goal
    while current in parent:
        current = parent[current]
        path.append(current)
    path.reverse()
    return path if path[0] == path[1] or all(a == b for a, b in zip(path, [start] + path)) else []
