import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]
    if not is_free(grid, *start) or not is_free(grid, *goal):
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def get_neighbors(r, c):
        return [(nr, nc) for dr, dc in directions if is_in_bounds(rows, cols, r + dr, c + dc) and is_free(grid, r + dr, c + dc)]

    def is_in_bounds(rows, cols, r, c):
        return 0 <= r < rows and 0 <= c < cols

    def is_free(grid, r, c):
        return grid[r][c] == '.'

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def a_star_search(start, goal):
        open_heap = [(manhattan(start, goal), 0, start)]
        came_from = {}
        g_score = {start: 0}

        while open_heap:
            _, g, current = heapq.heappop(open_heap)
            if current in came_from:
                continue
            if is_reached(current, goal):
                return reconstruct_path(came_from, start, goal)
            for neighbor in get_neighbors(*current):
                new_g = g + 1
                if neighbor not in g_score or new_g < g_score[neighbor]:
                    g_score[neighbor] = new_g
                    f = new_g + manhattan(neighbor, goal)
                    heapq.heappush(open_heap, (f, new_g, neighbor))
                    came_from[neighbor] = current
        return None

    def is_reached(p1, p2):
        return p1 == p2

    def reconstruct_path(came_from, start, goal):
        current = goal
        path = [current]
        while current != start:
            current = came_from[current]
            path.insert(0, current)
        return path

    forwardcame_from = {}
    backwardcame_from = {}
    forwardg = {start: 0}
    backwardg = {goal: 0}
    forwardheap = [(manhattan(start, goal) + 0, start)]  # f = g + h
    backwardheap = [(manhattan(start, goal) + 0, goal)]  # f = g + h

    while forwardheap and backwardheap:
        # Forward step
        f_forward, current = heapq.heappop(forwardheap)
        if current in backwardg:
            return join_paths(current, forwardcame_from, backwardcame_from, start, goal)
        if current in forwardcame_from:
            continue
        forwardcame_from[current] = None
        for neighbor in get_neighbors(*current):
            new_g = forwardg[current] + 1
            if neighbor not in forwardg or new_g < forwardg[neighbor]:
                forwardg[neighbor] = new_g
                f = new_g + manhattan(neighbor, goal)
                heapq.heappush(forwardheap, (f, neighbor))
                forwardcame_from[neighbor] = current

        # Backward step
        f_backward, current = heapq.heappop(backwardheap)
        if current in forwardg:
            return join_paths(current, forwardcame_from, backwardcame_from, start, goal)
        if current in backwardcame_from:
            continue
        backwardcame_from[current] = None
        for neighbor in get_neighbors(*current):
            new_g = backwardg[current] + 1
            if neighbor not in backwardg or new_g < backwardg[neighbor]:
                backwardg[neighbor] = new_g
                f = new_g + manhattan(neighbor, start)
                heapq.heappush(backwardheap, (f, neighbor))
                backwardcame_from[neighbor] = current

    return []

def join_paths(meet, forwardcame_from, backwardcame_from, start, goal):
    forward_path = [meet]
    current = meet
    while current != start:
        current = forwardcame_from[current]
        forward_path.insert(0, current)

    backward_path = [meet]
    current = meet
    while current != goal:
        current = backwardcame_from[current]
        backward_path.append(current)

    return forward_path + backward_path[1:]
