                    neighbor = (nx, ny)
                    new_g = g[current] + 1
                    if neighbor not in g or new_g < g[neighbor]:
                        g[neighbor] = new_g
                        f[neighbor] = new_g + manhattan(neighbor, goal)
                        heapq.heappush(open_heap, (f[neighbor], neighbor))
                        parent[neighbor] = current
