        if not g1 or not g2:
            break

        # Alternate expansion
        if g1:  # Expand forward search
            for node in list(g1.keys()):
                for dx, dy in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nx, ny = node[0] + dx, node[1] + dy
