        parent[(r, c)] = curr_cell
        frontier.append((key, r, c, steps))
        # Keep frontier sorted by key with stable insertion
        for i in range(len(frontier) - 1):
            if frontier[i] > frontier[i + 1]:
                frontier[i], frontier[i + 1] = frontier[i + 1], frontier[i]

    best_steps[start] = 0
    add_to_frontier(0, *start)

    while frontier:
        key, r, c, steps = frontier.pop(0)
        curr_cell = (r, c)

        if curr_cell == goal:
            path = []
            while curr_cell in parent:
                path.append(curr_cell)
                curr_cell = parent[curr_cell]
            return [start] + path[::-1]

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_free(grid, nr, nc) and best_steps.get((nr, nc), float('inf')) > steps + 1:
                add_to_frontier(steps + 1, nr, nc)

