def solve(grid, start, goal):
    if start == goal:
        return [start]
    rows, cols = len(grid), len(grid[0])
    came_from = {}
    cost_so_far = {}
    frontier = []
    steps = 0

    if not (0 <= start[0] < rows and 0 <= start[1] < cols and grid[start[0]][start[1]] == '.') or \
       not (0 <= goal[0] < rows and 0 <= goal[1] < cols and grid[goal[0]][goal[1]] == '.'):
        return []

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def push_frontier(r, c, steps):
        key = steps + manhattan((r, c), goal)
        for i in range(len(frontier)):
            if frontier[i][2:] == (r, c):
                frontier.pop(i)
                break
        frontier.append((key, steps, r, c))
        frontier.sort()

    push_frontier(start[0], start[1], steps)

    while frontier:
        key, steps, r, c = frontier.pop(0)
        if (r, c) == goal:
            break
        if (r, c) in came_from:
            continue
        cost_so_far[(r, c)] = steps
        for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                new_steps = steps + 1
                if (nr, nc) not in cost_so_far or new_steps < cost_so_far[(nr, nc)]:
                    cost_so_far[(nr, nc)] = new_steps
                    came_from[(nr, nc)] = (r, c)
                    push_frontier(nr, nc, new_steps)

    if goal not in came_from:
        return []

    path = [goal]
    while path[-1] != start:
        path.append(came_from[path[-1]])
    path.reverse()
    return path
