def solve(grid, start, goal):
    if start == goal:
        if grid[start[0]][start[1]] == '.':
            return [start]
        return []

    rows, cols = len(grid), len(grid[0])
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    open_flag = [[False for _ in range(cols)] for _ in range(rows)]
    closed_flag = [[False for _ in range(cols)] for _ in range(rows)]
    steps = [[float('inf') for _ in range(cols)] for _ in range(rows)]
    parent = [[None for _ in range(cols)] for _ in range(rows)]

    open_flag[start[0]][start[1]] = True
    steps[start[0]][start[1]] = 0

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while True:
        # Find the open cell with the smallest key
        min_key = float('inf')
        current = None
        for r in range(rows):
            for c in range(cols):
                if open_flag[r][c] and not closed_flag[r][c]:
                    key = steps[r][c] + abs(r - goal[0]) + abs(c - goal[1])
                    if key < min_key:
                        min_key = key
                        current = (r, c)

        if current is None:
            break  # No path found

        r, c = current
        if (r, c) == goal:
            break  # Goal reached

        closed_flag[r][c] = True
        open_flag[r][c] = False

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                if not closed_flag[nr][nc]:
                    new_steps = steps[r][c] + 1
                    if new_steps < steps[nr][nc]:
                        steps[nr][nc] = new_steps
                        parent[nr][nc] = (r, c)
                        open_flag[nr][nc] = True

    # Reconstruct path
    path = []
    current = goal
    while current is not None:
        path.append(current)
        current = parent[current[0]][current[1]]
    path.reverse()

    if path[0] != start or any(grid[r][c] == '#' for r, c in path):
        return []
    return path
