import heapq

def solve(grid, start, goal):
    if (
        not (0 <= start[0] < len(grid)) or 
        not (0 <= start[1] < len(grid[0])) or 
        not (0 <= goal[0] < len(grid)) or 
        not (0 <= goal[1] < len(grid[0])) or
        grid[start[0]][start[1]] == '#' or 
        grid[goal[0]][goal[1]] == '#'
    ):
        return []
    if start == goal:
        return [start]

    rows = len(grid)
    cols = len(grid[0])
    dist = [[float('inf')] * cols for _ in range(rows)]
    dist[start[0]][start[1]] = 0
    heap = [(0, start[0], start[1])]
    parent = {}

    directions = [(-1,0),(1,0),(0,-1),(0,1)]

    while heap:
        d, r, c = heapq.heappop(heap)
        if (r, c) == goal:
            break
        if d > dist[r][c]:
            continue
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                new_d = d + 1
                if new_d < dist[nr][nc]:
                    dist[nr][nc] = new_d
                    parent[(nr, nc)] = (r, c)
                    heapq.heappush(heap, (new_d, nr, nc))

    if (goal[0], goal[1]) not in parent:
        return []

    path = [goal]
    while path[-1] != start:
        path.append(parent[path[-1]])
    path.reverse()
    return path
