def solve(grid, start, goal):
    from copy import deepcopy

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    if not grid or not grid[0]:
        return []
    rows = len(grid)
    cols = len(grid[0])
    if not (0 <= start[0] < rows and 0 <= start[1] < cols and \
            0 <= goal[0] < rows and 0 <= goal[1] < cols):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    came_from = {}
    steps = {}
    current_steps = 0
    frontier = []
    steps[start] = current_steps
    frontier.append((manhattan(start, goal), current_steps, start[0], start[1]))

    def find_min_index(frontier):
        min_index = 0
        for i in range(1, len(frontier)):
            if frontier[i] < frontier[min_index]:
                min_index = i
        return min_index

    while frontier:
        index = find_min_index(frontier)
        current_key = frontier.pop(index)
        current = (current_key[2], current_key[3])
        current_steps = current_key[1]

        if current == goal:
            path = [current]
            while current in came_from:
                current = came_from[current]
                path.insert(0, current)
            return path

        for dx, dy in [(-1,0), (1,0), (0,-1), (0,1)]:
            neighbor = (current[0] + dx, current[1] + dy)
            if 0 <= neighbor[0] < rows and 0 <= neighbor[1] < cols and grid[neighbor[0]][neighbor[1]] != '#':
                new_steps = current_steps + 1
                if neighbor not in steps or new_steps < steps[neighbor]:
                    steps[neighbor] = new_steps
                    came_from[neighbor] = current
                    key = new_steps + manhattan(neighbor, goal)
                    frontier.append((key, new_steps, neighbor[0], neighbor[1]))

