            if grid[r][c] == '.':
                free.add((r, c))
    if start not in free or goal not in free:
        return []
    dist = {start: 0}
    open_cells = {start}
    parent = {}
    while open_cells:
        u = min(open_cells, key=lambda c: dist[c])
