                path.append(u)
                u = parent.get(u)
            return path[::-1]
        open_cells.remove(u)
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            v = (u[0] + dr, u[1] + dc)
            if v in free:
                if v not in dist or dist[u] + 1 < dist[v]:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    open_cells.add(v)
    return []
