from collections import deque

def solve(grid, start, goal):
    if start == goal:
        if 0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and grid[start[0]][start[1]] == '.':
            return [start]
        else:
            return []

    rows = len(grid)
    cols = len(grid[0])

    if (not (0 <= start[0] < rows and 0 <= start[1] < cols and grid[start[0]][start[1]] == '.')) or \
       (not (0 <= goal[0] < rows and 0 <= goal[1] < cols and grid[goal[0]][goal[1]] == '.')):
        return []

    def bfs(from_queue, from_visited, to_visited, from_parent):
        if not from_queue:
            return None
        for _ in range(len(from_queue)):
            x, y = from_queue.popleft()
            for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == '.' and (nx, ny) not in from_visited:
                    from_visited.add((nx, ny))
                    from_parent[(nx, ny)] = (x, y)
                    from_queue.append((nx, ny))
                    if (nx, ny) in to_visited:
                        return (nx, ny)
        return None

    start_queue = deque([start])
    goal_queue = deque([goal])
    start_visited = {start}
    goal_visited = {goal}
    start_parent = {}
    goal_parent = {}

    while start_queue or goal_queue:
        meet = bfs(start_queue, start_visited, goal_visited, start_parent)
        if meet:
            break
        meet = bfs(goal_queue, goal_visited, start_visited, goal_parent)
        if meet:
            break
    else:
        return []

    # Reconstruct path
    path = []

    # From start to meeting point
    curr = meet
    while curr != start:
        path.append(curr)
        curr = start_parent[curr]

    path.reverse()
    path = [start] + path

    # From meeting point to goal
    curr = meet
