    ):
        return []

    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(frontier, parents, other_parents):
        next_frontier = []
        for r, c in frontier:
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if (
                    0 <= nr < len(grid) and
                    0 <= nc < len(grid[0]) and
                    grid[nr][nc] == '.' and
                    (nr, nc) not in parents
                ):
                    if (nr, nc) in other_parents:
                        return (False, (r, c), (nr, nc))
                    parents[(nr, nc)] = (r, c)
                    next_frontier.append((nr, nc))
        return (True, next_frontier, None)

    forward_queue = deque([start])
    backward_queue = deque([goal])
    forward_parents = {start: None}
    backward_parents = {goal: None}

    while forward_queue and backward_queue:
        if forward_queue:
            success, next_forward, meeting = bfs(forward_queue, forward_parents, backward_parents)
            if not success:
                _, meet1, meet2 = bfs(forward_queue, forward_parents, backward_parents)
                path = build_path(meet1, forward_parents, backward_parents, goal)
                return path
            forward_queue = deque(next_forward)

        if backward_queue:
            success, next_backward, meeting = bfs(backward_queue, backward_parents, forward_parents)
            if not success:
                _, meet1, meet2 = bfs(backward_queue, backward_parents, forward_parents)
                path = build_path(meet1, forward_parents, backward_parents, goal)
                return path
            backward_queue = deque(next_backward)

    return []

def build_path(meeting_cell, forward_parents, backward_parents, goal):
    path = [meeting_cell]
    current = meeting_cell
    while current != None and current != (current := forward_parents.get(current, None)):
        path.append(current)
    path.reverse()
    current = meeting_cell
    while True:
        found = False
        for key, val in backward_parents.items():
            if val == current:
                path.append(key)
                current = key
                found = True
                break
        if not found or current == goal:
            break
    return path
