        while 0 <= col + d_col < cols and grid[row][col + d_col] == '.':
            col += d_col
            if (row, col) == goal:
                return (row, col)
            if (0 <= row - 1 < rows and grid[row - 1][col] == '.') or (
                0 <= row + 1 < rows and grid[row + 1][col] == '.'):
                return (row, col)
        return None

    def vertical_jump(row, col, d_row):
        original_row = row
        while 0 <= row + d_row < rows and grid[row + d_row][col] == '.':
            row += d_row
            if (row, col) == goal:
                return (row, col)
            for d_col in (-1, 1):
                jpt = horizontal_jump(row, col, d_col)
                if jpt:
                    return (row, col)
        return None

    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right
    queue = []
    heapq.heappush(queue, (0, start))
    came_from = {}
