            if jpt and jpt not in g_scores:
                g_new = g_scores[current] + abs(jpt[0] - current[0]) + abs(jpt[1] - current[1])
                g_scores[jpt] = g_new
                came_from[jpt] = current
                h = abs(jpt[0] - goal[0]) + abs(jpt[1] - goal[1])
