import heapq

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # Up, Down, Left, Right
    heap = [(manhattan(start, goal), 0, start, None)]
    visited = {start: None}

    while heap:
        f, g, current, parent = heapq.heappop(heap)
        if current == goal:
            return reconstruct_path(visited, start, goal)

        for dx, dy in directions:
            jump = jump_point(grid, current, dx, dy, goal)
            if jump is None:
                continue
            if jump in visited:
                continue
            if is_free(grid, jump[0], jump[1]):
                new_g = g + manhattan(current, jump)
                visited[jump] = current
                heapq.heappush(heap, (new_g + manhattan(jump, goal), new_g, jump, current))

    return []

def manhattan(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])

def is_free(grid, r, c):
    return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

def jump_point(grid, current, dx, dy, goal):
    x, y = current
    while True:
        x += dx
        y += dy
        if not is_free(grid, x, y):
            return None
        if (x, y) == goal:
            return (x, y)

        # Check for forced neighbors
        if dx != 0:  # Horizontal move
            if not is_free(grid, x, y - 1) or not is_free(grid, x, y + 1):
                return (x, y)
            if not is_free(grid, x - dx, y - 1) or not is_free(grid, x - dx, y + 1):
                return (x, y)
        else:  # Vertical move
            for dy2 in [-1, 1]:
                next_jp = jump_point(grid, (x, y), dy2, 0, goal)
                if next_jp is not None:
                    return (x, y)

        if dx != 0:
            next_jp = jump_point(grid, (x, y), 0, -1, goal)
            if next_jp is not None:
                return (x, y)
            next_jp = jump_point(grid, (x, y), 0, 1, goal)
            if next_jp is not None:
                return (x, y)

def reconstruct_path(visited, start, goal):
    path = []
    current = goal
    while current:
        path.append(current)
        current = visited[current]
    return path[::-1]
