    cols = len(grid[0])

    def in_bounds(r, c):
        return 0 <= r < rows and 0 <= c < cols

    def is_wall(r, c):
        return not in_bounds(r, c) or grid[r][c] == '#'

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def jump_horizontal(r, c, dr, dc):
        while True:
            r += dr
            if not in_bounds(r, c) or grid[r][c] == '#':
                return None
            if (r, c) == goal:
                return (r, c)
            # Check for forced vertical neighbors
            for nr, nc in [(r - 1, c), (r + 1, c)]:
                if not in_bounds(r, c + dc) or grid[r][c + dc] == '#':
                    if in_bounds(nr, nc) and grid[nr][nc] == '.':
                        return (r, c)
            # Check for horizontal jump continuation
            if (jump_vertical(r, c, 1) or
                jump_vertical(r, c, -1) or
                jump_horizontal(r, c, dr, dc) is None):
                return (r, c)

    def jump_vertical(r, c, dd):
        while True:
            c += dd
            if not in_bounds(r, c) or grid[r][c] == '#':
                return None
            if (r, c) == goal:
                return (r, c)
            # Check for forced horizontal neighbors
            for nr, nc in [(r, c - 1), (r, c + 1)]:
                if not in_bounds(r, c + dd) or grid[r][c + dd] == '#':
                    if in_bounds(nr, nc) and grid[nr][nc] == '.':
                        return (r, c)
            # Check for vertical jump continuation
            if (jump_horizontal(r, c, 1, 0) or
                jump_horizontal(r, c, -1, 0) or
                jump_vertical(r, c, dd) is None):
                return (r, c)

    heap = []
    heapq.heappush(heap, (0, start, None))
    parent = {}
    g = {start: 0}

    # Direction map: 'U', 'D', 'L', 'R'
    dir_map = {'U': (-1, 0), 'D': (1, 0), 'L': (0, -1), 'R': (0, 1)}

    def get_neighbors(r, c):
        res = []
        for d in dir_map:
            dr, dc = dir_map[d]
            nr, nc = r + dr, c + dc
            if in_bounds(nr, nc) and grid[nr][nc] == '.':
                if d in 'LR':
                    jump = jump_horizontal(r, c, dr, dc)
                else:
                    jump = jump_vertical(r, c, dr)
                if jump:
                    res.append(jump)
        return res

    while heap:
        _, current, prev = heapq.heappop(heap)
        if current == goal:
            break
        if current in parent and parent[current] == prev:
            continue
        parent[current] = prev

        for next in get_neighbors(*current):
            if next not in g or g[next] > g[current] + 1:
                g[next] = g[current] + 1
                f = g[next] + heuristic(next, goal)
                heapq.heappush(heap, (f, next, current))

    if goal not in parent:
        return []

    path = []
    curr = goal
    while curr != start:
        path.append(curr)
        curr = parent[curr]
    path.append(start)
    path.reverse()
    return path
