            if dr != 0:
                for ndc in (-1, 1):
                    nr, nc = r + dr, c + ndc
                    if not is_valid(nr, nc):
                        return (r, c)
            elif dc != 0:
                for ndr in (-1, 1):
                    nr, nc = r + ndr, c + dc
                    if not is_valid(nr, nc):
                        return (r, c)
            c += dc
        return None

