                return r, c

            if step_r != 0:  # vertical move
                if (is_valid(r - 1, c) and not is_valid(r - 1 - step_r, c)) or (is_valid(r + 1, c) and not is_valid(r + 1 + step_r, c)):
                    return r, c
                if step_r == 1:  # down
                    for horizontal in [(-1, 0), (1, 0)]:
                        if jump_point(r, c, horizontal) is not None:
                            return r, c
                else:  # up
                    for horizontal in [(-1, 0), (1, 0)]:
                        if jump_point(r, c, horizontal) is not None:
                            return r, c
            else:  # horizontal move
                if (is_valid(r, c - 1) and not is_valid(r, c - 1 - step_c)) or (is_valid(r, c + 1) and not is_valid(r, c + 1 + step_c)):
                    return r, c
                if jump_point(r, c, (-1, 0)) is not None or jump_point(r, c, (1, 0)) is not None:
