            if is_valid(nr, nc):
                jump = jump_point(nr, nc, (dr, dc))
                if jump is not None:
                    neighbors.append(jump)
        return neighbors

    open_set = []
    heapq.heappush(open_set, (manhattan(start, goal), 0, start, None, [start]))
