        _, current = heapq.heappop(open_list)
        if current in visited:
            continue
        if current == goal:
            break
        visited.add(current)

        for dir_idx in [0, 1, 2, 3]:  # Up, Down, Left, Right
            if dir_idx == 0:  # Up
                next_cell = jump_vertical(grid, current, (-1, 0), goal)
            elif dir_idx == 1:  # Down
                next_cell = jump_vertical(grid, current, (1, 0), goal)
            elif dir_idx == 2:  # Left
                next_cell = jump_horizontal(grid, current, (0, -1), goal)
            else:  # Right
                next_cell = jump_horizontal(grid, current, (0, 1), goal)

            if next_cell is not None:
                new_g = g[current] + manhattan_distance(current, next_cell)
                if next_cell not in g or new_g < g[next_cell]:
                    g[next_cell] = new_g
                    parent[next_cell] = current
                    f = new_g + manhattan(next_cell, goal)
                    heapq.heappush(open_list, (f, next_cell))

    if goal in parent:
        path = [goal]
        curr = goal
        while curr != start:
            curr = parent[curr]
            path.append(curr)
        return path[::-1]
    return []

def manhattan(pos, goal):
    return manhattan_distance(pos, goal)

def manhattan_distance(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])

def jump_horizontal(grid, pos, direction, goal):
    dr, dc = direction
    r, c = pos
    r += dr
    c += dc
    if not (0 <= r < len(grid) and 0 <= c < len(grid[0])):
        return None
    if grid[r][c] == '#':
        return None
    if (r, c) == goal:
        return (r, c)
    # Check if any forced neighbor is present (up or down is free and has wall one step back)
    if (0 <= r - 1 < len(grid) and grid[r - 1][c] == '.' and (r - 2 < 0 or grid[r - 2][c] == '#')):
        return (r, c)
    if (0 <= r + 1 < len(grid) and grid[r + 1][c] == '.' and (r + 2 >= len(grid) or grid[r + 2][c] == '#')):
        return (r, c)
    return jump_horizontal(grid, (r, c), direction, goal)

def jump_vertical(grid, pos, direction, goal):
    dr, dc = direction
    r, c = pos
    r += dr
    c += dc
    if not (0 <= r < len(grid) and 0 <= c < len(grid[0])):
        return None
    if grid[r][c] == '#':
        return None
    if (r, c) == goal:
        return (r, c)
    # Check if any horizontal jump from here yields a jump point
    for h_dir in [(0, 1), (0, -1)]:
        h_res = jump_horizontal(grid, (r, c), h_dir, goal)
        if h_res is not None:
            return (r, c)
    return jump_vertical(grid, (r, c), direction, goal)
