        return [start]
    if not is_free(grid, start) or not is_free(grid, goal):
        return []

    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    def is_in_bounds(pos):
        r, c = pos
        return 0 <= r < rows and 0 <= c < cols

    def is_free(grid, pos):
        r, c = pos
        return is_in_bounds(pos) and grid[r][c] == '.'

    def manhattan(pos):
        return abs(pos[0] - goal[0]) + abs(pos[1] - goal[1])

    def horizontal_jump(pos, d):
        r, c = pos
        while True:
            nc = c + d
            if not is_in_bounds((r, nc)) or grid[r][nc] == '#':
                return None
            next_pos = (r, nc)
            if next_pos == goal:
                return next_pos
            if is_free(grid, (r - 1, nc)) and is_free(grid, (r - 1, nc - d)) and grid[r - 1][nc - d] == '#':
                return next_pos
            if is_free(grid, (r + 1, nc)) and is_free(grid, (r + 1, nc - d)) and grid[r + 1][nc - d] == '#':
                return next_pos
            c = nc

    def vertical_jump(pos, d):
        r, c = pos
        while True:
            nr = r + d
            if not is_in_bounds((nr, c)) or grid[nr][c] == '#':
                return None
            next_pos = (nr, c)
            if next_pos == goal:
                return next_pos
            if any(horizontal_jump(next_pos, d) for d in (1, -1)):
                return next_pos
            r = nr

    def jump(pos, delta, parent):
        dr, dc = delta
        if dr != 0:
            return vertical_jump(pos, dr)
        return horizontal_jump(pos, dc)

    def get_neighbors(pos):
        r, c = pos
        for d in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nr, nc = r + d[0], c + d[1]
            if is_in_bounds((nr, nc)) and grid[nr][nc] == '.':
                yield (nr, nc), d

    came_from = {}
    cost_so_far = {}
    frontier = []
    heapq.heappush(frontier, (0 + manhattan(start), 0, start))
    cost_so_far[start] = 0

    while frontier:
        _, g, pos = heapq.heappop(frontier)
        if pos == goal:
            break
        for next_pos, direction in get_neighbors(pos):
            new_g = g + 1
            if next_pos not in cost_so_far or new_g < cost_so_far[next_pos]:
                cost_so_far[next_pos] = new_g
                came_from[next_pos] = pos
                f = new_g + manhattan(next_pos)
                heapq.heappush(frontier, (f, new_g, next_pos))
                jump_point = jump(next_pos, direction, pos)
                if jump_point:
                    extra_g = abs(next_pos[0] - jump_point[0]) + abs(next_pos[1] - jump_point[1])
                    jump_cost = new_g + extra_g
                    if jump_point not in cost_so_far or jump_cost < cost_so_far.get(jump_point, float('inf')):
                        cost_so_far[jump_point] = jump_cost
                        came_from[jump_point] = pos
                        f = jump_cost + manhattan(jump_point)
                        heapq.heappush(frontier, (f, jump_cost, jump_point))

    if goal not in came_from:
        return []

    # Reconstruct path
    path = [goal]
    current = goal
    while current != start:
        current = came_from[current]
        path.append(current)
    path.reverse()
    return path
