        return [start]

    rows = len(grid)
    cols = len(grid[0])

    def is_wall(r, c):
        return not (0 <= r < rows and 0 <= c < cols) or grid[r][c] != '.'

    def horizontal_jump(r, c, dir):
        while True:
            c += dir
            if not (0 <= c < cols):
                return None
            if is_wall(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            for offset in (-1, 1):
                nr, nc = r + offset, c
                if is_wall(r, c - dir) and not is_wall(nr, nc):
                    return (r, c)
            if is_wall(r, c + dir):
                return None

    def vertical_jump(r, c, dir):
        while True:
            r += dir
            if not (0 <= r < rows):
                return None
            if is_wall(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            for offset in (-1, 1):
                nr, nc = r, c + offset
                if is_wall(r - dir, c) and not is_wall(nr, nc):
                    return (r, c)
            if is_wall(r + dir, c):
                return None

    def reconstruct_path(came_from, current):
        path = [current]
        while current in came_from:
            current = came_from[current]
            path.insert(0, current)
        return path

    def jps():
        h = lambda r, c: abs(r - goal[0]) + abs(c - goal[1])
        open_set = []
        heapq.heappush(open_set, (h(start[0], start[1]), 0, start, None))
        g_score = {start: 0}
        came_from = {}

        while open_set:
            f, g, current, parent = heapq.heappop(open_set)
            if current == goal:
                return reconstruct_path(came_from, current)
            if g > g_score.get(current, float('inf')):
                continue

            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                if parent is None or not is_aligned(current, parent, dr, dc):
                    if dc != 0:
                        jump = horizontal_jump(current[0], current[1], dc)
                    else:
                        jump = vertical_jump(current[0], current[1], dr)
                    if jump is not None:
                        tentative_g = g + manhattan(current, jump)
                        if jump not in g_score or tentative_g < g_score[jump]:
                            g_score[jump] = tentative_g
                            heapq.heappush(open_set, (tentative_g + h(jump[0], jump[1]), tentative_g, jump, current))
                            came_from[jump] = current

        return []

    def is_aligned(current, parent, dr, dc):
        if parent is None:
            return False
        prev_dr = current[0] - parent[0]
        prev_dc = current[1] - parent[1]
        if dc != 0:
            return (prev_dr, prev_dc) != (0, dc)
        else:
            return (prev_dr, prev_dc) != (dr, 0)

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    path = jps()
    return path
