        return None

    def jump(r, c, parent_r, parent_c):
        jumps = []
        for dr, dc in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            if parent_r is not None and dr != 0 and parent_r == r + dr:
                res = jump_vertical(r, c, dr, dc, parent_r, parent_c)
            elif parent_c is not None and dc != 0 and parent_c == c + dc:
                res = jump_horizontal(r, c, dr, dc, parent_r, parent_c)
            else:
                res = jump_horizontal(r, c, dr, dc, parent_r, parent_c) or jump_vertical(r, c, dr, dc, parent_r, parent_c)
            if res:
                jumps.append(res)
        return jumps

    parent_map = {}
    open_set = [(heuristic(start[0], start[1]), 0, start, None)]  # (f, g, pos, parent)
    visited = set()
    g_scores = {start: 0}

    while open_set:
        f_score, g, pos, parent = heapq.heappop(open_set)
        r, c = pos

        if pos == goal:
            return get_path(parent_map, start, goal)
        if pos in visited:
            continue
        visited.add(pos)
        for next_r, next_c in jump(r, c, parent[0] if parent else None, parent[1] if parent else None):
            ng = g + 1
            if (next_r, next_c) in g_scores and g_scores[(next_r, next_c)] <= ng:
                continue
            g_scores[(next_r, next_c)] = ng
            h = heuristic(next_r, next_c)
            heapq.heappush(open_set, (ng + h, ng, (next_r, next_c), pos))
            parent_map[(next_r, next_c)] = pos

    return []
