        r, c = pos
        while True:
            c += dr
            if not is_valid((r, c)):
                return None
            next_pos = (r, c)
            if next_pos == goal:
                return next_pos
            # Check if vertical neighbor is a wall one step back
            if is_valid((r - 1, c)) and not is_valid((r - 2, c)) or is_valid((r + 1, c)) and not is_valid((r + 2, c)):
                return next_pos

    def vertical_jump(pos, dc):
        r, c = pos
        while True:
            r += dc
            if not is_valid((r, c)):
                return None
            next_pos = (r, c)
            if next_pos == goal:
                return next_pos
            # Check if horizontal jump in either direction finds something
            if horizontal_jump(next_pos, -1) or horizontal_jump(next_pos, 1):
                return next_pos

    def jump(pos, direction):
        dr, dc = direction
        r, c = pos
        nr, nc = r + dr, c + dc
        if not is_valid((nr, nc)):
            return None
        if (nr, nc) == goal:
            return (nr, nc)
        if dr == 0:
            return horizontal_jump((nr, nc), dc)
        else:
            return vertical_jump((nr, nc), dr)

    open_set = []
    heapq.heappush(open_set, (manhattan(start), 0, start))
    came_from = {}
    g_score = {start: 0}
    f_score = {start: manhattan(start)}

    while open_set:
        _, g, current = heapq.heappop(open_set)
        if current == goal:
            break
        if current in came_from and g_score[current] < g:
            continue
        for direction in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            next_pos = jump(current, direction)
            if next_pos:
                new_g = g + abs(next_pos[0] - current[0]) + abs(next_pos[1] - current[1])
                if next_pos not in g_score or new_g < g_score[next_pos]:
                    g_score[next_pos] = new_g
                    f_score[next_pos] = new_g + manhattan(next_pos)
                    heapq.heappush(open_set, (f_score[next_pos], new_g, next_pos))
                    came_from[next_pos] = current

    if goal not in came_from:
        return []

    path = []
    current = goal
    while current != start:
        path.append(current)
        current = came_from[current]
    path.append(start)
    path.reverse()

