                    path.append(node)
                    node = parent.get(node, None)
                return path[::-1], cost
            if node in g and g[node] < cost:
                continue
            parent[node] = prev
            for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                nx, ny = node[0] + dx, node[1] + dy
                if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == '.':
                    new_cost = cost + 1
                    if (nx, ny) not in g or g[(nx, ny)] > new_cost:
                        g[(nx, ny)] = new_cost
                        heapq.heappush(heap, (new_cost + manhattan((nx, ny), to_pos), new_cost, (nx, ny), node))
        return None, float('inf')

    forward = []
    backward = []
    f_path = f_cost = None
    b_path = b_cost = None
    min_meeting_cost = float('inf')
