        row, col = p
        drow, dcol = dir
        new_col = col + dcol
        if 0 <= new_col < cols and grid[row][new_col] == '.':
            if (row, new_col) == goal:
                return (row, new_col)
            next_pos = (row, new_col)
            if (0 <= (new_col + dcol) < cols and grid[row][new_col + dcol] == '#') or (
                    0 <= row - 1 < rows and grid[row - 1][new_col] == '.' or
                    0 <= row + 1 < rows and grid[row + 1][new_col] == '.'):
                return next_pos
            return jump_horizontal(next_pos, dir, goal)
        return None

    def jump_vertical(p, dir, goal):
        row, col = p
        drow, dcol = dir
        new_row = row + drow
        if 0 <= new_row < rows and grid[new_row][col] == '.':
            if (new_row, col) == goal:
                return (new_row, col)
            next_pos = (new_row, col)

            for d in [(-1, 0), (0, -1), (0, 1), (1, 0)]:
                if abs(d[0]) + abs(d[1]) == 1:
                    result = jump(p, d, goal)
                    if result is not None:
                        return next_pos

            if 0 <= new_row + drow < rows and grid[new_row + drow][col] == '#':
                return next_pos
            return jump_vertical(next_pos, dir, goal)
        return None

    def jump(p, dir, goal):
        if dir[0] != 0 and dir[1] != 0:
            return None
        if dir[0] == 1 or dir[0] == -1:
            return jump_vertical(p, dir, goal)
        else:
            return jump_horizontal(p, dir, goal)

    def expand_point(p, dr):
        return jump(p, dr, goal)

    def search():
        visited = set()
        heap = []
        heapq.heappush(heap, (manhattan(start, goal), 0, start, None))

        g = {start: 0}
        parent = {}

        while heap:
            f, c, current, prev = heapq.heappop(heap)

            if current == goal:
                path = []
                while current:
                    path.append(current)
                    current = parent.get(current)
                return path[::-1]

            if current in visited:
                continue
            visited.add(current)

            parent[current] = prev

            for dr in dirs:
                nxt = expand_point(current, dr)
                if nxt and is_valid(nxt) and nxt not in visited:
                    new_c = c + manhattan(current, nxt)
                    if nxt not in g or new_c < g[nxt]:
                        g[nxt] = new_c
                        heapq.heappush(heap, (new_c + manhattan(nxt, goal), new_c, nxt, current))

        return None

    path = search()
    if not path or path[0] != start or path[-1] != goal:
        return []

    full_path = [path[0]]
    for i in range(1, len(path)):
        x1, y1 = path[i - 1]
        x2, y2 = path[i]
        if x1 == x2:
            step = 1 if y2 > y1 else -1
            for y in range(y1 + step, y2, step):
                full_path.append((x1, y))
        else:
            step = 1 if x2 > x1 else -1
            for x in range(x1 + step, x2, step):
                full_path.append((x, y1))
        full_path.append((x2, y2))

    return full_path
