        if cell == goal:
            break
        r, c = cell
        for dr, dc in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            jump_point = jump(r, c, dr, dc)
            if jump_point and not jump_point is None:
                new_r, new_c = jump_point
                if is_wall((new_r, new_c)):
                    continue
                g_new = g_scores[cell] + manhattan((new_r, new_c), cell)
                if jump_point not in g_scores or g_new < g_scores[jump_point]:
                    parent[jump_point] = cell
                    g_scores[jump_point] = g_new
                    f_scores[jump_point] = g_new + manhattan(jump_point, goal)
                    heapq.heappush(hq, (f_scores[jump_point], g_new, jump_point))

    if goal not in parent:
        return []

    # Reconstruct the path
