            if curr in other_g:
                return join_paths(curr, parents, other_g, goal_point)
            if curr in g:
                continue
            g[curr] = path_cost
            r, c = curr
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                neighbor = (nr, nc)
                if is_free(grid, neighbor) and neighbor not in g:
                    new_cost = path_cost + 1
                    h = manhattan(neighbor, (goal_point,))
                    heapq.heappush(front_heap, (new_cost + h, neighbor, new_cost))
                    if neighbor not in parents:
                        parents[neighbor] = curr
        return []

    def join_paths(meet, parents, other_g, goal_point):
        path = []
        curr = meet
        while curr != start:
            path.append(curr)
            curr = parents[curr]
        path.append(start)
        curr = meet
        target = goal_point
        while curr != target:
            for key, val in other_g.items():
                if val == g[curr]:
                    curr = key
                    break
            path.append(curr)
        path.reverse()
        return path

    forward_heap = []
    backward_heap = []
    forward_g = {start: 0}
    backward_g = {goal: 0}
    forward_parents = {}
    backward_parents = {}

    heapq.heappush(forward_heap, (0 + manhattan(start, goal), start, 0))
    heapq.heappush(backward_heap, (0 + manhattan(goal, start), goal, 0))

    while forward_heap and backward_heap:
        f1, _, _ = forward_heap[0]
        f2, _, _ = backward_heap[0]
        if f1 + f2 >= forward_g.get(start, float('inf')) + backward_g.get(goal, float('inf')):
            return []

        for curr_heap, curr_g, curr_parents, other_g, goal_point in [
            (forward_heap, forward_g, forward_parents, backward_g, goal),
            (backward_heap, backward_g, backward_parents, forward_g, start)
        ]:
            if not curr_heap:
                return []
            path = search(curr_heap, start, goal_point, curr_g, curr_parents, other_g)
            if path:
                return path

    return []
