        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols and grid[goal[0]][goal[1]] == '.'):
        return []

    def in_bounds(r, c):
        return 0 <= r < rows and 0 <= c < cols

    def is_wall(r, c):
        return not in_bounds(r, c) or grid[r][c] == '#'

    def heur(r, c):
        return abs(r - goal[0]) + abs(c - goal[1])

    dirs = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # Right, Down, Left, Up

    def jump_horizontal(r, c, dr, dc):
        if is_wall(r, c):
            return None
        next_r = r
        next_c = c
        while True:
            next_r += dr
            next_c += dc
            if is_wall(next_r, next_c):
                return None
            if (next_r, next_c) == goal:
                return (next_r, next_c)
            if r == next_r:
                if not is_wall(next_r + 1, next_c) and is_wall(next_r + 1, next_c - 1):
                    return (next_r, next_c)
                if not is_wall(next_r - 1, next_c) and is_wall(next_r - 1, next_c - 1):
                    return (next_r, next_c)
            else:
                if not is_wall(next_r, next_c + 1) and is_wall(next_r - 1, next_c + 1):
                    return (next_r, next_c)
                if not is_wall(next_r, next_c - 1) and is_wall(next_r - 1, next_c - 1):
                    return (next_r, next_c)

    def jump_vertical(r, c, dr, dc):
        if is_wall(r, c):
            return None
        next_r = r
        next_c = c
        while True:
            next_r += dr
            next_c += dc
            if is_wall(next_r, next_c):
                return None
            if (next_r, next_c) == goal:
                return (next_r, next_c)
            res1 = jump_horizontal(next_r, next_c, 1, 0)
            res2 = jump_horizontal(next_r, next_c, -1, 0)
            res3 = jump_horizontal(next_r, next_c, 0, 1)
            res4 = jump_horizontal(next_r, next_c, 0, -1)
            if res1 or res2 or res3 or res4:
                return (next_r, next_c)

    def jump(r, c, dr, dc):
        if (r + dr, c + dc) == goal:
            return (r + dr, c + dc)
        if dr != 0:
            return jump_vertical(r, c, dr, dc)
        else:
            return jump_horizontal(r, c, dr, dc)

    def manhattan(r, c):
        return abs(r - goal[0]) + abs(c - goal[1])

    parent = {}
    cost = {}
    open_set = []

    heapq.heappush(open_set, (manhattan(start[0], start[1]), 0, start[0], start[1]))
    parent[(start[0], start[1])] = None
    cost[(start[0], start[1])] = 0

    while open_set:
        _, g, r, c = heapq.heappop(open_set)
        if (r, c) == goal:
            break
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if not in_bounds(nr, nc) or is_wall(nr, nc):
                continue
            jump_cell = jump(r, c, dr, dc)
            if jump_cell is not None:
                j_r, j_c = jump_cell
                if (j_r, j_c) not in cost or g + 1 < cost[(j_r, j_c)]:
                    cost[(j_r, j_c)] = g + 1
                    parent[(j_r, j_c)] = (r, c)
                    heapq.heappush(open_set, (g + 1 + manhattan(j_r, j_c), g + 1, j_r, j_c))

    if goal not in parent:
        return []

    path = []
    curr = goal
    while curr is not None:
        path.append(curr)
        curr = parent[curr]
    path.reverse()

    final_path = []
    for i in range(len(path) - 1):
        r1, c1 = path[i]
        r2, c2 = path[i + 1]
        dr = r2 - r1
        dc = c2 - c1
        if dr != 0:
            step = 1 if dr > 0 else -1
            for r in range(r1, r2, step):
                final_path.append((r, c1))
            final_path.append((r2, c1))
        elif dc != 0:
            step = 1 if dc > 0 else -1
            for c in range(c1, c2, step):
                final_path.append((r1, c))
            final_path.append((r1, c2))
    final_path.append((r2, c2))

    return final_path
