            return None
        f, current = heapq.heappop(frontier)
        if current in other_g:
            return current
        row, col = current
        for dr, dc in directions:
            neighbor = (row + dr, col + dc)
            if is_free(grid, neighbor) and g.get(neighbor, float('inf')) > g[current] + 1:
                if neighbor not in g or g[neighbor] > g[current] + 1:
                    g[neighbor] = g[current] + 1
                    parents[neighbor] = current
                    f_neighbor = g[neighbor] + manhattan(neighbor, target)
                    heapq.heappush(frontier, (f_neighbor, neighbor))
        return None

    forward_heap = [(manhattan(start, goal), start)]
    forward_g = {start: 0}
    forward_parents = {}

    backward_heap = [(manhattan(goal, start), goal)]
    backward_g = {goal: 0}
    backward_parents = {}

    meeting_point = None
    while forward_heap and backward_heap:
        meeting_point = search_step(forward_heap, forward_g, forward_parents, start, backward_g, goal)
        if meeting_point is not None:
            break
        meeting_point = search_step(backward_heap, backward_g, backward_parents, goal, forward_g, start)
        if meeting_point is not None:
            break
    if meeting_point is None:
        return []

    path = reconstruct_path(forward_parents, start, meeting_point)
    path += reconstruct_path(backward_parents, goal, meeting_point, reverse=True)
    return path

def reconstruct_path(parents, start, end, reverse=False):
    path = []
    current = end
