                    next_g = g + 1
                    heapq.heappush(frontier, (
                        next_g + manhattan(next_pos, to_pos),
                        next_g,
                        next_pos,
                        pos,
                        g
                    ))
        return visited

    best_f = float('inf')
    forward_visited = backward_visited = None

    def meet_in_middle():
        nonlocal best_f, forward_visited, backward_visited

        forward_visited = bfs(start, goal, is_reversed=False)
        if goal in forward_visited:
            return reconstruct_path(forward_visited, start, goal)
        backward_visited = bfs(goal, start, is_reversed=True)
        if start in backward_visited:
            return reconstruct_path(backward_visited, goal, start)

        while True:
            f_g = next_g = 0
            for node in forward_visited:
                f_g = max(f_g, forward_visited[node][0] + manhattan(node, goal))
            for node in backward_visited:
