                    meeting_point = node

            if best_f != float('inf'):
                forward_path = reconstruct_path(forward_visited, start, meeting_point)
                backward_path = reconstruct_path(backward_visited, goal, meeting_point)
                return forward_path + backward_path[::-1][1:]

            forward_visited = bfs(start, goal, is_reversed=False)
            if goal in forward_visited:
                return reconstruct_path(forward_visited, start, goal)
            backward_visited = bfs(goal, start, is_reversed=True)
            if start in backward_visited:
                return reconstruct_path(backward_visited, goal, start)
        return []

    def reconstruct_path(visited, start, end):
        path = []
        node = end
        while node is not None:
            path.append(node)
            _, node = visited[node]
        return path[::-1] if start == path[0] else []

