import heapq

def solve(grid, start, goal):
    def is_valid(pos):
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def heuristic_search(from_pos, to_pos, forward=True, other_g=None):
        heap = []
        g = {from_pos: 0}
        parent = {}
        heapq.heappush(heap, (manhattan(from_pos, to_pos), 0, from_pos))

        while heap:
            f, g_curr, current = heapq.heappop(heap)
            if current in g and g[current] < g_curr:
                continue
            if other_g and current in other_g:
                return g[current] + other_g[current], current, parent
            for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                nr, nc = current[0] + dr, current[1] + dc
                next_pos = (nr, nc)
                if is_valid(next_pos):
                    next_g = g_curr + 1
                    if next_pos not in g or next_g < g[next_pos]:
                        g[next_pos] = next_g
                        h = manhattan(next_pos, to_pos)
                        heapq.heappush(heap, (next_g + h, next_g, next_pos))
                        parent[next_pos] = current
        if other_g:
            return float('inf'), None, parent
        return g, parent

    if start == goal and is_valid(start):
        return [start]
    if not is_valid(start) or not is_valid(goal):
        return []

    forward_g = {start: 0}
    backward_g = {goal: 0}
    forward_parent = {}
    backward_parent = {}

    best_cost = float('inf')
    best_meet = None

    while True:
        cost_f, meet_f, forward_parent = heuristic_search(start, goal, forward=True, other_g=backward_g)
        if meet_f is not None and cost_f < best_cost:
            best_cost = cost_f
            best_meet = meet_f
        if best_cost == 0:  # path found
            break

        cost_b, meet_b, backward_parent = heuristic_search(goal, start, forward=False, other_g=forward_g)
        if meet_b is not None and cost_b < best_cost:
            best_cost = cost_b
            best_meet = meet_b
        if best_cost == 0:  # path found
            break

        if cost_f == float('inf') or cost_b == float('inf') or best_cost >= min(cost_f, cost_b):
            break

    if best_meet is None:
        return []

    # Reconstruct the path
    def build_path(meet, parent, start):
        path = []
        current = meet
        while current != start:
            path.append(current)
            current = parent[current]
        path.append(start)
        return path[::-1]

    path_start = build_path(best_meet, forward_parent, start)
    path_goal = build_path(best_meet, backward_parent, goal)

    return path_start + path_goal[1:]
