    def manhattan(r1, c1, r2, c2):
        return abs(r1 - r2) + abs(c1 - c2)

    def jump_horizontal(r, c, dr, dc):
        new_r, new_c = r + dr, c + dc
        while is_valid(new_r, new_c):
            # Check if the goal is directly reachable
            if (new_r, new_c) == goal:
                return new_r, new_c
            # Check for forced neighbors (a potential obstacle)
            if is_valid(new_r - 1, new_c) and not is_valid(new_r - 2, new_c):
                return new_r, new_c
            if is_valid(new_r + 1, new_c) and not is_valid(new_r + 2, new_c):
                return new_r, new_c
            new_r += dr
            new_c += dc
        return None

    def jump_vertical(r, c, dr, dc):
        new_r, new_c = r + dr, c + dc
        while is_valid(new_r, new_c):
            if (new_r, new_c) == goal:
                return new_r, new_c
            # Check for potential jump points in horizontal directions
            for d in [(-1, 0), (1, 0)]:
                nr, nc = new_r + d[0], new_c + d[1]
                if is_valid(nr, nc):
                    if jump_horizontal(new_r, new_c, d[0], d[1]):
                        return new_r, new_c
            new_r += dr
            new_c += dc
        return None

    visited = set()
    heap = []
    heapq.heappush(heap, (manhattan(*start, *goal), 0, start, None))
    parent_map = {}
    g_score = {start: 0}

    while heap:
        _, g, (r, c), parent = heapq.heappop(heap)
        if (r, c) == goal:
            break
        if (r, c) in visited:
            continue
        visited.add((r, c))
        parent_map[(r, c)] = parent

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if not is_valid(nr, nc):
                continue
            if (dr == 0 or dc == 0):  # Horizontal or vertical
                if dr != 0:
                    next_jump = jump_horizontal(r, c, dr, 0)
                else:
                    next_jump = jump_horizontal(r, c, 0, dc)
            else:
                continue

            if next_jump:
                r1, c1 = next_jump
                if (r1, c1) not in visited and (r1, c1) not in g_score or g + 1 < g_score[(r1, c1)]:
                    g_score[(r1, c1)] = g + 1
                    heapq.heappush(heap, (
                        g + 1 + manhattan(r1, c1, *goal), g + 1, (r1, c1), (r, c)))

    if (r, c) != goal:
        return []

    # Reconstruct path and add all intermediate steps
    path = [goal]
    current = goal
    while current != start:
        parent = parent_map.get(current)
        if parent is None:
            return []
        while parent != path[-1]:
            pr, pc = parent
            cr, cc = path[-1]
            if pr > cr:
                step = (cr + 1, cc)
            elif pr < cr:
                step = (cr - 1, cc)
            elif pc < cc:
                step = (cr, cc - 1)
            else:
                step = (cr, cc + 1)
            path.append(step)
        path.append(parent)
        current = parent

    # Remove duplicates
    path.reverse()
    final_path = [start]
    for cell in path:
        if cell not in final_path:
            final_path.append(cell)
    return final_path
