            if pos == to_pos or f > g[pos] + manhattan(pos, to_pos):
                continue
            for next_pos in get_next(pos):
                new_g = g[pos] + 1
                if next_pos not in g or new_g < g[next_pos]:
                    g[next_pos] = new_g
                    heapq.heappush(heap, (new_g + manhattan(next_pos, to_pos), next_pos))
                    parent[next_pos] = pos
        return g, parent

