        return [start]

    g1, parent1 = search(start, goal, lambda pos: get_neighbors(pos))
    g2, parent2 = search(goal, start, lambda pos: get_neighbors(pos))

    best_cost = float('inf')
    meeting_point = None
    for pos in g1:
        if pos in g2 and g1[pos] + g2[pos] < best_cost:
            best_cost = g1[pos] + g2[pos]
            meeting_point = pos

    if not meeting_point:
        return []

    path1 = []
    pos = meeting_point
    while pos in parent1:
        path1.append(pos)
        pos = parent1[pos]
    path1.reverse()

    path2 = []
    pos = meeting_point
    while pos in parent2:
        pos = parent2[pos]
        if pos != goal:
            path2.append(pos)
    path = [start] + path1 + path2 + [goal]

    for i in range(len(path)-1):
        r1, c1 = path[i]
        r2, c2 = path[i+1]
        if abs(r1 - r2) + abs(c1 - c2) != 1:
