import heapq

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])
            and 0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def jump_horizontal(r, c, dir):  # dir is +1 for right, -1 for left
        while True:
            c += dir
            if not (0 <= c < len(grid[0])):
                return None
            if (r, c) == goal:
                return (r, c)
            if grid[r][c] == '#':
                return None
            # Check for forced vertical
            if r > 0 and grid[r - 1][c] == '.' and (r - 2 < 0 or grid[r - 2][c] == '#'):
                return (r, c)
            if r < len(grid) - 1 and grid[r + 1][c] == '.' and (r + 2 >= len(grid) or grid[r + 2][c] == '#'):
                return (r, c)
            # Check if jump vertical from this position
            left = jump_vertical(r, c, -1)
            right = jump_vertical(r, c, +1)
            if left or right:
                return (r, c)

    def jump_vertical(r, c, dir):  # dir is +1 for down, -1 for up
        while True:
            r += dir
            if not (0 <= r < len(grid)):
                return None
            if (r, c) == goal:
                return (r, c)
            if grid[r][c] == '#':
                return None
            # Check for a horizontal jump to the left or right
            left = jump_horizontal(r, c, -1)
            right = jump_horizontal(r, c, +1)
            if left or right:
                return (r, c)

    open_list = [(manhattan(start, goal), 0, start, None)]
    visited = set()
    parent = {}

    while open_list:
        _, g, cell, prev = heapq.heappop(open_list)
        if cell in visited:
            continue
        if cell == goal:
            break
        visited.add(cell)
        parent[cell] = prev

        for dr, dc, jump in [(-1, 0, jump_vertical), (1, 0, jump_vertical),
                             (0, -1, jump_horizontal), (0, 1, jump_horizontal)]:
            if jump == jump_horizontal:
                next_cell = jump(cell[0], cell[1], dc)
            else:
                next_cell = jump(cell[0], cell[1], dr)
            if next_cell and grid[next_cell[0]][next_cell[1]] != '#' and next_cell not in visited:
                new_g = g + manhattan(cell, next_cell)
                f = new_g + manhattan(next_cell, goal)
                heapq.heappush(open_list, (f, new_g, next_cell, cell))

    if goal not in parent:
        return []

    # Reconstruct path
    path = []
    cur = goal
    while cur is not None:
        path.append(cur)
        cur = parent.get(cur)
    path.reverse()

    # Expand path into a sequence of consecutive neighbors
    result = [path[0]]
    for i in range(1, len(path)):
        r, c = path[i-1]
        goal_r, goal_c = path[i]
        while (r, c) != (goal_r, goal_c):
            if r < goal_r:
                r += 1
            elif r > goal_r:
                r -= 1
            elif c < goal_c:
                c += 1
            else:
                c -= 1
            result.append((r, c))
    return result
