import heapq

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    if start == goal:
        return [start] if grid[start[0]][start[1]] == '.' else []

    def get_neighbors(pos):
        r, c = pos
        directions = [(-1,0), (1,0), (0,-1), (0,1)]
        neighbors = []
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if (0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.'):
                neighbors.append((nr, nc))
        return neighbors

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def heuristic_search(heap, start, goal, g, parent, getneighbor, heap_other, g_other):
        while heap:
            f, cost, pos = heapq.heappop(heap)
            if pos in g:
                continue
            g[pos] = cost
            if pos in g_other:
                return pos
            for neighbor in getneighbor(pos):
                if neighbor not in g:
                    new_cost = cost + 1
                    f_val = new_cost + manhattan(neighbor, goal)
                    heapq.heappush(heap, (f_val, new_cost, neighbor))
                    parent[neighbor] = pos
            # Termination condition
            if heap and heap_other:
                min_f1 = heap[0][0] if heap else float('inf')
                min_f2 = heap_other[0][0] if heap_other else float('inf')
                best_meet_cost = float('inf')
                if g and g_other:
                    best_meet_cost = min(g[pos] + g_other[pos] for pos in g if pos in g_other)
                if min_f1 + min_f2 > best_meet_cost:
                    return None
        return None

    forward_g = {start: 0}
    backward_g = {goal: 0}

    forward_parent = {}
    backward_parent = {}

    forward_heap = [(manhattan(start, goal), 0, start)] if grid[start[0]][start[1]] == '.' and grid[goal[0]][goal[1]] == '.' else []
    backward_heap = [(manhattan(goal, start), 0, goal)] if forward_heap else []

    heapq.heapify(forward_heap)
    heapq.heapify(backward_heap)

    meeting_point = None

    while forward_heap and backward_heap:
        meeting_point = heuristic_search(forward_heap, start, goal, forward_g, forward_parent, get_neighbors, backward_heap, backward_g)
        if meeting_point is not None:
            break
        meeting_point = heuristic_search(backward_heap, goal, start, backward_g, backward_parent, get_neighbors, forward_heap, forward_g)
        if meeting_point is not None:
            break

    if meeting_point is None:
        return []

    def reconstruct_path(meet):
        path1 = []
        path2 = []
        curr = meet
        while curr in backward_parent:
            path1.append(curr)
            curr = backward_parent[curr]
        if not path1:
            return []
        if path1[-1] != start:
            return []

        path1.reverse()
        curr = meet
        while curr in forward_parent:
            path2.append(curr)
            curr = forward_parent[curr]
        if not path2:
            return []
        if path2[-1] != meet:
            return []

        path1.append(meet)
        path2.reverse()
        full_path = path1 + path2
        return [start] + full_path if full_path[0] != start else full_path

    path = reconstruct_path(meeting_point)
    if not path or path[0] != start or path[-1] != goal:
        return []
    return path
