    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols and grid[goal[0]][goal[1]] == '.'):
        return []

    def neighbors(r, c):
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                yield nr, nc

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def search(from_node, other, is_forward, g, parent, heap):
        while heap:
            f_total, g_total, node = heapq.heappop(heap)
            if node in other['g']:
                return node, g_total + other['g'][node]
            if g.get(node, float('inf')) < g_total:
                continue
            for next_node in neighbors(*node):
                new_cost = g[node] + 1
                if new_cost < g.get(next_node, float('inf')):
                    g[next_node] = new_cost
                    f_next = new_cost + manhattan(next_node, other['start'])
                    heapq.heappush(heap, (f_next, new_cost, next_node))
                    parent[next_node] = node
        return None, float('inf')

    forward_g = {start: 0}
    forward_parent = {}
    forward_heap = [(manhattan(start, goal), 0, start)]

    backward_g = {goal: 0}
    backward_parent = {}
    backward_heap = [(manhattan(goal, start), 0, goal)]

    forward = {'start': start, 'goal': goal, 'g': forward_g, 'parent': forward_parent, 'heap': forward_heap}
    backward = {'start': goal, 'goal': start, 'g': backward_g, 'parent': backward_parent, 'heap': backward_heap}
    meets = []

    while forward['heap'] and backward['heap']:
        meet, total_cost = search(forward['start'], backward, True, forward['g'], forward['parent'], forward['heap'])
        if meet:
            meets.append((meet, total_cost))
        else:
            break

        meet, total_cost = search(backward['start'], forward, False, backward['g'], backward['parent'], backward['heap'])
        if meet:
            meets.append((meet, total_cost))
        else:
            break

    if not meets:
        return []

    meet_point, _ = min(meets, key=lambda x: x[1])

    path = [meet_point]
    node = meet_point
    while node != forward['goal']:
        node = forward['parent'][node]
        path.append(node)
    path.reverse()

    node = meet_point
    while node != backward['goal']:
        node = backward['parent'][node]
        path.append(node)

    return path
