import heapq

def solve(grid, start, goal):
    if start == goal:
        if grid[start[0]][start[1]] == '.':
            return [start]
        else:
            return []

    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])) or \
       not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def bfs(prep, from_pos, to_pos, g_dict, parent, get_heur):
        heap = []
        heapq.heappush(heap, (get_heur(from_pos, to_pos), from_pos))
        g_dict[from_pos] = 0

        while heap:
            _, current = heapq.heappop(heap)
            if current in prep:
                return current
            if current in parent:
                continue
            parent[current] = None
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = current[0] + dx, current[1] + dy
                if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] == '.':
                    neighbor = (nx, ny)
                    new_g = g_dict[current] + 1
                    if neighbor not in g_dict or new_g < g_dict[neighbor]:
                        g_dict[neighbor] = new_g
                        f = new_g + get_heur(neighbor, to_pos)
                        heapq.heappush(heap, (f, neighbor))
                        parent[neighbor] = current
        return None

    g_forward = {start: 0}
    parent_forward = {}
    g_backward = {goal: 0}
    parent_backward = {}

    meet = None

    while True:
        # Forward step
        meet = bfs(g_forward, start, goal, g_forward, parent_forward, manhattan)
        if meet:
            break

        # Backward step
        meet = bfs(g_backward, goal, start, g_backward, parent_backward, manhattan)
        if meet:
            break

        # Early termination if both heaps are empty and no meeting point is found
        if not g_forward or not g_backward:
            return []

    if not meet:
        return []

    # Reconstruct path
    path = []
    current = meet
    while current != start:
        path.append(current)
        current = parent_forward[current]
    path.append(start)
    path.reverse()

    current = meet
    while current != goal:
        current = parent_backward[current]
        path.append(current)

    return path
