import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start] if is_free(grid, *start) else []

    if not is_free(grid, *start) or not is_free(grid, *goal):
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1,0), (1,0), (0,-1), (0,1)]  # up, down, left, right
    parent = {}
    g_scores = {}
    f_heap = []

    def is_free(grid, r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def is_wall(r, c):
        return not (0 <= r < len(grid) and 0 <= c < len(grid[0])) or grid[r][c] == '#'

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def jump_horizontal(r, c, dr, dc, parent_point):
        new_r, new_c = r + dr, c + dc
        if not is_free(grid, new_r, new_c):
            return None
        if (new_r, new_c) == goal:
            return (new_r, new_c)

        # Check for forced vertical
        if is_wall(new_r - dr, new_c) or is_wall(new_r + dr, new_c):
            return (new_r, new_c)

        if (new_r, new_c) in g_scores:
            return None

        g_scores[(new_r, new_c)] = g_scores.get(parent_point, 0) + 1
        parent[(new_r, new_c)] = (r, c)

        # Continue in the same direction
        return jump_horizontal(new_r, new_c, dr, dc, (new_r, new_c))

    def jump_vertical(r, c, dr, dc, parent_point):
        new_r, new_c = r + dr, c + dc
        if not is_free(grid, new_r, new_c):
            return None
        if (new_r, new_c) == goal:
            return (new_r, new_c)

        # Check for forced horizontal through jump_horizontal
        if jump_horizontal(new_r, new_c, 0, 1, None) or jump_horizontal(new_r, new_c, 0, -1, None):
            return (new_r, new_c)

        if (new_r, new_c) in g_scores:
            return None

        g_scores[(new_r, new_c)] = g_scores.get(parent_point, 0) + 1
        parent[(new_r, new_c)] = (r, c)

        # Continue in the same direction
        return jump_vertical(new_r, new_c, dr, dc, (new_r, new_c))

    def get_jump_points(r, c):
        points = []
        for dr, dc in directions:
            new_r, new_c = r + dr, c + dc
            if is_free(grid, new_r, new_c):
                if dr == 0:  # horizontal
                    jump_result = jump_horizontal(r, c, dr, dc, (r, c))
                else:  # vertical
                    jump_result = jump_vertical(r, c, dr, dc, (r, c))
                if jump_result:
                    points.append(jump_result)
        return points

    # Initialize
    g_scores[start] = 0
    parent[start] = None
    heapq.heappush(f_heap, (manhattan(start, goal), 0, start))

    while f_heap:
        f, g, (r, c) = heapq.heappop(f_heap)

        if (r, c) == goal:
            # Reconstruct path
