        return []

    def heuristic(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def get_neighbors(pos):
        r, c = pos
        neighbors = []
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                neighbors.append((nr, nc))
        return neighbors

    # Forward search (from start)
    forward_heap = [(heuristic(start, goal), 0, start)]
    forward_g = {start: 0}
    forward_parent = {}

    # Backward search (from goal)
    backward_heap = [(heuristic(goal, start), 0, goal)]
    backward_g = {goal: 0}
    backward_parent = {}

    while forward_heap and backward_heap:
        # Forward step
        f, g, node = heapq.heappop(forward_heap)
        if node in backward_g:
            return _join_paths(forward_parent, backward_parent, node, start, goal)
        if f > backward_g.get(node, float('inf')):
            continue
        for neighbor in get_neighbors(node):
            new_g = g + 1
            if neighbor not in forward_g or new_g < forward_g[neighbor]:
                forward_g[neighbor] = new_g
                heapq.heappush(forward_heap, (new_g + heuristic(neighbor, goal), new_g, neighbor))
                forward_parent[neighbor] = node

        # Backward step
        f, g, node = heapq.heappop(backward_heap)
        if node in forward_g:
            return _join_paths(forward_parent, backward_parent, node, start, goal)
        if f > forward_g.get(node, float('inf')):
            continue
        for neighbor in get_neighbors(node):
            new_g = g + 1
            if neighbor not in backward_g or new_g < backward_g[neighbor]:
                backward_g[neighbor] = new_g
                heapq.heappush(backward_heap, (new_g + heuristic(neighbor, start), new_g, neighbor))
                backward_parent[neighbor] = node

    return []

def _join_paths(forward_parent, backward_parent, meeting_point, start, goal):
    # Build forward path from start to meeting point
    path1 = [meeting_point]
    while path1[-1] != start:
        path1.append(forward_parent[path1[-1]])
    path1.reverse()

    # Build backward path from meeting point to goal
    path2 = [meeting_point]
    while path2[-1] != goal:
        path2.append(backward_parent[path2[-1]])

    return path1 + path2[1:]
