import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start] if is_valid(grid, *start) else []

    if not is_valid(grid, *start) or not is_valid(grid, *goal):
        return []

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def is_valid(grid, r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def expand(frontier, is_forward, g_dict, parent_dict, other_g, start, goal):
        f, (r, c), g = heapq.heappop(frontier)
        if (r, c) in g_dict and g_dict[(r, c)] < g:
            return None, f

        g_dict[(r, c)] = g
        parent_dict[(r, c)] = None if (r, c) == (start if is_forward else goal) else parent_dict.get((r, c))

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_valid(grid, nr, nc) and (nr, nc) not in g_dict:
                new_g = g + 1
                h = manhattan((nr, nc), goal if is_forward else start)
                key = new_g + h
                heapq.heappush(frontier, (key, (nr, nc), new_g))
                if (nr, nc) not in g_dict or new_g < g_dict[(nr, nc)]:
                    g_dict[(nr, nc)] = new_g
                    parent_dict[(nr, nc)] = (r, c)

        if (r, c) in other_g:
            return (r, c), f

        return None, f

    def reconstruct_path(parent1, parent2, meet):
        path1, curr = [], meet
        while curr in parent1 and parent1[curr] is not None:
            path1.append(curr)
            curr = parent1[curr]
        path1.reverse()

        path2, curr = [], meet
        while curr in parent2 and parent2[curr] is not None:
            curr = parent2[curr]
            path2.append(curr)

        return path1 + path2

    g_forward, g_backward = {start: 0}, {goal: 0}
    parent_forward, parent_backward = {start: None}, {goal: None}
    frontier_forward = [(manhattan(start, goal), start, 0)]
    frontier_backward = [(manhattan(goal, start), goal, 0)]

    meet = None
    turn = True  # True for forward, False for backward

    while frontier_forward or frontier_backward:
        if turn and frontier_forward:
            cand, _ = expand(frontier_forward, True, g_forward, parent_forward, g_backward, start, goal)
            if cand:
                meet = cand
                break
        elif not turn and frontier_backward:
            cand, _ = expand(frontier_backward, False, g_backward, parent_backward, g_forward, start, goal)
            if cand:
                meet = cand
                break
        turn = not turn

    if not meet:
        return []

    full_path = reconstruct_path(parent_forward, parent_backward, meet)

    if full_path[0] == start and full_path[-1] == goal:
        return full_path

    return []
