from collections import deque

def solve(grid, start, goal):
    def is_free(cell):
        r, c = cell
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.' 

    def get_neighbors(cell):
        r, c = cell
        return [(nr, nc) for nr, nc in [(r-1,c), (r+1,c), (r,c-1), (r,c+1)] if is_free((nr, nc))]

    def bfs_step(queue, parents, other_parents):
        level_nodes = deque()
        found = False
        while queue:
            current = queue.popleft()
            for next_cell in get_neighbors(current):
                if next_cell not in parents:
                    parents[next_cell] = current
                    if next_cell in other_parents:
                        found = next_cell
                    else:
                        level_nodes.append(next_cell)
        return found, level_nodes

    if start == goal and is_free(start):
        return [start]
    if not is_free(start) or not is_free(goal):
        return []

    forward_queue = deque([start])
    backward_queue = deque([goal])
    forward_parents = {start: None}
    backward_parents = {goal: None}

    while forward_queue and backward_queue:
        # BFS from start
        meeting, _ = bfs_step(forward_queue, forward_parents, backward_parents)
        if meeting:
            return reconstruct_path(forward_parents, backward_parents, start, goal, meeting)
        # BFS from goal
        meeting, _ = bfs_step(backward_queue, backward_parents, forward_parents)
        if meeting:
            return reconstruct_path(forward_parents, backward_parents, start, goal, meeting)

    return []

def reconstruct_path(forward_parents, backward_parents, start, goal, meeting):
    def path_from_parents(parents, start, end):
        path = []
        current = end
        while current is not None:
            path.append(current)
            current = parents[current]
        return path[::-1]

    forward_path = path_from_parents(forward_parents, start, meeting)
    backward_path = path_from_parents(backward_parents, goal, meeting)
    return forward_path + backward_path[1:]
