                    neighbor not in visited
                ):
                    if neighbor in other_visited:
                        # Found meeting point
                        return neighbor
                    visited.add(neighbor)
                    parents[neighbor] = current
                    queue.append(neighbor)
        return None

    # Initialize BFS from start and goal
    start_queue = deque([start])
    goal_queue = deque([goal])
    start_visited = {start}
    goal_visited = {goal}
    start_parents = {start: None}
    goal_parents = {goal: None}

    while start_queue and goal_queue:
        # Alternate BFS from start
        meeting_point = bfs_step(start_queue, start_visited, start_parents, goal_visited)
        if meeting_point:
            return build_path(meeting_point, start_parents, goal_parents)
        # Alternate BFS from goal
        meeting_point = bfs_step(goal_queue, goal_visited, goal_parents, start_visited)
        if meeting_point:
            return build_path(meeting_point, start_parents, goal_parents)

