            pos = forward_queue.popleft()
            for neighbor in get_neighbors(pos):
                if neighbor not in forward:
                    forward[neighbor] = pos
                    forward_queue.append(neighbor)
                    expanded.add(neighbor)
                    if neighbor in backward:
                        return _build_path(forward, backward, neighbor)
        if expanded.intersection(backward):
            return _build_path(forward, backward, next(iter(expanded.intersection(backward))))

        # Backward expansion
        expanded = set()
        for _ in range(len(backward_queue)):
            pos = backward_queue.popleft()
            for neighbor in get_neighbors(pos):
                if neighbor not in backward:
                    backward[neighbor] = pos
                    backward_queue.append(neighbor)
                    expanded.add(neighbor)
                    if neighbor in forward:
                        return _build_path(forward, backward, neighbor)
        if expanded.intersection(forward):
            return _build_path(forward, backward, next(iter(expanded.intersection(forward))))

