                    forward_parent[(ny, nx)] = current
                    forward_queue.append((ny, nx))
                    if (ny, nx) in backward_visited:
                        expanded = True
                        meeting = (ny, nx)
        if expanded:
            break
        # Expand backward
        expanded = False
        level_size = len(backward_queue)
        for _ in range(level_size):
            current = backward_queue.popleft()
            for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                ny, nx = current[0] + dy, current[1] + dx
                if 0 <= ny < rows and 0 <= nx < cols and grid[ny][nx] == '.' and (ny, nx) not in backward_visited:
                    backward_visited.add((ny, nx))
                    backward_parent[(ny, nx)] = current
                    backward_queue.append((ny, nx))
                    if (ny, nx) in forward_visited:
                        expanded = True
                        meeting = (ny, nx)
        if expanded:
            break

    if meeting:
        path = []
        cur = meeting
        while cur is not None:
            path.append(cur)
            cur = forward_parent.get(cur)
        path.reverse()
        cur = backward_parent.get(meeting)
        while cur is not None:
            path.append(cur)
            cur = backward_parent.get(cur)
        if path[0] == start:
            return path
        else:
            return path[::-1]
    return []
