from collections import deque

def solve(grid, start, goal):
    if start == goal:
        return [start]

    if (
        not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])) or
        not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])) or
        grid[start[0]][start[1]] == '#' or
        grid[goal[0]][goal[1]] == '#'
    ):
        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(queue, parent, parent_side):
        if not queue:
            return None
        level = deque()
        for pos in queue:
            for dr, dc in directions:
                nr, nc = pos[0] + dr, pos[1] + dc
                if (
                    0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and
                    grid[nr][nc] != '#' and (nr, nc) not in parent
                ):
                    parent[(nr, nc)] = pos
                    if (nr, nc) in parent_side:
                        return (nr, nc)
                    level.append((nr, nc))
        return bfs(level, parent, parent_side)

    start_queue = deque([start])
    goal_queue = deque([goal])
    start_parent = {start: None}
    goal_parent = {goal: None}

    while start_queue or goal_queue:
        meeting = bfs(start_queue, start_parent, goal_parent)
        if meeting:
            return _construct_path(start_parent, goal_parent, meeting)
        start_queue = bfs(start_queue, start_parent, goal_parent)
        if not start_queue:
            break
        meeting = bfs(goal_queue, goal_parent, start_parent)
        if meeting:
            return _construct_path(start_parent, goal_parent, meeting)
        goal_queue = bfs(goal_queue, goal_parent, start_parent)
        if not goal_queue:
            break

    return []

def _construct_path(start_parent, goal_parent, meeting):
    path = []
    node = meeting
    while node is not None:
        path.append(node)
        node = start_parent[node]
    path.reverse()
    node = goal_parent[meeting]
    while node != meeting:
        path.append(node)
        node = goal_parent[node]
    return path
