import heapq

def solve(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def is_wall(r, c):
        return not (0 <= r < rows and 0 <= c < cols) or grid[r][c] == '#'

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def horizontal_jump(r, c, d):
        orig = (r, c)
        while True:
            c += d
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            # Check for forced vertical neighbor
            if is_wall(r - 1, c) or is_wall(r + 1, c):
                return (r, c)
            if (r, c) == orig:
                return None

    def vertical_jump(r, c, d):
        orig = (r, c)
        while True:
            r += d
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            # Check for horizontal jump in either direction
            for dj in [-1, 1]:
                if horizontal_jump(r, c, dj):
                    return (r, c)
            if (r, c) == orig:
                return None

    def get_jump_points(r, c):
        neighbors = []
        # Up (vertical jump)
        jump = vertical_jump(r, c, -1)
        if jump:
            neighbors.append(jump)
        # Down (vertical jump)
        jump = vertical_jump(r, c, 1)
        if jump:
            neighbors.append(jump)
        # Left (horizontal jump)
        jump = horizontal_jump(r, c, -1)
        if jump:
            neighbors.append(jump)
        # Right (horizontal jump)
        jump = horizontal_jump(r, c, 1)
        if jump:
            neighbors.append(jump)
        return neighbors

    if not is_valid(*start) or not is_valid(*goal):
        return []

    if start == goal:
        return [start]

    open_set = []
    heapq.heappush(open_set, (manhattan(start, goal), 0, start, None))
    came_from = {}
    g_scores = {start: 0}

    while open_set:
        f, g, current, parent = heapq.heappop(open_set)

        if current == goal:
            # Reconstruct path
            path = []
            while current:
                path.append(current)
                current = came_from.get(current)
            return path[::-1]

        if current in came_from:
            continue

        came_from[current] = parent

        jump_points = get_jump_points(*current)
        for np in jump_points:
            new_g = g + manhattan(current, np)
            if np not in g_scores or new_g < g_scores[np]:
                g_scores[np] = new_g
                heapq.heappush(open_set, (new_g + manhattan(np, goal), new_g, np, current))

    return []
