import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start] if grid[start[0]][start[1]] == '.' else []

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    rows, cols = len(grid), len(grid[0])

    def valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def jump Horizontal(p, d):
        r, c = p
        dr, dc = d
        while True:
            r += dr
            c += dc
            if not valid(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            # Check for forced vertical neighbor
            if not valid(r - 1, c) and valid(r + 1, c):  # wall below and free above
                return (r, c)
            if not valid(r + 1, c) and valid(r - 1, c):  # wall above and free below
                return (r, c)

    def jump Vertical(p, d):
        r, c = p
        dr, dc = d
        while True:
            r += dr
            c += dc
            if not valid(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            # Check for forced horizontal neighbor on either side
            if jump Horizontal((r, c), (0, -1)) or jump Horizontal((r, c), (0, 1)):
                return (r, c)

    def neighbors(p):
        dir_map = {
            (0, 1): (0, 1),  # Right
            (0, -1): (0, -1),  # Left
            (1, 0): (1, 0),  # Down
            (-1, 0): (-1, 0),  # Up
        }
        jump_funcs = {
            (0, 1): jump Horizontal,
            (0, -1): jump Horizontal,
            (1, 0): jump Vertical,
            (-1, 0): jump Vertical,
        }
        for d, jump_func in jump_funcs.items():
            dr, dc = d
            next_p = (p[0] + dr, p[1] + dc)
            if not valid(next_p[0], next_p[1]):
                continue
            j = jump_func(p, d)
            if j:
                yield j

    came_from = {}
    g = {start: 0}
    f = {start: manhattan(start, goal)}
    heap = [(f[start], g[start], start, None)]

    while heap:
        _, current_g, current, parent = heapq.heappop(heap)
        if current not in g or g[current] < current_g:
            continue
        came_from[current] = parent
        if current == goal:
            break
        for next_p in neighbors(current):
            if next_p not in g or g[current] + 1 < g.get(next_p, float('inf')):
                g[next_p] = g[current] + 1
                f[next_p] = g[next_p] + manhattan(next_p, goal)
                heapq.heappush(heap, (f[next_p], g[next_p], next_p, current))

    if current != goal:
        return []

    # Reconstruct path from came_from
    path = []
    p = goal
    while p:
        path.append(p)
        p = came_from.get(p)
    path.reverse()

    return path
