def solve(grid, start, goal):
    if start == goal:
        return [start]
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and grid[start[0]][start[1]] == '.'):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0]) and grid[goal[0]][goal[1]] == '.'):
        return []

    rows = len(grid)
    cols = len(grid[0])

    def manhattan(pos):
        return abs(pos[0] - goal[0]) + abs(pos[1] - goal[1])

    def valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def jump_horizontal(pos, dir):
        r, c = pos
        dr = 0
        dc = 1 if dir else -1
        while 0 <= c + dc < cols and grid[r][c + dc] != '#':
            c += dc
            new_pos = (r, c)
            if new_pos == goal:
                return new_pos
            if dir == 0 and (not valid(r, c - 1) or valid(r - 1, c) or valid(r + 1, c)):
                return new_pos
            if dir == 1 and (not valid(r, c + 1) or valid(r - 1, c) or valid(r + 1, c)):
                return new_pos
        return None

    def jump_vertical(pos, dir):
        r, c = pos
        dr = 1 if dir else -1
        dc = 0
        while 0 <= r + dr < rows and grid[r + dr][c] != '#':
            r += dr
            new_pos = (r, c)
            if new_pos == goal:
                return new_pos
            for d in [0, 1]:
                if d == 0:
                    res = jump_horizontal(new_pos, 0)
                else:
                    res = jump_horizontal(new_pos, 1)
                if res:
                    return new_pos
        return None

    def jump_point_search():
        pq = [(manhattan(start), 0, start, None)]
        heapq.heapify(pq)
        visited = {start}
        parent = {}

        while pq:
            f, g, pos, prev = heapq.heappop(pq)
            if pos == goal:
                path = []
                while pos:
                    path.append(pos)
                    pos = parent[pos]
                return path[::-1]
            for dir in range(4):  # 0: up, 1: down, 2: left, 3: right
                if dir in [0, 1]:  # vertical
                    jump = jump_vertical(pos, dir % 2)
                else:  # horizontal
                    jump = jump_horizontal(pos, dir % 2)
                if jump and jump not in visited:
                    visited.add(jump)
                    parent[jump] = pos
                    new_g = g + abs(jump[0] - pos[0]) + abs(jump[1] - pos[1])
                    heapq.heappush(pq, (new_g + manhattan(jump), new_g, jump, pos))
        return []

    path = jump_point_search()
    if not path:
        return []

    result = [path[0]]
    for i in range(1, len(path)):
        r1, c1 = path[i - 1]
        r2, c2 = path[i]
        dr = r2 - r1
        dc = c2 - c1
        for step in range(1, max(abs(dr), abs(dc))):
            r = r1 + (dr // abs(dr)) * step if dr != 0 else r1
            c = c1 + (dc // abs(dc)) * step if dc != 0 else c1
            result.append((r, c))
        result.append(path[i])
    return result
