    x, y = pos
    while 0 <= x < len(grid) and 0 <= y < len(grid[0]):
        if grid[x][y] == '#':
            return None
        if (x, y) == goal:
            return (x, y)
        if dx != 0:  # Horizontal jump
            if (
                0 <= x + dx < len(grid) and 0 <= y - 1 < len(grid[0]) and
                grid[x + dx][y - 1] == '.' and grid[x + dx][y] == '#'
            ) or (
                0 <= x + dx < len(grid) and 0 <= y + 1 < len(grid[0]) and
                grid[x + dx][y + 1] == '.' and grid[x + dx][y] == '#'
            ):
                return (x, y)
        else:  # Vertical jump
            if jump_search(grid, (x, y), -1, 0, goal) or jump_search(grid, (x, y), 1, 0, goal) or jump_search(grid, (x, y), 0, -1, goal) or jump_search(grid, (x, y), 0, 1, goal):
                return (x, y)
        x += dx
        y += dy
    return None

