            dx, dy = d
            jump = jump_point(grid, current, d, goal)
            if jump and is_free(grid, *jump):
                if jump not in g_scores or g + step_count(current, jump) < g_scores[jump]:
                    g_new = g + step_count(current, jump)
                    g_scores[jump] = g_new
                    parent[jump] = current
                    h = manhattan(*jump, *goal)
                    heapq.heappush(heap, (g_new + h, g_new, jump, current))
    return []

