def manhattan(r1, c1, r2, c2):
    return abs(r1 - r2) + abs(c1 - c2)

def step_count(from_cell, to_cell):
    return manhattan(*from_cell, *to_cell)

def jump_point(grid, current, direction, goal):
    r, c = current
    dr, dc = direction
    steps = 0

    while True:
        r += dr
        c += dc
        steps += 1
        if not is_free(grid, r, c):
            return None
        if (r, c) == goal:
            return (r, c)

        if direction in [(-1, 0), (1, 0)]:  # Horizontal
            # Check for forced vertical
            if not is_free(grid, r - 1, c) or not is_free(grid, r + 1, c):
                return (r, c)
            if is_free(grid, r, c - dr) and not is_free(grid, r - 1, c - dr) or is_free(grid, r, c + dr) and not is_free(grid, r - 1, c + dr):
                return (r, c)
        else:  # Vertical
            # Check for forced horizontal
            jump_left = jump_point(grid, (r, c), (0, -1), goal)
            jump_right = jump_point(grid, (r, c), (0, 1), goal)
            if jump_left is not None or jump_right is not None:
                return (r, c)

def reconstruct_path(parent, start, goal):
    path = []
    current = goal
    while current:
        path.append(current)
        current = parent.get(current)
    if path[-1] != start:
        return []
    return path[::-1]
