        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def is_free(grid, pos):
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[r]) and grid[r][c] == '.'

    def jump_horizontal(grid, pos, dcol, goal):
        r, c = pos
        came_from_rc = [-dr, -dc] if dcol >= 0 else [dr, -dc]  # previous direction: left if going right, right if going left

        while True:
            c += dcol
            if not is_free(grid, (r, c)):
                return None
            pos = (r, c)

            if pos == goal:
                return pos

            # Check for forced vertical neighbors
            for dr_f in [-1, 1]:
                nr, nc = r + dr_f, c
                if is_free(grid, (nr, nc)) and not is_free(grid, (nr + came_from_rc[0], nc + came_from_rc[1])):
                    return pos

    def jump_vertical(grid, pos, drow, goal):
        r, c = pos
        came_from_rc = [-dr, -dc] if drow >= 0 else [dr, -dc]  # previous direction: down if going up, up if going down

        while True:
            r += drow
            if not is_free(grid, (r, c)):
                return None
            pos = (r, c)

            if pos == goal:
                return pos

            for dcol in [-1, 1]:
                if jump_horizontal(grid, pos, dcol, goal) is not None:
                    return pos

    def expand(grid, node, goal, parent):
        r, c = node
        pr, pc = parent
        dir_r = r - pr
        dir_c = c - pc

        if dir_r != 0:
            # Move vertically again
            new_node = jump_vertical(grid, node, dir_r, goal)
            if new_node:
                return [new_node]
        else:  # dir_c != 0
            # Move horizontally again
            new_node = jump_horizontal(grid, node, dir_c, goal)
            if new_node:
                return [new_node]

        # Look for forced neighbors and neighbors that need to branch
        neighbors = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < rows and 0 <= nc < cols) or grid[nr][nc] != '.':
                continue

            # Is this direction a forced neighbor?
            jumped = None
            if dr != 0:
                jumped = jump_vertical(grid, (nr, nc), dr, goal)
            else:
                jumped = jump_horizontal(grid, (nr, nc), dc, goal)

            if jumped:
                neighbors.append((nr, nc))

        return neighbors

    came_from = {}
    g_scores = {start: 0}
    f_scores = {start: manhattan(start, goal)}
    heap = [(f_scores[start], g_scores[start], start)]

    while heap:
        _, g, current = heapq.heappop(heap)
        if current == goal:
            break
        for next_node in expand(grid, current, goal, start):
            new_g = g + 1
            if next_node not in g_scores or new_g < g_scores[next_node]:
                g_scores[next_node] = new_g
                f_scores[next_node] = new_g + manhattan(next_node, goal)
                heapq.heappush(heap, (f_scores[next_node], new_g, next_node))
                came_from[next_node] = current

    if current != goal or current not in came_from:
        return []

    path = []
    while current != start:
        path.append(current)
        current = came_from[current]
    path.append(start)
    return path[::-1]
