        return abs(pos[0] - goal[0]) + abs(pos[1] - goal[1])

    def jump_horizontal(pos, dcol):
        r, c = pos
        while is_valid(r, c + dcol):
            c += dcol
            if (r, c) == goal:
                return r, c
            if (is_valid(r - 1, c) and not is_valid(r - 2, c)) or (is_valid(r + 1, c) and not is_valid(r + 2, c)):
                return r, c
        return None

    def jump_vertical(pos, drow):
        r, c = pos
        while is_valid(r + drow, c):
            r += drow
            if (r, c) == goal:
                return r, c
            if jump_horizontal((r, c), -1) or jump_horizontal((r, c), 1):
                return r, c
        return None

    def neighbors(pos, dir_from_parent=None):
        dirs = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        result = []
        for dr, dc in dirs:
            next_pos = (pos[0] + dr, pos[1] + dc)
            if is_valid(next_pos[0], next_pos[1]):
                if not dir_from_parent:
                    result.append(next_pos)
                elif (not (dr or dc) or (dr == dir_from_parent[0] or dc == dir_from_parent[1])):
                    jumped = next_pos
                    if dr or dc:
                        if dr:
                            jp = jump_vertical(next_pos, dr)
                        else:
                            jp = jump_horizontal(next_pos, dc)
                        if jp:
                            result.append(jp)
        return result

    visited = set()
    parent = {}
    hq = [(0 + heuristic(start), 0, start)]

    while hq:
        f, g, pos = heapq.heappop(hq)
        if pos in visited:
            continue
        if pos == goal:
            break
        visited.add(pos)
        for next_pos in neighbors(pos):
            if next_pos not in visited and is_valid(next_pos[0], next_pos[1]):
                new_g = g + abs(next_pos[0] - pos[0]) + abs(next_pos[1] - pos[1])
                parent[next_pos] = pos
                heapq.heappush(hq, (new_g + heuristic(next_pos), new_g, next_pos))

    if goal not in parent:
        return []

    path = []
    current = goal
    while current:
        path.append(current)
        current = parent.get(current)
    path.reverse()
    return path
