    if is_wall(grid, *start) or is_wall(grid, *goal):
        return []

    rows, cols = len(grid), len(grid[0])
    heap = [(manhattan(start, goal), 0, start, None)]
    visited = set()
    parent_map = {}

    def is_wall(r, c):
        return not (0 <= r < rows and 0 <= c < cols and grid[r][c] == '.')

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def is_goal(r, c):
        return (r, c) == goal

    def jump_horizontal(r, c, dr, dc, g):
        if is_wall(r, c) or (r, c) == start:
            return None
        while True:
            next_pos = (r, c)
            if is_goal(r, c):
                return next_pos
            # Check for forced neighbor (up or down)
            for dy in (-1, 1):
                nr, nc = r + dy, c
                if 0 <= nr < rows and 0 <= nc < cols:
                    if not is_wall(nr, nc) and is_wall(r - dr, c - dc):
                        return next_pos
            # Check if next step is wall or edge
            nr, nc = r + dr, c + dc
            if not (0 <= nr < rows and 0 <= nc < cols) or is_wall(nr, nc):
                return None
            r, c = nr, nc
            g += 1

    def jump_vertical(r, c, dr, dc, g):
        if is_wall(r, c) or (r, c) == start:
            return None
        while True:
            next_pos = (r, c)
            if is_goal(r, c):
                return next_pos
            # Check for horizontal jump in any direction
            for dc2 in (-1, 1):
                if jump_horizontal(r, c, 0, dc2, 0):
                    return next_pos
            # Check if next step is wall or edge
            nr, nc = r + dr, c + dc
            if not (0 <= nr < rows and 0 <= nc < cols) or is_wall(nr, nc):
                return None
            r, c = nr, nc
            g += 1

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while heap:
        f, g, current, parent = heapq.heappop(heap)
        if current == goal:
            parent_map[current] = parent
            break
        if current in visited:
            continue
        visited.add(current)
        parent_map[current] = parent

        for dr, dc in directions:
            nr, nc = current[0] + dr, current[1] + dc
            if is_wall(nr, nc) or not (0 <= nr < rows and 0 <= nc < cols):
                continue
            if (dr in (1, -1) and dc == 0):  # Vertical
                jump_cell = jump_vertical(current[0] + dr, current[1], dr, 0, g + 1)
            elif (dc in (1, -1) and dr == 0):  # Horizontal
                jump_cell = jump_horizontal(current[0], current[1] + dc, 0, dc, g + 1)
            else:
                continue  # Not a straight line in jump logic

            if jump_cell is None:
                continue
            new_g = g + manhattan(current, jump_cell)
            if jump_cell not in visited:
                heapq.heappush(heap, (new_g + manhattan(jump_cell, goal), new_g, jump_cell, current))

    # Reconstruct the jump path
    path = []
    if goal not in parent_map:
        return []

    current = goal
    while current is not None:
        path.append(current)
        current = parent_map[current]
    path.reverse()

    # Interpolate the path to include every cell on the straight lines
    final_path = [start]
    for i in range(1, len(path)):
        p1, p2 = path[i - 1], path[i]
        dr, dc = step(p1, p2)
        r, c = p1
        while (r, c) != p2:
            r += dr
            c += dc
            final_path.append((r, c))
    return final_path

def step(p1, p2):
    return (p2[0] - p1[0], p2[1] - p1[1])
