        steps = 0
        while True:
            c += dr
            steps += 1
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return (r, c, steps)
            # Check for forced vertical neighbor (wall below or above?)
            if not is_valid(r+1, c) or not is_valid(r-1, c):
                return (r, c, steps)

    def vertical_jump(r, c, dc):
        steps = 0
        while True:
            r += dc
            steps += 1
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return (r, c, steps)
            # Check for forced horizontal neighbors
            if not is_valid(r, c+1) or not is_valid(r, c-1):
                return (r, c, steps)
            # Check if horizontal jump from this point finds a jump point
            for dr in (-1, 1):
                jp = horizontal_jump(r, c, dr)
                if jp:
                    return (r, c, steps)

    def jps():
        open_set = []
        heapq.heappush(open_set, (0, start))
        came_from = {}
        g_scores = {start: 0}
        while open_set:
            f, current = heapq.heappop(open_set)
            if current == goal:
                break
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:  # up, down, left, right
                if dr != 0:
                    jump = vertical_jump(current[0], current[1], dr)
                else:
                    jump = horizontal_jump(current[0], current[1], dc)
                if jump:
                    next_cell, steps = jump[0:2], jump[2]
                    new_g = g_scores[current] + steps
                    if next_cell not in g_scores or new_g < g_scores[next_cell]:
                        g_scores[next_cell] = new_g
                        h = abs(next_cell[0] - goal[0]) + abs(next_cell[1] - goal[1])
                        heapq.heappush(open_set, (new_g + h, next_cell))
                        came_from[next_cell] = current
        if goal not in came_from:
            return []
        # Reconstruct path
        path = [goal]
        while path[-1] != start:
            path.append(came_from[path[-1]])
        return path[::-1]

    path = jps()
    if not path:
        return []

    # Reconstruct full path with all intermediate steps between jump points
    detailed_path = []
    for i in range(len(path) - 1):
        r1, c1 = path[i]
        r2, c2 = path[i + 1]
        dr = r2 - r1
        dc = c2 - c1
        if dr != 0:
            for step in range(1, abs(dr) + 1):
                detailed_path.append((r1 + (1 if dr > 0 else -1) * step, c1))
        if dc != 0:
            for step in range(1, abs(dc) + 1):
                detailed_path.append((r1, c1 + (1 if dc > 0 else -1) * step))
    detailed_path.insert(0, path[0])

    return [path[0]] + [cell for i, cell in enumerate(detailed_path) if i == 0 or cell != detailed_path[i - 1]]
