            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            # Check for horizontal jump in either direction
            if not is_valid(r+1, c) or not is_valid(r-1, c):
                return (r, c)
            elif (horizontal_jump(r, c, 1, parent) or horizontal_jump(r, c, -1, parent)):
                return (r, c)

    def horizontal_jump(r, c, dc, parent):
        while True:
            c += dc
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            # Check for vertical jump in either direction
            if not is_valid(r, c+1) or not is_valid(r, c-1):
                return (r, c)
            elif (vertical_jump(r, c, 1, parent) or vertical_jump(r, c, -1, parent)):
                return (r, c)

    def get_neighbors(r, c, parent):
        jump_points = []
        # Up
        r_jump = vertical_jump(r, c, -1, (r, c))
        if r_jump and r_jump != parent:
            jump_points.append(r_jump)
        # Down
        r_jump = vertical_jump(r, c, 1, (r, c))
        if r_jump and r_jump != parent:
            jump_points.append(r_jump)
        # Left
        c_jump = horizontal_jump(r, c, -1, (r, c))
        if c_jump and c_jump != parent:
            jump_points.append(c_jump)
        # Right
        c_jump = horizontal_jump(r, c, 1, (r, c))
        if c_jump and c_jump != parent:
            jump_points.append(c_jump)
        return jump_points

    heapq_heap = [(manhattan(start, goal), 0, start, None)]
    visited = set()
    parent = {}

    while heapq_heap:
        f, g, node, prev = heapq.heappop(heapq_heap)
        if node in visited:
            continue
        visited.add(node)
        parent[node] = prev
        if node == goal:
            break
        for j in get_neighbors(*node, prev):
            if j not in visited:
                new_g = g + 1
                if j != goal:
                    new_g += manhattan(j, node)  # Add remaining steps to next jump point
                heapq.heappush(heapq_heap, (new_g + manhattan(j, goal), new_g, j, node))

