                    return None
                if (new_r, new_c) == goal:
                    return (new_r, new_c)
                for ndr in (-1, 1):
                    nr, nc = new_r + ndr, new_c
                    if not is_wall(nr, nc) and is_wall(new_r, new_c - dc):
                        return (new_r, new_c)

    def vertical_jump(r, c, dr, dc):
