            new_r, new_c = r, c
            while True:
                new_r += dr
                if is_wall(new_r, new_c):
                    return None
                if (new_r, new_c) == goal:
                    return (new_r, new_c)
                for ndc in (-1, 1):
                    if horizontal_jump(new_r, new_c, 0, ndc) or horizontal_jump(new_r, new_c, 0, -ndc):
                        return (new_r, new_c)

    def get_jump_neighbors(r, c):
        neighbors = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            new_cell = (r + dr, c + dc)
            if not is_wall(*new_cell):
                if (dr == -1 or dr == 1):
                    j = horizontal_jump(r + dr, c + dc, dr, dc)
                else:
                    j = vertical_jump(r + dr, c + dc, dr, dc)
                if j:
                    neighbors.append((j, (r + dr, c + dc)))
        return neighbors

    parent = {}
    g = {start: 0}
    f = {start: manhattan(start, goal)}
    open_set = [(f[start], len(g), start)]

