        if current == goal or (prev[0] != current[0] and prev[1] != current[1]):
            path.append(prev)
            current = prev
        else:
            r, c = current
            dr = r - prev[0]
            dc = c - prev[1]
            next_point = (current[0] - dr, current[1] - dc)
            path.append(next_point)
            current = next_point

