                    new_g = g_scores[current] + manhattan(current, jump_result)
                    if jump_result not in g_scores or new_g < g_scores[jump_result]:
                        g_scores[jump_result] = new_g
                        f_scores[jump_result] = new_g + manhattan(jump_result, goal)
                        heapq.heappush(heap, (f_scores[jump_result], jump_result))
                        came_from[jump_result] = current
        return []

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def horizontal_jump(grid, current, direction):
        step = 1 if direction[1] > 0 else -1
        r, c = current
        dr, dc = direction

        r += dr
        while is_valid(r, c):
            if (r, c) == goal:
                return (r, c)
            check = (r + dr, c) if is_valid(r + dr, c) else None
            if not check:  # wall ahead
                return None
            if not is_valid(r, c - step):  # wall or edge on the left/right
                return (r, c)
            if not is_valid(r + dr, c - step):  # left or right is blocked
                return (r, c)
            r += dr
        return None

    def vertical_jump(grid, current, direction):
        step = 1 if direction[0] > 0 else -1
        r, c = current
        dr, dc = direction

        c += dc
        while is_valid(r, c):
            if (r, c) == goal:
                return (r, c)
            check = (r, c + dc) if is_valid(r, c + dc) else None
            if not check:  # wall ahead
                return None
            if not is_valid(r - step, c):  # wall or edge above/below
                return (r, c)
            if not is_valid(r - step, c + dc):  # above or below is blocked
                return (r, c)
            for d in [(0, 1), (0, -1)]:  # check horizontal for jump points
                hj = horizontal_jump(grid, (r, c), d)
                if hj:
                    return (r, c)
            c += dc
        return None

    def reconstruct_path(came_from, start, goal):
        path = [goal]
        current = goal
        while current != start:
            current = came_from[current]
            path.insert(0, current)
        return path

    # Run JPS both from start to goal and from goal to start (reverse search for performance in certain cases)
    for p in [jump_point_search(grid, start, goal), jump_point_search(grid, goal, start)]:
        if p:
            return p if p[0] == start else p[::-1]
    return []

