import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]
    if not (is_free(grid, start) and is_free(grid, goal)):
        return []

    rows = len(grid)
    cols = len(grid[0])

    def is_inbounds(pos):
        r, c = pos
        return 0 <= r < rows and 0 <= c < cols

    def is_wall(pos):
        r, c = pos
        return not is_inbounds(pos) or grid[r][c] == '#'

    def is_free(pos):
        r, c = pos
        return is_inbounds(pos) and grid[r][c] == '.'

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # right, down, left, up

    def get_opposite_dir(dir_idx):
        return (dir_idx + 2) % 4

    def is_forced_vertical(pos, dir_idx):
        # Vertical direction: up or down
        r, c = pos
        dr, dc = directions[dir_idx]
        rd, cd = directions[1 if dr > 0 else 2]  # down or right
        ru, cu = directions[2 if dr > 0 else 0]  # left or right
        next_pos = (r + dr, c + dc)
        if is_wall(next_pos):
            return False
        down_pos = (r + dr + dr, c + dc)
        up_pos = (r + ru, c + cu)
        if is_wall(up_pos) or is_wall(down_pos):
            return True
        return False

    def is_forced_horizontal(pos, dir_idx):
        # Horizontal direction: left or right
        r, c = pos
        dr, dc = directions[dir_idx]
        rd, cd = directions[0 if dc > 0 else 3]  # right or up
        ru, cu = directions[3 if dc > 0 else 1]  # up or down
        next_pos = (r + dr, c + dc)
        if is_wall(next_pos):
            return False
        up_pos = (r + ru, c + cu)
        down_pos = (r + rd, c + cd)
        if is_wall(up_pos) or is_wall(down_pos):
            return True
        return False

    def jump_horizontal(pos, dir_idx):
        r, c = pos
        dr, dc = directions[dir_idx]
        while True:
            r += dr
            c += dc
            if not is_inbounds((r, c)) or grid[r][c] == '#':
                return None
            if (r, c) == goal:
                return (r, c)
            if is_forced_vertical((r, c), dir_idx):
                return (r, c)
            if is_corner((r, c), dir_idx):
                return (r, c)

    def is_corner(pos, dir_idx):
        # Check for vertical corner
        r, c = pos
        dr, dc = directions[dir_idx]
        if dir_idx % 2 == 0:  # Left or Right
            up = (r - 1, c)
            down = (r + 1, c)
            if not is_wall(up) and not is_wall(down):
                # Can't jump straight, can jump up/down
                if jump_vertical(up, 1) or jump_vertical(up, 3) or \
                   jump_vertical(down, 1) or jump_vertical(down, 3):
                    return True
        else:  # Up or down
            left = (r, c - 1)
            right = (r, c + 1)
            if not is_wall(left) and not is_wall(right):
                # Can't jump straight, can jump left/right
                if jump_horizontal(left, 0) or jump_horizontal(left, 2) or \
                   jump_horizontal(right, 0) or jump_horizontal(right, 2):
                    return True
        return False

    def jump_vertical(pos, dir_idx):
        r, c = pos
        dr, dc = directions[dir_idx]
        while True:
            r += dr
            c += dc
            if not is_inbounds((r, c)) or grid[r][c] == '#':
                return None
            if (r, c) == goal:
                return (r, c)
            if jump_horizontal((r, c), 0) or jump_horizontal((r, c), 2):
                return (r, c)

    def heuristic(pos):
        r1, c1 = pos
        r2, c2 = goal
        return abs(r1 - r2) + abs(c1 - c2)

    def f_score(pos, g):
        return g + heuristic(pos)

    heap = []
    heapq.heappush(heap, (f_score(start, 0), 0, start, None))

    came_from = {}

    while heap:
        _, g, pos, prev = heapq.heappop(heap)

        if pos == goal:
            return reconstruct_path(came_from, start, goal)

        for i, (dr, dc) in enumerate(directions):
            next_pos = (pos[0] + dr, pos[1] + dc)
            if is_wall(next_pos):
                continue
            if get_opposite_dir(i) % 2 == 0:  # Left/Right
                j = jump_horizontal(next_pos, i)
            else:  # Up/Down
                j = jump_vertical(next_pos, i)
            if j:
                if j not in came_from:
                    g_new = g + steps(pos, j)
                    came_from[j] = pos
                    heapq.heappush(heap, (f_score(j, g_new), g_new, j, pos))

    return []

def steps(fr, to):
    r1, c1 = fr
    r2, c2 = to
    return abs(r1 - r2) + abs(c1 - c2)

def reconstruct_path(came_from, start, goal):
    current = goal
    recon_path = [current]
    while current != start:
        current = came_from[current]
        recon_path.append(current)
    return recon_path[::-1]

def is_free(grid, pos):
    r, c = pos
    return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'
