        return pos == goal

    def neighbors(r, c):
        return [(r+1, c), (r-1, c), (r, c+1), (r, c-1)]

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def jump(p, d, is_horizontal):
        pr, pc = p
        dr, dc = d
        while True:
            pr += dr
            pc += dc
            if not is_valid(grid, pr, pc) or (pr, pc) == goal:
                return (pr, pc)
            if is_horizontal:
                if grid[pr - dr][pc] == '#' or grid[pr + dr][pc] == '#':
                    if pr - dr < 0 or pr + dr >= rows:
                        continue
                    if grid[pr - dr][pc] == '#' or grid[pr + dr][pc] == '#':
                        continue
                if grid[pr][pc - dc] == '#' or grid[pr][pc + dc] == '#':
                    return (pr, pc)
            else:
                if grid[pr][pc - dc] == '#' or grid[pr][pc + dc] == '#':
                    return (pr, pc)
        return None

    def horizontal_jump(p, d):
        return jump(p, d, True)

    def vertical_jump(p, d):
        return jump(p, d, False)

    def get_jump_points(p):
        jump_points = []
        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        for d in directions:
            step = tuple(p[i] + d[i] for i in range(2))
            if is_valid(grid, *step):
                if d[0] == 0:
                    j = horizontal_jump(p, d)
                else:
                    j = vertical_jump(p, d)
                if j and j != p:
                    jump_points.append(j)
        return jump_points

    def reconstruct_path(came_from, current):
        path = [current]
        while current in came_from:
            current = came_from[current]
            path.append(current)
        path.reverse()
        return path

    heap = [(manhattan(start, goal), start)]
    came_from = {}
    g = {start: 0}
    visited = set()

    while heap:
        _, current = heapq.heappop(heap)
        if current in visited:
            continue
        if current == goal:
            return reconstruct_path(came_from, current)
        visited.add(current)
        for j in get_jump_points(current):
            jr, jc = j
            next_g = g[current] + abs(jr - current[0]) + abs(jc - current[1])
            if grid[jr][jc] == '#' or (jr, jc) in visited:
                continue
            if j not in g or next_g < g[j]:
                g[j] = next_g
                heapq.heappush(heap, (g[j] + manhattan(j, goal), j))
                came_from[j] = current
    return []
