        steps = 0
        while True:
            nr, nc = r + dr, c + dc
            if not is_valid(nr, nc):
                return None
            if (nr, nc) == goal:
                return (nr, nc)
            # Check for forced vertical neighbors
            if not is_valid(nr + 1, nc) and is_valid(nr, nc):
                if (r, c) != parent:
                    return (nr, nc)
            if not is_valid(nr - 1, nc) and is_valid(nr, nc):
                if (r, c) != parent:
                    return (nr, nc)
            steps += 1
            r, c = nr, nc
            if (r, c) == parent:
                return None

    def jump_vertical(r, c, dr, dc, parent):
        steps = 0
        while True:
            nr, nc = r + dr, c + dc
            if not is_valid(nr, nc):
                return None
            if (nr, nc) == goal:
                return (nr, nc)
            # Check for jump points in horizontal directions
            if jump_horizontal(nr, nc, 0, 1, (nr, nc)) or jump_horizontal(nr, nc, 0, -1, (nr, nc)):
                return (nr, nc)
            steps += 1
            r, c = nr, nc
            if (r, c) == parent:
                return None

    def get_neighbors(r, c):
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                if dr == 0:
                    # Horizontal jump
                    jump = jump_horizontal(r, c, dr, dc, (r, c))
                else:
                    # Vertical jump
                    jump = jump_vertical(r, c, dr, dc, (r, c))
                if jump:
                    yield jump

    open_set = [(heuristic(*start, *goal), heuristic(*start, *goal), start, [start], {start: None})]
    while open_set:
        f, h, current, path, came_from = heapq.heappop(open_set)
        if current == goal:
            return path
        for jump_point in get_neighbors(*current):
            if jump_point not in came_from:
                g = len(path)
                h = heuristic(*jump_point, *goal)
                f = g + h
                new_path = path + [jump_point]
                new_came_from = came_from.copy()
                new_came_from[jump_point] = current
                heapq.heappush(open_set, (f, h, jump_point, new_path, new_came_from))
    return []
