    def heuristic_search(from_pos, to_pos, is_forward):
        open_heap = []
        heapq.heappush(open_heap, (manhattan(from_pos, to_pos), 0, from_pos))
        visited = {from_pos: None}
        cost = {from_pos: 0}
        while open_heap:
            f, g, current = heapq.heappop(open_heap)
            if current in visited and visited[current] is not None:
                continue
            visited[current] = None  # Mark as visited and not expanded
            if g > cost[current]:
                continue
            yield current, g, visited, cost
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                neighbor = (current[0] + dx, current[1] + dy)
                if is_valid(neighbor) and neighbor not in cost:
                    new_g = g + 1
                    new_h = manhattan(neighbor, to_pos)
                    heapq.heappush(open_heap, (new_g + new_h, new_g, neighbor))
