        if path_found:
            break

    if not path_found or not is_valid(start) or not is_valid(goal):
        return []

    if start == goal:
        return [start]

    def reconstruct_path(start_pos, goal_pos, came_from):
        path = []
        current = goal_pos
        while current != start_pos:
            path.append(current)
            current = came_from[current]
        path.append(start_pos)
        return path[::-1]

    forward_came_from = {v: k for k, v in forward_cost.items() if v is not None}
    backward_came_from = {v: k for k, v in backward_cost.items() if v is not None}

    forward_path = reconstruct_path(start, meeting_node, forward_came_from)
    backward_path = reconstruct_path(goal, meeting_node, backward_came_from)
    backward_path.reverse()
    forward_path.extend(backward_path[1:])
    return forward_path
