    visited = set()
    parent = {}

    while heap:
        f, g, current, prev_dir = heapq.heappop(heap)
        if current in visited:
            continue
        visited.add(current)

        if current == goal:
            return reconstruct_path(parent, start, goal)

        for dx, dy, dir_label in [(0, 1, 'right'), (0, -1, 'left'), (1, 0, 'down'), (-1, 0, 'up')]:
            if dir_label in ['right', 'left']:
                jump_point = horizontal_jump(grid, current, dx, dy, goal, rows, cols, f - g, g, parent, visited)
            else:
                jump_point = vertical_jump(grid, current, dx, dy, goal, rows, cols, f - g, g, parent, visited)

            if jump_point:
                heap.append((manhattan(jump_point, goal) + (g + steps(current, jump_point)), g + steps(current, jump_point), jump_point, dir_label))
                heapq.heapify(heap)

    return []

def manhattan(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])

def steps(a, b):
    return manhattan(a, b)

def is_free(grid, pos):
    r, c = pos
    return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

def horizontal_jump(grid, current, dx, dy, goal, rows, cols, h, g, parent, visited):
    r, c = current
    while is_free(grid, (r, c)):
        if (r, c) == goal:
            return (r, c)
        if has_forced_neighbor(grid, rows, cols, (r, c), (dx, 0)) or has_forced_neighbor(grid, rows, cols, (r, c), (0, dy)):
            parent[(r, c)] = current
            return (r, c)
        r += dx
        c += dy
    return None

def vertical_jump(grid, current, dx, dy, goal, rows, cols, h, g, parent, visited):
    r, c = current
    while is_free(grid, (r, c)):
        if (r, c) == goal:
            return (r, c)
        if any(horizontal_jump(grid, (r, c), 0, 1, goal, rows, cols, h, g, parent, visited),
               horizontal_jump(grid, (r, c), 0, -1, goal, rows, cols, h, g, parent, visited)):
            parent[(r, c)] = current
            return (r, c)
        r += dx
        c += dy
    return None

def has_forced_neighbor(grid, rows, cols, pos, direction):
    dx, dy = direction
    r, c = pos
    r += dx
    c += dy
    if not is_free(grid, (r, c)):
        return False
    # Check above and below for forced neighbor
    for dr in (-1, 1):
        nr, nc = r + dr, c
        if 0 <= nr < rows and 0 <= nc < cols:
            if grid[nr][nc] == '#' and is_free(grid, (nr - dr, nc)):
                return True
    return False

def reconstruct_path(parent, start, goal):
    path = [goal]
    while path[-1] != start:
        path.append(parent.get(path[-1], start))
        if path[-1] == path[-2]:
            break
    return path[::-1]
