    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def jump_horizontal(r, c, step, goal, came_from):
        while True:
            c += step
            if (r, c) == goal:
                return r, c
            if not is_valid(r, c):
                return None
            if c == came_from[1] or step == 0:
                break
            if not is_valid(r - 1, c) or not is_valid(r + 1, c):
                return r, c
            if grid[r - 1][c] != '.' and grid[r + 1][c] != '.':
                return None
        return None

    def jump_vertical(r, c, step, goal, came_from):
        while True:
            r += step
            if (r, c) == goal:
                return r, c
            if not is_valid(r, c):
                return None
            if r == came_from[0] or step == 0:
                break
            if not is_valid(r, c - 1) or not is_valid(r, c + 1):
                return r, c
            if grid[r][c - 1] != '.' and grid[r][c + 1] != '.':
                return None
        return None

    def jump(r, c, direction, goal, came_from):
        dr, dc = direction
        new_r, new_c = r + dr, c + dc
        if not is_valid(new_r, new_c):
            return None

        if (new_r, new_c) == goal:
            return new_r, new_c

        if (dr == 0):  # Horizontal move
            j = jump_horizontal(new_r, new_c, dc, goal, (r, c))
        else:  # Vertical move
            j = jump_vertical(new_r, new_c, dr, goal, (r, c))
        if j:
            return j
        return None

    came_from = {}
    heap = [(manhattan(start, goal), 0, start, None)]
    visited = set()

    while heap:
        f, g, current, parent = heapq.heappop(heap)
        came_from[(current, parent)] = g

        if current in visited:
            continue
        visited.add(current)

        if current == goal:
            break

        for direction in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            jump_point = jump(current[0], current[1], direction, goal, current if parent is not None else (0, 0))
            if jump_point and jump_point not in visited:
                new_g = g + (abs(jump_point[0] - current[0]) + abs(jump_point[1] - current[1]))
                heapq.heappush(heap, (
                    new_g + manhattan(jump_point, goal),
                    new_g,
                    jump_point,
                    current
                ))

    path = []
    if current != goal or not came_from:
        return []

    while current != start:
        path.append(current)
        # Find predecessor that led to current
        for key in came_from:
            if key[0] == current:
                current = key[1]
                break
    path.append(start)
    path.reverse()

    # Fill in the straight line between consecutive jump points
    result = []
    for i in range(len(path) - 1):
        r1, c1 = path[i]
        r2, c2 = path[i + 1]
        dr = r2 - r1
        dc = c2 - c1
        if dr:
            for step in range(1, dr//abs(dr) * (abs(dr) + 1)):
                result.append((r1 + step * (1 if dr > 0 else -1), c1))
        if dc:
            for step in range(1, dc//abs(dc) * (abs(dc) + 1)):
                result.append((r1, c1 + step * (1 if dc > 0 else -1)))

    if path:
        result.append(path[-1])
    return result
