import heapq

def solve(grid, start, goal):
    if (start == goal) and (grid[start[0]][start[1]] == '.'):
        return [start]
    if (grid[start[0]][start[1]] == '#') or (grid[goal[0]][goal[1]] == '#'):
        return []

    rows, cols = len(grid), len(grid[0])
    dirs = [(0, 1, 'R'), (0, -1, 'L'), (1, 0, 'D'), (-1, 0, 'U')]  # direction & jump identifier

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def is_wall(r, c):
        return not (0 <= r < rows and 0 <= c < cols and grid[r][c] == '.')

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols

    def force_vertical(r, c, d):
        # Check for forced vertical moves
        dr, dc, _ = d
        ndr1, ndc1 = -1 if dr == 1 else 1, 0
        if is_valid(r + ndr1, c) and not is_wall(r + ndr1, c):
            if not is_valid(r + 2 * ndr1, c) or is_wall(r + 2 * ndr1, c):
                return True
        ndr2, ndc2 = 0, 1 if dc == 1 else -1
        if is_valid(r, c + ndc2) and not is_wall(r, c + ndc2):
            if not is_valid(r, c + 2 * ndc2) or is_wall(r, c + 2 * ndc2):
                return True
        return False

    def jump_horizontal(r, c, dr, dc):
        while True:
            next_r, next_c = r + dr, c + dc
            if not is_valid(next_r, next_c) or is_wall(next_r, next_c):
                return None
            if (next_r, next_c) == goal:
                return (next_r, next_c)
            if force_vertical(next_r, next_c, (dr, dc, ' ')):
                return (next_r, next_c)
            r, c = next_r, next_c

    def jump_vertical(r, c, dr, dc):
        while True:
            next_r, next_c = r + dr, c + dc
            if not is_valid(next_r, next_c) or is_wall(next_r, next_c):
                return None
            if (next_r, next_c) == goal:
                return (next_r, next_c)
            for d in [(0, 1), (0, -1)]:
                if jump_horizontal(next_r, next_c, 0, d[1]) is not None:
                    return (next_r, next_c)
            r, c = next_r, next_c

    def jump(r, c, came_from):
        for dr, dc, _ in dirs:
            if (dr, dc) == came_from:
                continue
            next_r, next_c = r + dr, c + dc
            if not is_valid(next_r, next_c) or is_wall(next_r, next_c):
                continue
            if (next_r, next_c) == goal:
                return [(next_r, next_c)]
            if dr != 0 and dc != 0:
                continue
            if dr != 0:
               jp = jump_horizontal(next_r, next_c, dr, 0)
            else:
                jp = jump_vertical(next_r, next_c, 0, dc)
            if jp is not None:
                res = jump(next_r, next_c, (-dr, -dc))
                if res:
                    return [(next_r, next_c)] + res

    def heuristic(r, c):
        return manhattan((r, c), goal)

    parent = {}
    visited = set()
    heap = [(heuristic(start[0], start[1]), 0, start, None)]  # (f, g, position, from dir)

    while heap:
        f, g, pos, from_dir = heapq.heappop(heap)
        r, c = pos
        if pos == goal:
            break
        if pos in visited:
            continue
        visited.add(pos)

        for dr, dc, _ in dirs:
            if (dr, dc) == from_dir:
                continue
            if is_wall(r + dr, c + dc):
                continue
            if (dr != 0 and dc != 0):
                continue
            if dr != 0:
                jp = jump_horizontal(r + dr, c + dc, dr, 0)
            else:
                jp = jump_vertical(r + dc, c + dc, dc, dc)
            if jp is not None:
                if (r + dr, c + dc) not in visited or (ip := parent.get(jp, None)) is None:
                    ng = g + 1
                    while (r + dr, c + dc) != jp:
                        r += dr
                        c += dc
                        ng += 1
                    heapq.heappush(heap, (ng + heuristic(r, c), ng, (r, c), (-dr, -dc)))
                    parent[(r, c)] = ip

    if goal not in parent:
        return []

    # Reconstruct path with jumps
    path = set()
    path.add(start)
    curr = goal
    while curr in parent and curr != start:
        prev = parent[curr]
        path.add(curr)
        path.add(prev)
        if curr[0] == prev[0]:
            move_steps = abs(curr[1] - prev[1])
            for i in range(1, move_steps):
                path.add((curr[0], prev[1] if curr[1] > prev[1] else curr[1] + i if prev[1] < curr[1] else curr[1] - i))
        else:
            move_steps = abs(curr[0] - prev[0])
            for i in range(1, move_steps):
                path.add((prev[0] if curr[0] > prev[0] else curr[0] + i if prev[0] < curr[0] else curr[0] - i, curr[1]))
        curr = prev

    # Now construct ordered path from start to goal (need to reverse)
    path = list(path)
    path.reverse()
    path = list(reversed([x for x in path if x in path]))
    if path[-1] != goal:
        path.append(goal)
    if path[0] != start:
        path.insert(0, start)

    ordered = [start]
    for p in path[1:]:
        if (p[0] != ordered[-1][0] and p[1] != ordered[-1][1]):
            if p[0] > ordered[-1][0]:
                for i in range(1, p[0] - ordered[-1][0] + 1):
                    ordered.append((ordered[-1][0]+i, ordered[-1][1]))
            else:
                for i in range(1, ordered[-1][0] - p[0] + 1):
                    ordered.append((ordered[-1][0]-i, ordered[-1][1]))
        elif p[1] > ordered[-1][1]:
            for i in range(1, p[1] - ordered[-1][1] + 1):
                ordered.append((ordered[-1][0], ordered[-1][1]+i))
        else:
            for i in range(1, ordered[-1][1] - p[1] + 1):
                ordered.append((ordered[-1][0], ordered[-1][1]-i))
    return ordered
