import heapq

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and grid[start[0]][start[1]] == '.'):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0]) and grid[goal[0]][goal[1]] == '.'):
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    dirs = [(-1,0),(1,0),(0,-1),(0,1)]  # up, down, left, right

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def jump_point(r, c, dr, dc, parent):
        if (r, c) == goal:
            return (r, c)
        if not is_valid(r, c):
            return None

        # Check for forced neighbors
        if dc != 0:
            # Horizontal jump
            for ndr in [-1, 1]:
                if is_valid(r + ndr, c) and not is_valid(r + dr, c):
                    return (r, c)
        else:
            # Vertical jump
            for ndc in [-1, 1]:
                if is_valid(r, c + ndc) and not is_valid(r, c + dc):
                    return (r, c)

        # Recursive jump in the same direction
        j = jump_point(r + dr, c + dc, dr, dc, (r, c))
        if j:
            return j
        return None

    # Main jump point search
    def jump_helper(r, c, dr, dc):
        current = (r, c)
        steps = 0
        while True:
            next_r = current[0] + dr
            next_c = current[1] + dc
            if not is_valid(next_r, next_c):
                return None
            steps += 1
            if (next_r, next_c) == goal:
                return (next_r, next_c), steps
            if abs(dr) == 1:
                # Horizontal jump
                ndr = -1 if dr > 0 else 1
                if is_valid(current[0] + ndr, current[1]) and not is_valid(next_r + ndr, next_c):
                    return (next_r, next_c), steps
            else:  # vertical jump
                ndc = -1 if dc > 0 else 1
                if is_valid(current[0], current[1] + ndc) and not is_valid(next_r, next_c + ndc):
                    return (next_r, next_c), steps
            j = jump_point(next_r, next_c, dr, dc, current)
            if j:
                return j, steps + 1
            current = (next_r, next_c)

    came_from = {}
    g_score = {start: 0}
    f_score = {start: manhattan(start, goal)}
    heap = [(f_score[start], g_score[start], start, None)]

    while heap:
        _, g, current, parent = heapq.heapop(heap)
        if current == goal:
            break
        if current in came_from and came_from[current] != parent:
            continue

        if parent:
            dr = current[0] - parent[0]
            dc = current[1] - parent[1]
        else:
            dr = dc = 0

        for rd, cd in [(0,1),(0,-1),(1,0),(-1,0)]:
            if (rd, cd) == (-dr, -cd):
                continue  # skip opposite direction
            j, steps = jump_helper(current[0], current[1], rd, cd)
            if j is None:
                continue
            new_g = g + steps
            if j not in g_score or new_g < g_score[j]:
                g_score[j] = new_g
                f_score[j] = new_g + manhattan(j, goal)
                heapq.heapush(heap, (f_score[j], new_g, j, current))
                came_from[j] = current

    if goal not in came_from:
        return []

    # Reconstruct path
    path = []
    current = goal
    while current:
        path.append(current)
        current = came_from.get(current)
    path.reverse()

