    final_path = [start]
    for i in range(1, len(path)):
        p1, p2 = path[i-1], path[i]
        dr = p2[0] - p1[0]
        dc = p2[1] - p1[1]
        if dr != 0:
            for j in range(1, abs(dr)):
                final_path.append((p1[0] + dr // abs(dr) * j, p1[1]))
        if dc != 0:
            for j in range(1, abs(dc)):
                final_path.append((p1[0], p1[1] + dc // abs(dc) * j))
        final_path.append(p2)

    return final_path
