import heapq

def solve(grid, start, goal):
    if (
        not grid or
        not 0 <= start[0] < len(grid) or
        not 0 <= start[1] < len(grid[0]) or
        not 0 <= goal[0] < len(grid) or
        not 0 <= goal[1] < len(grid[0]) or
        grid[start[0]][start[1]] == '#' or
        grid[goal[0]][goal[1]] == '#'
    ):
        return []

    if start == goal:
        return [start]

    rows = len(grid)
    cols = len(grid[0])

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def is_in_bounds(p):
        r, c = p
        return 0 <= r < rows and 0 <= c < cols

    def is_wall(p):
        r, c = p
        return grid[r][c] == '#'

    def jump_vertical(p, d):
        r, c = p
        dr = d[0], d[1]
        while is_in_bounds((r + dr[0], c + dr[1])):
            r += dr[0]
            c += dr[1]
            if (r, c) == goal:
                return (r, c)
            if (is_wall((r + 1, c)) and not is_wall((r - 1 if dr[0] == -1 else r + 1, c - 1 if dr[1] == -1 else c + 1))) or \
               (is_wall((r - 1, c)) and not is_wall((r + 1 if dr[0] == -1 else r - 1, c - 1 if dr[1] == -1 else c + 1))):
                return (r, c)
            if (is_wall((r, c + 1)) and not is_wall((r + 1, c)) and dr[1] == -1) or \
               (is_wall((r, c - 1)) and not is_wall((r + 1, c)) and dr[1] == 1):
                return (r, c)
            if is_wall((r + dr[0], c + dr[1])):
                return None

    def jump_horizontal(p, d):
        r, c = p
        dc = d[0], d[1]
        while is_in_bounds((r + dc[0], c + dc[1])):
            r += dc[0]
            c += dc[1]
            if (r, c) == goal:
                return (r, c)
            if not is_wall((r, c + 1)) and not is_wall((r, c - 1)) and (is_wall((r - 1, c)) or is_wall((r + 1, c))):
                return (r, c)
            if not is_wall((r, c + 1)) and is_wall((r, c + 2)) and not is_wall((r + 1, c + 1)):
                return (r, c)
            if not is_wall((r, c - 1)) and is_wall((r, c - 2)) and not is_wall((r + 1, c - 1)):
                return (r, c)
            if is_wall((r + dc[0], c + dc[1])):
                return None

    def get_neighbors(p, parent):
        r, c = p
        pr, pc = parent
        dr = r - pr
        dc = c - pc
        if dr != 0:
            if jump_vertical((r, c), (dr, 0)):
                yield jump_vertical((r, c), (dr, 0))
            if jump_vertical((r, c), (-dr, 0)):
                yield jump_vertical((r, c), (-dr, 0))
        elif dc != 0:
            if jump_horizontal((r, c), (0, dc)):
                yield jump_horizontal((r, c), (0, dc))
            if jump_horizontal((r, c), (0, -dc)):
                yield jump_horizontal((r, c), (0, -dc))

    came_from = {}
    g_score = {start: 0}
    f_score = {start: manhattan(start, goal)}
    frontier = [(f_score[start], start)]

    while frontier:
        _, current = heapq.heappop(frontier)
        if current == goal:
            break
        if current in came_from:
            parent = came_from[current]
        else:
            continue  # No parent means current is the start node
        for next_p in get_neighbors(current, parent):
            if next_p is None:
                continue
            new_g = g_score[current] + abs(next_p[0] - current[0]) + abs(next_p[1] - current[1])
            if next_p not in g_score or new_g < g_score[next_p]:
                g_score[next_p] = new_g
                f_score[next_p] = new_g + manhattan(next_p, goal)
                heapq.heappush(frontier, (f_score[next_p], next_p))
                came_from[next_p] = current

    if goal not in came_from:
        return []

    path = []
    current = goal
    while current != start:
        path.append(current)
        current = came_from[current]
    path.append(start)
    path.reverse()

    # Connect jump points with straight line
    result = []
    for i in range(len(path)):
        if i == 0:
            result.append(path[i])
        else:
            px, py = path[i - 1]
            cx, cy = path[i]
            dx = cx - px
            dy = cy - py
            if dx != 0:
                step = 1 if dx > 0 else -1
                for j in range(px + step, cx, step):
                    result.append((j, py))
            if dy != 0:
                step = 1 if dy > 0 else -1
                for j in range(py + step, cy, step):
                    result.append((cx, j))
            result.append(path[i])

    return result
