import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]
    if (
        not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])) or
        not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])) or
        grid[start[0]][start[1]] == '#' or
        grid[goal[0]][goal[1]] == '#'
    ):
        return []

    rows, cols = len(grid), len(grid[0])
    open_list = []
    heapq.heappush(open_list, (manhattan(start, goal), 0, start, None))
    parent = {}
    visited = {start}

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def jump_horizontal(r, c, step, g, parent_cell):
        while True:
            c += step
            if (c < 0 or c >= cols or grid[r][c] == '#'):
                return None
            g += 1
            if (r, c) == goal:
                return (r, c, g, parent_cell)
            # Check for vertical forced neighbors
            if grid[r - 1][c] == '.' or grid[r + 1][c] == '.':
                if grid[r - 1][c] == '#' or grid[r + 1][c] == '#':
                    if (0 <= c - step < cols and grid[r][c - step] != '#'):
                        if grid[r - 1][c] == '#':
                            return (r, c, g, parent_cell)
                        if grid[r + 1][c] == '#':
                            return (r, c, g, parent_cell)
                else:
                    if (grid[r - 1][c - step] == '#' and grid[r - 1][c] == '.') or \
                        (grid[r + 1][c - step] == '#' and grid[r + 1][c] == '.'):
                        return (r, c, g, parent_cell)
            parent_cell = (r, c)
        return None

    def jump_vertical(r, c, step, g, parent_cell):
        while True:
            r += step
            if (r < 0 or r >= rows or grid[r][c] == '#'):
                return None
            g += 1
            if (r, c) == goal:
                return (r, c, g, parent_cell)
            # Check for horizontal jump points
            for dir in [1, -1]:
                res = jump_horizontal(r, c, dir, 0, (r, c))
                if res and res[0] is not None:
                    return (r, c, g, parent_cell)
            parent_cell = (r, c)
        return None

    def jump(r, c, dr, dc, g, parent_cell):
        if dr == 0:
            return jump_horizontal(r, c, dc, g, parent_cell)
        else:
            return jump_vertical(r, c, dr, g, parent_cell)

    while open_list:
        _, g, current, prev = heapq.heappop(open_list)
        if current == goal:
            break
        for dr, dc in directions:
            nr, nc = current[0] + dr, current[1] + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                if prev is not None and (current[0] - prev[0], current[1] - prev[1]) == (dr, dc):
                    res = jump(current[0], current[1], dr, dc, 0, current)
                else:
                    res = current[0] + dr, current[1] + dc, g + 1, current
                if res and res[0] is not None:
                    rj, cj, gj, _ = res
                    if (rj, cj) not in visited:
                        heapq.heappush(open_list, (gj + manhattan((rj, cj), goal), gj, (rj, cj), current))
                        parent[(rj, cj)] = current
                        visited.add((rj, cj))

    if goal not in parent:
        return []

    path = []
    current = goal
    while current is not None:
        path.append(current)
        current = parent.get(current)
    path.reverse()

    # Fill in straight-line cells between jump points
    extended_path = [path[0]]
    for i in range(1, len(path)):
        r1, c1 = path[i - 1]
        r2, c2 = path[i]
        dr = r2 - r1
        dc = c2 - c1
        if dr != 0:
            for r in range(1, abs(dr)):
                extended_path.append((r1 + (1 if dr > 0 else -1) * r, c1))
        if dc != 0:
            for c in range(1, abs(dc)):
                extended_path.append((r2, c1 + (1 if dc > 0 else -1) * c))
    extended_path.append(path[-1])

    # Validate path
    if not all(0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' for r, c in extended_path):
        return []

    return extended_path
