        came_from = {}
        g_cost = {start_pos: 0}
        while heap:
            f, g, current = heapq.heappop(heap)
            if current in came_from:
                continue
            if current == goal_pos:
                return (True, reconstruct_path(came_from, start_pos, goal_pos))
            for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                nx, ny = current[0] + dx, current[1] + dy
                neighbor = (nx, ny)
                if is_valid(grid, nx, ny) and neighbor not in g_cost:
                    new_g = g + 1
                    g_cost[neighbor] = new_g
                    h = manhattan(neighbor, goal_pos)
                    f = new_g + h
                    heapq.heappush(heap, (f, new_g, neighbor))
                    came_from[neighbor] = current
        return (False, [])

    def is_valid(grid, x, y):
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == '.'

    def reconstruct_path(came_from, start, goal):
        path = []
        current = goal
        while current != start:
            path.append(current)
            current = came_from[current]
        path.append(start)
        path.reverse()
        return path

    forward_came_from = {}
    forward_g = {start: 0}
    backward_came_from = {}
    backward_g = {goal: 0}

    forward_heap = [(manhattan(start, goal), 0, start)]
    backward_heap = [(manhattan(start, goal), 0, goal)]

    while forward_heap and backward_heap:
        forward_f, forward_g_cost, forward_current = heapq.heappop(forward_heap)
        if forward_current in backward_g:
            return join_paths(reconstruct_path(forward_came_from, start, forward_current), reconstruct_path(backward_came_from, goal, forward_current))
        if forward_current not in forward_came_from:
            forward_came_from[forward_current] = None
            for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                nx, ny = forward_current[0] + dx, forward_current[1] + dy
                neighbor = (nx, ny)
                if is_valid(grid, nx, ny) and neighbor not in forward_g:
                    new_g = forward_g_cost + 1
                    forward_g[neighbor] = new_g
                    h = manhattan(neighbor, goal)
                    f = new_g + h
                    heapq.heappush(forward_heap, (f, new_g, neighbor))
                    forward_came_from[neighbor] = forward_current

        backward_f, backward_g_cost, backward_current = heapq.heappop(backward_heap)
        if backward_current in forward_g:
            return join_paths(reconstruct_path(forward_came_from, start, backward_current), reconstruct_path(backward_came_from, goal, backward_current))
        if backward_current not in backward_came_from:
            backward_came_from[backward_current] = None
            for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                nx, ny = backward_current[0] + dx, backward_current[1] + dy
                neighbor = (nx, ny)
                if is_valid(grid, nx, ny) and neighbor not in backward_g:
                    new_g = backward_g_cost + 1
                    backward_g[neighbor] = new_g
                    h = manhattan(neighbor, start)
                    f = new_g + h
                    heapq.heappush(backward_heap, (f, new_g, neighbor))
                    backward_came_from[neighbor] = backward_current

