    def heuristic_search(start_pos, goal_pos):
        visited = {}
        parents = {}
        heap = [(manhattan(start_pos, goal_pos), 0, start_pos)]

        while heap:
            f, g, pos = heapq.heappop(heap)
            if pos in visited:
                continue
            visited[pos] = g
            if pos == goal_pos:
                break
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = pos[0] + dr, pos[1] + dc
                if is_valid(nr, nc) and (nr, nc) not in visited:
                    new_g = g + 1
                    heapq.heappush(heap, (new_g + manhattan((nr, nc), goal_pos), new_g, (nr, nc)))
                    if (nr, nc) not in parents:
                        parents[(nr, nc)] = pos
        return visited, parents

    forward = {"visited": {}, "parents": {}}
    backward = {"visited": {}, "parents": {}}
    forward_found = False
    backward_found = False

    while True:
        if not forward_found:
            f_visited, f_parents = heuristic_search(start, goal)
            forward["visited"] = f_visited
            forward["parents"] = f_parents
            forward_found = True
        if not backward_found:
            b_visited, b_parents = heuristic_search(goal, start)
            backward["visited"] = b_visited
            backward["parents"] = b_parents
            backward_found = True

        best_meeting_f = float('inf')
        meeting_cell = None

        for cell in forward["visited"]:
            if cell in backward["visited"]:
                total_cost = forward["visited"][cell] + backward["visited"][cell]
                if total_cost < best_meeting_f:
                    best_meeting_f = total_cost
                    meeting_cell = cell

        if meeting_cell is None:
            return []

        # Reconstruct path
        path = []
        curr = meeting_cell
        while curr != start:
            path.append(curr)
            curr = forward["parents"][curr]
        path.append(start)
        path.reverse()

        curr = meeting_cell
        while curr != goal:
            curr = backward["parents"][curr]
            path.append(curr)

        return path
