        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def heuristic_search(frontier, g, parents, target, other_g):
        if not frontier:
            return
        cost, pos = heapq.heappop(frontier)
        if pos in other_g:
            return pos, cost + other_g[pos]
        if pos in g and g[pos] <= cost:
            return
        g[pos] = cost
        for dr, dc in directions:
            nr, nc = pos[0] + dr, pos[1] + dc
            neighbor = (nr, nc)
            if is_valid(grid, neighbor) and neighbor not in g:
                new_cost = cost + 1
                heapq.heappush(frontier, (new_cost + manhattan(neighbor, target), neighbor))
                if neighbor not in parents:
                    parents[neighbor] = pos
        return None

    # Forward search from start
    forward_frontier = [(0 + manhattan(start, goal), start)]
    forward_g = {start: 0}
    forward_parents = {}

    # Backward search from goal
    backward_frontier = [(0 + manhattan(goal, start), goal)]
    backward_g = {goal: 0}
    backward_parents = {}

    meeting_point = None
    best_cost = float('inf')

    while forward_frontier and backward_frontier:
        result = heuristic_search(forward_frontier, forward_g, forward_parents, goal, backward_g)
        if result:
            meeting_point, total_cost = result
            if total_cost < best_cost:
                best_cost = total_cost
                break
        result = heuristic_search(backward_frontier, backward_g, backward_parents, start, forward_g)
        if result:
            meeting_point, total_cost = result
            if total_cost < best_cost:
                best_cost = total_cost
                break

    if not meeting_point:
        return []

    # Reconstruct path
    path = []
    cur = meeting_point
    while cur in forward_parents:
        path.append(cur)
        cur = forward_parents[cur]
    path.append(start)
    cur = meeting_point
    while cur in backward_parents:
        cur = backward_parents[cur]
        path.append(cur)
    path.reverse()
    return path
