                if neighbor not in cost_backward or new_g < cost_backward[neighbor]:
                    cost_backward[neighbor] = new_g
                    f = new_g + heuristic(neighbor, start)
                    if f < best_f:
                        heapq.heappush(open_backward, (f, new_g, neighbor))
                        came_from_backward[neighbor] = current

        # Check if paths meet
        for pos in cost_forward:
            if pos in cost_backward:
                total_cost = cost_forward[pos] + cost_backward[pos]
                if total_cost <= best_f:
                    best_f = total_cost
