    def is_free(grid, pos):
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def search(from_pos, to_pos, is_forward):
        hq = []
        heapq.heappush(hq, (0, from_pos))
        g = {from_pos: 0}
        parent = {}

        if is_forward:
            other_side = set()
            other_g = {}
        else:
            other_side = set()
            other_g = {}

        while hq:
            f, pos = heapq.heappop(hq)
            if pos in other_side:
                return pos, g, parent

            if is_forward:
                if f > min(other_g.get(n, float('inf')) for n in other_side) if other_side else float('inf'):
                    continue
            else:
                if f > min(other_g.get(n, float('inf')) for n in other_side) if other_side else float('inf'):
                    continue

            for dr, dc in directions:
                nr, nc = pos[0] + dr, pos[1] + dc
                next_pos = (nr, nc)
                if not is_free(grid, next_pos):
                    continue
                cost = 1
                new_g = g[pos] + cost
                if next_pos not in g or new_g < g[next_pos]:
                    g[next_pos] = new_g
                    h = manhattan(next_pos, to_pos)
                    heapq.heappush(hq, (new_g + h, next_pos))
                    parent[next_pos] = pos
