        return [start]
    if not is_free(grid, start) or not is_free(grid, goal):
        return []

    rows = len(grid)
    cols = len(grid[0])
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_free(grid, pos):
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def manhattan(pos1, pos2):
        return abs(pos1[0] - pos2[0]) + abs(pos1[1] - pos2[1])

    def search_forward(frontier, f_costs, g_costs, parents, reverse=False):
        while frontier:
            f, pos = heapq.heappop(frontier)
            if pos in g_costs:
                continue
            if reverse and pos in g_back:
                return pos
            g = g_costs[pos]
            r, c = pos
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                next_pos = (nr, nc)
                if is_free(grid, next_pos):
                    if next_pos not in g_costs or g + 1 < g_costs[next_pos]:
                        g_costs[next_pos] = g + 1
                        parent_pos = pos
                        if reverse:
                            parent_pos = next_pos
                        parents[next_pos] = parent_pos
                        f = g + 1 + manhattan(next_pos, (goal if not reverse else start))
                        heapq.heappush(frontier, (f, next_pos))
        return None

    g_front = {start: 0}
    f_front = [(manhattan(start, goal), start)]
    p_front = {}
    heapq.heapify(f_front)

    g_back = {goal: 0}
    f_back = [(manhattan(goal, start), goal)]
    p_back = {}
    heapq.heapify(f_back)

    while f_front and f_back:
        meet = search_forward(f_front, g_front, p_front, g_back)
        if meet is not None:
            return build_path(p_front, p_back, meet, start, goal)
        meet = search_forward(f_back, g_back, p_back, g_front, reverse=True)
        if meet is not None:
            return build_path(p_front, p_back, meet, start, goal)

    return []

def build_path(fwd_parents, bwd_parents, meet, start, goal):
    path = []
    curr = meet
    while curr != start:
        path.append(curr)
        curr = fwd_parents[curr]
    path.append(start)
    curr = meet
    while curr != goal:
        curr = bwd_parents[curr]
        path.insert(-1, curr)
    path.reverse()
    return path
