        if not frontier:
            return None
        cost, curr = heapq.heappop(frontier)
        if curr in other_g:
            return cost, curr
        if curr in g and g[curr] <= cost:
            return None
        g[curr] = cost
        for next_cell in neighbors(*curr):
            new_cost = cost + 1
            if next_cell not in g or new_cost < g[next_cell]:
                parents[next_cell] = curr
                h = manhattan(next_cell, goal)
                heapq.heappush(frontier, (new_cost + h, next_cell))
        return None

    def reconstruct_path(parents1, parents2, meeting_point):
        path1, path2 = [], []
        curr = meeting_point
        while curr is not None:
            path1.append(curr)
            curr = parents1.get(curr)
        path1.reverse()
        curr = meeting_point
        while curr is not None:
            path2.append(curr)
            curr = parents2.get(curr)
        return path1 + path2[1:]

