        if heuristic_search(goal, start, backward_g, backward_parent, forward_g):
            break
        if forward_g.get(meeting, float('inf')) + backward_g.get(meeting, float('inf')) > min(
            forward_g.get(current, float('inf')) + backward_g.get(current, float('inf')) for current in set(forward_g) | set(backward_g)
        ):
            return []

    if meeting is None:
        return []

    path = reconstruct_path(start, meeting, forward_parent)
    path += reconstruct_path(meeting, goal, backward_parent)[::-1]
    return path

def reconstruct_path(start, end, parent_dict):
    path = []
    current = end
    while current != start:
        path.append(current)
        current = parent_dict[current]
    path.append(start)
    return path[::-1]
