def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])

    # Check if start or goal is a wall
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    # Special case: start is goal and cell is free
    if start == goal:
        return [start]

    # Initialize level and parent arrays
    level = [[-1] * cols for _ in range(rows)]
    parent = [[None] * cols for _ in range(rows)]

    # Set level of start to 0
    level[start[0]][start[1]] = 0

    def neighbors(r, c):
        moves = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # Right, Down, Left, Up
        for dr, dc in moves:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                yield nr, nc

    # BFS using level array
    current_level = 0
    while True:
        updated = False
        for r in range(rows):
            for c in range(cols):
                if level[r][c] == current_level:
                    for nr, nc in neighbors(r, c):
                        if level[nr][nc] == -1:
                            level[nr][nc] = current_level + 1
                            parent[nr][nc] = (r, c)
                            updated = True
        if not updated or level[goal[0]][goal[1]] != -1:
            break
        current_level += 1

    # If goal is unreachable
    if level[goal[0]][goal[1]] == -1:
        return []

    # Reconstruct path from start to goal
    path = []
    curr = goal
    while curr != start:
        path.append(curr)
        curr = parent[curr[0]][curr[1]]
    path.append(start)
    path.reverse()
    return path
