def solve(grid, start, goal):
    if start == goal:
        return [start]
    if not is_valid(grid, start) or not is_valid(grid, goal):
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1,0), (1,0), (0,-1), (0,1)]

    def is_valid(pos):
        r, c = pos
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def manhattan(a, b):
        return abs(a[0]-b[0]) + abs(a[1]-b[1])

    def a_star(queue, g, parents, came_from_start, other_g, goal_pos, other_pos, start_pos):
        f, g_val, current = heapq.heappop(queue)
        if current in other_g:
            return True, g_val + other_g[current], current
        if f >= other_g.get(best_meet, float('inf')):
            return False, float('inf'), None
        for dr, dc in directions:
            neighbor = (current[0]+dr, current[1]+dc)
            if is_valid(neighbor) and g.get(neighbor, float('inf')) > g_val + 1:
                new_g = g_val + 1
                if neighbor not in g or new_g < g[neighbor]:
                    g[neighbor] = new_g
                    parents[neighbor] = current
                    h = manhattan(neighbor, goal_pos)
                    heapq.heappush(queue, (new_g + h, new_g, neighbor))
        return False, float('inf'), None

    forward_queue = [(manhattan(start, goal), 0, start)]
    backward_queue = [(manhattan(goal, start), 0, goal)]
    forward_g = {start: 0}
    backward_g = {goal: 0}
    forward_parents = {}
    backward_parents = {}
    best_meet = float('inf')
    meet_node = None

    while forward_queue and backward_queue and forward_queue[0][0] < best_meet and backward_queue[0][0] < best_meet:
        found, cost, node = a_star(forward_queue, forward_g, forward_parents, True, backward_g, goal, backward_g, start)
        if found:
            best_meet = cost
            meet_node = node
        if forward_queue and backward_queue and forward_queue[0][0] < best_meet and backward_queue[0][0] < best_meet:
            found, cost, node = a_star(backward_queue, backward_g, backward_parents, False, forward_g, start, forward_g, goal)
            if found:
                best_meet = min(best_meet, cost)
                meet_node = node

    if best_meet == float('inf'):
        return []

    path = []
    current = meet_node
    while current in backward_parents:
        path.append(current)
        current = backward_parents[current]
    path.reverse()
    current = forward_parents.get(meet_node, start)
    while current != start:
        path.append(current)
        current = forward_parents[current]
    path.append(start)
    return path

