import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]

    if not is_free(grid, start) or not is_free(grid, goal):
        return []

    def is_free(grid, pos):
        row, col = pos
        return 0 <= row < len(grid) and 0 <= col < len(grid[row]) and grid[row][col] == '.'

    def neighbors(pos):
        row, col = pos
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = row + dr, col + dc
            if is_free(grid, (nr, nc)):
                yield (nr, nc)

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def a_star(start, goal, forward=True):
        g = {start: 0}
        f = {start: manhattan(start, goal)}
        heap = [(f[start], start)]
        parent = {}

        while heap:
            _, current = heapq.heappop(heap)
            if current in g and g[current] < f.get(current, float('inf')):
                continue

            for next_node in neighbors(current):
                new_g = g[current] + 1
                if next_node not in g or new_g < g[next_node]:
                    g[next_node] = new_g
                    f[next_node] = new_g + manhattan(next_node, goal)
                    parent[next_node] = current
                    heapq.heappush(heap, (f[next_node], next_node))
        return g, parent

    def reconstruct_path(parent1, parent2, start, goal, meet):
        path = []
        current = meet
        while current != start:
            path.insert(0, current)
            current = parent1[current]
        path.insert(0, start)
        current = meet
        while current != goal:
            path.append(parent2[current])
            current = parent2[current]
        return path

    # Bidirectional A* search
    g1, parent1 = a_star(start, goal, forward=True)
    g2, parent2 = a_star(goal, start, forward=False)

    best_meeting_cost = float('inf')
    best_meet = None
    h1_heap = [(manhattan(start, goal), start)]
    h2_heap = [(manhattan(goal, start), goal)]
    f1 = {start: manhattan(start, goal)}
    f2 = {goal: manhattan(goal, start)}
    g1_dict = {start: 0}
    g2_dict = {goal: 0}
    parent1_dict = {}
    parent2_dict = {}

    while h1_heap and h2_heap and min(f1[h1_heap[0][0]], f2[h2_heap[0][0]]) < best_meeting_cost:
        # Expand forward
        if f1[h1_heap[0][1]] == h1_heap[0][0]:
            _, current = heapq.heappop(h1_heap)
            if current in g2_dict:
                if g1_dict[current] + g2_dict[current] < best_meeting_cost:
                    best_meeting_cost = g1_dict[current] + g2_dict[current]
                    best_meet = current
            for next_node in neighbors(current):
                new_g = g1_dict.get(current, float('inf')) + 1
                new_f = new_g + manhattan(next_node, goal)
                if next_node not in g1_dict or new_g < g1_dict[next_node]:
                    g1_dict[next_node] = new_g
                    f1[next_node] = new_f
                    heapq.heappush(h1_heap, (new_f, next_node))
                    parent1_dict[next_node] = current
        else:
            heapq.heappop(h1_heap)

        # Expand backward
        if f2[h2_heap[0][1]] == h2_heap[0][0]:
            _, current = heapq.heappop(h2_heap)
            if current in g1_dict:
                if g1_dict[current] + g2_dict[current] < best_meeting_cost:
                    best_meeting_cost = g1_dict[current] + g2_dict[current]
                    best_meet = current
            for next_node in neighbors(current):
                new_g = g2_dict.get(current, float('inf')) + 1
                new_f = new_g + manhattan(next_node, start)
                if next_node not in g2_dict or new_g < g2_dict[next_node]:
                    g2_dict[next_node] = new_g
                    f2[next_node] = new_f
                    heapq.heappush(h2_heap, (new_f, next_node))
                    parent2_dict[next_node] = current
        else:
            heapq.heappop(h2_heap)

    if best_meet is None:
        return []

    return reconstruct_path(parent1_dict, parent2_dict, start, goal, best_meet)
