def solve(grid, start, goal):
    if start == goal:
        if is_valid(grid, *start):
            return [start]
        else:
            return []

    rows = len(grid)
    cols = len(grid[0])

    directions = [(-1,0), (1,0), (0,-1), (0,1)]

    def is_valid(r, c):
        return (0 <= r < rows and 0 <= c < cols and grid[r][c] == '.')

    def dfs(limit):
        visited = {start: 0}
        stack = [(start, 0)]

        while stack:
            (r, c), depth = stack.pop()

            if (r, c) == goal:
                return True, visited

            if depth >= limit:
                continue

            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc):
                    if (nr, nc) not in visited or visited[(nr, nc)] > depth + 1:
                        visited[(nr, nc)] = depth + 1
                        stack.append(((nr, nc), depth + 1))

        return False, visited

    for depth in range(rows * cols + 1):
        found, best_depth = dfs(depth)
        if found:
            r, c = goal
            path = [ (r, c) ]
            while (r, c) != start:
                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    if (nr, nc) in best_depth and best_depth[(nr, nc)] == best_depth[(r, c)] - 1:
                        r, c = nr, nc
                        path.append((r, c))
                        break
            return path[::-1]

    return []
