                    front_queue.append(next_cell)
                    if next_cell in back_parent_ref:
                        return join_paths(front_parent, back_parent_ref, next_cell, start, goal)
        return None

    def join_paths(front_parent, back_parent, meeting_point, start, goal):
        path = []
        curr = meeting_point
        while curr != start:
            path.append(curr)
            curr = front_parent[curr]
        path.append(start)
        path.reverse()
        curr = meeting_point
        while curr != goal:
            curr = back_parent[curr]
            path.append(curr)
        return path

    front_queue = deque([start])
    back_queue = deque([goal])
    front_parent = {start: None}
    back_parent = {goal: None}

    while front_queue and back_queue:
        found = False
        level_size = len(front_queue)
        for _ in range(level_size):
            node = front_queue.popleft()
            result = bfs(node, back_parent, front_queue, front_parent, back_parent)
            if result:
                return result
        if found:
            break
        level_size = len(back_queue)
        for _ in range(level_size):
            node = back_queue.popleft()
            result = bfs(node, front_parent, back_queue, back_parent, front_parent)
            if result:
