def solve(grid, start, goal):
    if (
        not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])) or
        not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])) or
        grid[start[0]][start[1]] == '#' or
        grid[goal[0]][goal[1]] == '#'
    ):
        return []

    if start == goal:
        return [start]

    # Directions: up, down, left, right
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]

    def bfs_step(queue, visited, parents, other_visited):
        level = len(queue)
        for _ in range(level):
            current = queue.popleft()
            for dr, dc in dirs:
                neighbor = (current[0]+dr, current[1]+dc)
                if (
                    0 <= neighbor[0] < len(grid) and
                    0 <= neighbor[1] < len(grid[0]) and
                    grid[neighbor[0]][neighbor[1]] == '.' and
                    neighbor not in visited
                ):
                    if neighbor in other_visited:
                        # Found meeting point
                        return neighbor
                    visited.add(neighbor)
                    parents[neighbor] = current
                    queue.append(neighbor)
        return None

    # Initialize BFS from start and goal
    start_queue = deque([start])
    goal_queue = deque([goal])
    start_visited = {start}
    goal_visited = {goal}
    start_parents = {start: None}
    goal_parents = {goal: None}

    while start_queue and goal_queue:
        # Alternate BFS from start
        meeting_point = bfs_step(start_queue, start_visited, start_parents, goal_visited)
        if meeting_point is not None:
            return build_path(meeting_point, start_parents, goal_parents)
        # Alternate BFS from goal
        meeting_point = bfs_step(goal_queue, goal_visited, goal_parents, start_visited)
        if meeting_point is not None:
            return build_path(meeting_point, start_parents, goal_parents)

    return []

def build_path(meet, start_parents, goal_parents):
    path = [meet]
    current = meet
    while start_parents[current] is not None:
        current = start_parents[current]
        path.insert(0, current)
    current = meet
    while goal_parents[current] is not None:
        current = goal_parents[current]
        path.append(current)
    return path
