            r, c = queue.popleft()
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if (0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and
                    grid[nr][nc] == '.' and (nr, nc) not in parents and (nr, nc) not in other_parents):
                    queue.append((nr, nc))
                    parents[(nr, nc)] = (r, c)

    def join_paths(forward_parents, backward_parents):
        meeting = next(pos for pos in forward_parents if pos in backward_parents)
        path = [meeting]
        r, c = meeting
        while (r, c) != forward_parents[(r, c)]:
            r, c = forward_parents[(r, c)]
            path.append((r, c))
        r, c = meeting
        while (r, c) != backward_parents[(r, c)]:
            r, c = backward_parents[(r, c)]
            path.append((r, c))
        return path[::-1]

    forward_queue = deque([start])
    backward_queue = deque([goal])
    forward_parents = {start: None}
    backward_parents = {goal: None}

    while forward_queue and backward_queue:
        bfs_step(forward_queue, forward_parents, backward_parents)
        if any(pos in forward_parents for pos in backward_parents):
            return join_paths(forward_parents, backward_parents)
        if not backward_queue:
            break
        bfs_step(backward_queue, backward_parents, forward_parents)
        if any(pos in backward_parents for pos in forward_parents):
            return join_paths(forward_parents, backward_parents)
        if not forward_queue:
            break

    return []
