            for _ in range(level_size):
                current = queue.popleft()
                if current == goal:
                    return (True, parent)
                for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    ny, nx = current[0] + dy, current[1] + dx
                    if 0 <= ny < rows and 0 <= nx < cols and grid[ny][nx] == '.' and (ny, nx) not in parent:
                        parent[(ny, nx)] = current
                        queue.append((ny, nx))
            if is_forward:
                if queue:
                    yield 'forward'
            else:
                if queue:
                    yield 'backward'
        return (False, {})

    forward_parent = {}
    backward_parent = {}

    forward_queue = deque([start])
    forward_visited = set([start])

    backward_queue = deque([goal])
    backward_visited = set([goal])

    meeting = None

    while forward_queue or backward_queue:
        # Expand forward one level
        level_size = len(forward_queue)
        for _ in range(level_size):
            current = forward_queue.popleft()
            for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                ny, nx = current[0] + dy, current[1] + dx
                if 0 <= ny < rows and 0 <= nx < cols and grid[ny][nx] == '.':
                    if (ny, nx) not in forward_visited:
                        forward_visited.add((ny, nx))
                        forward_parent[(ny, nx)] = current
                        forward_queue.append((ny, nx))
                        if (ny, nx) in backward_visited:
                            meeting = (ny, nx)
                            break
            if meeting:
                break
        if meeting:
            break

        # Expand backward one level
        level_size = len(backward_queue)
        for _ in range(level_size):
            current = backward_queue.popleft()
            for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                ny, nx = current[0] + dy, current[1] + dx
                if 0 <= ny < rows and 0 <= nx < cols and grid[ny][nx] == '.':
                    if (ny, nx) not in backward_visited:
                        backward_visited.add((ny, nx))
                        backward_parent[(ny, nx)] = current
                        backward_queue.append((ny, nx))
                        if (ny, nx) in forward_visited:
                            meeting = (ny, nx)
                            break
            if meeting:
                break

    if meeting:
        path = []
        cur = meeting
        while cur is not None:
            path.append(cur)
            cur = forward_parent.get(cur)
        path.reverse()
        cur = backward_parent.get(meeting)
        while cur is not None:
            path.append(cur)
            cur = backward_parent.get(cur)
        if path[0] == start:
            return path
        else:
            return path[::-1]
    return []

