import heapq

def solve(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def is_wall(r, c):
        return not (0 <= r < rows and 0 <= c < cols) or grid[r][c] == '#'

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def horizontal_jump(r, c, d):
        while True:
            c += d
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            # Check if there's a forced vertical jump
            if not is_valid(r - 1, c) and is_valid(r + 1, c) or \
               not is_valid(r + 1, c) and is_valid(r - 1, c):
                return (r, c)
            if is_valid(r - 1, c) and is_valid(r + 1, c) and not horizontal_jump(r - 1, c, d) or \
               is_valid(r - 1, c) and is_valid(r + 1, c) and not horizontal_jump(r + 1, c, d):
                return (r, c)

    def vertical_jump(r, c, d):
        while True:
            r += d
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            # Check if there's a forced horizontal jump
            for dc in [-1, 1]:
                hj = horizontal_jump(r, c, dc)
                if hj:
                    return (r, c)
            if is_valid(r, c - 1) and is_valid(r, c + 1) and not vertical_jump(r, c - 1, d) or \
               is_valid(r, c - 1) and is_valid(r, c + 1) and not vertical_jump(r, c + 1, d):
                return (r, c)

    def get_jump_points(r, c):
        jump_points = []
        # Up
        jp = vertical_jump(r, c, -1)
        if jp:
            jump_points.append(jp)
        # Down
        jp = vertical_jump(r, c, 1)
        if jp:
            jump_points.append(jp)
        # Left
        jp = horizontal_jump(r, c, -1)
        if jp:
            jump_points.append(jp)
        # Right
        jp = horizontal_jump(r, c, 1)
        if jp:
            jump_points.append(jp)
        return jump_points

    def in_bounds(r, c):
        return 0 <= r < rows and 0 <= c < cols

    if not is_valid(*start) or not is_valid(*goal):
        return []

    if start == goal:
        return [start]

    open_set = []
    heapq.heappush(open_set, (manhattan(start, goal), 0, start, None))
    came_from = {}
    g_scores = {start: 0}

    while open_set:
        f, g, current, parent = heapq.heappop(open_set)

        if current in came_from:
            continue

        came_from[current] = parent

        if current == goal:
            # Reconstruct path
            path = []
            while current:
                path.append(current)
                current = came_from.get(current)
            return path[::-1]

        for np in get_jump_points(*current):
            if in_bounds(*np) and grid[np[0]][np[1]] == '.':
                new_g = g + manhattan(current, np)
                if np not in g_scores or new_g < g_scores.get(np, float('inf')):
                    g_scores[np] = new_g
                    heapq.heappush(open_set, (new_g + manhattan(np, goal), new_g, np, current))

    return []
