        r, c = pos
        while is_valid(r + drow, c):
            r += drow
            if (r, c) == goal:
                return r, c
            if jump_horizontal((r, c), -1) or jump_horizontal((r, c), 1):
                return r, c
        return None

    def neighbors(pos, dir_from_parent=None):
        dirs = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        result = []
        for dr, dc in dirs:
            next_pos = (pos[0] + dr, pos[1] + dc)
            if is_valid(next_pos[0], next_pos[1]):
                if not dir_from_parent:
                    result.append(next_pos)
                elif (not (dr or dc) or (dr == dir_from_parent[0] or dc == dir_from_parent[1])):
