import heapq

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and grid[start[0]][start[1]] == '.'):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0]) and grid[goal[0]][goal[1]] == '.'):
        return []
    if start == goal:
        return [start]

    rows = len(grid)
    cols = len(grid[0])

    def manhattan(pos):
        return abs(pos[0] - goal[0]) + abs(pos[1] - goal[1])

    def valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def jump_horizontal(pos, direction):
        r, c = pos
        dc = 1 if direction else -1
        while valid(r, c + dc):
            c += dc
            new_pos = (r, c)
            if new_pos == goal:
                return new_pos
            if (not valid(r, c + dc) or (valid(r - 1, c) and grid[r - 1][c] == '.') or (valid(r + 1, c) and grid[r + 1][c] == '.')):
                return new_pos
        return None

    def jump_vertical(pos, direction):
        r, c = pos
        dr = 1 if direction else -1
        while valid(r + dr, c):
            r += dr
            new_pos = (r, c)
            if new_pos == goal:
                return new_pos
            if (not valid(r + dr, c) or jump_horizontal(new_pos, 0) or jump_horizontal(new_pos, 1)):
                return new_pos
        return None

    def jp_search():
        heap = [(manhattan(start), 0, start, None)]
        heapq.heapify(heap)
        visited = {start}
        parent = {}

        while heap:
            f, g, pos, prev = heapq.heappop(heap)
            if pos == goal:
                path = []
                while pos:
                    path.append(pos)
                    pos = parent[pos]
                return path[::-1]
            for d in range(4):  # 0 - up, 1 - down, 2 - left, 3 - right
                if d in [0, 1]:
                    jump = jump_vertical(pos, d % 2)
                else:
                    jump = jump_horizontal(pos, (d - 2) % 2)
                if jump and jump not in visited:
                    visited.add(jump)
                    parent[jump] = pos
                    new_g = g + abs(jump[0] - pos[0]) + abs(jump[1] - pos[1])
                    heapq.heappush(heap, (new_g + manhattan(jump), new_g, jump, pos))
        return []

    path = jp_search()
    if not path:
        return []

    res = [path[0]]
    for i in range(1, len(path)):
        r1, c1 = path[i - 1]
        r2, c2 = path[i]
        dr, dc = r2 - r1, c2 - c1
        if dr != 0:
            for s in range(1, abs(dr)):
                r = r1 + (1 if dr > 0 else -1) * s
                c = c1
                res.append((r, c))
        if dc != 0:
            for s in range(1, abs(dc)):
                r = r1
                c = c1 + (1 if dc > 0 else -1) * s
                res.append((r, c))
        res.append(path[i])
    return res
