import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start] if is_free(grid, *start) else []

    if not is_free(grid, *start) or not is_free(grid, *goal):
        return []

    rows, cols = len(grid), len(grid[0])
    directions = {(-1, 0): 'up', (1, 0): 'down', (0, -1): 'left', (0, 1): 'right'}
    parent = {}
    g_scores = {}
    heap = []

    init_g = 0
    g_scores[start] = init_g
    heapq.heappush(heap, (manhattan(*start, *goal) + init_g, init_g, start, None))

    while heap:
        f, g, current, prev = heapq.heappop(heap)
        if current == goal:
            return reconstruct_path(parent, start, goal)

        if current in g_scores and g_scores[current] < g:
            continue

        for d in directions:
            dx, dy = d
            jump = jump_point(grid, current, d, goal)
            if jump and is_free(grid, *jump):
                if jump not in g_scores or g + step_count(current, jump) < g_scores[jump]:
                    g_new = g + step_count(current, jump)
                    g_scores[jump] = g_new
                    parent[jump] = current
                    h = manhattan(*jump, *goal)
                    heapq.heappush(heap, (g_new + h, g_new, jump, current))
    return []

def is_free(grid, r, c):
    return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

def manhattan(r1, c1, r2, c2):
    return abs(r1 - r2) + abs(c1 - c2)

def step_count(from_cell, to_cell):
    return manhattan(*from_cell, *to_cell)

def jump_point(grid, current, direction, goal):
    r, c = current
    dr, dc = direction
    steps = 0

    while True:
        r += dr
        c += dc
        steps += 1
        if not is_free(grid, r, c):
            return None
        if (r, c) == goal:
            return (r, c)

        if direction in [(-1, 0), (1, 0)]:  # Horizontal
            if not is_free(grid, r - 1, c) or not is_free(grid, r + 1, c):
                return (r, c)
            if (is_free(grid, r, c - 1) and not is_free(grid, r - 1, c - 1)) or \
               (is_free(grid, r, c + 1) and not is_free(grid, r - 1, c + 1)):
                return (r, c)
        else:  # Vertical
            if not is_free(grid, r, c - 1) or not is_free(grid, r, c + 1):
                return (r, c)
            jump = jump_point(grid, (r, c), (0, -1), goal)
            if jump is not None:
                return (r, c)
            jump = jump_point(grid, (r, c), (0, 1), goal)
            if jump is not None:
                return (r, c)

def reconstruct_path(parent, start, goal):
    path = [goal]
    current = goal
    while current != start:
        current = parent.get(current)
        if current is None:
            return []
        path.append(current)
    return path[::-1]
