import heapq

def solve(grid, start, goal):
    if (
        not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])) or
        not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])) or
        grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#'
    ):
        return []

    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right
    parent = {}
    open_set = []
    heapq.heappush(open_set, (manhattan(start, goal), 0, start))
    visited = set()

    while open_set:
        _, g, current = heapq.heappop(open_set)
        if current in visited:
            continue
        visited.add(current)

        if current == goal:
            return reconstruct_path(parent, start, goal)

        for dx, dy in directions:
            if dx == 0 or dy == 0:  # Horizontal or vertical move
                jump = jump_search(grid, current, dx, dy, goal)
                if jump and jump not in visited and jump not in parent:
                    parent[jump] = current
                    new_g = g + distance(current, jump)
                    heapq.heappush(open_set, (new_g + manhattan(jump, goal), new_g, jump))

    return []

def jump_search(grid, pos, dx, dy, goal):
    x, y = pos
    while 0 <= x < len(grid) and 0 <= y < len(grid[0]):
        if grid[x][y] == '#':
            return None
        if (x, y) == goal:
            return (x, y)
        if dx != 0:  # Horizontal jump
            if (
                0 <= x + dx < len(grid) and 0 <= y - 1 < len(grid[0]) and
                grid[x + dx][y - 1] == '.' and grid[x + dx][y] == '#'
            ) or (
                0 <= x + dx < len(grid) and 0 <= y + 1 < len(grid[0]) and
                grid[x + dx][y + 1] == '.' and grid[x + dx][y] == '#'
            ):
                return (x, y)
        else:  # Vertical jump
            # Check horizontal neighbors without recursion to avoid stack overflow
            if 0 <= y - 1 < len(grid[0]) and grid[x][y - 1] == '.' and grid[x][y] == '.':
                # Left
                nx_l = x
                ny_l = y - 1
                while 0 <= ny_l and grid[x][ny_l] == '.':
                    if jump_search(grid, (x, ny_l), 1, 0, goal) or jump_search(grid, (x, ny_l), -1, 0, goal):
                        break
                    ny_l -= 1
                else:
                    return (x, y)
            if 0 <= y + 1 < len(grid[0]) and grid[x][y + 1] == '.' and grid[x][y] == '.':
                # Right
                nx_r = x
                ny_r = y + 1
                while ny_r < len(grid[0]) and grid[x][ny_r] == '.':
                    if jump_search(grid, (x, ny_r), 1, 0, goal) or jump_search(grid, (x, ny_r), -1, 0, goal):
                        break
                    ny_r += 1
                else:
                    return (x, y)
        x += dx
        y += dy
    return None

def manhattan(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])

def distance(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])

def reconstruct_path(parent, start, goal):
    path = [goal]
    while path[-1] != start:
        path.append(parent[path[-1]])
    return path[::-1]
