                return None
            if (r, c) == goal:
                return (r, c)
            if not is_valid(r - 1, c) or not is_valid(r + 1, c):
                return (r, c)
            if not is_valid(r, c + dc):
                return None

    def vertical_jump(r, c, dr):
        while True:
            r += dr
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            if not is_valid(r, c - 1) or not is_valid(r, c + 1):
                return (r, c)
            # Check if any horizontal jump from here finds a jump point
            left = horizontal_jump(r, c, -1)
            right = horizontal_jump(r, c, 1)
            if left or right:
                return (r, c)

    def jps():
        open_set = []
        heapq.heappush(open_set, (0, start))
        came_from = {}
        g_scores = {start: 0}

        while open_set:
            f, current = heapq.heappop(open_set)
            if current == goal:
                break
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                next_cell = current[0] + dr, current[1] + dc
                if is_valid(*next_cell):
                    jump = next_cell
                    if dr != 0:
                        jump_res = vertical_jump(current[0], current[1], dr)
                    else:
                        jump_res = horizontal_jump(current[0], current[1], dc)
                    if jump_res is None:
                        continue
                    jump = jump_res
                else:
                    continue

                if jump not in g_scores or g_scores[current] + 1 < g_scores[jump]:
                    g_scores[jump] = g_scores[current] + 1
                    h = abs(jump[0] - goal[0]) + abs(jump[1] - goal[1])
                    heapq.heappush(open_set, (g_scores[jump] + h, jump))
                    came_from[jump] = current

        if goal not in came_from:
            return []
        # Reconstruct path from came_from
        path = [goal]
        while path[-1] != start:
            path.append(came_from[path[-1]])
        return path[::-1]

    path = jps()
    if not path:
        return []

    # Interpolate full path
    result = [path[0]]
    for i in range(1, len(path)):
        r1, c1 = path[i - 1]
        r2, c2 = path[i]
        # Move vertically
        if r1 < r2:
            for r in range(r1 + 1, r2 + 1):
                result.append((r, c1))
        elif r1 > r2:
            for r in range(r1 - 1, r2 - 1, -1):
                result.append((r, c1))
        # Move horizontally
        elif c1 < c2:
            for c in range(c1 + 1, c2 + 1):
                result.append((r2, c))
        elif c1 > c2:
            for c in range(c1 - 1, c2 - 1, -1):
                result.append((r2, c))
    return result
