        return (r, c) == goal

    def jump_horizontal(r, c, dr, dc, g):
        if is_wall(r, c):
            return None
        while True:
            next_pos = (r, c)
            if is_goal(r, c):
                return next_pos
            # Check for forced neighbor (up or down)
            for dy in (-1, 1):
                nr, nc = r + dy, c
                if not is_wall(nr, nc):
                    pr, pc = r - dr, c - dc
                    if is_wall(pr, pc):
                        return next_pos
            # Check if next step is wall or edge
            nr, nc = r + dr, c + dc
            if not (0 <= nr < rows and 0 <= nc < cols) or is_wall(nr, nc):
                return None
            r, c = nr, nc
            g += 1

    def jump_vertical(r, c, dr, dc, g):
        if is_wall(r, c):
            return None
        while True:
            next_pos = (r, c)
            if is_goal(r, c):
                return next_pos
            # Check for horizontal jump in any direction
            for dc2 in (-1, 1):
                if jump_horizontal(r, c, 0, dc2, 0):
                    return next_pos
            # Check if next step is wall or edge
            nr, nc = r + dr, c + dc
            if not (0 <= nr < rows and 0 <= nc < cols) or is_wall(nr, nc):
                return None
            r, c = nr, nc
            g += 1

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while heap:
        f, g, current, parent = heapq.heappop(heap)
        if current == goal:
            parent_map[current] = parent
            break
        if current in visited:
            continue
        visited.add(current)
        parent_map[current] = parent

        r, c = current
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < rows and 0 <= nc < cols) or is_wall(nr, nc):
                continue
            if dr in (1, -1) and dc == 0:
                jump_cell = jump_vertical(nr, nc, dr, 0, g + 1)
            elif dc in (1, -1) and dr == 0:
                jump_cell = jump_horizontal(r, nc, 0, dc, g + 1)
            else:
                continue
            if not jump_cell or jump_cell in visited:
                continue
            new_g = g + manhattan(current, jump_cell)
            heapq.heappush(heap, (new_g + manhattan(jump_cell, goal), new_g, jump_cell, current))

    # Reconstruct the jump path
    path = []
    current = goal
    while current and current in parent_map:
        path.append(current)
        current = parent_map[current]
    if path and path[-1] == start:
        path.reverse()
        final_path = [start]
        for i in range(1, len(path)):
            p1, p2 = path[i - 1], path[i]
            dr, dc = p2[0] - p1[0], p2[1] - p1[1]
            r, c = p1
            while (r, c) != p2:
                r += dr
                c += dc
                final_path.append((r, c))
        return final_path
    return []

