        return r < 0 or c < 0 or r >= len(grid) or c >= len(grid[0]) or grid[r][c] == '#'

    def is_goal(r, c):
        return (r, c) == goal

    def horizontal_jump(r, c, dr, dc):
        while True:
            c += dc
            if is_wall(r, c):
                return None
            if is_goal(r, c):
                return (r, c)
            if dc > 0:
                ndc = 1
            else:
                ndc = -1
            nr = r - 1
            if not is_wall(nr, c) and is_wall(r, c - ndc):
                return (r, c)
            nr = r + 1
            if not is_wall(nr, c) and is_wall(r, c - ndc):
                return (r, c)

    def vertical_jump(r, c, dr, dc):
        while True:
            r += dr
            if is_wall(r, c):
                return None
            if is_goal(r, c):
                return (r, c)
            if dr > 0:
                ndr = 1
            else:
                ndr = -1
            nc = c - 1
            if not is_wall(r, nc) and is_wall(r - ndr, nc):
                return (r, c)
            nc = c + 1
            if not is_wall(r, nc) and is_wall(r - ndr, nc):
                return (r, c)

    def get_jump_neighbors(r, c):
        neighbors = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            new_r = r + dr
            new_c = c + dc
            if not is_wall(new_r, new_c):
                if dr != 0:
                    jp = horizontal_jump(new_r, new_c, dr, dc)
                else:
                    jp = vertical_jump(new_r, new_c, dr, dc)
                if jp:
                    neighbors.append((jp, (new_r, new_c)))
        return neighbors

    parent = {}
    g = {start: 0}
    f = {start: manhattan(start, goal)}
    open_set = [(f[start], len(g), start)]

    while open_set:
        _, _, current = heapq.heappop(open_set)
        if current == goal:
            break
        for jump_point, step in get_jump_neighbors(*current):
            step_cost = 1
            new_g = g[current] + step_cost
            if jump_point not in g or new_g < g.get(jump_point, float('inf')):
                g[jump_point] = new_g
                f[jump_point] = new_g + manhattan(jump_point, goal)
                heapq.heappush(open_set, (f[jump_point], len(g), jump_point))
                parent[jump_point] = (current, step)

    if goal not in parent:
        return []

    path = [goal]
    current = goal
    while current != start:
        if current not in parent:
            return []
        prev, step = parent[current]
        path.append(prev)
        current = prev

    # Fill in straight-line cells
    full_path = []
    for i in range(len(path) - 1):
        r1, c1 = path[i]
        r2, c2 = path[i+1]
        if r1 != r2:
            step = 1 if r2 > r1 else -1
            for r in range(r1, r2, step):
                full_path.append((r, c1))
        else:
            step = 1 if c2 > c1 else -1
            for c in range(c1, c2, step):
                full_path.append((r1, c))
    full_path.append(goal)

