            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            if not is_valid(r - dc, c):
                return (r, c)
            if not is_valid(r + (2 * dr), c):
                return (r, c)
            if not is_valid(r, c + dc):
                return None
            if horizontal_helper(grid, (r, c), (dr,)):
                return (r, c)

