            if (r, c) == goal:
                return (r, c)
            # A vertical jump point is found if at least one horizontal jump reveals a jump point
            if not is_valid(r, c+1) or not is_valid(r, c-1):
                return (r, c)
            left_jump = horizontal_jump(r, c, -1, (r, c))
            right_jump = horizontal_jump(r, c, 1, (r, c))
