                return (r, c)
            up_jump = vertical_jump(r, c, -1, (r, c))
            down_jump = vertical_jump(r, c, 1, (r, c))
            if up_jump or down_jump:
                return (r, c)

    def get_neighbors(r, c, prev):
        jump_points = []

        # Up
        up = vertical_jump(r, c, -1, (r, c))
        if up and up != prev:
            jump_points.append(up)

        # Down
        down = vertical_jump(r, c, 1, (r, c))
        if down and down != prev:
