            # Check if at a jump point (has a forced neighbor or goal)
            if (not is_free((r + 1, c)) and is_free((r, c - 1)) and not is_free((r + drow, c - 1)) or
                not is_free((r - 1, c)) and is_free((r, c - 1)) and not is_free((r - drow, c - 1)) or
                not is_free((r + 1, c)) and is_free((r, c + 1)) and not is_free((r + drow, c + 1)) or
                not is_free((r - 1, c)) and is_free((r, c + 1)) and not is_free((r - drow, c + 1)) or
                p == goal):
                return p

    def jump_horizontal(grid, pos, dcol, goal):
        r, c = pos
        came_from = (r, c - dcol)
        while True:
            c += dcol
            if not is_free((r, c)):
                return None
            p = (r, c)
            if p == goal:
                return p
            # Check if at a jump point (has a forced neighbor or goal)
            if (not is_free((r, c + 1)) and is_free((r - 1, c)) and not is_free((r - 1, c + dcol)) or
                not is_free((r, c - 1)) and is_free((r - 1, c)) and not is_free((r - 1, c - dcol)) or
                not is_free((r, c + 1)) and is_free((r + 1, c)) and not is_free((r + 1, c + dcol)) or
                not is_free((r, c - 1)) and is_free((r + 1, c)) and not is_free((r + 1, c - dcol)) or
                p == goal):
                return p

    def neighbors(pos):
        r, c = pos
        steps = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        res = []
        for dr, dc in steps:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == '.':
                if (dr != 0 and (dc != 0 or (dc == 0 and dr == -1 * (r - start[0]) and r != start[0])) or 
                    dc != 0 and (dr != 0 or (dr == 0 and dc == -1 * (c - start[1]) and c != start[1]))):
                    res.append((nr, nc))
        return res

    def jump_search(pos, goal, came_from):
        if pos == goal:
            return [pos]
        res = []
        dr = pos[0] - came_from[0]
        dc = pos[1] - came_from[1]
        if dr != 0:
            next_p = jump_vertical(grid, pos, dr, goal)
        else:
            next_p = jump_horizontal(grid, pos, dc, goal)
        if next_p:
            return [pos] + jump_search(next_p, goal, pos)
        return []

    def heuristic(pos, goal):
        return manhattan(pos, goal)

    heap = [(heuristic(start, goal), 0, start, (0, 0))]
    came_from = {start: (0, 0)}
    g = {start: 0}

    while heap:
        f, cost, curr, dir = heapq.heappop(heap)
        if curr == goal:
            path = jump_search(start, curr, (0, 0))
            return path
        for n in neighbors(curr):
            if heuristic(n, curr) != 1:
                continue
            ndr = n[0] - curr[0]
            ndc = n[1] - curr[1]
            next_dir = (ndr, ndc) if n != curr else dir
            jumped = curr
            if ndr != 0:
                jumped = jump_vertical(grid, curr, ndr, goal)
            elif ndc != 0:
                jumped = jump_horizontal(grid, curr, ndc, goal)
            if jumped is not None:
                ng = cost + manhattan(jumped, curr)
                if jumped not in g or ng < g[jumped]:
                    g[jumped] = ng
                    hf = ng + heuristic(jumped, goal)
                    heapq.heappush(heap, (hf, ng, jumped, next_dir))
                    came_from[jumped] = curr
    return []
