        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def heuristic(r1, c1, r2, c2):
        return abs(r1 - r2) + abs(c1 - c2)

    def jump_horizontal(r, c, dr, dc, parent):
        while True:
            r += dr
            c += dc
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            if is_valid(r + 1, c) and not is_valid(r + 1, c + dc):
                return (r, c)
            if is_valid(r - 1, c) and not is_valid(r - 1, c + dc):
                return (r, c)
            if (r, c) == parent:
                return None

    def jump_vertical(r, c, dr, dc, parent):
        while True:
            r += dr
            c += dc
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            if jump_horizontal(r, c, 0, 1, (r, c)) or jump_horizontal(r, c, 0, -1, (r, c)):
                return (r, c)
            if (r, c) == parent:
                return None

    def get_neighbors(r, c):
        directions = [(0, 1, 0, -1), (1, 0, -1, 0)]  # (dr, dc, jump_dir, reverse_dir)
        for dr, dc, _, _ in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                if dr == 0:
                    jump = jump_horizontal(r, c, dr, dc, (r, c))
                else:
                    jump = jump_vertical(r, c, dr, dc, (r, c))
                if jump:
                    yield jump

    open_set = [(heuristic(*start, *goal), heuristic(*start, *goal), start, [start], {start: None})]
    while open_set:
        f, h, current, path, came_from = heapq.heappop(open_set)
        if current == goal:
            return path
        for jump_point in get_neighbors(*current):
            if jump_point not in came_from:
                g = len(path)
                h = heuristic(*jump_point, *goal)
                f = g + h
                new_path = path + [jump_point]
                new_came_from = came_from.copy()
                new_came_from[jump_point] = current
                heapq.heappush(open_set, (f, h, jump_point, new_path, new_came_from))
    return []
