        return [(r+1, c), (r-1, c), (r, c+1), (r, c-1)]

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def jump(grid, p, d, is_horizontal):
        pr, pc = p
        dr, dc = d
        while True:
            pr += dr
            pc += dc
            if not (0 <= pr < len(grid) and 0 <= pc < len(grid[0])) or grid[pr][pc] == '#':
                return None
            if (pr, pc) == goal:
                return (pr, pc)
            if is_horizontal:
                # Check for forced vertical neighbors
                if pr - dr >= 0 and pr + dr < len(grid) and pc >= 0 and pc < len(grid[0]):
                    if grid[pr][pc + dc] == '#' or grid[pr][pc - dc] == '#':
                        return (pr, pc)
            else:
                # Check for horizontal jump points
                for dir in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    if pr + dir[0] >= 0 and pr + dir[0] < len(grid) and pc + dir[1] >= 0 and pc + dir[1] < len(grid[0]):
                        if grid[pr + dir[0]][pc + dir[1]] == '#':
                            return (pr, pc)

    def horizontal_jump(p, d):
        return jump(grid, p, d, True)

    def vertical_jump(p, d):
        return jump(grid, p, d, False)

    def get_jump_points(p):
        jump_points = []
        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        for d in directions:
            step = (p[0] + d[0], p[1] + d[1])
            if 0 <= step[0] < len(grid) and 0 <= step[1] < len(grid[0]) and grid[step[0]][step[1]] == '.':
                if d[0] == 0:
                    j = horizontal_jump(p, d)
                else:
                    j = vertical_jump(p, d)
                if j:
                    jump_points.append(j)
        return jump_points

    def reconstruct_path(came_from, current):
        path = [current]
        while current in came_from:
            current = came_from[current]
            path.append(current)
        path.reverse()
        return path

    heap = [(manhattan(start, goal), start)]
    came_from = {}
    g = {start: 0}
    visited = set()

    while heap:
        _, current = heapq.heappop(heap)
        if current in visited:
            continue
        if current == goal:
            return reconstruct_path(came_from, current)
        visited.add(current)
        for j in get_jump_points(current):
            next_g = g[current] + abs(j[0] - current[0]) + abs(j[1] - current[1])
            if j not in g or next_g < g[j]:
                g[j] = next_g
                heapq.heappush(heap, (g[j] + manhattan(j, goal), j))
                came_from[j] = current
    return []
