    visited = set()
    parent = {}

    while heap:
        f, g, current, prev_dir = heapq.heappop(heap)
        if current in visited:
            continue
        visited.add(current)

        if current == goal:
            return reconstruct_path(parent, start, goal)

        for dx, dy, dir_label in [(0, 1, 'right'), (0, -1, 'left'), (1, 0, 'down'), (-1, 0, 'up')]:
            if dir_label in ['right', 'left']:
                jump_point = horizontal_jump(grid, current, dx, dy, goal, rows, cols)
            else:
                jump_point = vertical_jump(grid, current, dx, dy, goal, rows, cols)
            if jump_point:
                if jump_point not in visited:
                    parent[jump_point] = current
                    new_g = g + manhattan(current, jump_point)
                    heapq.heappush(heap, (manhattan(jump_point, goal) + new_g, new_g, jump_point, dir_label))

    return []

def manhattan(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])

def is_free(grid, pos):
    r, c = pos
    return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

def horizontal_jump(grid, current, dx, dy, goal, rows, cols):
    r, c = current
    while is_free(grid, (r, c)):
        if (r, c) == goal:
            return (r, c)
        if has_forced_neighbor(grid, (r, c), (dx, 0)):
            return (r, c)
        r += dx
        c += dy
    return None

def vertical_jump(grid, current, dx, dy, goal, rows, cols):
    r, c = current
    while is_free(grid, (r, c)):
        if (r, c) == goal:
            return (r, c)
        if any(horizontal_jump(grid, (r, c), 0, 1, goal, rows, cols),
               horizontal_jump(grid, (r, c), 0, -1, goal, rows, cols)):
            return (r, c)
        r += dx
        c += dy
    return None

def has_forced_neighbor(grid, pos, direction):
    dx, dy = direction
    r, c = pos
    r += dx
    c += dy
    if not is_free(grid, (r, c)):
        return False
    if is_free(grid, (r - dx, c - dy)) and grid[r + 1][c] == '#' or grid[r - 1][c] == '#':
        return True
    if is_free(grid, (r - dx, c - dy)) and grid[r][c + 1] == '#' or grid[r][c - 1] == '#':
        return True
    return False

def reconstruct_path(parent, start, goal):
    if goal not in parent:
        return []
    path = [goal]
    while path[-1] != start:
        path.append(parent[path[-1]])
    path.reverse()
    return path
