import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and
            0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    rows = len(grid)
    cols = len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def get_jps_path(parents, start, end):
        path = []
        current = end
        while current:
            path.append(current)
            current = parents.get(current)
        if path[-1] != start:
            return []
        path.reverse()
        return path

    def jump_point_search(start, goal):
        heap = [(0, start)]
        g_scores = {start: 0}
        parents = {}

        while heap:
            _, current = heapq.heappop(heap)
            if current == goal:
                return get_jps_path(parents, start, current)

            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                next_point = jump(current, dx, dy, g_scores, parents, goal)
                if next_point and g_scores[next_point] > g_scores[current] + manhattan(current, next_point):
                    parents[next_point] = current
                    g_scores[next_point] = g_scores[current] + manhattan(current, next_point)
                    heapq.heappush(heap, (g_scores[next_point] + manhattan(next_point, goal), next_point))

        return []

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def jump_horizontal(current, dx, dy, g_scores, parents, goal):
        r, c = current
        steps = 0
        while True:
            r += dx
            c += dy
            steps += 1
            if not is_valid(r, c):
                return None
            next_cell = (r, c)
            if next_cell == goal:
                parents[next_cell] = current
                g_scores[next_cell] = g_scores[current] + steps
                return next_cell
            # Checks for forced vertical
            if (is_valid(r, c - 1) and (not is_valid(r + 1, c - 1) or not is_valid(r - 1, c - 1)) or
                is_valid(r, c + 1) and (not is_valid(r + 1, c + 1) or not is_valid(r - 1, c + 1))):
                parents[next_cell] = current
                g_scores[next_cell] = g_scores[current] + steps
                return next_cell
            # Check jump in both horizontal directions
            if jump_vertical(next_cell, 1, 0, g_scores, parents, goal) or \
               jump_vertical(next_cell, -1, 0, g_scores, parents, goal):
                return next_cell
            if next_cell in g_scores:
                break
        return None

    def jump_vertical(current, dx, dy, g_scores, parents, goal):
        r, c = current
        steps = 0
        while True:
            r += dx
            c += dy
            steps += 1
            if not is_valid(r, c):
                return None
            next_cell = (r, c)
            if next_cell == goal:
                parents[next_cell] = current
                g_scores[next_cell] = g_scores[current] + steps
                return next_cell
            # Check for forced horizontal
            if (is_valid(r - 1, c) and (not is_valid(r - 1, c - 1) or not is_valid(r - 1, c + 1)) or
                is_valid(r + 1, c) and (not is_valid(r + 1, c - 1) or not is_valid(r + 1, c + 1))):
                parents[next_cell] = current
                g_scores[next_cell] = g_scores[current] + steps
                return next_cell
            # Check jump in vertical directions
            if jump_horizontal(next_cell, 1, 0, g_scores, parents, goal) or \
               jump_horizontal(next_cell, -1, 0, g_scores, parents, goal):
                return next_cell
            if next_cell in g_scores:
                break
        return None

    def jump(current, dx, dy, g_scores, parents, goal):
        if (dx == 0 and dy != 0) or (dy == 0 and dx != 0):
            return jump_horizontal(current, dx, dy, g_scores, parents, goal)
        else:
            return jump_vertical(current, dx, dy, g_scores, parents, goal)

    result = jump_point_search(start, goal)
    if not result:
        return []

    # Expand to one-step path
    expanded = [result[0]]
    for i in range(1, len(result)):
        x1, y1 = result[i - 1]
        x2, y2 = result[i]
        if x1 != x2:
            step = 1 if x2 > x1 else -1
            for x in range(x1 + step, x2, step):
                expanded.append((x, y1))
        elif y1 != y2:
            step = 1 if y2 > y1 else -1
            for y in range(y1 + step, y2, step):
                expanded.append((x1, y))
        expanded.append((x2, y2))
    return expanded
