        while True:
            new_c += dc
            if new_c < 0 or new_c >= cols:
                return None
            new_r = r
            if grid[new_r][new_c] != '.':
                return None
            if (new_r, new_c) == goal:
                return (new_r, new_c, g + 1, parent)
            up = new_r - 1 >= 0 and grid[new_r - 1][new_c] == '.'
            down = new_r + 1 < rows and grid[new_r + 1][new_c] == '.'
