                prev_c = c if dc == 1 else 2 * new_c - c
                if 0 <= prev_c < cols and grid[new_r - 1][prev_c] == '#':
                    return (new_r, new_c, g + 1, parent)
            if down:
                prev_c = c if dc == 1 else 2 * new_c - c
