            left = new_c - 1 >= 0 and grid[new_r][new_c - 1] == '.'
            right = new_c + 1 < cols and grid[new_r][new_c + 1] == '.'
            if (left and (new_r, new_c - 1) == goal) or (right and (new_r, new_c + 1) == goal):
                return (new_r, new_c, g + 1, parent)
            left_result = jump_horizontal(new_r, new_c, -1, g + 1, parent)
            right_result = jump_horizontal(new_r, new_c, 1, g + 1, parent)
            if left_result is not None or right_result is not None:
