            if (left and new_r - 1 >= 0 and grid[new_r - 1][new_c - 1] == '#') or \
               (left and new_r + 1 < rows and grid[new_r + 1][new_c - 1] == '#') or \
               (right and new_r - 1 >= 0 and grid[new_r - 1][new_c + 1] == '#') or \
               (right and new_r + 1 < rows and grid[new_r + 1][new_c + 1] == '#'):
                return (new_r, new_c, g + 1, parent)

    def reconstruct_path(current):
        path = [current]
        while g_prev[current] is not None:
