            path.append(current)
        path.reverse()
        return path

    g_map = {}
    g_prev = {}
    heap = []
    heapq.heappush(heap, (0 + manhattan(start, goal), 0, start, None))
    visited = set()

    while heap:
        f, g, cell, parent = heapq.heappop(heap)
        if cell in visited:
            continue
        visited.add(cell)
        if cell == goal:
            return reconstruct_path(cell)

        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            r, c = cell
            if dr != 0:
                result = jump_vertical(r, c, dr, g + 1, cell)
            else:
                result = jump_horizontal(r, c, dc, g + 1, cell)
            if result is not None:
                new_r, new_c, new_g, new_parent = result
                new_cell = (new_r, new_c)
                if new_cell not in visited:
                    g_map[new_cell] = new_g
                    g_prev[new_cell] = cell
                    f_new = new_g + manhattan(new_cell, goal)
                    heapq.heappush(heap, (f_new, new_g, new_cell, cell))

    return []
