def solve(grid, start, goal):
    if start == goal:
        if 0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and grid[start[0]][start[1]] == '.':
            return [start]
        else:
            return []

    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and
            0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    rows, cols = len(grid), len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def jump_horizontal(r, c, step, goal, came_from):
        while True:
            c += step
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return r, c
            if (c == came_from[1] or step == 0):
                break
            if not is_valid(r - 1, c) or not is_valid(r + 1, c):
                return r, c
        return None

    def jump_vertical(r, c, step, goal, came_from):
        while True:
            r += step
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return r, c
            if (r == came_from[0] or step == 0):
                break
            if not is_valid(r, c - 1) or not is_valid(r, c + 1):
                return r, c
        return None

    def jump(r, c, direction, goal, came_from):
        dr, dc = direction
        new_r, new_c = r + dr, c + dc
        if not is_valid(new_r, new_c):
            return None
        if (new_r, new_c) == goal:
            return new_r, new_c

        if direction in [(-1, 0), (1, 0)]:  # vertical
            result = jump_vertical(new_r, new_c, direction[0], goal, came_from)
        else:  # horizontal
            result = jump_horizontal(new_r, new_c, direction[1], goal, came_from)

        if result is not None:
            return result
        return None

    came_from = {}
    heap = [(manhattan(start, goal), 0, start, None)]
    visited = set()

    while heap:
        f, g, current, parent = heapq.heappop(heap)

        if current in visited:
            continue
        visited.add(current)

        if current == goal:
            # Found a path
            break

        for direction in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            jump_point = jump(current[0], current[1], direction, goal, current if parent else (0, 0))
            if jump_point is not None and jump_point not in visited:
                new_g = g + abs(jump_point[0] - current[0]) + abs(jump_point[1] - current[1])
                heapq.heappush(heap, (
                    new_g + manhattan(jump_point, goal),
                    new_g,
                    jump_point,
                    current
                ))
                came_from[jump_point] = current

    else:
        # No path found
        return []

    # Reconstruct path
    path = [goal]
    current = came_from.get(goal, None)
    if current is None:
        return []
    while current != start:
        path.append(current)
        current = came_from.get(current, None)
        if current is None:
            return []
    path.append(start)
    path.reverse()

    # Fill in the straight line between consecutive jump points
    result = [path[0]]
    for i in range(1, len(path)):
        r1, c1 = path[i - 1]
        r2, c2 = path[i]
        dr = r2 - r1
        dc = c2 - c1
        if dr != 0:
            for step in range(1, abs(dr)):
                result.append((r1 + (1 if dr > 0 else -1) * step, c1))
        elif dc != 0:
            for step in range(1, abs(dc)):
                result.append((r1, c1 + (1 if dc > 0 else -1) * step))
    result.append(path[-1])
    return result
