        open_heap = []
        heapq.heappush(open_heap, (manhattan(from_pos, to_pos), 0, from_pos))
        visited = {}
        cost = {from_pos: 0}
        parent = {}

        while open_heap:
            f, g, current = heapq.heappop(open_heap)
            if current in visited and g > cost[current]:
                continue
            yield current, g, visited, cost, parent
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                neighbor = (current[0] + dx, current[1] + dy)
                if is_valid(neighbor) and neighbor not in cost:
                    new_g = g + 1
                    new_h = manhattan(neighbor, to_pos)
                    heapq.heappush(open_heap, (new_g + new_h, new_g, neighbor))
                    cost[neighbor] = new_g
                    parent[neighbor] = current
            visited[current] = True

    forward_gen = heuristic_search(start, goal, is_forward_search=True)
    backward_gen = heuristic_search(goal, start, is_forward_search=False)

    forward_expanded = set()
    backward_expanded = set()

    best_path = None
    best_cost = float('inf')

