    forward_cost = {start: 0}
    forward_cost[goal] = float('inf')  # in case it is not expanded
    start_cost = 0
    forward_done = False

    backward_visited = {}
    backward_cost = {goal: 0}
    backward_cost[start] = float('inf')  # in case it is not expanded
    backward_done = False

    while True:
        # Run forward search
        try:
            _, g_f, new_visited, new_cost, new_parent = next(forward_gen)
            forward_visited.update(new_visited)
            forward_cost.update(new_cost)
            for k in new_cost:
