                    forward_cost[k] = new_cost[k]
                    forward_visited[k] = True
        except:
            forward_done = True

        # Run backward search
        try:
            _, g_b, new_visited, new_cost, new_parent = next(backward_gen)
            backward_visited.update(new_visited)
            backward_cost.update(new_cost)
            for k in new_cost:
                if k not in backward_cost or new_cost[k] < backward_cost[k]:
                    backward_cost[k] = new_cost[k]
                    backward_visited[k] = True
        except:
            backward_done = True

        # Check intersection
        merged = set(forward_visited).intersection(set(backward_visited))
        for node in merged:
            total_cost = forward_cost[node] + backward_cost[node]
            if total_cost < best_cost:
                best_cost = total_cost
                best_intersection = node

        # Stop conditions
        if forward_done and backward_done:
            break
        if any(v in forward_visited for v in backward_visited if v != start and v != goal and v not in (forward_visited and backward_visited) and forward_cost.get(v, float('inf')) + backward_cost.get(v, float('inf')) < best_cost):
            break

    # Reconstruct the best path
    if best_intersection is None:
        return []

    def reconstruct_path(parents, start, end):
        path = []
        curr = end
        while curr != start:
            path.append(curr)
            if curr not in parents:
                return []
            curr = parents[curr]
        path.append(start)
        return path[::-1]

    def get_forward_parents():
        p = {}
        curr = best_intersection
        while curr != start:
            if curr not in p or p[curr] not in forward_cost:
                return {}
            p[curr] = forward_cost[p[curr]]
            curr = p[curr]
        return p

    def get_backward_parents(parents, goal, node):
        p = {}
        curr = node
        while curr != goal:
            if curr not in parents or parents[curr] not in backward_cost:
                return {}
            p[curr] = parents[curr]
            curr = parents[curr]
        return p

    forward_parents = get_forward_parents()
    backward_parents = get_backward_parents(backward_cost, goal, best_intersection)

    if not forward_parents or not backward_parents:
        return []

    path = list(reversed(reconstruct_path(forward_parents, start, best_intersection)))
    path += reconstruct_path(backward_parents, best_intersection, goal)
    return path
