    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def is_free(grid, r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def get_neighbors(r, c):
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        neighbors = []
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_free(grid, nr, nc):
                neighbors.append((nr, nc))
        return neighbors

    def search(from_p, to_p, from_neighbors, get_opposite):
        g = {from_p: 0}
        heap = [(manhattan(from_p, to_p), from_p)]
        parents = {}

        while heap:
            f, node = heapq.heappop(heap)
            if f > g.get(node, float('inf')) + manhattan(node, to_p):
                continue
            if node in get_opposite():
                return node, g[node] + g_with_cost[node]
            for neighbor in from_neighbors(*node):
                new_g = g[node] + 1
                if neighbor not in g or new_g < g[neighbor]:
                    g[neighbor] = new_g
                    heapq.heappush(heap, (new_g + manhattan(neighbor, to_p), neighbor))
                    parents[neighbor] = node
        return None, float('inf')

    def build_path(backward, forward, meet):
        path = []
        while meet in backward:
            path.append(meet)
            meet = backward[meet]
        path.reverse()
        meet = path[-1]
        while meet in forward:
            path.append(forward[meet])
            meet = forward[meet]
        return path

    forward_g = {start: 0}
    backward_g = {goal: 0}
    forward_parents = {}
    backward_parents = {}

    g_with_cost = {}

    def forward_neighbors(r, c):
        return get_neighbors(r, c)

    def backward_neighbors(r, c):
        return get_neighbors(r, c)

    def get_forward_set():
        return forward_g.keys()

    def get_backward_set():
        return backward_g.keys()

    best_meet = None
    best_cost = float('inf')

    while True:
        # Forward search
        for node in forward_g:
            g_with_cost[node] = forward_g[node]
        meet, cost = search(start, goal, forward_neighbors, get_backward_set)
        if cost < best_cost:
            best_cost = cost
            best_meet = meet
        if best_meet is not None:
            break

        # Backward search
        for node in backward_g:
            g_with_cost[node] = backward_g[node]
        meet, cost = search(goal, start, backward_neighbors, get_forward_set)
        if cost < best_cost:
            best_cost = cost
            best_meet = meet
        if best_meet is not None:
            break

    if best_cost == float('inf'):
        return []

    return build_path(backward_parents, forward_parents, best_meet)
