        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                yield nr, nc

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def search(start_node, goal_node):
        open_list = [(manhattan(start_node, goal_node), 0, start_node)]
        visited = {}
        came_from = {}
        while open_list:
            f, g, current = heapq.heappop(open_list)
            if current in visited and visited[current] < g:
                continue
            visited[current] = g
            for next_node in neighbors(*current):
                new_g = g + 1
                if next_node not in visited or new_g < visited.get(next_node, float('inf')):
                    heapq.heappush(open_list, (new_g + manhattan(next_node, goal_node), new_g, next_node))
                    came_from[next_node] = current
        return visited, came_from

    forward_visited, forward_path = search(start, goal)
    backward_visited, backward_path = search(goal, start)

    best_meeting_cost = float('inf')
    best_meeting = None
    meet_set = set(forward_visited) & set(backward_visited)
    for cell in meet_set:
        total_cost = forward_visited[cell] + backward_visited[cell]
        if total_cost < best_meeting_cost:
            best_meeting = cell
            best_meeting_cost = total_cost

    if best_meeting is None:
        return []

    def reconstruct_path(came_from, start, end):
        path = [end]
        while path[-1] != start:
            if path[-1] not in came_from:
                return []
            path.append(came_from[path[-1]])
        path.reverse()
        return path

    forward_segment = reconstruct_path(forward_path, start, best_meeting)
    backward_segment = reconstruct_path(backward_path, goal, best_meeting)
    backward_segment.reverse()
    backward_segment.pop(0)

    return forward_segment + backward_segment
