import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start] if grid[start[0]][start[1]] == '.' else []

    rows, cols = len(grid), len(grid[0])
    if not (0 <= start[0] < rows and 0 <= start[1] < cols and 0 <= goal[0] < rows and 0 <= goal[1] < cols):
        return []

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # Up, Down, Left, Right

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def jump_horiz(r, c, dr, dc, dir_cd):
        while True:
            r += dr
            c += dc
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return r, c
            # Check for forced neighbor vertically (up or down)
            for ndr in [-1, 1]:
                nr, nc = r + ndr, c
                if is_valid(nr, nc) and not is_valid(r + 2*ndr, nc):
                    return r, c
            if any(jump_vertical(r, c, ndd) for ndd in [(-1, 0), (1, 0)]):
                return r, c

    def jump_vert(r, c, dr, dc, dir_cd):
        while True:
            r += dr
            c += dc
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return r, c
            # Check for forced neighbors horizontally (left or right)
            for ndc in [-1, 1]:
                nr, nc = r, c + ndc
                if is_valid(nr, nc) and not is_valid(nr, nc + ndc):
                    return r, c
            if any(jump_horizontal(r, c, ndd) for ndd in [(0, -1), (0, 1)]):
                return r, c

    def jump(r, c, came_from):
        for dr, dc in dirs:
            if (dr, dc) == came_from:
                continue
            nr, nc = r + dr, c + dc
            if not is_valid(nr, nc):
                continue
            if dr == 0 or dc == 0:
                if dr != 0:
                    res = jump_horiz(r, c, dr, 1 if dc > 0 else -1, (dr, dc))
                else:
                    res = jump_vert(r, c, dr, dc, (dr, dc))
                if res:
                    return [res]

    def jump_point(r, c, from_dir):
        came_from = ( -from_dir[0], -from_dir[1] ) if from_dir else (0, 0)
        for dr, dc in dirs:
            if (dr, dc) == came_from:
                continue
            nr, nc = r + dr, c + dc
            if not is_valid(nr, nc):
                continue
            if dr == 0 or dc == 0:
                if dr != 0:  # Horizontal
                    j = jump_horiz(r, c, dr, 0, (dr, dc))
                else:        # Vertical
                    j = jump_vert(r, c, 0, dc, (dr, dc))
                if j is not None:
                    return j

    def reconstruct_path(parent, goal):
        path = [goal]
        curr = parent.get(goal)
        while curr:
            path.append(curr)
            curr = parent.get(curr)
        path.reverse()
        for i in range(1, len(path)):
            r1, c1 = path[i-1]
            r2, c2 = path[i]
            dr = r2 - r1
            dc = c2 - c1
            if abs(dr) > 1:
                for mid in range(1, abs(dr)):
                    path.insert(i, (r1 + (1 if dr > 0 else -1) * mid, c1))
                    i += 1
            elif abs(dc) > 1:
                for mid in range(1, abs(dc)):
                    path.insert(i, (r1, c1 + (1 if dc > 0 else -1) * mid))
                    i += 1
        return path

    parent = {}
    heap = [(manhattan(start, goal), 0, start, None)]
    visited = set()

    while heap:
        f, g, curr, came_from = heapq.heappop(heap)
        if curr == goal:
            return reconstruct_path(parent, curr)
        if curr in visited:
            continue
        visited.add(curr)

        for dr, dc in dirs:
            if (dr, dc) == came_from:
                continue
            next_pos = (curr[0] + dr, curr[1] + dc)
            if not is_valid(*next_pos):
                continue
            if next_pos in visited:
                continue
            jp = jump_point(curr[0] + dr, curr[1] + dc, (dr, dc))
            if not jp:
                continue
            ng = g + 1
            while (curr[0] + dr, curr[1] + dc) != jp:
                curr = (curr[0] + dr, curr[1] + dc)
                ng += 1
            heapq.heappush(heap, (ng + manhattan(jp, goal), ng, jp, (-dr, -dc)))
            parent[jp] = curr

    return []
