import heapq

def solve(grid, start, goal):
    if start == goal:
        if not is_free(grid, *start):
            return []
        return [start]
    if not is_free(grid, *start) or not is_free(grid, *goal):
        return []

    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def is_free(grid, r, c):
        if 0 <= r < len(grid) and 0 <= c < len(grid[0]):
            return grid[r][c] == '.'
        return False

    forward_heap = [(manhattan(start, goal), 0, start)]
    backward_heap = [(manhattan(goal, start), 0, goal)]
    forward_g = {start: 0}
    backward_g = {goal: 0}
    forward_parent = {}
    backward_parent = {}

    while forward_heap and backward_heap:
        # Run one forward step
        if forward_heap:
            f = forward_heap[0][0]
            b_min = min((forward_g[cell] + backward_g[cell] for cell in forward_g if cell in backward_g), default=float('inf'))
            if f >= b_min - forward_g.get(forward_heap[0][2], float('inf')):
                break
            _, g, node = heapq.heappop(forward_heap)
            if node in backward_g:
                return join_paths(forward_parent, backward_parent, node, start, goal)
            for dr, dc in directions:
                nr, nc = node[0] + dr, node[1] + dc
                next_node = (nr, nc)
                if is_free(grid, nr, nc) and next_node not in forward_g:
                    forward_g[next_node] = g + 1
                    heapq.heappush(
                        forward_heap,
                        (g + 1 + manhattan(next_node, goal), g + 1, next_node)
                    )
                    forward_parent[next_node] = node

        # Run one backward step
        if backward_heap:
            b = backward_heap[0][0]
            f_min = min((forward_g[cell] + backward_g[cell] for cell in forward_g if cell in backward_g), default=float('inf'))
            if b >= f_min - backward_g.get(backward_heap[0][2], float('inf')):
                break
            _, g, node = heapq.heappop(backward_heap)
            if node in forward_g:
                return join_paths(forward_parent, backward_parent, node, start, goal)
            for dr, dc in directions:
                nr, nc = node[0] + dr, node[1] + dc
                next_node = (nr, nc)
                if is_free(grid, nr, nc) and next_node not in backward_g:
                    backward_g[next_node] = g + 1
                    heapq.heappush(
                        backward_heap,
                        (g + 1 + manhattan(next_node, start), g + 1, next_node)
                    )
                    backward_parent[next_node] = node

    meeting_points = [cell for cell in forward_g if cell in backward_g]
    if not meeting_points:
        return []
    best_meet = min(meeting_points, key=lambda x: forward_g[x] + backward_g[x])
    return join_paths(forward_parent, backward_parent, best_meet, start, goal)


def join_paths(forward_parent, backward_parent, meet, start, goal):
    path = []
    cur = meet
    while cur != start:
        path.append(cur)
        cur = forward_parent[cur]
    path.append(start)
    path.reverse()

    cur = meet
    while cur != goal:
        cur = backward_parent[cur]
        path.append(cur)

    return path
