            if not is_valid(next_r, next_c):
                return None
            steps += 1
            if (next_r, next_c) == goal:
                return (next_r, next_c), steps
            if abs(dr) == 1:
                # Horizontal jump
                ndr = -1 if dr > 0 else 1
                if is_valid(current[0] + ndr, current[1]) and not is_valid(next_r + ndr, next_c):
                    return (next_r, next_c), steps
            else:  # vertical jump
                ndc = -1 if dc > 0 else 1
                if is_valid(current[0], current[1] + ndc) and not is_valid(next_r, next_c + ndc):
                    return (next_r, next_c), steps
            j = jump_point(next_r, next_c, dr, dc, current)
            if j:
                return j, steps + 1
            current = (next_r, next_c)

    came_from = {}
    g_score = {start: 0}
    f_score = {start: manhattan(start, goal)}
    heap = [(f_score[start], g_score[start], start, None)]

    while heap:
        _, g, current, parent = heapq.heappop(heap)
        if current == goal:
            break
        if current in came_from and came_from[current] != parent:
            continue

        if parent:
            dr = current[0] - parent[0]
            dc = current[1] - parent[1]
        else:
            dr = dc = 0

        for rd, cd in [(0,1),(0,-1),(1,0),(-1,0)]:
            if (rd, cd) == (-dr, -cd):
                continue  # skip opposite direction
            j = jump_helper(current[0], current[1], rd, cd)
            if j is None:
                continue
            (j_cell, steps) = j
            new_g = g + steps
            if j_cell not in g_score or new_g < g_score[j_cell]:
                g_score[j_cell] = new_g
                f_score[j_cell] = new_g + manhattan(j_cell, goal)
                heapq.heappush(heap, (f_score[j_cell], new_g, j_cell, current))
                came_from[j_cell] = current

    if goal not in came_from:
        return []

    # Reconstruct path
    path = []
    current = goal
    while current:
        path.append(current)
        current = came_from.get(current)
    path.reverse()

    # Fill in straight-line cells
    final_path = [start]
    for i in range(1, len(path)):
        p1, p2 = path[i-1], path[i]
        dr = p2[0] - p1[0]
        dc = p2[1] - p1[1]
        if dr != 0:
            step = 1 if dr > 0 else -1
            for j in range(1, abs(dr)):
                final_path.append((p1[0] + step * j, p1[1]))
        if dc != 0:
            step = 1 if dc > 0 else -1
            for j in range(1, abs(dc)):
                final_path.append((p1[0], p1[1] + step * j))
        final_path.append(p2)

    return final_path
