                        parent_rev[(nx, ny)] = n2

        if not open_rev or not open_for or best_meeting and best_cost <= min(f2, (*open_for[0])[0] if open_for else float('inf')):
            break

    if not best_meeting:
        return []

    path = []
    curr = best_meeting
    while curr in parent_for and curr != start:
        path.append(curr)
