import heapq

def solve(grid, start, goal):
    if start == goal:
        if is_valid(grid, *start):
            return [start]
        return []

    if not is_valid(grid, *start) or not is_valid(grid, *goal):
        return []

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def neighbors(pos):
        r, c = pos
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_valid(grid, nr, nc):
                yield (nr, nc)

    def is_valid(grid, r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def search(from_pos, to_pos):
        open_set = []
        heapq.heappush(open_set, (heuristic(from_pos, to_pos), 0, from_pos))
        came_from = {}
        cost_so_far = {from_pos: 0}
        return open_set, came_from, cost_so_far

    def build_path(came_from_a, meet, came_from_b):
        path = [meet]
        current = meet
        while current in came_from_a:
            current = came_from_a[current]
            path.insert(0, current)
        current = meet
        while current in came_from_b:
            current = came_from_b[current]
            path.append(current)
        return path

    open_forward, came_from_forward, cost_forward = search(start, goal)
    open_backward, came_from_backward, cost_backward = search(goal, start)

    best_f = float('inf')
    best_meet = None

    while open_forward and open_backward:
        # Forward step
        if open_forward:
            f, g, current = heapq.heappop(open_forward)
            if f >= best_f:
                continue
            for neighbor in neighbors(current):
                new_g = g + 1
                if neighbor not in cost_forward or new_g < cost_forward[neighbor]:
                    cost_forward[neighbor] = new_g
                    h = heuristic(neighbor, goal)
                    f = new_g + h
                    heapq.heappush(open_forward, (f, new_g, neighbor))
                    came_from_forward[neighbor] = current

        # Backward step
        if open_backward:
            f, g, current = heapq.heappop(open_backward)
            if f >= best_f:
                continue
            for neighbor in neighbors(current):
                new_g = g + 1
                if neighbor not in cost_backward or new_g < cost_backward[neighbor]:
                    cost_backward[neighbor] = new_g
                    h = heuristic(neighbor, start)
                    f = new_g + h
                    heapq.heappush(open_backward, (f, new_g, neighbor))
                    came_from_backward[neighbor] = current

        # Check for intersection
        for pos in cost_forward:
            if pos in cost_backward:
                total_cost = cost_forward[pos] + cost_backward[pos]
                if total_cost < best_f:
                    best_f = total_cost
                    best_meet = pos

        for pos in cost_backward:
            if pos in cost_forward:
                total_cost = cost_forward[pos] + cost_backward[pos]
                if total_cost < best_f:
                    best_f = total_cost
                    best_meet = pos

        if best_meet is not None:
            return build_path(came_from_forward, best_meet, came_from_backward)

    return []
