import heapq

def solve(grid, start, goal):
    if start == goal:
        if is_free(grid, *start):
            return [start]
        return []

    rows = len(grid)
    cols = len(grid[0])

    def is_free(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def heuristic_search(start, goal, is_forward):
        open_set = []
        heapq.heappush(open_set, (0, start))
        g_score = {start: 0}
        parents = {}

        while open_set:
            _, current = heapq.heappop(open_set)

            if current in g_score and g_score[current] < manhattan(current, goal):
                continue

            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = current[0] + dr, current[1] + dc
                neighbor = (nr, nc)

                if not is_free(*neighbor):
                    continue

                tentative_g = g_score[current] + 1

                if tentative_g < g_score.get(neighbor, float('inf')):
                    g_score[neighbor] = tentative_g
                    heapq.heappush(open_set, (tentative_g + manhattan(neighbor, goal), neighbor))
                    parents[neighbor] = current

        return g_score, parents

    def reconstruct_path(start, goal, parents1, parents2):
        path1 = []
        current = goal
        while current in parents1:
            path1.append(current)
            current = parents1[current]
            if current == start:
                break
        path1.reverse()

        path2 = []
        current = start
        while current in parents2:
            path2.append(current)
            current = parents2[current]
            if current == goal:
                break

        common = set(path1) & set(path2)
        if not common:
            return []

        best_meet = None
        best_cost = float('inf')
        for p in common:
            cost = parents1.get(p, 0) + parents2.get(p, 0)
            p1 = p
            count1 = 0
            while p1 != start and p1 in parents1:
                p1 = parents1[p1]
                count1 += 1
            p2 = p
            count2 = 0
            while p2 != goal and p2 in parents2:
                p2 = parents2[p2]
                count2 += 1
            total_cost = count1 + count2
            if total_cost < best_cost:
                best_meet = p
                best_cost = total_cost

        if best_meet is None:
            return []

        idx1 = path1.index(best_meet)
        idx2 = path2.index(best_meet)

        full_path = path2[:idx2 + 1] + path1[idx1 + 1:]
        return full_path

    g1, parents1 = heuristic_search(start, goal, True)
    g2, parents2 = heuristic_search(goal, start, False)

    if not g1 or not g2:
        return []

    path = reconstruct_path(start, goal, parents1, parents2)
    if path and path[0] == start and path[-1] == goal:
        return path
    else:
        return []
