        if not is_free(from_pos):
            return None, g_dict, parent_dict

        if from_pos in g_dict:
            return None, g_dict, parent_dict

        g = g_dict.get(from_pos, float('inf'))
        for dr, dc in directions:
            nr, nc = from_pos[0] + dr, from_pos[1] + dc
            next_pos = (nr, nc)
            if not is_free(next_pos):
                continue
            cost = 1
            new_g = g + cost
            if next_pos not in g_dict or new_g < g_dict[next_pos]:
                g_dict[next_pos] = new_g
                h = manhattan(next_pos, to_pos)
                heapq.heappush(heap, (new_g + h, next_pos))
                parent_dict[next_pos] = from_pos

        if from_pos in other_g:
            return from_pos, g_dict, parent_dict

        return None, g_dict, parent_dict

    f_g = {start: 0}
    b_g = {goal: 0}
    f_parent = {}
    b_parent = {}
    f_heap = [(manhattan(start, goal), start)]
    b_heap = [(manhattan(goal, start), goal)]

    while f_heap and b_heap:
        if f_heap:
            _, pos_f = heapq.heappop(f_heap)
            if pos_f in b_g:
                return reconstruct_path(f_parent, start, pos_f) + reconstruct_path(b_parent, pos_f, goal)[::-1][1:]

            meet, f_g, f_parent = search(pos_f, goal, True, f_g, f_parent, b_g, f_heap)

        if b_heap:
            _, pos_b = heapq.heappop(b_heap)
            if pos_b in f_g:
                return reconstruct_path(f_parent, start, pos_b) + reconstruct_path(b_parent, pos_b, goal)[::-1][1:]

            meet, b_g, b_parent = search(pos_b, start, False, b_g, b_parent, f_g, b_heap)

    return []

def reconstruct_path(parent, start, end):
    path = [end]
    while path[-1] != start:
        path.append(parent[path[-1]])
    return path
