import heapq

def solve(grid, start, goal):
    if (
        not grid or
        not 0 <= start[0] < len(grid) or
        not 0 <= start[1] < len(grid[0]) or
        not 0 <= goal[0] < len(grid) or
        not 0 <= goal[1] < len(grid[0]) or
        grid[start[0]][start[1]] == '#' or
        grid[goal[0]][goal[1]] == '#'
    ):
        return []

    if start == goal:
        return [start]

    rows = len(grid)
    cols = len(grid[0])

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def is_in_bounds(p):
        r, c = p
        return 0 <= r < rows and 0 <= c < cols

    def is_free(p):
        r, c = p
        return is_in_bounds(p) and grid[r][c] == '.'

    def jump_horizontal(p, direction):
        r, c = p
        dr, dc = direction
        step = 1 if dc > 0 else -1
        while True:
            c += step
            new_p = (r, c)
            if not is_free(new_p):
                return None
            if new_p == goal:
                return new_p
            if (is_free((r + 1, c)) and not is_free((r + 1, c - step))) or \
               (is_free((r - 1, c)) and not is_free((r - 1, c - step))):
                return new_p

    def jump_vertical(p, direction):
        r, c = p
        dr, dc = direction
        step = 1 if dr > 0 else -1
        while True:
            r += step
            new_p = (r, c)
            if not is_free(new_p):
                return None
            if new_p == goal:
                return new_p
            if (is_free((r, c + 1)) and not is_free((r - step, c + 1))) or \
               (is_free((r, c - 1)) and not is_free((r - step, c - 1))):
                return new_p

    def jump(p, d, parent):
        if d == (0, 1):
            return jump_horizontal(p, (0, 1))
        elif d == (0, -1):
            return jump_horizontal(p, (0, -1))
        elif d == (1, 0):
            if jump_horizontal(p, (0, 1)) or jump_horizontal(p, (0, -1)) or (1, 0) == ((p[0] - parent[0]), (p[1] - parent[1])):
                return jump_vertical(p, (1, 0))
            return None
        elif d == (-1, 0):
            if jump_horizontal(p, (0, 1)) or jump_horizontal(p, (0, -1)) or (-1, 0) == ((p[0] - parent[0]), (p[1] - parent[1])):
                return jump_vertical(p, (-1, 0))
            return None
        return None

    def get_neighbors(p, parent):
        if parent == p:
            return []
        dr = p[0] - parent[0]
        dc = p[1] - parent[1]
        directions = []
        if dr != 0:
            if dr == 1:
                directions = [(1, 0)]
            elif dr == -1:
                directions = [(-1, 0)]
        elif dc != 0:
            if dc == 1:
                directions = [(0, 1)]
            elif dc == -1:
                directions = [(0, -1)]
        for d in directions:
            result = jump(p, d, parent)
            if result and result != p:
                yield result

    came_from = {}
    g_score = {start: 0}
    f_score = {start: manhattan(start, goal)}
    frontier = [(f_score[start], start)]

    while frontier:
        current_score, current = heapq.heappop(frontier)
        if current == goal:
            break
        if current not in came_from:
            came_from[current] = start  # start has no parent, default to start
        parent = came_from[current]
        for neighbor in get_neighbors(current, parent):
            if not neighbor:
                continue
            nr, nc = neighbor
            # Manhattan distance
            g = g_score[current] + abs(nr - current[0]) + abs(nc - current[1])
            if neighbor not in g_score or g < g_score[neighbor]:
                came_from[neighbor] = current
                g_score[neighbor] = g
                f = g + manhattan(neighbor, goal)
                heapq.heappush(frontier, (f, neighbor))

    if goal not in came_from:
        return []

    path = []
    current = goal
    while current != start:
        path.append(current)
        current = came_from[current]
    path.append(start)
    path.reverse()

    result = []
    for i in range(len(path) - 1):
        step_from, step_to = path[i], path[i + 1]
        dx = step_to[0] - step_from[0]
        dy = step_to[1] - step_from[1]
        if dx != 0:
            step_x = 1 if dx > 0 else -1
            for x in range(step_from[0], step_to[0], step_x):
                result.append((x, step_from[1]))
        if dy != 0:
            step_y = 1 if dy > 0 else -1
            for y in range(step_from[1], step_to[1], step_y):
                result.append((step_to[0], y))
        result.append(step_to)
    result = list(dict.fromkeys(result))
    return result
