import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start] if is_free(grid, start) else []
    if not is_free(grid, start) or not is_free(grid, goal):
        return []

    rows, cols = len(grid), len(grid[0])

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def get_neighbors(pos):
        r, c = pos
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                yield (nr, nc)

    def is_free(grid, pos):
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def a_star(start, goal, forward=True):
        g = {start: 0}
        f = {start: manhattan(start, goal)}
        heap = [(f[start], g[start], start)]
        parent = {}

        while heap:
            _, cost, node = heapq.heappop(heap)
            if node in g and g[node] < cost:
                continue
            for neighbor in get_neighbors(node):
                new_cost = cost + 1
                if neighbor not in g or new_cost < g[neighbor]:
                    g[neighbor] = new_cost
                    f_neighbor = new_cost + manhattan(neighbor, goal)
                    heapq.heappush(heap, (f_neighbor, new_cost, neighbor))
                    parent[neighbor] = node
            yield node, cost, g, parent

    forward_gen = a_star(start, goal, forward=True)
    backward_gen = a_star(goal, start, forward=False)
    forward_search = next(forward_gen)
    backward_search = next(backward_gen)
    forward_heap = [(manhattan(start, goal), 0, start)]
    backward_heap = [(manhattan(goal, start), 0, goal)]
    forward_g, forward_parent = {start: 0}, {}
    backward_g, backward_parent = {goal: 0}, {}

    def reconstruct_path(meet):
        path = []
        node = meet
        while node != start:
            path.append(node)
            node = forward_parent[node]
        path.append(start)
        path.reverse()
        node = meet
        while node != goal:
            node = backward_parent[node]
            path.append(node)
        return path

    best_cost = float('inf')
    common_cells = set()

    while forward_heap and backward_heap:
        f1, g1, node1 = forward_heap[0]
        f2, g2, node2 = backward_heap[0]
        if f1 + f2 >= best_cost:
            break

        if node1 in backward_g:
            common_cells.add(node1)
        elif node2 in forward_g:
            common_cells.add(node2)
        else:
            if f1 < f2:
                try:
                    node, cost, new_g, new_parent = next(forward_gen)
                    for k, v in new_g.items():
                        forward_g[k] = v
                    forward_parent.update(new_parent)
                    for neighbor in get_neighbors(node):
                        if neighbor not in forward_g or cost + 1 < forward_g[neighbor]:
                            forward_g[neighbor] = cost + 1
                            heapq.heappush(forward_heap, (cost + 1 + manhattan(neighbor, goal), cost + 1, neighbor))
                            forward_parent[neighbor] = node
                except StopIteration:
                    return []
            else:
                try:
                    node, cost, new_g, new_parent = next(backward_gen)
                    for k, v in new_g.items():
                        backward_g[k] = v
                    backward_parent.update(new_parent)
                    for neighbor in get_neighbors(node):
                        if neighbor not in backward_g or cost + 1 < backward_g[neighbor]:
                            backward_g[neighbor] = cost + 1
                            heapq.heappush(backward_heap, (cost + 1 + manhattan(neighbor, start), cost + 1, neighbor))
                            backward_parent[neighbor] = node
                except StopIteration:
                    return []

        for meet in common_cells:
            cost = forward_g[meet] + backward_g[meet]
            if cost < best_cost:
                best_cost = cost
                best_meet = meet
        if common_cells:
            return reconstruct_path(best_meet)

    return []
