def solve(grid, start, goal):
    if start == goal:
        if (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])
            and grid[start[0]][start[1]] == '.'):
            return [start]
        return []

    if (
        not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])) or
        not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])) or
        grid[start[0]][start[1]] == '#' or
        grid[goal[0]][goal[1]] == '#'
    ):
        return []

    rows, cols = len(grid), len(grid[0])
    open_list = []
    heapq.heappush(open_list, (manhattan(start, goal), 0, start, None))
    parent = {}
    visited = {start}

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def is_open(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def jump_horizontal(r, c, step, g, parent_cell):
        while True:
            c += step
            if not is_open(r, c):
                return None
            g += 1
            if (r, c) == goal:
                return (r, c, g, parent_cell)
            # Check if the cell has a forced neighbor to the left or right
            if is_open(r, c - step) and grid[r - 1][c] == '#' or grid[r + 1][c] == '#':
                return (r, c, g, parent_cell)
            # Check for vertical forced neighbors (up/down)
            if is_open(r + 1, c) and not is_open(r + 1, c - step):
                return (r, c, g, parent_cell)
            if is_open(r - 1, c) and not is_open(r - 1, c - step):
                return (r, c, g, parent_cell)
            parent_cell = (r, c)
        return None

    def jump_vertical(r, c, step, g, parent_cell):
        while True:
            r += step
            if not is_open(r, c):
                return None
            g += 1
            if (r, c) == goal:
                return (r, c, g, parent_cell)
            # Check for forced neighbors
            if is_open(r, c + 1) or is_open(r, c - 1):
                if (jump_horizontal(r, c, 1, 0, (r, c)) is not None
                    or jump_horizontal(r, c, -1, 0, (r, c)) is not None):
                    return (r, c, g, parent_cell)
            parent_cell = (r, c)
        return None

    def jump(r, c, dr, dc, g, parent_cell):
        if dr == 0:
            return jump_horizontal(r, c, dc, g, parent_cell)
        else:
            return jump_vertical(r, c, dr, g, parent_cell)

    while open_list:
        _, g, current, prev = heapq.heappop(open_list)
        if current == goal:
            break
        for dr, dc in directions:
            nr, nc = current[0] + dr, current[1] + dc
            if is_open(nr, nc) and (nr, nc) not in visited:
                if prev and (current[0] - prev[0], current[1] - prev[1]) == (dr, dc):
                    res = jump(current[0], current[1], dr, dc, 0, current)
                else:
                    res = (current[0] + dr, current[1] + dc, g + 1, current)
                if res and res[0] is not None:
                    rj, cj, gj, _ = res
                    if (rj, cj) not in visited:
                        heapq.heappush(open_list, (gj + manhattan((rj, cj), goal), gj, (rj, cj), current))
                        parent[(rj, cj)] = current
                        visited.add((rj, cj))

    if goal not in parent:
        return []

    path = []
    current = goal
    while current is not None:
        path.append(current)
        current = parent.get(current)
    path.reverse()

    # Fill in the straight-line steps between jump points
    extended_path = []
    for i in range(len(path) - 1):
        p1, p2 = path[i], path[i + 1]
        r1, c1 = p1
        r2, c2 = p2
        if r1 == r2:
            # Horizontal line
            if c1 < c2:
                for c in range(c1, c2 + 1):
                    extended_path.append((r1, c))
            else:
                for c in range(c1, c2 - 1, -1):
                    extended_path.append((r1, c))
        elif c1 == c2:
            # Vertical line
            if r1 < r2:
                for r in range(r1, r2 + 1):
                    extended_path.append((r, c1))
            else:
                for r in range(r1, r2 - 1, -1):
                    extended_path.append((r, c1))
    # Make sure the goal is included once
    if extended_path and extended_path[-1] == goal:
        pass
    else:
        extended_path.append(goal)

    # Prune duplicates
    final_path = []
    for p in extended_path:
        if not final_path or p != final_path[-1]:
            final_path.append(p)

    if final_path and final_path[0] != start:
        final_path.insert(0, start)

    # Validate path
    for r, c in final_path:
        if not is_open(r, c):
            return []

    return final_path
