        current = goal
        while current != start:
            path.append(current)
            current = came_from[current]
        path.reverse()
        return [start] + path

    forward_heap = [(manhattan(start, goal), 0, start)]
    backward_heap = [(manhattan(goal, start), 0, goal)]
