        if not frontier:
            return None
        cost, curr = heapq.heappop(frontier)
        if curr in other_g:
            return cost, curr
        if curr in g and g[curr] <= cost:
            return None
        g[curr] = cost
        for next_cell in neighbors(*curr):
            new_cost = cost + 1
            if next_cell not in g or new_cost < g[next_cell]:
                parents[next_cell] = curr
                h = manhattan(next_cell, goal)
                heapq.heappush(frontier, (new_cost + h, next_cell))
        return None

    def reconstruct_path(parents1, parents2, meeting_point):
