            new_row, new_col = row + dr, col + dc
            if is_valid(new_row, new_col) and (new_row, new_col) not in g:
                new_g = g[(row, col)] + 1
                if (new_row, new_col) not in frontier_growing or new_g < frontier_growing[(new_row, new_col)]:
                    frontier_growing[(new_row, new_col)] = new_g
                    heapq.heappush(front_queue, (new_g + manhattan((new_row, new_col), target), (new_row, new_col)))
        return None, None, g, parent

    def reconstruct_path(meet, start, goal, forward_parent, backward_parent):
        path1 = []
        curr = meet
        while curr != start:
            path1.append(curr)
            curr = forward_parent[curr]
        path1.append(start)
        path2 = []
        curr = meet
        while curr != goal:
            path2.append(curr)
            curr = backward_parent[curr]
        path2.append(goal)
        return path1[::-1] + path2

    if start == goal:
        if is_valid(*start):
            return [start]
