        return []

    forward_heap = [(0 + manhattan(start, goal), start)]
    forward_g = {start: 0}
    forward_parent = {}
    backward_heap = [(0 + manhattan(goal, start), goal)]
    backward_g = {goal: 0}
    backward_parent = {}

    forward_frontier = {start: 0}
    backward_frontier = {goal: 0}

    while forward_heap and backward_heap:
        meet, cost, fg, fp = heuristic_search(forward_heap, forward_g, forward_parent, forward_frontier, backward_g, goal)
        if meet:
            return reconstruct_path(meet, start, goal, fp, backward_parent)
        forward_g = fg

