        r, c = pos
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if (0 <= nr < len(grid)) and (0 <= nc < len(grid[0])) and grid[nr][nc] == '.':
                yield (nr, nc)

    forward_g = {start: 0}
    backward_g = {goal: 0}
    forward_path = {}
    backward_path = {}

    forward_heap = [(manhattan(start, goal), 0, start)]
    backward_heap = [(manhattan(goal, start), 0, goal)]

    best_meet_cost = float('inf')
    best_meet = None

    while forward_heap and backward_heap:
        # Check if any node has been expanded by both
        for node in forward_g:
            if node in backward_g:
                cost = forward_g[node] + backward_g[node]
                if cost < best_meet_cost:
                    best_meet_cost = cost
                    best_meet = node
        if best_meet is not None and best_meet_cost <= forward_heap[0][0] and best_meet_cost <= backward_heap[0][0]:
            break

        if not forward_heap or not backward_heap:
            break

        if forward_heap:
            f_val, g_val, current = heapq.heappop(forward_heap)
            if g_val > forward_g[current]:
                continue

            for next_pos in neighbors(current):
                new_g = g_val + 1
                if next_pos not in forward_g or new_g < forward_g[next_pos]:
                    forward_g[next_pos] = new_g
                    forward_path[next_pos] = current
                    heapq.heappush(forward_heap, (new_g + manhattan(next_pos, goal), new_g, next_pos))

        if backward_heap:
            f_val, g_val, current = heapq.heappop(backward_heap)
            if g_val > backward_g[current]:
                continue
            for next_pos in neighbors(current):
                new_g = g_val + 1
                if next_pos not in backward_g or new_g < backward_g[next_pos]:
                    backward_g[next_pos] = new_g
                    backward_path[next_pos] = current
                    heapq.heappush(backward_heap, (new_g + manhattan(next_pos, start), new_g, next_pos))

    if best_meet is None:
        return []

    def reconstruct_path(meet_point):
        path = []
        current = meet_point
        while current != start:
            path.append(current)
            current = forward_path[current]
        path.reverse()
        path = [start] + path

        current = meet_point
        while current != goal:
            current = backward_path[current]
            path.append(current)
        path.append(goal)
        return path

