    if start == goal:
        return [start]

    if not is_free(grid, start) or not is_free(grid, goal):
        return []

    def get_neighbors(pos):
        row, col = pos
        neighbors = []
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = row + dr, col + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == '.':
                neighbors.append((nr, nc))
        return neighbors

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def is_free(grid, pos):
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def search(start, goal, reverse=False):
        frontier = []
        heapq.heappush(frontier, (manhattan(start, goal), 0, start))
        came_from = {}
        cost_so_far = {start: 0}

        while frontier:
            f, g, current = heapq.heappop(frontier)

            if current in (came_from if not reverse else came_from_rev):
                continue

            (came_from if not reverse else came_from_rev)[current] = start if current == start else (goal if current == goal else (frontier[0][2] if frontier else current))

            if current in (came_from_rev if not reverse else came_from):
                return (g, (came_from if not reverse else came_from_rev), current)

            for next_cell in get_neighbors(current):
                new_cost = g + 1
                if next_cell not in cost_so_far or new_cost < cost_so_far[next_cell]:
                    cost_so_far[next_cell] = new_cost
                    priority = new_cost + manhattan(next_cell, goal)
                    heapq.heappush(frontier, (priority, new_cost, next_cell))

        return (float('inf'), {}, None)

    came_from = {start: None}
    came_from_rev = {goal: None}

    # Perform alternating expansions until a meeting point is found or both sides are blocked
    forward_heap = [(manhattan(start, goal), 0, start)]
    backward_heap = [(manhattan(goal, start), 0, goal)]
    forward_cost = {start: 0}
    backward_cost = {goal: 0}
    forward_came_from = {start: None}
    backward_came_from = {goal: None}

    while forward_heap and backward_heap:
        # Forward expansion
        f, g, current = heapq.heappop(forward_heap)
        if current not in forward_came_from or forward_cost[current] < g:
            continue
        forward_came_from[current] = start if current == start else forward_came_from[current]

        if current in backward_came_from and backward_came_from[current] is not None:
            meeting = current
            break
        for next_cell in get_neighbors(current):
            new_cost = g + 1
            if next_cell not in forward_cost or new_cost < forward_cost[next_cell]:
                forward_cost[next_cell] = new_cost
                heapq.heappush(forward_heap, (new_cost + manhattan(next_cell, goal), new_cost, next_cell))
                forward_came_from[next_cell] = current

        if not forward_heap:
            continue

        # Backward expansion
        f, g, current = heapq.heappop(backward_heap)
        if current not in backward_came_from or backward_cost[current] < g:
            continue
        backward_came_from[current] = goal if current == goal else backward_came_from[current]

        if current in forward_came_from and forward_came_from[current] is not None:
            meeting = current
            break
        for next_cell in get_neighbors(current):
            new_cost = g + 1
            if next_cell not in backward_cost or new_cost < backward_cost[next_cell]:
                backward_cost[next_cell] = new_cost
                heapq.heappush(backward_heap, (new_cost + manhattan(next_cell, start), new_cost, next_cell))
                backward_came_from[next_cell] = current

    else:
        # If we exited the loop due to no expansions left, no path was found
        return []

    # Reconstruct path from forward and backward trace
    path = []
    current = meeting
    while current != start:
        path.append(current)
        current = forward_came_from[current]
    path.reverse()
    path = [start] + path

    current = backward_came_from[meeting]
    while current != goal:
        path.append(current)
        current = backward_came_from[current]
    path.append(goal)

    return path if all(is_free(grid, p) for p in path) else []

