import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start] if is_free(grid, start) else []

    if not is_free(grid, start) or not is_free(grid, goal):
        return []

    def is_free(grid, pos):
        row, col = pos
        return 0 <= row < len(grid) and 0 <= col < len(grid[row]) and grid[row][col] == '.'

    def neighbors(pos):
        row, col = pos
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = row + dr, col + dc
            if is_free(grid, (nr, nc)):
                yield (nr, nc)

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    # Bidirectional A* search
    h1_heap = [(manhattan(start, goal), start)]
    h2_heap = [(manhattan(goal, start), goal)]
    g1_dict = {start: 0}
    g2_dict = {goal: 0}
    parent1_dict = {}
    parent2_dict = {}
    f1 = {start: manhattan(start, goal)}
    f2 = {goal: manhattan(goal, start)}
    best_meeting_cost = float('inf')
    best_meet = None

    while h1_heap and h2_heap and min(f1.get(h1_heap[0][1], float('inf')), f2.get(h2_heap[0][1], float('inf'))) < best_meeting_cost:
        # Expand forward
        while h1_heap and f1.get(h1_heap[0][1], float('inf')) != h1_heap[0][0]:
            heapq.heappop(h1_heap)

        if h1_heap:
            _, current = heapq.heappop(h1_heap)
            if current in g2_dict and g1_dict[current] + g2_dict[current] < best_meeting_cost:
                best_meeting_cost = g1_dict[current] + g2_dict[current]
                best_meet = current

            for next_node in neighbors(current):
                new_g = g1_dict[current] + 1
                new_f = new_g + manhattan(next_node, goal)
                if next_node not in g1_dict or new_g < g1_dict.get(next_node, float('inf')):
                    g1_dict[next_node] = new_g
                    f1[next_node] = new_f
                    heapq.heappush(h1_heap, (new_f, next_node))
                    parent1_dict[next_node] = current

        # Expand backward
        while h2_heap and f2.get(h2_heap[0][1], float('inf')) != h2_heap[0][0]:
            heapq.heappop(h2_heap)

        if h2_heap:
            _, current = heapq.heappop(h2_heap)
            if current in g1_dict and g1_dict[current] + g2_dict[current] < best_meeting_cost:
                best_meeting_cost = g1_dict[current] + g2_dict[current]
                best_meet = current

            for next_node in neighbors(current):
                new_g = g2_dict[current] + 1
                new_f = new_g + manhattan(next_node, start)
                if next_node not in g2_dict or new_g < g2_dict.get(next_node, float('inf')):
                    g2_dict[next_node] = new_g
                    f2[next_node] = new_f
                    heapq.heappush(h2_heap, (new_f, next_node))
                    parent2_dict[next_node] = current

    if best_meet is None:
        return []

    def reconstruct_path(parent1, parent2, start, goal, meet):
        path = []
        current = meet
        while current != start:
            path.insert(0, current)
            current = parent1[current]
        path.insert(0, start)
        current = meet
        while current != goal:
            path.append(parent2[current])
            current = parent2[current]
        return path

    return reconstruct_path(parent1_dict, parent2_dict, start, goal, best_meet)
