        next_front = []
        for r, c in front:
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc) and (nr, nc) not in parents:
                    parents[(nr, nc)] = (r, c)
                    next_front.append((nr, nc))
        return next_front

    # Initialize both sides
    start_parents = {start: None}
    goal_parents = {goal: None}

    start_front = deque([start])
    goal_front = deque([goal])

    while start_front and goal_front:
        # Expand start side
        next_start_front = []
        while start_front:
            r, c = start_front.popleft()
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc) and (nr, nc) not in start_parents:
                    if (nr, nc) in goal_parents:
                        # Found a meeting point
                        return build_path(start_parents, goal_parents, (nr, nc))
                    start_parents[(nr, nc)] = (r, c)
                    next_start_front.append((nr, nc))
        start_front = deque(next_start_front)

        if not start_front:
            return []

        # Expand goal side
        next_goal_front = []
        while goal_front:
            r, c = goal_front.popleft()
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc) and (nr, nc) not in goal_parents:
                    if (nr, nc) in start_parents:
                        return build_path(start_parents, goal_parents, (nr, nc))
                    goal_parents[(nr, nc)] = (r, c)
                    next_goal_front.append((nr, nc))
        goal_front = deque(next_goal_front)

        if not goal_front:
            return []

    return []

def build_path(start_parents, goal_parents, meet):
    path_forward = []
    current = meet
    while current is not None:
        path_forward.append(current)
        current = start_parents[current]
    path_forward.reverse()

    path_backward = []
    current = meet
    while current is not None:
        path_backward.append(current)
        current = goal_parents[current]

    return path_forward + path_backward[1:]
