        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def is_valid(row, col):
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] == '.'

    def jump_horizontal(current, delta):
        while True:
            x, y = current
            dx, dy = delta
            nx, ny = x + dx, y + dy
            if not is_valid(nx, ny):
                return None
            if (nx, ny) == goal:
                return (nx, ny)
            # Check for forced vertical neighbour
            if is_valid(nx, y - 1) and grid[nx][y - 1] == '.' and not is_valid(nx - dx, y - 1):
                return (nx, ny)
            if is_valid(nx, y + 1) and grid[nx][y + 1] == '.' and not is_valid(nx - dx, y + 1):
                return (nx, ny)
            current = (nx, ny)

    def jump_vertical(current, delta):
        while True:
            x, y = current
            dx, dy = delta
            nx, ny = x + dx, y + dy
            if not is_valid(nx, ny):
                return None
            if (nx, ny) == goal:
                return (nx, ny)
            # Check for horizontal jump from current
            if jump_horizontal((nx, ny), (0, 1)) is not None or jump_horizontal((nx, ny), (0, -1)) is not None:
                return (nx, ny)
            current = (nx, ny)

    while heap:
        f, g, current = heapq.heappop(heap)
        if current in visited:
            continue
        visited.add(current)
        if current == goal:
            return reconstruct_path(parent, start, current)

        for i, (dx, dy) in enumerate(directions):
            x, y = current
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and (nx, ny) not in visited:
                if i % 2 == 0:  # Horizontal direction
                    jump_point = jump_horizontal((nx, ny), (dx, dy))
                else:  # Vertical direction
                    jump_point = jump_vertical((nx, ny), (dx, dy))
                if jump_point and jump_point not in visited:
                    parent[jump_point] = current
                    new_g = g + abs(jump_point[0] - x) + abs(jump_point[1] - y)
                    heapq.heappush(heap, (new_g + manhattan(jump_point, goal), new_g, jump_point))

    return []

def reconstruct_path(parent, start, goal):
    path = [goal]
    while path[-1] != start:
        current = path[-1]
        if current not in parent:
            return []
        path.append(parent[current])
    path.reverse()
    return path
