                return new_pos
            if is_valid(r - 1, c) and grid[r - 1][c] == '.':
                if not is_valid(r - 1, c - dc):
                    return new_pos
            if is_valid(r + 1, c) and grid[r + 1][c] == '.':
                if not is_valid(r + 1, c - dc):
                    return new_pos

    def vertical_jump(pos, dir):
        r, c = pos
        dr = 1 if dir == 'down' else -1
        steps = 0
        while True:
            r += dr
            steps += 1
            if not is_valid(r, c):
                return None
            new_pos = (r, c)
            if new_pos == goal:
                return new_pos
            if horizontal_jump(new_pos, 'left') or horizontal_jump(new_pos, 'right'):
                return new_pos

    def get_jump_neighbors(pos):
        res = []
        r, c = pos
        # Horizontal directions
        for direction in ['left', 'right']:
            if direction == 'left' and is_valid(r, c - 1):
                jump = horizontal_jump((r, c), 'left')
                if jump:
                    res.append(jump)
            elif direction == 'right' and is_valid(r, c + 1):
                jump = horizontal_jump((r, c), 'right')
                if jump:
                    res.append(jump)
        # Vertical directions
        for direction in ['up', 'down']:
            if direction == 'up' and is_valid(r - 1, c):
                jump = vertical_jump((r, c), 'up')
                if jump:
                    res.append(jump)
            elif direction == 'down' and is_valid(r + 1, c):
                jump = vertical_jump((r, c), 'down')
                if jump:
                    res.append(jump)
        return res

    def reconstruct_path(came_from, current):
        path = [current]
        while current in came_from:
            current = came_from[current]
            path.append(current)
        path.reverse()
        return path

    open_set = []
    heapq.heappush(open_set, (manhattan(start, goal), start))
    came_from = {}
    g_score = {start: 0}

    while open_set:
        _, current = heapq.heappop(open_set)
        if current == goal:
            return reconstruct_path(came_from, current)
        for next_node in get_jump_neighbors(current):
            r, c = next_node
            step_diff = abs(r - current[0]) + abs(c - current[1])
            tentative_g = g_score[current] + step_diff
            if next_node not in g_score or tentative_g < g_score[next_node]:
                g_score[next_node] = tentative_g
                came_from[next_node] = current
                f_score = tentative_g + manhattan(next_node, goal)
                heapq.heappush(open_set, (f_score, next_node))
    return []
