        parent = {}
        g_score = {start: 0}
        f_score = {start: heuristic(start, goal)}
        queue = [(f_score[start], g_score[start], start)]
        visited = set()

        while queue:
            _, cost, current = heapq.heappop(queue)
            if current == goal:
                path = [current]
                while current in parent:
                    current = parent[current]
                    path.append(current)
                return path[::-1]
            if current in visited:
                continue
            visited.add(current)

            for d in directions:
                x, y = current[1] + d[1], current[0] + d[0]
                if not (0 <= x < cols and 0 <= y < rows) or grid[y][x] == '#':
                    continue
                if (y, x) not in g_score or g_score[(y, x)] > cost + 1:
                    g_score[(y, x)] = cost + 1
                    f_score[(y, x)] = g_score[(y, x)] + heuristic((y, x), goal)
                    parent[(y, x)] = current
                    heapq.heappush(queue, (f_score[(y, x)], g_score[(y, x)], (y, x)))

                jump = jump_point(grid, current, d)
                if jump and jump not in visited and grid[jump[0]][jump[1]] == '.':
                    if jump not in g_score or g_score[jump] > cost + manhattan(current, jump):
                        g_score[jump] = cost + manhattan(current, jump)
                        f_score[jump] = g_score[jump] + heuristic(jump, goal)
                        parent[jump] = current
                        heapq.heappush(queue, (f_score[jump], g_score[jump], jump))
        return []

