        dr, dc = direction
        row, col = node
        new_row = row + dr
        new_col = col + dc
        if not (0 <= new_row < rows and 0 <= new_col < cols) or grid[new_row][new_col] == '#':
            return None
        if (new_row, new_col) == goal:
            return (new_row, new_col)

        is_straight = (dr != 0 and dc == 0) or (dr == 0 and dc != 0)
        if is_straight:
            # Check for forced vertical neighbor
            if dr != 0:  # vertical move (up/down)
                for side in [(-1,0),(1,0)]:  # left and right
                    r, c = new_row + side[0], new_col + side[1]
                    if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.':
                        if grid[r + dr][c] == '#':
                            return (new_row, new_col)
            else:  # horizontal move (left/right)
                for side in [(-1,0),(1,0)]:  # up and down
                    r, c = new_row + side[0], new_col + side[1]
                    if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.':
                        if grid[r][c + dc] == '#':
                            return (new_row, new_col)
            return jump_point(grid, (new_row, new_col), direction)
        return None

