        r, c = r, c + dc
        while is_free((r, c)):
            if (r, c) == goal:
                return (r, c)
            if (
                (is_free((r - 1, c)) and not is_free((r - 1, c - dc))) or
                (is_free((r + 1, c)) and not is_free((r + 1, c - dc)))
            ):
                return (r, c)
            r, c = r, c + dc
        return None

    def jump_vertical(pos, direction):
        r, c = pos
        dr, dc = 1 if direction == 'down' else -1, 0
        r, c = r + dr, c
        while is_free((r, c)):
            if (r, c) == goal:
                return (r, c)
            for d in ['right', 'left']:
                if jump_horizontal((r, c), d):
                    return (r, c)
            r, c = r + dr, c
        return None

    def jump(pos, dir):
        r, c = pos
        dr, dc = dir

        if dr != 0:
            res = jump_vertical(pos, 'down' if dr > 0 else 'up')
        else:
            res = jump_horizontal(pos, 'right' if dc > 0 else 'left')
        return res

    def expand(pos):
        r, c = pos
        for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if is_free((nr, nc)):
                next_pos = (nr, nc)
                jpt = jump(next_pos, (dr, dc))
                if jpt:
                    yield jpt

    def reconstruct_path(came_from, start, goal):
        path = [goal]
        current = goal
        while current != start:
            current = came_from[current]
