        return 0 <= r < rows and 0 <= c < cols

    def is_wall(r, c):
        return not is_in_bounds(r, c) or grid[r][c] == '#'

    def get_neighbors(r, c):
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        return [(r + dr, c + dc) for dr, dc in directions if is_in_bounds(r + dr, c + dc) and not is_wall(r + dr, c + dc)]

    def is_forced_vertical(r, c, dr):
        if is_wall(r + dr, c):  # Wall below/above
            return False
        above = grid[r + dr][c] == '.' and is_wall(r, c)
        below = grid[r - dr][c] == '.' and is_wall(r, c)
        return above or below

    def jump_horizontal(r, c, dc, dr=0):
        step = 1
        while True:
            nr, nc = r + step * dr, c + step * dc
            if not is_in_bounds(nr, nc) or grid[nr][nc] == '#':
                return None
            if (nr, nc) == goal:
                return (nr, nc)
            if is_forced_vertical(nr, nc, 1) or is_forced_vertical(nr, nc, -1):
                return (nr, nc)
            step += 1

    def jump_vertical(r, c, dr, dc=0):
        step = 1
        while True:
            nr, nc = r + step * dr, c + step * dc
            if not is_in_bounds(nr, nc) or grid[nr][nc] == '#':
                return None
            if (nr, nc) == goal:
                return (nr, nc)
            if jump_horizontal(nr, nc, 1, 0) or jump_horizontal(nr, nc, -1, 0):
                return (nr, nc)
            step += 1

    def reconstruct_path(came_from, start, goal):
        path = []
        current = goal
        while current:
            path.append(current)
            current = came_from.get(current)
        path.reverse()
        return path if path[0] == start else []

    def get_manhattan(r, c):
        return abs(r - goal[0]) + abs(c - goal[1])

    open_set = []
    heapq.heappush(open_set, (get_manhattan(*start), 0, start, None))  # (f, g, pos, parent)

    came_from = dict()
    g_score = {start: 0}

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    while open_set:
        f, g, current, parent = heapq.heappop(open_set)

        if current == goal:
            came_from[current] = parent
            return reconstruct_path(came_from, start, goal)

        if parent and current in came_from:
            continue

        came_from[current] = parent

        for dr, dc in directions:
            nr, nc = current[0] + dr, current[1] + dc
            if is_in_bounds(nr, nc) and grid[nr][nc] != '#' and (nr, nc) not in g_score:
                if dr != 0:
                    jump_point = jump_vertical(current[0], current[1], dr, dc)
                else:
                    jump_point = jump_horizontal(current[0], current[1], dc, dr)

                if jump_point:
                    ng = g + 1
                    while (nr, nc) != jump_point:
                        ng += 1
                        nr += dr
                        nc += dc
                    if jump_point not in g_score or ng < g_score[jump_point]:
                        g_score[jump_point] = ng
                        heapq.heappush(open_set, (ng + get_manhattan(*jump_point), ng, jump_point, current))

    return []
