import heapq

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0])

    if not (0 <= start[0] < rows and 0 <= start[1] < cols and 0 <= goal[0] < rows and 0 <= goal[1] < cols):
        return []

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal:
        return [start]

    def is_goal(r, c):
        return (r, c) == goal

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def horizontal_jump(r, c, d):
        while True:
            next_c = c + d
            if next_c < 0 or next_c >= cols or grid[r][next_c] == '#':
                return None
            c = next_c
            if is_goal(r, c):
                return (r, c)
            if is_valid(r - 1, c) and (grid[r - 1][c - d] == '#' or grid[r + 1][c - d] == '#'):
                return (r, c)
            if not (is_valid(r - 1, c) or is_valid(r + 1, c)):
                return None

    def vertical_jump(r, c, d):
        while True:
            next_r = r + d
            if next_r < 0 or next_r >= rows or grid[next_r][c] == '#':
                return None
            r = next_r
            if is_goal(r, c):
                return (r, c)
            left = horizontal_jump(r, c, -1)
            right = horizontal_jump(r, c, 1)
            if left or right:
                return (r, c)

    def heuristic(r, c):
        return abs(r - goal[0]) + abs(c - goal[1])

    def jump(r, c, from_r, from_c):
        if is_goal(r, c):
            return (r, c)
        if is_valid(r, c):
            dx = c - from_c
            dy = r - from_c
            if dx != 0:  # Moving horizontally
                if is_valid(r, c - dx) and not (is_valid(r - 1, c) or is_valid(r + 1, c)):
                    return None
                result = horizontal_jump(r, c, dx)
                if result:
                    return result
            if dy != 0:  # Moving vertically
                if is_valid(r - dy, c) and not (is_valid(r, c - 1) or is_valid(r, c + 1)):
                    return None
                result = vertical_jump(r, c, dy)
                if result:
                    return result
        return None

    def neighbors(r, c):
        for dr, dc, dir_ in [(-1, 0, 'U'), (1, 0, 'D'), (0, -1, 'L'), (0, 1, 'R')]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                jump_point = jump(nr, nc, r, c)
                if jump_point:
                    yield jump_point

    visited = set()
    parent = {}
    g = {start: 0}
    pq = []
    heapq.heappush(pq, (heuristic(*start), g[start], start))

    while pq:
        f, cost, (r, c) = heapq.heappop(pq)
        if (r, c) == goal:
            break
        if (r, c) in visited:
            continue
        visited.add((r, c))
        for np in neighbors(r, c):
            nr, nc = np
            if is_valid(nr, nc):
                new_g = cost + abs(nr - r) + abs(nc - c)
                if (nr, nc) not in g or new_g < g[(nr, nc)]:
                    g[(nr, nc)] = new_g
                    parent[(nr, nc)] = (r, c)
                    heapq.heappush(pq, (new_g + heuristic(nr, nc), new_g, (nr, nc)))

    if goal not in parent:
        return []

    # Reconstruct path
    path = []
    curr = goal
    while curr != start:
        path.append(curr)
        curr = parent[curr]
    path.append(start)
    path.reverse()

    # Fill straight path
    final_path = [path[0]]
    for i in range(1, len(path)):
        r1, c1 = path[i-1]
        r2, c2 = path[i]
        dr = r2 - r1
        dc = c2 - c1
        if dr != 0:
            dr = 1 if dr > 0 else -1
        else:
            dr = 0
        if dc != 0:
            dc = 1 if dc > 0 else -1
        else:
            dc = 0
        r, c = r1, c1
        while (r, c) != (r2, c2):
            r += dr
            c += dc
            final_path.append((r, c))

    return final_path
