                return None
            if (r, c) == goal:
                return (r, c)
            # Check if next step has a forced vertical neighbor
            if is_free(r - 1, c) and (is_wall(r - 1, c - dr) or is_wall(r - 1 + dr, c - dr)):
                if parent[0] == r and parent[1] == c:
                    return (r, c)
                return (r, c)
            elif is_free(r + 1, c) and (is_wall(r + 1, c - dr) or is_wall(r + 1 + dr, c - dr)):
                if parent[0] == r and parent[1] == c:
                    return (r, c)
                return (r, c)
            # Continue if in straight path without forced neighbor
            if (r, c) in visited:
                return None

