            # Use horizontal jump to check for jump points
            left = jump_horizontal(r, c, -1, (r, c))
            if left:
                if parent[0] == r and parent[1] == c:
                    return (r, c)
                return (r, c)
            right = jump_horizontal(r, c, 1, (r, c))
            if right:
                if parent[0] == r and parent[1] == c:
                    return (r, c)
                return (r, c)
            # Continue if in straight path without jump point
            if (r, c) in visited:
                return None

    def reconstruct_path(came_from, current):
        path = [current]
        while current in came_from:
            current = came_from[current]
            path.append(current)
        return path[::-1]

    heap = []
    heapq.heappush(heap, (manhattan(start, goal), 0, start, None))
    came_from = {}
    g_score = {start: 0}

    while heap:
        f, g, curr, parent = heapq.heappop(heap)
        if curr == goal:
            path = reconstruct_path(came_from, curr)
            full_path = []
            for i in range(len(path) - 1):
                x1, y1 = path[i]
                x2, y2 = path[i + 1]
                dx = (x2 - x1) // abs(x2 - x1) if x1 != x2 else 0
                dy = (y2 - y1) // abs(y2 - y1) if y1 != y2 else 0
                step = 1
                while step < abs(x2 - x1) + abs(y2 - y1):
                    if dx:
                        full_path.append((x1 + dx * step, y1))
                    else:
                        full_path.append((x1, y1 + dy * step))
                    step += 1
                full_path.append((x2, y2))
            full_path.insert(0, start)
            return full_path

        if curr in visited:
            continue
        visited.add(curr)

        for dr, dc in [(0, -1), (0, 1), (-1, 0), (1, 0)]:
            if parent and (curr[0] + dr == parent[0] and curr[1] + dc == parent[1]):
                continue  # Skip the direction back to parent
            next_r, next_c = curr[0] + dr, curr[1] + dc
            if is_wall(next_r, next_c):
                continue
            if (dr == 0 or dc == 0):  # horizontal or vertical
                if dr == 0:  # horizontal
                    jump_point = jump_horizontal(curr[0], curr[1], dc, curr)
                else:  # vertical
                    jump_point = jump_vertical(curr[0], curr[1], dr, curr)
                if jump_point and jump_point not in visited:
                    new_g = g + (abs(jump_point[0] - curr[0]) + abs(jump_point[1] - curr[1]))
                    if jump_point not in g_score or new_g < g_score[jump_point]:
                        g_score[jump_point] = new_g
                        came_from[jump_point] = curr
                        heapq.heappush(heap, (new_g + manhattan(jump_point, goal), new_g, jump_point, curr))

    return []
