import heapq

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0])

    def is_goal(r, c):
        return (r, c) == goal

    def is_free(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def manhattan(r1, c1, r2, c2):
        return abs(r1 - r2) + abs(c1 - c2)

    def get_neighbors(r, c):
        return [(r + dr, c + dc) for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)] if is_free(r + dr, c + dc)]

    def horizontal_jump(r, c, d, g, parent):
        if not is_free(r, c) or (r, c) == parent:
            return None
        if is_goal(r, c):
            return (r, c, g, parent)
        # Check for forced vertical neighbors
        for dr in [-1, 1]:
            nr, nc = r + dr, c
            if is_free(nr, nc) and not is_free(nr + dr, nc) and (nr, nc) != parent:
                return (r, c, g, parent)
        while True:
            next_r, next_c = r, c + d
            if not is_free(next_r, next_c):
                return None
            if is_goal(next_r, next_c):
                return (next_r, next_c, g + 1, (r, c))
            if any(is_free(next_r, next_c + dr) and not is_free(r, c + d + dr, next_c + dr)
                   for dr in [-1, 1] if is_free(next_r, next_c + dr)):
                return (next_r, next_c, g + 1, (r, c))
            r, c = next_r, next_c
            g += 1

    def vertical_jump(r, c, d, g, parent):
        if not is_free(r, c) or (r, c) == parent:
            return None
        if is_goal(r, c):
            return (r, c, g, parent)
        # Check if any horizontal jump from this cell finds a jump point
        for dc in [-1, 1]:
            res = horizontal_jump(r, c, dc, 0, None)
            if res is not None:
                return (r, c, g, parent)
        while True:
            next_r, next_c = r + d, c
            if not is_free(next_r, next_c):
                return None
            if is_goal(next_r, next_c):
                return (next_r, next_c, g + 1, (r, c))
            r, c = next_r, next_c
            g += 1

    def a_star():
        open_list = [(manhattan(start[0], start[1], goal[0], goal[1]), 0, start, None)]
        visited = set()
        parent_map = {}

        while open_list:
            _, g, current, parent = heapq.heappop(open_list)
            if current in visited:
                continue
            visited.add(current)
            if current == goal:
                path = []
                node = current
                while node is not None:
                    path.append(node)
                    node = parent_map.get(node, None)
                return path[::-1]

            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                if dr == 0:
                    # Horizontal move
                    res = horizontal_jump(current[0], current[1], dc, g + 1, current)
                else:
                    # Vertical move
                    res = vertical_jump(current[0], current[1], dr, g + 1, current)
                if res is not None:
                    next_node, new_g, _parent = res
                    if next_node not in visited:
                        parent_map[next_node] = _parent
                        f = new_g + manhattan(next_node[0], next_node[1], goal[0], goal[1])
                        heapq.heappush(open_list, (f, new_g, next_node, current))
        return []

    def is_line_clear(p1, p2):
        r1, c1 = p1
        r2, c2 = p2
        if r1 == r2:  # Horizontal
            step = 1 if c2 > c1 else -1
            for c in range(c1 + step, c2, step):
                if not is_free(r1, c):
                    return False
        elif c1 == c2:  # Vertical
            step = 1 if r2 > r1 else -1
            for r in range(r1 + step, r2, step):
                if not is_free(r, c1):
                    return False
        return True

    if not is_free(start[0], start[1]) or not is_free(goal[0], goal[1]):
        return []
    if start == goal:
        return [start]

    path = a_star()
    if not path:
        return []

    # Fill in straight line from consecutive jump points
    result = [start]
    for i in range(1, len(path)):
        while True:
            next_point = path[i]
            if is_neighbour(result[-1], next_point):
                result.append(next_point)
                break
            found = False
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                r, c = result[-1]
                nr, nc = r + dr, c + dc
                if is_line_clear(result[-1], (nr, nc)) and is_line_clear((nr, nc), next_point) and is_free(nr, nc):
                    result.append((nr, nc))
                    found = True
                    break
            if not found:
                return []
    return result

def is_neighbour(p1, p2):
    r1, c1 = p1
    r2, c2 = p2
    return abs(r1 - r2) + abs(c1 - c2) == 1
