        next_r, next_c = r + dr, c + dc
        if not is_free(grid, (next_r, next_c)):
            return None

        if (dr != 0 and dc != 0):
            # Vertical direction
            while True:
                prev_r, prev_c = r - dr, c - dc
                next_r += dr
                next_c += dc
                if not is_free(grid, (next_r, next_c)):
                    return None
                if (next_r, next_c) == goal:
                    return (next_r, next_c)
                # Check for forced horizontal neighbors
                for ddr, ddc in [(-1, 0), (1, 0)]:  # Check above and below
                    next_next = (next_r + ddr, next_c + ddc)
                    if is_free(grid, next_next) and (next_r + ddr, next_c + ddc) == goal:
                        return (next_r, next_c)
                    if is_free(grid, next_next):
                        if not is_free(grid, (next_r + ddr - dr, next_c + ddc - dc)):
                            return (next_r, next_c)
        else:
            # Horizontal direction
            while True:
                next_r += dr
                next_c += dc
                if not is_free(grid, (next_r, next_c)):
                    return None
                if (next_r, next_c) == goal:
                    return (next_r, next_c)
                # Check for forced vertical neighbor (above or below, not equal to start cell)
                for ddr, ddc in [(-1, 0), (1, 0)]:  # Check above and below
                    temp_r, temp_c = next_r + ddr, next_c + ddc
                    if is_free(grid, (temp_r, temp_c)):
                        if not is_free(grid, (temp_r - dr, temp_c - dc)):
                            return (next_r, next_c)
                if (next_r, next_c) in came_from:
                    return (next_r, next_c)

    def get_neighbors(r, c):
        neighbors = []
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if is_free(grid, (nr, nc)):
                j = jump_point(r, c, dr, dc)
                if j:
                    neighbors.append(j)
        return neighbors

    open_set = []
    heapq.heappush(open_set, (manhattan(start, goal), 0, start))
    came_from = {}
    g_score = {start: 0}

    while open_set:
        _, g, current = heapq.heappop(open_set)

        if current == goal:
            path = [current]
            while current in came_from:
                current = came_from[current]
                path.insert(0, current)
            return path

        for neighbor in get_neighbors(current[0], current[1]):
            r1, c1 = current
            r2, c2 = neighbor
            new_g = g + (abs(r1 - r2) + abs(c1 - c2))
            if neighbor not in g_score or new_g < g_score[neighbor]:
                g_score[neighbor] = new_g
                heapq.heappush(open_set, (new_g + manhattan(neighbor, goal), new_g, neighbor))
                came_from[neighbor] = current

    return []

