import heapq

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and grid[start[0]][start[1]] == '.'):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0]) and grid[goal[0]][goal[1]] == '.'):
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def get_neighbors(r, c):
        return [(r + dr, c + dc) for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)] if 0 <= r + dr < rows and 0 <= c + dc < cols and grid[r + dr][c + dc] == '.']

    def is_wall(r, c):
        return r < 0 or c < 0 or r >= rows or c >= cols or grid[r][c] == '#'

    def jump_point(r, c, d):
        dr, dc = d
        nr, nc = r + dr, c + dc
        if not (0 <= nr < rows and 0 <= nc < cols) or grid[nr][nc] == '#':
            return None
        if (nr, nc) == goal:
            return (nr, nc)
        # Check for forced neighbors
        if dr != 0:  # vertical move
            if is_wall(r, nc - 1) != is_wall(nr, nc - 1) or is_wall(r, nc + 1) != is_wall(nr, nc + 1):
                return (nr, nc)
        elif dc != 0:  # horizontal move
            if is_wall(r - 1, c) != is_wall(r - 1, nc) or is_wall(r + 1, c) != is_wall(r + 1, nc):
                return (nr, nc)
        # Recursive jump
        result = jump_point(nr, nc, d)
        if result:
            return result
        return None

    def jump_horizontal(r, c, dc):
        while True:
            c += dc
            if not (0 <= c < cols) or grid[r][c] == '#':
                return None
            if (r, c) == goal:
                return (r, c)
            if (is_wall(r - 1, c) != is_wall(r - 1, c - dc)) or (is_wall(r + 1, c) != is_wall(r + 1, c - dc)):
                return (r, c)
            result = jump_point(r, c, (0, dc))
            if result:
                return result
            result = jump_horizontal(r, c, dc)
            if result:
                return result
            return None

    def jump_vertical(r, c, dr):
        while True:
            r += dr
            if not (0 <= r < rows) or grid[r][c] == '#':
                return None
            if (r, c) == goal:
                return (r, c)
            horizontal = jump_horizontal(r, c, -1) or jump_horizontal(r, c, 1)
            if horizontal:
                return (r, c)
            result = jump_point(r, c, (dr, 0))
            if result:
                return result
            result = jump_vertical(r, c, dr)
            if result:
                return result
            return None

    def get_jump_neighbors(r, c):
        result = []
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < rows and 0 <= nc < cols) or grid[nr][nc] == '#':
                continue
            if (nr, nc) == goal:
                result.append((nr, nc))
                continue
            if dc != 0:
                result.append(jump_horizontal(r, c, dc))
            else:
                result.append(jump_vertical(r, c, dr))
        return [cell for cell in result if cell is not None]

    def reconstruct_path(came_from, current):
        path = [current]
        while current in came_from:
            current = came_from[current]
            path.append(current)
        path.reverse()
        full_path = [path[0]]
        for i in range(1, len(path)):
            dx, dy = path[i][0] - path[i - 1][0], path[i][1] - path[i - 1][1]
            step = 1
            while full_path[-1] != path[i]:
                r, c = full_path[-1]
                full_path.append((r + dx * step, c + dy * step))
        return full_path

    came_from = {}
    g = {start: 0}
    f = {start: manhattan(start, goal)}
    heap = [(f[start], g[start], start)]
    visited = set()

    while heap:
        _, curr_g, current = heapq.heappop(heap)
        if current == goal:
            return reconstruct_path(came_from, current)
        if current in visited:
            continue
        visited.add(current)
        for next_cell in get_jump_neighbors(*current):
            new_g = curr_g + abs(next_cell[0] - current[0]) + abs(next_cell[1] - current[1])
            if next_cell not in g or new_g < g[next_cell]:
                g[next_cell] = new_g
                f[next_cell] = new_g + manhattan(next_cell, goal)
                heapq.heappush(heap, (f[next_cell], new_g, next_cell))
                came_from[next_cell] = current

    return []
