import heapq

def solve(grid, start, goal):
    if (
        not grid or
        not 0 <= start[0] < len(grid) or
        not 0 <= start[1] < len(grid[0]) or
        not 0 <= goal[0] < len(grid) or
        not 0 <= goal[1] < len(grid[0]) or
        grid[start[0]][start[1]] == '#' or
        grid[goal[0]][goal[1]] == '#'
    ):
        return []

    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    parent = {}

    def heuristic(r, c):
        return abs(r - goal[0]) + abs(c - goal[1])

    open_heap = []
    heapq.heappush(open_heap, (0 + heuristic(*start), 0, start))
    closed = set()

    def jump_horizontal(r, c, dr, dc):
        step = 1
        while is_valid(r + dr, c):
            r += dr
            step += 1
            if (r, c) == goal:
                return r, c
            if is_valid(r, c + dc) and (not is_valid(r, c + dc - 1) or not is_valid(r, c + dc + 1)):
                return r, c
        return None

    def jump_vertical(r, c, dr, dc):
        step = 1
        while is_valid(r + dr, c):
            r += dr
            step += 1
            if (r, c) == goal:
                return r, c
            lr, lc = jump_horizontal(r, c, 0, -1)
            if lr is not None and lc is not None:
                return lr, lc
            lr, lc = jump_horizontal(r, c, 0, 1)
            if lr is not None and lc is not None:
                return lr, lc
        return None

    while open_heap:
        f, g, (r, c) = heapq.heappop(open_heap)
        if (r, c) == goal:
            path = []
            while (r, c) in parent:
                path.append((r, c))
                r, c = parent[(r, c)]
            path.append(start)
            return path[::-1]
        closed.add((r, c))
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and (nr, nc) not in closed:
                if dr == 0 or dc == 0:
                    # Horizontal/Vertical move
                    jpr, jpc = jump_horizontal(r, c, dr, dc)
                else:
                    # Diagonal direction (not used in 4-connected)
                    continue
                if jpr is not None and jpc is not None:
                    jg = g + (abs(jpr - r) + abs(jpc - c))
                    jf = jg + heuristic(jpr, jpc)
                    if (jpr, jpc) not in closed and (jf, jg, (jpr, jpc)) not in open_heap:
                        parent[(jpr, jpc)] = (r, c)
                        heapq.heappush(open_heap, (jf, jg, (jpr, jpc)))

    return []
