    visited = set()
    parent = {}
    g_cost = {start: 0}

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def is_free(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def jump_point(r, c, parent_dir):
        if (r, c) == goal:
            return (r, c)
        if not is_free(r, c):
            return None
        if (r, c) in visited:
            return None

        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # Right, Down, Left, Up
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_free(nr, nc):
                if parent_dir is None:
                    visited.add((r, c))
                if (dr == 0 and jump_horizontally(r, c, dc, parent_dir is None)) or \
                   (dr != 0 and jump_vertically(r, c, dr, dc, parent_dir is None)):
                    return (r, c)
        return None

    def jump_horizontally(r, c, dc, first_call=True):
        path = []
        while True:
            nr, nc = r, c + dc
            if not is_free(nr, nc):
                return None
            if (nr, nc) == goal:
                return (nr, nc)
            path.append((r, c))
            c = nc
            if first_call and (r - 1, c) in visited or (r + 1, c) in visited:
                return (r, c)
            if jump_vertically(r, c, 1, dc, False) or jump_vertically(r, c, -1, dc, False):
                return (r, c)
        return None

    def jump_vertically(r, c, dr, dc, first_call=True):
        path = []
        while True:
            nr, nc = r + dr, c
            if not is_free(nr, nc):
                return None
            if (nr, nc) == goal:
                return (nr, nc)
            if first_call:
                path.append((r, c))
            r = nr
            if jump_horizontally(r, c, dc, False) or jump_horizontally(r, c, -dc, False):
                return (r, c)
        return None

    while heap:
        f, g, current, prev = heapq.heappop(heap)
        if current == goal:
            path = [current]
            while prev is not None:
                path.append(prev)
                prev = parent.get(prev)
            return path[::-1]

        if current in visited:
            continue
        visited.add(current)

        if current not in g_cost or g > g_cost[current]:
            g = g_cost[current]

        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # Up, Down, Left, Right
        for dr, dc in directions:
            nr, nc = current[0] + dr, current[1] + dc
            if is_free(nr, nc) and (nr, nc) not in visited:
                parent_dir = (dr, dc)
                jp = jump_point(nr, nc, parent_dir)
                if jp:
                    g_new = g + abs(nr - current[0]) + abs(nc - current[1])
                    if jp not in g_cost or g_new < g_cost[jp]:
                        g_cost[jp] = g_new
                        parent[jp] = current
                        h = manhattan(jp, goal)
                        f = g_new + h
                        heapq.heappush(heap, (f, g_new, jp, current))

    return []
