            result.append(jp)
    return result

def jump_helper(grid, current, goal, dr, dc, rows, cols):
    r, c = current
    nr, nc = r + dr, c + dc

    # Check bounds
    if not (0 <= nr < rows and 0 <= nc < cols):
        return None
    if grid[nr][nc] == '#':
        return None

    new_pos = (nr, nc)

    # If the next cell is the goal
    if new_pos == goal:
        return new_pos

    # For horizontal movement (dr == 0 or dc == 0)
    if dr == 0 or dc == 0:
        # Check for forced vertical move
        if dr != 0:
            if 0 <= nr-1 < rows and grid[nr-1][nc] == '#':  # above is wall
                if 0 <= nc-1 < cols and grid[nr][nc-1] == '.':
                    return new_pos
            if 0 <= nr+1 < rows and grid[nr+1][nc] == '#':  # below is wall
                if 0 <= nc-1 < cols and grid[nr][nc-1] == '.':
                    return new_pos
        else:
            if 0 <= nc-1 < cols and grid[nr][nc-1] == '#':  # left is wall
                if 0 <= nr-1 < rows and grid[nr-1][nc] == '.':
                    return new_pos
            if 0 <= nc+1 < cols and grid[nr][nc+1] == '#':  # right is wall
                if 0 <= nr-1 < rows and grid[nr-1][nc] == '.':
                    return new_pos

    # Continue in the same direction
    return jump_helper(grid, new_pos, goal, dr, dc, rows, cols)
