        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def is_in_bounds(r, c):
        return 0 <= r < rows and 0 <= c < cols

    def is_free(r, c):
        return is_in_bounds(r, c) and grid[r][c] == '.'

    def get_neighbors(r, c, dr, dc):
        cells = []
        r += dr
        c += dc
        while is_in_bounds(r, c) and grid[r][c] == '.':
            cells.append((r, c))
            r += dr
            c += dc
        return cells

    def is_forced_vertical(r, c, dr, dc):
        r += dr
        if 0 <= r < rows and grid[r][c] == '#':
            return False
        if 0 <= r - dr < rows and 0 <= c - dc < cols and grid[r - dr][c - dc] == '#':
            return False
        if 0 <= r + 1 < rows and grid[r + 1][c] == '#':
            return False
        if 0 <= r - 1 < rows and grid[r - 1][c] == '#':
            return False
        if 0 <= r + 1 < rows and 0 <= c + 1 < cols and grid[r + 1][c + 1] == '#':
            return False
        if 0 <= r - 1 < rows and 0 <= c - 1 < cols and grid[r - 1][c - 1] == '#':
            return False
        return False

    def jump_horizontal(r, c, dc, parent):
        steps = 0
        while True:
            c += dc
            if not is_in_bounds(r, c) or grid[r][c] == '#':
                return None, None
            steps += 1
            if (r, c) == goal:
                return (r, c), steps
            if is_forced_vertical(r, c, 1, dc) or is_forced_vertical(r, c, -1, dc):
                return (r, c), steps
            if parent:
                if (r, c) == parent:
                    return None, None

    def jump_vertical(r, c, dr, parent):
        steps = 0
        while True:
            r += dr
            if not is_in_bounds(r, c) or grid[r][c] == '#':
                return None, None
            steps += 1
            if (r, c) == goal:
                return (r, c), steps
            if jump_horizontal(r, c, 1, (r - dr, c))[0] or jump_horizontal(r, c, -1, (r - dr, c))[0]:
                return (r, c), steps
            if parent:
                if (r, c) == parent:
                    return None, None

    pq = [(manhattan(start, goal), 0, start, None)]
    visited = {start: None}

    while pq:
        _, g, current, parent = heapq.heappop(pq)
        if current == goal:
            break
        if grid[current[0]][current[1]] == '#':
            continue
        r, c = current
        for dr, dc, jump_func in [(1, 0, jump_vertical), (-1, 0, jump_vertical), (0, 1, jump_horizontal), (0, -1, jump_horizontal)]:
            jr, steps = jump_func(r, c, dr, dc, parent)
            if jr:
                if jr not in visited or g + steps < gval(visited[jr]):
                    visited[jr] = current
                    heapq.heappush(pq, (g + steps + manhattan(jr, goal), g + steps, jr, current))

    if goal not in visited:
        return []

    path = []
    cur = goal
    while cur:
        path.append(cur)
        cur = visited.get(cur)
    path.reverse()

    def gval(p):
        if not p:
            return -1
        i = 0
        while p:
            p = visited.get(p)
            i += 1
        return i

    final_path = [start]
    i = 1
    while i < len(path):
        last, curr = path[i - 1], path[i]
        dr = curr[0] - last[0]
        dc = curr[1] - last[1]
        if dr != 0:
            for r in range(last[0], curr[0], dr):
                final_path.append((r, last[1]))
        else:
            for c in range(last[1], curr[1], dc):
                final_path.append((last[0], c))
        if final_path[-1] != curr:
            final_path.append(curr)
        i += 1

    if final_path[-1] == goal:
        return final_path
    return []
