import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]

    rows = len(grid)
    cols = len(grid[0])

    if (not (0 <= start[0] < rows and 0 <= start[1] < cols) or 
        not (0 <= goal[0] < rows and 0 <= goal[1] < cols) or 
        grid[start[0]][start[1]] == '#' or 
        grid[goal[0]][goal[1]] == '#'):
        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right
    parent = {}
    open_list = []
    heapq.heappush(open_list, (heuristic(start, goal), 0, start))

    while open_list:
        _, g, cell = heapq.heappop(open_list)
        if cell == goal:
            return reconstruct_path(parent, start, goal)

        if cell in parent or grid[cell[0]][cell[1]] == '#':
            continue

        parent[cell] = None

        for dx, dy in directions:
            if ( (dx == -1 or dx == 1) and (dy == 0) ):
                jump = jump_horizontal(grid, cell, dx, dy, parent, g, goal)
            elif ( (dx == 0) and (dy == -1 or dy == 1) ):
                jump = jump_vertical(grid, cell, dx, dy, parent, g, goal)
            else:
                continue

            if jump:
                new_g = g + manhattan_distance(cell, jump)
                new_h = heuristic(jump, goal)
                heapq.heappush(open_list, (new_g + new_h, new_g, jump))
                parent[jump] = cell

    return []

def heuristic(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])

def manhattan_distance(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])

def jump_horizontal(grid, current, dx, dy, parent, g, goal):
    row, col = current
    rows = len(grid)
    cols = len(grid[0])
    next_cell = (row + dx, col + dy)

    if not (0 <= next_cell[0] < rows and 0 <= next_cell[1] < cols):
        return None
    if grid[next_cell[0]][next_cell[1]] == '#':
        return None

    next_row, next_col = next_cell
    if next_cell == goal:
        return next_cell

    if grid[next_row + 1][next_col] == '.' or grid[next_row - 1][next_col] == '.':
        return next_cell

    rest = jump_horizontal(grid, next_cell, dx, dy, parent, g, goal)

    if rest:
        parent[rest] = current
        return rest
    else:
        return None

def jump_vertical(grid, current, dx, dy, parent, g, goal):
    row, col = current
    rows = len(grid)
    cols = len(grid[0])
    next_cell = (row + dx, col + dy)

    if not (0 <= next_cell[0] < rows and 0 <= next_cell[1] < cols):
        return None
    if grid[next_cell[0]][next_cell[1]] == '#':
        return None

    next_row, next_col = next_cell
    if next_cell == goal:
        return next_cell

    for d in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        if d != (0, 0):
            jump = jump_horizontal(grid, next_cell, d[0], d[1], parent, g, goal)
            if jump:
                parent[jump] = current
                return jump

    rest = jump_vertical(grid, next_cell, dx, dy, parent, g, goal)

    if rest:
        parent[rest] = current
        return rest
    else:
        return None

def reconstruct_path(parent, start, goal):
    path = [goal]
    while path[-1] != start:
        prev = parent.get(path[-1])
        if prev is None:
            return []
        path.append(prev)
    path.reverse()
    return path
