        r, c = pos
        step = 1
        while True:
            r += dr * step
            c += dc * step
            if r < 0 or r >= rows or c < 0 or c >= cols or grid[r][c] == '#':
                return None
            if (r, c) == goal:
                return (r, c)
            if ((r + dr < rows and r + dr >= 0 and c < cols and c >= 0 and grid[r + dr][c] == '.') and
                (grid[r + dr][c] == '.' and (grid[r + dr][c + dr] == '#' or grid[r - dr][c - dr] == '#'))):
                return (r, c)
            if jump_vertical((r, c), (1, 0)) or jump_vertical((r, c), (-1, 0)):
                return (r, c)
            step += 1

    def jump_vertical(pos, direction):
        dr, dc = direction
        r, c = pos
        step = 1
        while True:
            r += dr * step
            if r < 0 or r >= rows or grid[r][c] == '#':
                return None
            if (r, c) == goal:
                return (r, c)
            if jump_horizontal((r, c), (0, -1)) or jump_horizontal((r, c), (0, 1)):
                return (r, c)
            step += 1

    while heap:
        (_, current) = heapq.heappop(heap)

        if current == goal:
            break

        for direction in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            next_cell = (current[0] + direction[0], current[1] + direction[1])
            if next_cell[0] < 0 or next_cell[0] >= rows or next_cell[1] < 0 or next_cell[1] >= cols or grid[next_cell[0]][next_cell[1]] == '#':
