        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def horizontal_jumps(r, c, step_x, parent):
        jump_point = None
        while True:
            c += step_x
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            # Look up and down for forced neighbors
            if is_valid(r - 1, c) and (not is_valid(r - 1, c - step_x) if step_x != 0 else False):
                return (r, c)
            if is_valid(r + 1, c) and (not is_valid(r + 1, c - step_x) if step_x != 0 else False):
                return (r, c)
            if (r, c) in came_from:
                return None
            jump_point = (r, c)

    def vertical_jumps(r, c, step_y, parent):
        jump_point = None
        while True:
            r += step_y
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            # Check for forced neighbors in horizontal directions
            if is_valid(r, c - 1) and (not is_valid(r - step_y, c - 1)):
                return (r, c)
            if is_valid(r, c + 1) and (not is_valid(r - step_y, c + 1)):
                return (r, c)
            res1 = horizontal_jumps(r, c, 1, (r, c))
            res2 = horizontal_jumps(r, c, -1, (r, c))
            if res1 or res2:
                return (r, c)
            if (r, c) in came_from:
                return None
            jump_point = (r, c)

    def jump(r, c, parent):
        dr, dc = 0, 0
        if parent[0] < r:
            dr = 1
        elif parent[0] > r:
            dr = -1
        if parent[1] < c:
            dc = 1
        elif parent[1] > c:
            dc = -1
        if dr != 0:
            return vertical_jumps(r, c, dr, parent)
        elif dc != 0:
            return horizontal_jumps(r, c, dc, parent)
        return None

    def neighbors(r, c, parent):
        res = []
        for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and (nr, nc) != parent:
                j = jump(nr, nc, (r, c))
                if j:
                    res.append((nr, nc))
        return res

    came_from = {}
    g_score = {start: 0}
    f_score = {start: manhattan(start, goal)}
    heap = [(f_score[start], g_score[start], start)]
    goal_found = None

    while heap:
        _, curr_g, curr = heapq.heappop(heap)
        if curr == goal:
            goal_found = curr
            break
        for nr, nc in neighbors(*curr, None if curr == start else [x for x in [curr[0], curr[1]]]):
            new_g = curr_g + 1
            if (nr, nc) not in g_score or new_g < g_score[(nr, nc)]:
                came_from[(nr, nc)] = curr
                g_score[(nr, nc)] = new_g
                f_score[(nr, nc)] = new_g + manhattan((nr, nc), goal)
                heapq.heappush(heap, (f_score[(nr, nc)], new_g, (nr, nc)))

    if not goal_found:
        return []

    path = []
    curr = goal
    while curr in came_from:
        path.append(curr)
        curr = came_from[curr]
    path.append(start)
    path.reverse()

    return path
