        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])

    def is_valid(pos):
        r, c = pos
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def horizontal_jump(pos, parent_dir):
        curr_r, curr_c = pos
        dir = 1 if parent_dir[1] > 0 else -1  # Right or left
        step = 0
        while True:
            next_r, next_c = curr_r, curr_c + dir
            if not (0 <= next_c < cols):
                return None
            curr_c += dir
            step += 1
            if (curr_r, curr_c) == goal:
                return (curr_r, curr_c)
            # Check for forced vertical neighbor
            if grid[curr_r - 1][curr_c] == '.' or grid[curr_r + 1][curr_c] == '.':
                if grid[curr_r - 1][curr_c] == '#' or grid[curr_r + 1][curr_c] == '#':
                    if is_valid((curr_r - 1, curr_c - dir)) or is_valid((curr_r + 1, curr_c - dir)):
                        return (curr_r, curr_c)
                elif (grid[curr_r - 1][curr_c] == '.' and is_valid((curr_r - 1, curr_c - dir))) or \
                     (grid[curr_r + 1][curr_c] == '.' and is_valid((curr_r + 1, curr_c - dir))):
                    return (curr_r, curr_c)
            elif not is_valid((curr_r, curr_c + dir)) and not is_valid((curr_r, curr_c - dir)):
                return None

    def vertical_jump(pos, parent_dir):
        curr_r, curr_c = pos
        dir = 1 if parent_dir[0] > 0 else -1  # Down or up
        step = 0
        while True:
            next_r, next_c = curr_r + dir, curr_c
            if not (0 <= next_r < rows):
                return None
            curr_r += dir
            step += 1
            if (curr_r, curr_c) == goal:
                return (curr_r, curr_c)
            # Check for forced horizontal neighbor
            for d in (-1, 1):
                next_pos = horizontal_jump((curr_r, curr_c), (0, d))
                if next_pos:
                    return (curr_r, curr_c)
            if not is_valid((curr_r + dir, curr_c)) and not is_valid((curr_r - dir, curr_c)):
                return None

    def get_jump_points(pos, direction):
        jump_points = []
        if direction == (0, 1):  # Right
            jump = horizontal_jump(pos, direction)
            if jump:
                jump_points.append(jump)
        elif direction == (0, -1):  # Left
            jump = horizontal_jump(pos, direction)
            if jump:
                jump_points.append(jump)
        elif direction == (1, 0):  # Down
            jump = vertical_jump(pos, direction)
            if jump:
                jump_points.append(jump)
        elif direction == (-1, 0):  # Up
            jump = vertical_jump(pos, direction)
            if jump:
                jump_points.append(jump)
        return jump_points

    open_set = []
    heapq.heappush(open_set, (manhattan(start, goal), manhattan(start, goal), start, None, 0))
    came_from = {}
    g_scores = {start: 0}

