        if current == goal:
            break
        if current in came_from and current == came_from[current]:
            continue
        if parent is not None:
            dr = current[0] - parent[0]
            dc = current[1] - parent[1]
            if dr != 0:
                jump_dirs = [(1, 0), (-1, 0)]
            else:
                jump_dirs = [(0, 1), (0, -1)]
        else:
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if abs(dr) + abs(dc) != 1:
                        continue
                    neighbor = (current[0] + dr, current[1] + dc)
                    if is_valid(neighbor):
                        jump_points = get_jump_points(current, (dr, dc))
                        if jump_points:
                            for jp in jump_points:
                                if jp not in g_scores or g_scores[jp] > g + 1:
                                    g_scores[jp] = g + 1
                                    heapq.heappush(open_set, (
                                        g + 1 + manhattan(jp, goal), manhattan(jp, goal), jp, current, g + 1
                                    ))
                                    came_from[jp] = current
            continue

        for (dr, dc) in jump_dirs:
