                next_pos = jump[0]
                next_g = g + 1
                if next_pos not in g_scores or g_scores[next_pos] > next_g:
                    g_scores[next_pos] = next_g
                    heapq.heappush(open_set, (
                        next_g + manhattan(next_pos, goal), manhattan(next_pos, goal), next_pos, current, next_g
                    ))
                    came_from[next_pos] = current

    if goal not in came_from:
        return []

    # Reconstruct path
    path = [goal]
    curr = goal
    while curr != start:
        curr = came_from[curr]
        path.append(curr)
    path.reverse()

    # Return the unbroken path
    result_path = []
    for i in range(len(path) - 1):
        direction = (path[i+1][0] - path[i][0], path[i+1][1] - path[i][1])
        while path[i] != path[i+1]:
            result_path.append(path[i])
            path[i] = (path[i][0] + direction[0], path[i][1] + direction[1])
    result_path.append(path[-1])

    return result_path
