import heapq

def solve(grid, start, goal):
    if (start == goal) and (grid[start[0]][start[1]] == '.'):
        return [start]

    if not is_free(grid, *start) or not is_free(grid, *goal):
        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # Up, Down, Left, Right
    parent = {}
    g = {start: 0}
    f = {start: heuristic(start, goal)}
    heap = [(f[start], *start)]

    while heap:
        _, r, c = heapq.heappop(heap)
        if (r, c) == goal:
            return reconstruct_path(parent, start, goal)

        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:  # Horizontal and vertical jump directions
            jumped = jump(grid, start, goal, r, c, dr, dc, g, parent)
            if jumped:
                nr, nc = jumped
                new_g = g[(r, c)] + distance((r, c), (nr, nc))
                if (nr, nc) not in g or new_g < g[(nr, nc)]:
                    g[(nr, nc)] = new_g
                    f[(nr, nc)] = new_g + heuristic((nr, nc), goal)
                    heapq.heappush(heap, (f[(nr, nc)], nr, nc))
                    parent[(nr, nc)] = (r, c)

    return []

def jump(grid, start, goal, r, c, dr, dc, g, parent):
    if not in_bounds(grid, r, c) or grid[r][c] == '#':
        return None

    if (r, c) == goal:
        return r, c

    if dr == 0 and dc != 0:  # Horizontal jump
        while 1:
            nr, nc = r + dr, c + dc
            if not in_bounds(grid, nr, nc) or grid[nr][nc] == '#':
                return None
            # Check for forced vertical neighbor
            if check_forced_vertical(grid, r, c, dr, dc):
                return r, c
            if jump(grid, start, goal, nr, nc, dr, dc, g, parent):
                return jump(grid, start, goal, nr, nc, dr, dc, g, parent)
            c += dc
    else:
        if dr != 0 and dc == 0:  # Vertical jump
            while 1:
                nr, nc = r + dr, c + dc
                if not in_bounds(grid, nr, nc) or grid[nr][nc] == '#':
                    return None
                # Check for forced horizontal neighbor
                if check_forced_horizontal(grid, r, c, dr, dc):
                    return r, c
                if jump(grid, start, goal, nr, nc, dr, dc, g, parent):
                    return jump(grid, start, goal, nr, nc, dr, dc, g, parent)
                r += dr

    return None

def check_forced_vertical(grid, r, c, dr, dc):
    # Up/down neighbor
    if in_bounds(grid, r - 1, c) and grid[r - 1][c] == '.' and grid[r - 2][c] == '#':
        return True
    if in_bounds(grid, r + 1, c) and grid[r + 1][c] == '.' and grid[r + 2][c] == '#':
        return True
    return False

def check_forced_horizontal(grid, r, c, dr, dc):
    if jump(grid, start=None, goal=(r, c), r=r, c=c, dr=0, dc=1, g=None, parent=None) or \
       jump(grid, start=None, goal=(r, c), r=r, c=c, dr=0, dc=-1, g=None, parent=None):
        return True
    return False

def in_bounds(grid, r, c):
    return 0 <= r < len(grid) and 0 <= c < len(grid[0])

def is_free(grid, r, c):
    return in_bounds(grid, r, c) and grid[r][c] == '.'

def heuristic(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])

def distance(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])

def reconstruct_path(parent, start, goal):
    path = []
    current = goal
    while current != start:
        path.append(current)
        current = parent.get(current)
        if current is None:
            return []
    path.append(start)
    path.reverse()
    return path
