    if not is_free(grid, start) or not is_free(grid, goal):
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1,0), (1,0), (0,-1), (0,1)]

    def is_free(grid, pos):
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[r]) and grid[r][c] == '.'

    def manhattan(a, b):
        return abs(a[0]-b[0]) + abs(a[1]-b[1])

    forward_open = []
    backward_open = []
    heapq.heappush(forward_open, (manhattan(start, goal), 0, start))
    heapq.heappush(backward_open, (manhattan(start, goal), 0, goal))

    forward_g = {start: 0}
    backward_g = {goal: 0}
    forward_parent = {}
    backward_parent = {}

    def expand_forward():
        if not forward_open:
            return None
        f, g, node = heapq.heappop(forward_open)
        if node in forward_g and forward_g[node] < g:
            return None
        for dr, dc in directions:
            nr, nc = node[0]+dr, node[1]+dc
            next_cell = (nr, nc)
            if is_free(grid, next_cell) and forward_g.get(next_cell, float('inf')) > g + 1:
                forward_g[next_cell] = g + 1
                heapq.heappush(forward_open, (g + 1 + manhattan(next_cell, goal), g + 1, next_cell))
                forward_parent[next_cell] = node
        return (node, g)

    def expand_backward():
        if not backward_open:
            return None
        f, g, node = heapq.heappop(backward_open)
        if node in backward_g and backward_g[node] < g:
            return None
        for dr, dc in directions:
            nr, nc = node[0]+dr, node[1]+dc
            next_cell = (nr, nc)
            if is_free(grid, next_cell) and backward_g.get(next_cell, float('inf')) > g + 1:
                backward_g[next_cell] = g + 1
                heapq.heappush(backward_open, (g + 1 + manhattan(next_cell, start), g + 1, next_cell))
                backward_parent[next_cell] = node
        return (node, g)

    best_meeting_point = None
    best_cost = float('inf')

    while forward_open and backward_open:
        forward_expanded = expand_forward()
        if not forward_expanded:
            break
        (f_node, f_cost) = forward_expanded

        if f_node in backward_g:
            total_cost = f_cost + backward_g[f_node]
            if total_cost < best_cost:
                best_meeting_point = f_node
                best_cost = total_cost
                break

        backward_expanded = expand_backward()
        if not backward_expanded:
            break
        (b_node, b_cost) = backward_expanded

        if b_node in forward_g:
            total_cost = b_cost + forward_g[b_node]
            if total_cost < best_cost:
                best_meeting_point = b_node
                best_cost = total_cost
                break

    if best_meeting_point is None:
        return []

    def build_path(meet):
        path_forward = []
        node = meet
        while node in forward_parent:
            path_forward.append(node)
            node = forward_parent[node]
        path_forward = path_forward[::-1]

        path_backward = []
        node = meet
        while node in backward_parent:
            path_backward.append(node)
            node = backward_parent[node]

        return [start] + path_forward + path_backward

    return build_path(best_meeting_point)
