import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start] if grid[start[0]][start[1]] == '.' else []

    rows = len(grid)
    cols = len(grid[0])

    def is_valid(r, c):
        return (0 <= r < rows) and (0 <= c < cols)

    def is_wall(r, c):
        return not is_valid(r, c) or grid[r][c] == '#'

    def get_neighbors(r, c):
        neighbors = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and not is_wall(nr, nc):
                neighbors.append((nr, nc))
        return neighbors

    def heuristic(r, c):
        return abs(r - goal[0]) + abs(c - goal[1])

    def jump_horizontal(r, c, dr, dc):
        if (r, c) == goal:
            return (r, c)
        if is_wall(r, c):
            return None
        if is_wall(r + dr, c) or is_wall(r, c + dc):
            return (r, c)
        if (r + dr, c) == goal or (r, c + dc) == goal:
            return (r, c)
        if is_wall(r - dr, c) or is_wall(r, c - dc):
            return (r, c)

        next_r, next_c = r + dc, c + dc
        if is_wall(next_r, next_c + dr) or is_wall(next_r, next_c - dr):
            return (next_r, next_c)

        next_r, next_c = r + dr, c + dr
        if is_wall(next_r, next_c + dc) or is_wall(next_r, next_c - dc):
            return (next_r, next_c)

        return jump_horizontal(r + dc, c + dc, dr, dc)

    def jump_vertical(r, c, dr, dc):
        if (r, c) == goal:
            return (r, c)
        if is_wall(r, c):
            return None
        if is_wall(r + dr, c) or is_wall(r, c + dc):
            return (r, c)
        if (r + dr, c) == goal or (r, c + dc) == goal:
            return (r, c)
        if is_wall(r - dr, c) or is_wall(r, c - dc):
            return (r, c)

        next_r, next_c = r + dr, c + dr
        if is_wall(next_r, next_c + dc) or is_wall(next_r, next_c - dc):
            return (next_r, next_c)

        next_r, next_c = r + dc, c + dc
        if is_wall(next_r, next_c + dr) or is_wall(next_r, next_c - dr):
            return (next_r, next_c)

        return jump_vertical(r + dr, c + dr, dr, dc)

    def jump(r, c, parent_r, parent_c):
        if (r, c) == goal:
            return (r, c)
        if is_wall(r, c):
            return None

        dr = r - parent_r
        dc = c - parent_c
        if dr != 0 and dc != 0:
            return None

        if dc != 0:
            result = jump_horizontal(r, c, dr, dc)
        else:
            result = jump_vertical(r, c, dr, dc)

        return result

    open_set = []
    came_from = {}
    g_score = {}

    start_g = 0
    start_f = start_g + heuristic(*start)
    heapq.heappush(open_set, (start_f, start_g, start))
    g_score[start] = start_g

    while open_set:
        _, current_g, current = heapq.heappop(open_set)

        if current == goal:
            return reconstruct_path(came_from, current)

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            next_cell = (current[0] + dr, current[1] + dc)
            if is_valid(*next_cell) and not is_wall(*next_cell):
                jump_result = jump(next_cell[0], next_cell[1], current[0], current[1])
                if jump_result is not None:
                    new_g = current_g + abs(jump_result[0] - current[0]) + abs(jump_result[1] - current[1])
                    if jump_result not in g_score or new_g < g_score[jump_result]:
                        g_score[jump_result] = new_g
                        f_score = new_g + heuristic(*jump_result)
                        heapq.heappush(open_set, (f_score, new_g, jump_result))
                        came_from[jump_result] = current

    return []

def reconstruct_path(came_from, current):
    path = [current]
    while current in came_from:
        current = came_from[current]
        path.append(current)

    path.reverse()
    return path
