    rows = len(grid)
    cols = len(grid[0])

    def in_bounds(pos):
        r, c = pos
        return 0 <= r < rows and 0 <= c < cols

    def is_free(pos):
        r, c = pos
        return grid[r][c] == '.' if in_bounds(pos) else False

    def manhattan(pos):
        return abs(pos[0] - goal[0]) + abs(pos[1] - goal[1])

    def get_neighbors(pos):
        r, c = pos
        return [(r+1, c), (r-1, c), (r, c+1), (r, c-1)]

    def jump_horizontal(pos, d_x, parent):
        r, c = pos
        new_c = c + d_x
        ns = (r, new_c)
        if not is_free(ns):
            return None

        if ns == goal:
            return ns

        # Check if forced
        up = (r - 1, c)
        down = (r + 1, c)
        prev = (r, c - d_x) if d_x > 0 else (r, c + d_x)
        if is_free(up) and not is_free((up[0], prev[1])):
            return ns
        if is_free(down) and not is_free((down[0], prev[1])):
            return ns

        # Recursively jump further
        new_jump = jump_horizontal(ns, d_x, pos)
        if new_jump:
            return new_jump
        return None

    def jump_vertical(pos, d_y, parent):
        r, c = pos
        new_r = r + d_y
        ns = (new_r, c)
        if not is_free(ns):
            return None

        if ns == goal:
            return ns

        # Check if forced
        left = (r, c - 1)
        right = (r, c + 1)
        prev = (prev_r, c) if d_y > 0 else (prev_r, c)
        if is_free(left) and not is_free((prev_r, c - 1)):
            return ns
        if is_free(right) and not is_free((prev_r, c + 1)):
            return ns

        # Check horizontal jump
        jump = jump_horizontal(ns, -1, ns)
        if jump:
            return jump
        jump = jump_horizontal(ns, 1, ns)
        if jump:
            return jump

        # Recursively jump further
        new_jump = jump_vertical(ns, d_y, pos)
        if new_jump:
            return new_jump
        return None

    def jump_point_search():
        visited = set()
        parent_map = {}
        pq = [(manhattan(start), 0, start, None)]

        while pq:
            _, g, pos, prev = heapq.heappop(pq)
            if pos in visited:
                continue
            if pos == goal:
                return reconstruct_path(parent_map, start, goal)
            visited.add(pos)

            r, c = pos
            # Check left and right
            for dx in [-1, 1]:
                if dx == -1:
                    next_pos = jump_horizontal(pos, dx, pos)
                else:
                    next_pos = jump_horizontal(pos, dx, pos)
                if next_pos and next_pos not in visited:
                    heapq.heappush(pq, (manhattan(next_pos) + g + length_between(pos, next_pos), g + length_between(pos, next_pos), next_pos, pos))
                    parent_map[next_pos] = pos

            # Check up and down
            for dy in [-1, 1]:
                next_pos = jump_vertical(pos, dy, pos)
                if next_pos and next_pos not in visited:
                    heapq.heappush(pq, (manhattan(next_pos) + g + length_between(pos, next_pos), g + length_between(pos, next_pos), next_pos, pos))
                    parent_map[next_pos] = pos

        return []

    def length_between(a, b):
        r1, c1 = a
        r2, c2 = b
        return abs(r1 - r2) + abs(c1 - c2)

    def reconstruct_path(parent_map, start, goal):
        if goal not in parent_map:
            return []
        path = [goal]
        current = goal
        while current != start:
            prev = parent_map[current]
            path.append(prev)
            current = prev
        path.reverse()
        return fill_path(path)

    def fill_path(path):
        filled = [path[0]]
        for i in range(1, len(path)):
            p, p1 = filled[-1], path[i]
            dr = p1[0] - p[0]
            dc = p1[1] - p[1]
            step_r = 1 if dr > 0 else -1
            step_c = 1 if dc > 0 else -1
            for j in range(1, max(abs(dr), abs(dc))):
                r = p[0] + step_r * j
                c = p[1] + step_c * j
                filled.append((r, c))
            filled.append(p1)
        return filled

    # Check if start or goal is a wall
    if not is_free(start) or not is_free(goal):
        return []

    return jump_point_search()
