        g = {from_pos: 0}
        heap = [(manhattan(from_pos, to_pos), from_pos, g)]
        parent = {}
        path_cost = float('inf')
        meeting_cell = None

        while heap:
            f, pos, g_dict = heapq.heappop(heap)
            if pos in g and g[pos] < f - manhattan(pos, to_pos):
                continue
            if is_forward:
                other = backward_g
            else:
                other = forward_g
            if pos in other:
                total = g[pos] + other[pos]
                if total < path_cost:
                    path_cost = total
                    meeting_cell = pos
            if f >= path_cost:
                continue

            for dr, dc in directions:
                nr, nc = pos[0] + dr, pos[1] + dc
                new_pos = (nr, nc)
                if not is_valid(new_pos) or new_pos in g:
                    continue
                g_new = g[pos] + 1
                g[new_pos] = g_new
                h = manhattan(new_pos, to_pos)
                heapq.heappush(heap, (g_new + h, new_pos, g_new))
                parent[new_pos] = pos

    forward_g = {start: 0}
    backward_g = {goal: 0}
    forward_parent = {}
    backward_parent = {}

    forward_heap = [(manhattan(start, goal), start, forward_g[start])]
    backward_heap = [(manhattan(goal, start), goal, backward_g[goal])]
    heapq.heapify(forward_heap)
    heapq.heapify(backward_heap)

    best_meeting_cost = float('inf')
    best_meeting = None

    while forward_heap and backward_heap:
        # Forward expansion
        if forward_heap:
            f, pos, g_val = heapq.heappop(forward_heap)
            if pos in backward_g:
                if g_val + backward_g[pos] < best_meeting_cost:
                    best_meeting_cost = g_val + backward_g[pos]
                    best_meeting = pos
            else:
                forward_g[pos] = g_val
            for dr, dc in directions:
                nr, nc = pos[0] + dr, pos[1] + dc
                new_pos = (nr, nc)
                if not is_valid(new_pos) or new_pos in forward_g:
                    continue
                new_g = g_val + 1
                heapq.heappush(forward_heap, (new_g + manhattan(new_pos, goal), new_pos, new_g))
                forward_g[new_pos] = new_g
                forward_parent[new_pos] = pos

        # Backward expansion
        if backward_heap:
            f, pos, g_val = heapq.heappop(backward_heap)
            if pos in forward_g:
                if g_val + forward_g[pos] < best_meeting_cost:
                    best_meeting_cost = g_val + forward_g[pos]
                    best_meeting = pos
            else:
                backward_g[pos] = g_val
            for dr, dc in directions:
                nr, nc = pos[0] + dr, pos[1] + dc
                new_pos = (nr, nc)
                if not is_valid(new_pos) or new_pos in backward_g:
                    continue
                new_g = g_val + 1
                heapq.heappush(backward_heap, (new_g + manhattan(new_pos, start), new_pos, new_g))
                backward_g[new_pos] = new_g
                backward_parent[new_pos] = pos

        if best_meeting is not None:
            break

    if best_meeting is None:
        return []

    # Reconstruct path
    path = []
    curr = best_meeting
    while curr != start:
        path.append(curr)
        curr = forward_parent[curr]
    path.append(start)
    path.reverse()
    curr = best_meeting
    while curr != goal:
        curr = backward_parent[curr]
        path.append(curr)
    path.append(goal)

    return path


