    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def heuristic_search(start, goal, is_forward):
        open_set = []
        heapq.heappush(open_set, (manhattan(start, goal), 0, start))
        closed = set()
        g = {start: 0}
        parent = {}

        while open_set:
            _, cost, pos = heapq.heappop(open_set)
            if pos in closed:
                continue
            closed.add(pos)

            if not is_forward and pos in g_other:
                return pos, g, parent
            g_other_set = g_goal if is_forward else g_start
            if g_other_set and g_other_set.get(pos, float('inf')) <= g[pos]:
                return pos, g, parent

            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = pos[0] + dr, pos[1] + dc
                if is_wall(nr, nc):
                    continue
                next_pos = (nr, nc)
                new_cost = cost + 1
                if next_pos not in g or new_cost < g[next_pos]:
                    g[next_pos] = new_cost
                    heapq.heappush(open_set, (new_cost + manhattan(next_pos, goal), new_cost, next_pos))
                    parent[next_pos] = pos
        return None, g, parent

    if start == goal:
        return [start] if not is_wall(*start) else []

    if is_wall(*start) or is_wall(*goal):
        return []

    g_start, g_goal = {start: 0}, {goal: 0}
    parent_start, parent_goal = {}, {}
    meeting_start, meeting_goal = None, None

    while True:
        meeting, g, parent = heuristic_search(start, goal, True)
        if meeting is not None:
            meeting_start = meeting
            g_start = g
            parent_start = parent

        if meeting_start is not None and g_goal.get(meeting_start, float('inf')) <= g_start[meeting_start]:
            break

        meeting, g, parent = heuristic_search(goal, start, False)
        if meeting is not None:
            meeting_goal = meeting
            g_goal = g
            parent_goal = parent

        if meeting_goal is not None and g_start.get(meeting_goal, float('inf')) <= g_goal[meeting_goal]:
            break

        if meeting_start is None and meeting_goal is None:
            return []

    if meeting_start:
        meeting = meeting_start
    else:
        meeting = meeting_goal

    path_start = deque()
    pos = meeting
    while pos != start:
        path_start.appendleft(pos)
        pos = parent_start[pos]
    path_start.appendleft(start)

    path_goal = []
    pos = meeting
    while pos != goal:
        pos = parent_goal[pos]
        path_goal.append(pos)
    path_goal.append(goal)

    return list(path_start) + path_goal
