            p = forward_parent[p]
        path.append(start)
        path.reverse()
        p = meet
        while p != end:
            p = backward_parent[p]
            path.append(p)
        return path

    return reconstruct_path(start, goal, forward_parent, backward_parent, meeting_pos)
