from collections import deque

def solve(grid, start, goal):
    if start == goal:
        return [start] if grid[start[0]][start[1]] == '.' else []

    rows = len(grid)
    cols = len(grid[0])

    if (grid[start[0]][start[1]] == '#' or
        grid[goal[0]][goal[1]] == '#'):
        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs_step(front, parents, other_parents):
        next_front = []
        for r, c in front:
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if (0 <= nr < rows and 0 <= nc < cols and
                    grid[nr][nc] != '#' and (nr, nc) not in parents):
                    if (nr, nc) in other_parents:
                        return (nr, nc)
                    parents[(nr, nc)] = (r, c)
                    next_front.append((nr, nc))
        return next_front

    start_queue = deque([start])
    goal_queue = deque([goal])

    start_parents = {start: None}
    goal_parents = {goal: None}

    while start_queue and goal_queue:
        if len(start_queue) <= len(goal_queue):
            meeting = bfs_step(start_queue, start_parents, goal_parents)
            while start_queue:
                start_queue.popleft()
            if meeting:
                return _build_path(start_parents, goal_parents, meeting)
        else:
            meeting = bfs_step(goal_queue, goal_parents, start_parents)
            while goal_queue:
                goal_queue.popleft()
            if meeting:
                return _build_path(start_parents, goal_parents, meeting)

    return []

def _build_path(start_parents, goal_parents, meeting):
    path = []
    r, c = meeting
    while (r, c) != start_parents[r, c]:
        path.append((r, c))
        r, c = start_parents[r, c]
    path.reverse()
    r, c = meeting
    while (r, c) != goal_parents[r, c]:
        r, c = goal_parents[r, c]
        path.append((r, c))
    return path
