        # Forward search data
        g_start = {start: 0}
        f_start = {start: manhattan(start, goal)}
        heap_start = [(f_start[start], g_start[start], start)]
        parent_start = {}

        # Backward search data
        g_goal = {goal: 0}
        f_goal = {goal: manhattan(goal, start)}
        heap_goal = [(f_goal[goal], g_goal[goal], goal)]
        parent_goal = {}

        # Set of directions: up, down, left, right
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        # Best cost meeting
        best_meeting = float('inf')
        best_intersec = None

        # Alternate between forward and backward searches
        forward_turn = True
        while heap_start and heap_goal:
            if forward_turn:
                # Forward expansion
                _, current_g, curr = heapq.heappop(heap_start)
                if curr in g_goal:
                    # A meeting point found
                    if current_g + g_goal[curr] < best_meeting:
                        best_meeting = current_g + g_goal[curr]
                        best_intersec = curr
                if best_meeting <= min(f_start.get(heap_start[0][2], float('inf')), f_goal.get(heap_goal[0][2], float('inf'))):
                    break
                for dr, dc in directions:
                    nr, nc = curr[0] + dr, curr[1] + dc
                    if is_valid(nr, nc) and (nr, nc) not in g_start:
                        next_g = current_g + 1
                        if (nr, nc) in g_start and g_start[(nr, nc)] <= next_g:
                            continue
                        g_start[(nr, nc)] = next_g
                        f = next_g + manhattan((nr, nc), goal)
                        heapq.heappush(heap_start, (f, next_g, (nr, nc)))
                        parent_start[(nr, nc)] = curr
            else:
                # Backward expansion
                _, current_g, curr = heapq.heappop(heap_goal)
                if curr in g_start:
                    # A meeting point found
                    if current_g + g_start[curr] < best_meeting:
                        best_meeting = current_g + g_start[curr]
                        best_intersec = curr
                if best_meeting <= min(f_start.get(heap_start[0][2], float('inf')), f_goal.get(heap_goal[0][2], float('inf'))):
                    break
                for dr, dc in directions:
                    nr, nc = curr[0] + dr, curr[1] + dc
                    if is_valid(nr, nc) and (nr, nc) not in g_goal:
                        next_g = current_g + 1
                        if (nr, nc) in g_goal and g_goal[(nr, nc)] <= next_g:
                            continue
                        g_goal[(nr, nc)] = next_g
                        f = next_g + manhattan((nr, nc), start)
                        heapq.heappush(heap_goal, (f, next_g, (nr, nc)))
                        parent_goal[(nr, nc)] = curr
            forward_turn = not forward_turn

        if best_intersec is None:
            return []

        # Reconstruct the path from start to meeting point
        def reconstruct(from_dict, start, end, parent_map):
            path = [end]
            curr = end
            while curr != start:
                curr = parent_map[curr]
                path.append(curr)
            path.reverse()
            return path

        # Build the full path
        part1 = reconstruct(g_start, start, best_intersec, parent_start)
        part2 = reconstruct(g_goal, goal, best_intersec, parent_goal)[1:]
        full_path = part1 + part2

        # Special case: start == goal
        if start == goal:
            return [start]
        return full_path

    # Check if start or goal are walls
    if not is_valid(*start) or not is_valid(*goal):
        return []

    return search()
