        next_front = []
        for r, c in front:
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if is_free(grid, (nr, nc)) and (nr, nc) not in parents:
                    parents[(nr, nc)] = (r, c)
                    next_front.append((nr, nc))
        return next_front

    def build_path(sp, gp, meet):
        path_forward = []
        current = meet
        while current is not None:
            path_forward.append(current)
            current = sp[current]
        path_forward.reverse()

        path_backward = []
        current = meet
        while current is not None:
            path_backward.append(current)
            current = gp[current]

        return path_forward + path_backward[1:]

    if not is_free(grid, start) or not is_free(grid, goal):
        return []

    start_front = deque([start])
    goal_front = deque([goal])
    start_parents = {start: None}
    goal_parents = {goal: None}

    while start_front and goal_front:
        # Expand from start side
        next_start = []
        for r, c in start_front:
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if is_free(grid, (nr, nc)) and (nr, nc) not in start_parents:
                    if (nr, nc) in goal_parents:
                        return build_path(start_parents, goal_parents, (nr, nc))
                    start_parents[(nr, nc)] = (r, c)
                    next_start.append((nr, nc))
        start_front = deque(next_start)

        if not start_front:
            return []

        # Expand from goal side
        next_goal = []
        for r, c in goal_front:
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if is_free(grid, (nr, nc)) and (nr, nc) not in goal_parents:
                    if (nr, nc) in start_parents:
                        return build_path(start_parents, goal_parents, (nr, nc))
                    goal_parents[(nr, nc)] = (r, c)
                    next_goal.append((nr, nc))
        goal_front = deque(next_goal)

        if not goal_front:
            return []

    return []
