def solve(grid, start, goal):
    if start == goal:
        return [start]
    if not is_free(grid, start) or not is_free(grid, goal):
        return []

    rows, cols = len(grid), len(grid[0])

    def heur(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def neighbors(pos):
        r, c = pos
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                yield (nr, nc)

    def is_free(grid, pos):
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def a_star(from_pos, to_pos):
        heap = [(heur(from_pos, to_pos), 0, from_pos, None)]
        g = {from_pos: 0}
        parent = {}
        visited = set()

        while heap:
            f, cost, pos, p = heapq.heappop(heap)
            if pos in visited:
                continue
            visited.add(pos)
            if pos == to_pos:
                return pos, g[pos], parent
            for n in neighbors(pos):
                new_cost = cost + 1
                if n not in g or new_cost < g[n]:
                    g[n] = new_cost
                    priority = new_cost + heur(n, to_pos)
                    heapq.heappush(heap, (priority, new_cost, n, pos))
                    parent[n] = pos
        return None, float('inf'), {}

    def reconstruct_path(parent1, meeting, parent2):
        path = []
        current = meeting
        while current is not None:
            path.append(current)
            current = parent1[current]
        path = path[::-1]
        current = parent2.get(meeting)
        while current is not None:
            path.append(current)
            current = parent2[current]
        return path

    forward_heap = [(heur(start, goal), 0, start, None)]
    backward_heap = [(heur(goal, start), 0, goal, None)]
    g_forward = {start: 0}
    g_backward = {goal: 0}
    parent_forward = {}
    parent_backward = {}
    visited_forward = set()
    visited_backward = set([goal])

    while forward_heap and backward_heap:
        min_forward_f = forward_heap[0][0]
        min_backward_f = backward_heap[0][0]
        if min_forward_f >= g_backward.get(start, float('inf')) or min_backward_f >= g_forward.get(goal, float('inf')):
            return []

        f, cost, pos, p = heapq.heappop(forward_heap)
        if pos in visited_forward:
            continue
        visited_forward.add(pos)
        parent_forward[pos] = p
        g_forward[pos] = cost

        if pos in g_backward:
            return reconstruct_path(parent_forward, pos, parent_backward)

        for n in neighbors(pos):
            if n not in g_forward or cost + 1 < g_forward[n]:
                g_forward[n] = cost + 1
                priority = g_forward[n] + heur(n, goal)
                heapq.heappush(forward_heap, (priority, g_forward[n], n, pos))

        f, cost, pos, p = heapq.heappop(backward_heap)
        if pos in visited_backward:
            continue
        visited_backward.add(pos)
        parent_backward[pos] = p
        g_backward[pos] = cost

        if pos in g_forward:
            return reconstruct_path(parent_forward, pos, parent_backward)

        for n in neighbors(pos):
            if n not in g_backward or cost + 1 < g_backward[n]:
                g_backward[n] = cost + 1
                priority = g_backward[n] + heur(n, start)
                heapq.heappush(backward_heap, (priority, g_backward[n], n, pos))

    return []
