        path = path1 + [meet]
        curr = parents2[meet]
        while curr:
            path.append(curr)
            curr = parents2.get(curr)
        return path[::-1]

    dirs = [(-1,0), (1,0), (0,-1), (0,1)]

    frontier_start = []
    frontier_goal = []
    heapq.heappush(frontier_start, (manhattan(start, goal), start))
