        for node in g_start:
            if node in g_goal:
                cost = g_start[node] + g_goal[node]
                if cost < best_meet_cost:
                    best_meet_cost = cost
                    meeting_cell = node

        if best_meet_cost < float('inf'):
            break

        frontier_goal, g_goal, parents_goal = a_star(frontier_goal, g_goal, parents_goal, goal, start, grid, dirs)
        for node in g_goal:
            if node in g_start:
                cost = g_start[node] + g_goal[node]
                if cost < best_meet_cost:
                    best_meet_cost = cost
                    meeting_cell = node

        if best_meet_cost < float('inf'):
            break

    if meeting_cell is None:
        return []

    curr = start
    while curr in g_start:
        path_start.append(curr)
        if curr in parents_start:
            curr = parents_start[curr]
