        def neighbor_fn(cell):
            r, c = cell
            return [n for n in [(r-1,c), (r+1,c), (r,c-1), (r,c+1)] 
                    if 0 <= n[0] < rows and 0 <= n[1] < cols and grid[n[0]][n[1]] == '.']

        if get_neighbors is None:
            get_neighbors = neighbor_fn

        heapfy = [(g[cell] + manhattan(cell, to_node), cell) for cell in g]
        heapq.heapify(heapfy)
        while heapfy:
            f, cell = heapq.heappop(heapfy)
            if cell in g and g[cell] < f:
                continue
            for n in get_neighbors(cell):
                ng = g[cell] + 1
                if n not in g or ng < g[n]:
                    g[n] = ng
                    parent[n] = cell
                    heapq.heappush(heapfy, (ng + manhattan(n, to_node), n))
        return heapfy

    g_forward, g_backward = {start: 0}, {goal: 0}
    parent_forward, parent_backward = {}, {}
    heap_forward, heap_backward = [(0 + manhattan(start, goal), start)], [(0 + manhattan(goal, start), goal)]
    best_meeting_cost = float('inf')
