        if best_meeting is not None and best_meeting_cost <= min(heap_forward[0][0], heap_backward[0][0]):
            break

    if best_meeting is None:
        return []

    def build_path(meet):
        path_forward = [meet]
        while path_forward[-1] != start:
            path_forward.append(parent_forward[path_forward[-1]])
        path_forward.reverse()

        path_backward = [meet]
        while path_backward[-1] != goal:
            path_backward.append(parent_backward[path_backward[-1]])

        return path_forward + path_backward[1:]

    return build_path(best_meeting)
