import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]
    if not is_valid(grid, start) or not is_valid(grid, goal):
        return []

    rows, cols = len(grid), len(grid[0])
    heap = [(manhattan(start, goal), 0, start, None)]
    visited = set()
    parent = {}

    while heap:
        f, g, current, prev_dir = heapq.heappop(heap)
        if current in visited:
            continue
        visited.add(current)

        if current == goal:
            return reconstruct_path(parent, start, goal)

        for direction in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            jump = jump_search(grid, current, direction, goal, rows, cols)
            if jump:
                r, c = jump
                if (r, c) not in visited:
                    parent[(r, c)] = current
                    heapq.heappush(heap, (g + manhattan((r, c), goal), g + 1, (r, c), direction))

    return []

def is_valid(grid, pos):
    row, col = pos
    return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

def manhattan(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])

def reconstruct_path(parent, start, goal):
    path = [goal]
    current = goal
    while current != start:
        current = parent[current]
        path.append(current)
    return path[::-1]

def jump_search(grid, current, direction, goal, rows, cols):
    dr, dc = direction
    r, c = current

    while is_valid(grid, (r, c)):
        if (r, c) == goal:
            return (r, c)

        # Check for forced neighbor in horizontal or vertical jump
        if dr != 0:  # moving left or right (horizontal)
            if is_valid(grid, (r, c + 1)) and not is_valid(grid, (r + dr, c + 1)):
                return (r, c)
            if is_valid(grid, (r, c - 1)) and not is_valid(grid, (r + dr, c - 1)):
                return (r, c)
        else:  # moving up or down (vertical)
            if is_valid(grid, (r + 1, c)) and not is_valid(grid, (r + 1, c + dc)):
                return (r, c)
            if is_valid(grid, (r - 1, c)) and not is_valid(grid, (r - 1, c + dc)):
                return (r, c)

        r += dr
        c += dc

    return None
