        visited = {}
        parent = {}
        heap = []
        heapq.heappush(heap, (manhattan(from_point, to_point), 0, from_point))
        visited[from_point] = 0

        while heap:
            f, g, current = heapq.heappop(heap)
            if current in other_set:
                return (current, visited, parent)
            if g > visited.get(current, 0):
                continue

            r, c = current
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                neighbor = (nr, nc)
                if is_valid(nr, nc) and neighbor not in visited:
                    new_g = g + 1
                    h = manhattan(neighbor, to_point)
                    heapq.heappush(heap, (new_g + h, new_g, neighbor))
                    visited[neighbor] = new_g
                    parent[neighbor] = current

            if not heap:
                return (None, visited, parent)
        return (None, visited, parent)

    def reconstruct_path(start, goal, forward_parent, backward_parent, meet):
        path = [meet]
        curr = meet
        while curr != start:
            curr = forward_parent[curr]
            path.insert(0, curr)
        curr = meet
        while curr != goal:
            curr = backward_parent[curr]
            path.append(curr)
        return path

    if not is_valid(*start) or not is_valid(*goal):
        return []

    forward_visited = {start: 0}
    backward_visited = {goal: 0}
    forward_parent = {}
    backward_parent = {}

    best_meet = None
    best_cost = float('inf')

    while True:
        meet, forward_v, forward_p = heuristic_search(start, goal, backward_visited)
        if meet:
            if meet not in backward_parent:
                continue
            cost = forward_v[meet] + backward_visited[meet]
            if cost < best_cost:
                best_cost = cost
                best_meet = meet
                best_forward_v = forward_v
                best_forward_p = forward_p
                best_backward_p = backward_parent
            break

        if not forward_v:
            return []

        meet, backward_v, backward_p = heuristic_search(goal, start, forward_visited)
        if meet:
            if meet not in forward_parent:
                continue
            cost = best_forward_v[meet] + backward_v[meet]
            if cost < best_cost:
                best_cost = cost
                best_meet = meet
                best_forward_v = forward_v
                best_forward_p = forward_p
                best_backward_p = backward_p
            break

        if not backward_v:
            return []

        forward_parent.update(forward_p)
        backward_parent.update(backward_p)
        forward_visited.update(forward_v)
        backward_visited.update(backward_v)

    if not best_meet:
        return []

    return reconstruct_path(start, goal, best_forward_p, best_backward_p, best_meet)
