        row, col = pos
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            new_pos = (row + dr, col + dc)
            if not is_wall(new_pos):
                yield new_pos

    def search(start_pos, goal_pos, is_forward):
        heap = []
        heapq.heappush(heap, (0, start_pos))
        g = {start_pos: 0}
        parent = {}

        while heap:
            f, current = heapq.heappop(heap)
            if g.get(current, float('inf')) > f:
                continue
            if current in other_seen:
                return current, g, parent

            for next_pos in neighbors(current):
                new_g = g[current] + 1
                if next_pos not in g or new_g < g[next_pos]:
                    g[next_pos] = new_g
                    h = manhattan(next_pos, goal_pos)
                    f = new_g + h
                    heapq.heappush(heap, (f, next_pos))
                    parent[next_pos] = current

        return None, g, parent

    if start == goal:
        return [start] if not is_wall(start) else []

    if is_wall(start) or is_wall(goal):
        return []

    forward_seen = set([start])
    backward_seen = set([goal])

    g_forward = {start: 0}
    g_backward = {goal: 0}
    parent_forward = {}
    parent_forward[start] = None
    parent_backward = {}
    parent_backward[goal] = None

    forward_heap = [(manhattan(start, goal), start)]
    backward_heap = [(manhattan(goal, start), goal)]

    while forward_heap and backward_heap:
        if forward_heap[0][0] >= g_forward[forward_seen.intersection(backward_seen).pop()] if forward_seen.intersection(backward_seen) else float('inf'):
            break

        # Forward search
        if forward_heap:
            _, pos = heapq.heappop(forward_heap)
            if pos not in forward_seen or g_forward[pos] < g_forward.get(forward_seen, float('inf')):
                forward_seen.add(pos)
                for n in neighbors(pos):
                    new_g = g_forward[pos] + 1
                    if n not in g_forward or new_g < g_forward[n]:
                        g_forward[n] = new_g
                        f = new_g + manhattan(n, goal)
                        heapq.heappush(forward_heap, (f, n))
                        parent_forward[n] = pos

        if backward_heap:
            _, pos = heapq.heappop(backward_heap)
            if pos not in backward_seen or g_backward[pos] < g_backward.get(backward_seen, float('inf')):
                backward_seen.add(pos)
                for n in neighbors(pos):
                    new_g = g_backward[pos] + 1
                    if n not in g_backward or new_g < g_backward[n]:
                        g_backward[n] = new_g
                        f = new_g + manhattan(n, start)
                        heapq.heappush(backward_heap, (f, n))
                        parent_backward[n] = pos

        if forward_seen.intersection(backward_seen):
            meet = forward_seen.intersection(backward_seen).pop()
            break
    else:
        return []  # No intersection found

    # Reconstruct path
    path = build_path(parent_forward, parent_backward, meet, start, goal)
    path.reverse()
    return path

def build_path(parent_forward, parent_backward, meet_point, start, goal):
    path_forward = [meet_point]
    node = meet_point
    while node != start:
        node = parent_forward[node]
        path_forward.append(node)
    path_forward.reverse()

    path_backward = []
    node = meet_point
    while node != goal:
        node = parent_backward[node]
        path_backward.append(node)

    return path_forward + path_backward
