            if (nx, ny) == goal:
                return (nx, ny)
            if (is_valid(nx, y - 1) and grid[nx][y - 1] == '.' and (not is_valid(nx - dx, y - 1))):
                return (nx, ny)
            if (is_valid(nx, y + 1) and grid[nx][y + 1] == '.' and (not is_valid(nx - dx, y + 1))):
                return (nx, ny)
            current = (nx, ny)
            if not is_valid(nx + dx, ny + dy):
                return None

    def jump_vertical(current, delta):
        while True:
            x, y = current
            dx, dy = delta
            nx, ny = x + dx, y + dy
            if not is_valid(nx, ny):
                return None
            if (nx, ny) == goal:
                return (nx, ny)
            if jump_horizontal((nx, ny), (0, 1)) is not None or \
               jump_horizontal((nx, ny), (0, -1)) is not None:
                return (nx, ny)
            current = (nx, ny)
            if not is_valid(nx + dx, ny + dy):
                return None

    while heap:
        f, g, current = heapq.heappop(heap)
        if current in visited:
            continue
        visited.add(current)
        if current == goal:
            return reconstruct_path(parent, start, current)

        for i, (dx, dy) in enumerate(directions):
            x, y = current
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and (nx, ny) not in visited:
                if i % 2 == 0:  # Horizontal
                    jump_point = jump_horizontal((nx, ny), (dx, dy))
                else:  # Vertical
                    jump_point = jump_vertical((nx, ny), (dx, dy))
                if jump_point is not None and jump_point not in visited:
                    parent[jump_point] = current
                    new_g = g + abs(jump_point[0] - x) + abs(jump_point[1] - y)
                    heapq.heappush(heap, (new_g + manhattan(jump_point, goal), new_g, jump_point))

    return []

def reconstruct_path(parent, start, goal):
    path = [goal]
    while path[-1] != start:
        if path[-1] not in parent:
            return []
        path.append(parent[path[-1]])
    path = path[::-1]
    expanded = [path[0]]
    for i in range(1, len(path)):
        x1, y1 = path[i - 1]
        x2, y2 = path[i]
        dx, dy = (1 if x2 > x1 else -1 if x2 < x1 else 0), (1 if y2 > y1 else -1 if y2 < y1 else 0)
        while x1 != x2 or y1 != y2:
            x1 += dx
            y1 += dy
            expanded.append((x1, y1))
    return expanded
