        r, c = pos
        return is_valid(r, c) and grid[r][c] == '.'

    def is_wall(r, c):
        if not is_valid(r, c):
            return True
        return grid[r][c] == '#'

    def is_goal(r, c):
        return (r, c) == goal

    def manhattan(pos):
        return abs(pos[0] - goal[0]) + abs(pos[1] - goal[1])

    def horizontal_jump(r, c, dr, dc):
        while is_valid(r, c) and grid[r][c] != '#':
            if (is_wall(r, c - 1) and is_valid(r, c - 1)) or (is_wall(r, c + 1) and is_valid(r, c + 1)):
                return (r, c)
            elif is_goal(r, c):
                return (r, c)
            r += dr
            c += dc
        return None

    def vertical_jump(r, c, dr, dc):
        while is_valid(r, c) and grid[r][c] != '#':
            left = horizontal_jump(r, c, 1, 0) if is_valid(r, c) else None
            right = horizontal_jump(r, c, -1, 0) if is_valid(r, c) else None
            if left or right:
                return (r, c)
            elif is_goal(r, c):
                return (r, c)
            r += dr
            c += dc
        return None

    def jump(r, c, parent_r, parent_c):
        if is_goal(r, c):
            return (r, c)
        dr, dc = r - parent_r, c - parent_c
        if dr != 0:
            return vertical_jump(r, c, dr, 0)
        if dc != 0:
            return horizontal_jump(r, c, 0, dc)
        return None

    visited = set()
    heap = []
    heapq.heappush(heap, (manhattan(start), 0, start, None))
    parent_map = {}
    g_scores = {start: 0}

    while heap:
        _, g, (r, c), parent = heapq.heappop(heap)

        if (r, c) in visited:
            continue

        visited.add((r, c))

        if (r, c) == goal:
            path = []
            current = (r, c)
            while current:
                path.append(current)
                current = parent_map.get(current)
            return path[::-1]

        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

        for nr, nc in directions:
            next_r, next_c = r + nr, c + nc
            if is_valid(next_r, next_c) and grid[next_r][next_c] == '.':
                jump_result = jump(next_r, next_c, r, c)
                if jump_result is not None and jump_result not in visited:
                    parent_map[jump_result] = (r, c)
                    if jump_result not in g_scores or g + 1 < g_scores[jump_result]:
                        g_scores[jump_result] = g + 1
                        heapq.heappush(heap, (g_scores[jump_result] + manhattan(jump_result), g_scores[jump_result], jump_result, (r, c)))

    return []
