import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start] if grid[start[0]][start[1]] == '.' else []
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and
            0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    rows, cols = len(grid), len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def horizontal_jump(pos, dir):
        r, c = pos
        dc = 1 if dir == 'right' else -1
        steps = 0
        while True:
            c += dc
            steps += 1
            if not is_valid(r, c):
                return None
            new_pos = (r, c)
            if new_pos == goal:
                return new_pos
            if is_valid(r - 1, c) and not (is_valid(r - 1, c - dc) or is_valid(r - 1, c + dc)):
                return new_pos
            if is_valid(r + 1, c) and not (is_valid(r + 1, c - dc) or is_valid(r + 1, c + dc)):
                return new_pos

    def vertical_jump(pos, dir):
        r, c = pos
        dr = 1 if dir == 'down' else -1
        steps = 0
        while True:
            r += dr
            steps += 1
            if not is_valid(r, c):
                return None
            new_pos = (r, c)
            if new_pos == goal:
                return new_pos
            if horizontal_jump(new_pos, 'left') or horizontal_jump(new_pos, 'right'):
                return new_pos

    def get_jump_neighbors(pos):
        res = []
        r, c = pos
        # Left, right
        if c > 0 and grid[r][c - 1] == '.':
            returned = horizontal_jump(pos, 'left')
            if returned:
                res.append(returned)
        if c < cols - 1 and grid[r][c + 1] == '.':
            returned = horizontal_jump(pos, 'right')
            if returned:
                res.append(returned)
        # Up, down
        if r > 0 and grid[r - 1][c] == '.':
            returned = vertical_jump(pos, 'up')
            if returned:
                res.append(returned)
        if r < rows - 1 and grid[r + 1][c] == '.':
            returned = vertical_jump(pos, 'down')
            if returned:
                res.append(returned)
        return res

    def reconstruct_path(came_from, current):
        path = [current]
        while current in came_from:
            current = came_from[current]
            path.append(current)
        path.reverse()
        return path

    open_set = []
    heapq.heappush(open_set, (0, start))  # Start with f = 0 (g is 0, h = manhattan)
    came_from = {}
    g_score = {start: 0}
    manhattan = lambda a, b: abs(a[0] - b[0]) + abs(a[1] - b[1])

    while open_set:
        f, current = heapq.heappop(open_set)
        if current == goal:
            return reconstruct_path(came_from, current)
        for neighbor in get_jump_neighbors(current):
            r1, c1 = current
            r2, c2 = neighbor
            step_diff = abs(r2 - r1) + abs(c2 - c1)
            tentative_g = g_score[current] + step_diff
            if neighbor not in g_score or tentative_g < g_score[neighbor]:
                g_score[neighbor] = tentative_g
                came_from[neighbor] = current
                f_score = tentative_g + manhattan(neighbor, goal)
                heapq.heappush(open_set, (f_score, neighbor))
    return []
