        return 0 <= r < rows and 0 <= c < cols

    def is_wall(r, c):
        return not is_in_bounds(r, c) or grid[r][c] == '#'

    def get_manhattan(r, c):
        return abs(r - goal[0]) + abs(c - goal[1])

    def jump_horizontal(r, c, dc):
        step = 1
        while True:
            nc = c + step * dc
            if not is_in_bounds(r, nc) or grid[r][nc] == '#':
                return None
            if (r, nc) == goal:
                return (r, nc)
            # Check if this is a forced vertical jump point
            if (is_wall(r + 1, c) and not is_wall(r + 1, nc)) or (is_wall(r - 1, c) and not is_wall(r - 1, nc)):
                return (r, nc)
            step += 1

    def jump_vertical(r, c, dr):
        step = 1
        while True:
            nr = r + step * dr
            if not is_in_bounds(nr, c) or grid[nr][c] == '#':
                return None
            if (nr, c) == goal:
                return (nr, c)
            # Check if this is a forced horizontal jump point
            if jump_horizontal(nr, c, 1) or jump_horizontal(nr, c, -1):
                return (nr, c)
            step += 1

    def reconstruct_path(came_from, start, current):
        path = [current]
        while current in came_from:
            current = came_from[current]
            path.append(current)
            if current == start:
                break
        return path[::-1]

    open_heap = []
    heapq.heappush(open_heap, (get_manhattan(*start), 0, start, None))
    came_from = {}
    g_score = {start: 0}

    while open_heap:
        f, g, current, parent = heapq.heappop(open_heap)

        if current == goal:
            path = reconstruct_path(came_from, start, current)
            return path

        if current in came_from or current is None:
            continue

        if parent:
            came_from[current] = parent

        for dr, dc in [(1,0), (-1,0), (0,1), (0,-1)]:
            nr, nc = current[0] + dr, current[1] + dc
            if is_in_bounds(nr, nc) and not is_wall(nr, nc):
                if dr != 0:
                    jump_point = jump_vertical(current[0], current[1], dr)
                else:
                    jump_point = jump_horizontal(current[0], current[1], dc)

                if jump_point:
                    ng = g + 1
                    while (current[0] + step * dr, current[1] + step * dc) != jump_point:
                        ng += 1
                    if jump_point not in g_score or ng < g_score.get(jump_point, float('inf')):
                        g_score[jump_point] = ng
                        heapq.heappush(open_heap, (ng + get_manhattan(*jump_point), ng, jump_point, current))

    return []
