import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start] if grid[start[0]][start[1]] == '.' else []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    rows = len(grid)
    cols = len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def jump_point_search(grid, start, goal):
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right
        parent = {}
        g_score = {start: 0}
        f_score = {start: heuristic(start, goal)}
        queue = [(f_score[start], g_score[start], start)]
        visited = set()

        while queue:
            _, cost, current = heapq.heappop(queue)
            if current == goal:
                path = [current]
                while current in parent:
                    current = parent[current]
                    path.append(current)
                return path[::-1]
            if current in visited:
                continue
            visited.add(current)

            # Regular JPS neighbors
            for d in directions:
                step_r, step_c = current[0] + d[0], current[1] + d[1]
                if not (0 <= step_r < rows and 0 <= step_c < cols) or grid[step_r][step_c] == '#':
                    continue
                next_node = (step_r, step_c)
                if next_node not in g_score or g_score[next_node] > cost + 1:
                    g_score[next_node] = cost + 1
                    f_score[next_node] = g_score[next_node] + heuristic(next_node, goal)
                    parent[next_node] = current
                    heapq.heappush(queue, (f_score[next_node], g_score[next_node], next_node))

            # Jump neighbors
            for d in directions:
                jmp = jump(grid, current, d, direction='straight')
                if jmp and is_valid(jmp[0], jmp[1]) and grid[jmp[0]][jmp[1]] == '.':
                    if jmp not in g_score or g_score[jmp] > cost + heuristic(current, jmp):
                        g_score[jmp] = cost + heuristic(current, jmp)
                        f_score[jmp] = g_score[jmp] + heuristic(jmp, goal)
                        parent[jmp] = current
                        heapq.heappush(queue, (f_score[jmp], g_score[jmp], jmp))

        return []

    def jump(grid, node, direction, direction_type='straight'):
        dr, dc = direction
        r, c = node
        nr, nc = r + dr, c + dc
        if not (0 <= nr < len(grid) and 0 <= nc < len(grid[0])) or grid[nr][nc] == '#':
            return None

        if (nr, nc) == goal:
            return (nr, nc)

        if direction_type == 'straight':
            # Check for forced neighbors
            if dr != 0:  # vertical move
                for side in [(-1, 0), (1, 0)]:
                    sr, sc = nr + side[0], nc + side[1]
                    if 0 <= sr < len(grid) and 0 <= sc < len(grid[0]):
                        if grid[sr][sc] == '.' and (grid[sr + dr][sc] == '#' or (sr + dr, sc) == goal):
                            return (nr, nc)
            else:  # horizontal move
                for side in [(-1, 0), (1, 0)]:
                    sr, sc = nr + side[0], nc + side[1]
                    if 0 <= sr < len(grid) and 0 <= sc < len(grid[0]):
                        if grid[sr][sc] == '.' and (grid[sr][sc + dc] == '#' or (sr, sc + dc) == goal):
                            return (nr, nc)

            # Continue jumping
            next_jump = jump(grid, (nr, nc), direction, direction_type)
            if next_jump:
                return next_jump

        return None

    return jump_point_search(grid, start, goal)
