            r, c = next_r, next_c
            next_r += dr
            next_c += dc
            if not is_free(grid, (next_r, next_c)):
                return None
            if (next_r, next_c) == goal:
                return (next_r, next_c)

            # Check for vertical forced neighbors
            if dc == 0:
                # Moving horizontally, check above and below
                for d in (-1, 1):
                    nr, nc = r + d, c
                    if is_free(grid, (nr, nc)) and not is_free(grid, (nr + d, nc)):
                        return (r, c)
            # Check for horizontal forced neighbors or jump point
            else:
                # Moving vertically, check left and right
                for d in (-1, 1):
                    nr, nc = r, c + d
                    if is_free(grid, (nr, nc)) and not is_free(grid, (nr, nc + d)):
                        return (r, c)
                # If a horizontal jump from (r, c) in any direction finds a jump point, return (r, c)
                if jump_point(r, c, 0, 1) is not None or jump_point(r, c, 0, -1) is not None:
