        if (0 <= r - 1 < rows and grid[r - 1][c] == '#' and is_valid(grid, (r + 1, c))) or \
           (0 <= r + 1 < rows and grid[r + 1][c] == '#' and is_valid(grid, (r - 1, c))) or \
           (0 <= c - 1 < cols and grid[r][c - 1] == '#') or \
           (0 <= c + 1 < cols and grid[r][c + 1] == '#'):
                return next_pos
    else:
        jr = jump(grid, (r, c), dr, 0, goal, rows, cols)
        if jr and (0 <= c - 1 < cols and grid[r][c - 1] == '#') or (0 <= c + 1 < cols and grid[r][c + 1] == '#'):
            return jr

    return jump(grid, next_pos, dr, dc, goal, rows, cols)
