                        return (r, c)
                    return (r, c)

    def reconstruct_path(came_from, current):
        path = [current]
        while current in came_from:
            current = came_from[current]
            path.append(current)
        return path[::-1]

    def fill_path(path):
        if not path:
            return path
        result = [path[0]]
        for i in range(1, len(path)):
            x1, y1 = result[-1]
            x2, y2 = path[i]
            dx = (x2 - x1) // max(1, abs(x2 - x1))
            dy = (y2 - y1) // max(1, abs(y2 - y1))
