    rows, cols = len(grid), len(grid[0])
    if (
        not (0 <= start[0] < rows and 0 <= start[1] < cols)
        or not (0 <= goal[0] < rows and 0 <= goal[1] < cols)
        or grid[start[0]][start[1]] == '#'
        or grid[goal[0]][goal[1]] == '#'
    ):
        return []

    if start == goal:
        return [start]

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def is_free(pos):
        r, c = pos
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def jump_horizontal(pos, direction):
        r, c = pos
        dr, dc = 0, 1 if direction == 'right' else -1
        r, c = r, c + dc
        while is_free((r, c)):
            if (r, c) == goal:
                return (r, c)
            if is_free((r - 1, c)) and (not is_free((r - 2, c)) or not (r - 1, c) in [(x, c) for x in range(rows)] or grid[r - 1][c - dc] == '#'):
                return (r, c)
            if is_free((r + 1, c)) and (not is_free((r + 2, c)) or not (r + 1, c) in [(x, c) for x in range(rows)] or grid[r + 1][c - dc] == '#'):
                return (r, c)
            r, c = r, c + dc
        return None

    def jump_vertical(pos, direction):
        r, c = pos
        dr, dc = 1 if direction == 'down' else -1, 0
        r, c = r + dr, c
        while is_free((r, c)):
            if (r, c) == goal:
                return (r, c)
            if jump_horizontal((r, c), 'right') or jump_horizontal((r, c), 'left'):
                return (r, c)
            r, c = r + dr, c
        return None

    def jump(pos, dir):
        r, c = pos
        dr, dc = dir

        if dr != 0:
            if dr > 0:
                res = jump_vertical(pos, 'down')
            else:
                res = jump_vertical(pos, 'up')
        else:
            if dc > 0:
                res = jump_horizontal(pos, 'right')
            else:
                res = jump_horizontal(pos, 'left')
        return res

    def expand(pos):
        r, c = pos
        for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if is_free((nr, nc)) and (nr, nc) != goal:
                next_pos = (nr, nc)
                jpt = jump(next_pos, (dr, dc))
                if jpt:
                    yield jpt
            elif (nr, nc) == goal:
                yield (nr, nc)

    def reconstruct_path(came_from, start, goal):
        path = [goal]
        current = goal
        while current != start:
            current = came_from[current]
            path.append(current)
        path.reverse()
        filled_path = []
        for i in range(len(path) - 1):
            p1, p2 = path[i], path[i+1]
            step = (p2[0] - p1[0], p2[1] - p1[1])
            r, c = p1[0], p1[1]
            filled_path.append(p1)
            while (r, c) != p2:
                r += step[0]
                c += step[1]
                filled_path.append((r, c))
        return filled_path

    open_set = []
    heapq.heappush(open_set, (heuristic(start, goal), 0, start))
    came_from = {}
    g_cost = {start: 0}

    while open_set:
        _, current_g, current = heapq.heappop(open_set)
        if current == goal:
            path = reconstruct_path(came_from, start, current)
            return [cell for cell in path if is_free(cell)]

        for next_node in expand(current):
            if next_node is None:
                continue
            step_cost = abs(next_node[0] - current[0]) + abs(next_node[1] - current[1])
            tentative_g = current_g + step_cost
            if next_node not in g_cost or tentative_g < g_cost[next_node]:
                came_from[next_node] = current
                g_cost[next_node] = tentative_g
                f = tentative_g + heuristic(next_node, goal)
                heapq.heappush(open_set, (f, tentative_g, next_node))

    return []
