def solve(grid, start, goal):
    if start == goal:
        # Explicitly check if the cell is free
        if grid[start[0]][start[1]] == '#':
            return []
        return [start]

    if not (grid[start[0]][start[1]] == '.' and grid[goal[0]][goal[1]] == '.'):
        return []

    rows = len(grid)
    cols = len(grid[0])

    def is_free(pos):
        r, c = pos
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    heuristic = lambda a, b: abs(a[0] - b[0]) + abs(a[1] - b[1])

    dir_map = {
        'up': (-1, 0),
        'down': (1, 0),
        'left': (0, -1),
        'right': (0, 1)
    }

    inv_dir = {
        'up': 'down',
        'down': 'up',
        'left': 'right',
        'right': 'left'
    }

    dir_to_str = {
        (-1, 0): 'up',
        (1, 0): 'down',
        (0, -1): 'left',
        (0, 1): 'right'
    }

    def get_neighbors(pos):
        r, c = pos
        return [
            (r + dr, c + dc)
            for (dr, dc) in [(-1, 0), (1, 0), (0, -1), (0, 1)]
            if is_free((r + dr, c + dc))
        ]

    def jump_horizontal(pos, direction, goal):
        r, c = pos
        dr, dc = dir_map[direction]
        r += dr
        c += dc

        while is_free((r, c)):
            if (r, c) == goal:
                return (r, c)

            # Check for vertical forced neighbors (up and down)
            if not is_free((r - 1, c)) and is_free((r - 1, c - 1)) or \
               not is_free((r + 1, c)) and is_free((r + 1, c - 1)):
                return (r, c)
            elif not is_free((r - 1, c)) and is_free((r - 1, c + 1)) or \
                 not is_free((r + 1, c)) and is_free((r + 1, c + 1)):
                return (r, c)

            r += dr
            c += dc

        return None

    def jump_vertical(pos, direction, goal):
        r, c = pos
        dr, dc = dir_map[direction]
        r += dr
        c += dc

        while is_free((r, c)):
            if (r, c) == goal:
                return (r, c)

            # Check for horizontal jumps
            for horiz in ['left', 'right']:
                if not horiz == inv_dir[direction]:
                    second_res = jump_horizontal((r, c), horiz, goal)
                    if second_res:
                        return (r, c)

            r += dr
            c += dc

        return None

    def jump(pos, direction, goal):
        dr, dc = dir_map[direction]
        r, c = pos[0] + dr, pos[1] + dc

        if not is_free((r, c)):
            return None

        if direction in ['left', 'right']:
            return jump_horizontal((r, c), direction, goal)
        else:
            return jump_vertical((r, c), direction, goal)

    came_from = {}
    g_score = {}

    for r in range(rows):
        for c in range(cols):
            g_score[(r, c)] = float('inf')

    g_score[start] = 0
    heap = [(heuristic(start, goal), 0, start, None)]

    while heap:
        _, g, current, parent = heapq.heappop(heap)
        if current == goal:
            break
        if g > g_score[current]:
            continue
        if current not in came_from:
            came_from[current] = parent

        for direction in dir_map:
            res = jump(current, direction, goal)
            if res is not None and is_free(res):
                new_g = g + heuristic(current, res)
                if new_g < g_score[res]:
                    g_score[res] = new_g
                    heapq.heappush(heap, (new_g + heuristic(res, goal), new_g, res, current))

    # Build the path
    if current != goal:
        return []

    path = []
    curr = goal
    while curr is not None:
        path.append(curr)
        curr = came_from.get(curr)

    # Reverse the path
    path = path[::-1]

    # Fill in the straight-line steps
    filled_path = []
    for i in range(len(path) - 1):
        start_point = path[i]
        end_point = path[i + 1]
        dr = end_point[0] - start_point[0]
        dc = end_point[1] - start_point[1]

        if dr != 0:
            step = 1 if dr > 0 else -1
            for r in range(start_point[0], end_point[0] + step, step):
                filled_path.append((r, start_point[1]))
        else:
            step = 1 if dc > 0 else -1
            for c in range(start_point[1], end_point[1] + step, step):
                filled_path.append((start_point[0], c))

    return filled_path if all(grid[r][c] == '.' for r, c in filled_path) else []
