import heapq

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and grid[start[0]][start[1]] == '.'):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0]) and grid[goal[0]][goal[1]] == '.'):
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def is_wall(r, c):
        return r < 0 or c < 0 or r >= rows or c >= cols or grid[r][c] == '#'

    def jump(r, c, dr, dc):
        # Step in the direction (dr, dc)
        nr, nc = r + dr, c + dc
        if is_wall(nr, nc):
            return None
        if (nr, nc) == goal:
            return (nr, nc)

        # Check for horizontal jump if moving in a straight line
        if dc != 0 and dr == 0:
            # Check for forced neighbor (up or down)
            if not is_wall(r - 1, c) and is_wall(r - 1, nc):
                return (nr, nc)
            if not is_wall(r + 1, c) and is_wall(r + 1, nc):
                return (nr, nc)
        elif dr != 0 and dc == 0:
            # Check for forced neighbor (left or right)
            if not is_wall(r, c - 1) and is_wall(r + dr, c - 1):
                return (nr, nc)
            if not is_wall(r, c + 1) and is_wall(r + dr, c + 1):
                return (nr, nc)

        # Recursively jump
        result = jump(nr, nc, dr, dc)
        if result:
            return result

        # If no jump point, check for diagonal implications
        if dc != 0 and dr != 0:
            # Left or right jump from top or bottom
            if jump(r, nc, -dr, -dc) or jump(r, nc, -dr, dc):
                return (nr, nc)

        if dc != 0:
            if jump(r, nc, 0, -dc) or jump(r, nc, 0, dc):
                return (nr, nc)
        if dr != 0:
            if jump(nr, c, -dr, -dc) or jump(nr, c, -dr, dc):
                return (nr, nc)

        return None

    def get_jump_neighbors(r, c):
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        neighbors = []
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < rows and 0 <= nc < cols):
                continue
            if grid[nr][nc] == '#':
                continue
            if (nr, nc) == goal:
                neighbors.append((nr, nc))
                continue
            result = jump(r, c, dr, dc)
            if result:
                neighbors.append(result)
        return [cell for cell in neighbors if cell is not None]

    def reconstruct_path(came_from, current):
        path = []
        while current is not None:
            path.append(current)
            current = came_from.get(current)
        path.reverse()
        full_path = [path[0]]
        for i in range(1, len(path)):
            dx, dy = path[i][0] - path[i - 1][0], path[i][1] - path[i - 1][1]
            steps = abs(dx) + abs(dy)
            for s in range(1, steps + 1):
                full_path.append((path[i - 1][0] + dx * s, path[i - 1][1] + dy * s))
        return full_path

    came_from = {}
    g = {start: 0}
    f = {start: manhattan(start, goal)}
    heap = [(f[start], g[start], start)]
    closed_set = set()

    while heap:
        _, curr_g, current = heapq.heappop(heap)
        if current == goal:
            return reconstruct_path(came_from, current)
        if current in closed_set:
            continue
        closed_set.add(current)

        for next_cell in get_jump_neighbors(*current):
            if next_cell in closed_set:
                continue
            new_g = curr_g + abs(next_cell[0] - current[0]) + abs(next_cell[1] - current[1])
            if next_cell not in g or new_g < g[next_cell]:
                g[next_cell] = new_g
                f[next_cell] = new_g + manhattan(next_cell, goal)
                came_from[next_cell] = current
                heapq.heappush(heap, (f[next_cell], new_g, next_cell))
    return []
