        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def is_in_bounds(r, c):
        return 0 <= r < rows and 0 <= c < cols

    def is_free(r, c):
        return is_in_bounds(r, c) and grid[r][c] == '.'

    def jump_horizontal(r, c, dc, parent):
        steps = 0
        while True:
            c += dc
            if not is_in_bounds(r, c) or grid[r][c] == '#':
                return None, None
            steps += 1
            if (r, c) == goal:
                return (r, c), steps
            r_free = is_free(r + 1, c)
            r_free2 = is_free(r - 1, c)
            if (r_free and grid[r + 1][c - dc] != '.') or (r_free2 and grid[r - 1][c - dc] != '.'):
                return (r, c), steps
            if parent and (r, c) == parent:
                return None, None

    def jump_vertical(r, c, dr, parent):
        steps = 0
        while True:
            r += dr
            if not is_in_bounds(r, c) or grid[r][c] == '#':
                return None, None
            steps += 1
            if (r, c) == goal:
                return (r, c), steps
            _, h1 = jump_horizontal(r, c, 1, (r - dr, c))
            _, h2 = jump_horizontal(r, c, -1, (r - dr, c))
            if h1 or h2:
                return (r, c), steps
            if parent and (r, c) == parent:
                return None, None

    pq = [(manhattan(start, goal), 0, start, None)]
    visited = {start: None}

    while pq:
        _, g, current, parent = heapq.heappop(pq)
        if current == goal:
            break
        if grid[current[0]][current[1]] == '#':
            continue
        r, c = current
        for dr, dc, jump_func in [(1, 0, jump_vertical), (-1, 0, jump_vertical), (0, 1, jump_horizontal), (0, -1, jump_horizontal)]:
            jr, steps = jump_func(r, c, dr, parent)
            if jr and (jr not in visited or g + steps < gval(visited[jr])):
                visited[jr] = current
                heapq.heappush(pq, (g + steps + manhattan(jr, goal), g + steps, jr, current))

    if goal not in visited:
        return []

    path = []
    cur = goal
    while cur:
        path.append(cur)
        cur = visited.get(cur)
    path.reverse()

    def gval(p):
        if not p:
            return -1
        k = 0
        while p:
            p = visited.get(p)
            k += 1
        return k

    final_path = [start]
    i = 1
    while i < len(path):
        last, curr = path[i - 1], path[i]
        dr = curr[0] - last[0]
        dc = curr[1] - last[1]
        if dr != 0:
            for r in range(last[0], curr[0], dr):
                final_path.append((r, last[1]))
        else:
            for c in range(last[1], curr[1], dc):
                final_path.append((last[0], c))
        if final_path[-1] != curr:
            final_path.append(curr)
        i += 1

    if final_path[-1] == goal:
        return final_path
    return []
