import heapq

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0])

    def is_goal(r, c):
        return (r, c) == goal

    def is_free(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def manhattan(r1, c1, r2, c2):
        return abs(r1 - r2) + abs(c1 - c2)

    def horizontal_jump(r, c, d, g, parent):
        if not is_free(r, c):
            return None
        if is_goal(r, c):
            return (r, c, g, parent)
        # Forced neighbors
        for dr in [-1, 1]:
            nr, nc = r + dr, c
            if is_free(nr, nc) and not is_free(nr + dr, nc):
                return (r, c, g, parent)
        while True:
            next_r, next_c = r, c + d
            if not is_free(next_r, next_c):
                return None
            for dr in [-1, 1]:
                nr, nc = next_r + dr, next_c
                if is_free(nr, nc) and not is_free(next_r + dr, next_c):
                    return (next_r, next_c, g + 1, (r, c))
            if is_goal(next_r, next_c):
                return (next_r, next_c, g + 1, (r, c))
            r, c = next_r, next_c
            g += 1

    def vertical_jump(r, c, d, g, parent):
        if not is_free(r, c):
            return None
        if is_goal(r, c):
            return (r, c, g, parent)
        # Check if any horizontal jump from this cell finds a jump point
        for dc in [-1, 1]:
            jump_result = horizontal_jump(r, c, dc, 0, None)
            if jump_result is not None:
                return (r, c, g, parent)
        while True:
            next_r, next_c = r + d, c
            if not is_free(next_r, next_c):
                return None
            jump_result = horizontal_jump(next_r, next_c, -1, 0, (r, c))
            if jump_result is not None:
                return (next_r, next_c, g + 1, (r, c))
            if is_goal(next_r, next_c):
                return (next_r, next_c, g + 1, (r, c))
            r, c = next_r, next_c
            g += 1

    def is_neighbour(p1, p2):
        r1, c1 = p1
        r2, c2 = p2
        return abs(r1 - r2) + abs(c1 - c2) == 1

    def a_star():
        open_list = [(manhattan(start[0], start[1], goal[0], goal[1]), 0, start, None)]
        parent_map = {}
        visited = set()

        while open_list:
            f, g, current, parent = heapq.heappop(open_list)
            if current in visited:
                continue
            visited.add(current)
            if current == goal:
                path = []
                node = current
                while node is not None:
                    path.append(node)
                    node = parent_map.get(node)
                return path[::-1]
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                if dc != 0:  # Horizontal
                    res = horizontal_jump(current[0], current[1], dc, g + 1, current)
                else:  # Vertical
                    res = vertical_jump(current[0], current[1], dr, g + 1, current)
                if res is not None:
                    jump_point, new_g, jump_parent = res
                    if jump_point not in visited:
                        parent_map[jump_point] = current
                        f = new_g + manhattan(jump_point[0], jump_point[1], goal[0], goal[1])
                        heapq.heappush(open_list, (f, new_g, jump_point, current))
        return []

    def is_line_clear(p1, p2):
        r1, c1 = p1
        r2, c2 = p2
        if r1 == r2:  # Horizontal
            step = 1 if c2 > c1 else -1
            for c in range(c1 + step, c2, step):
                if not is_free(r1, c):
                    return False
        elif c1 == c2:  # Vertical
            step = 1 if r2 > r1 else -1
            for r in range(r1 + step, r2, step):
                if not is_free(r, c1):
                    return False
        return True

    if not is_free(start[0], start[1]) or not is_free(goal[0], goal[1]):
        return []
    if start == goal:
        return [start]

    path = a_star()
    if not path:
        return []

    result = [start]
    for i in range(1, len(path)):
        current = result[-1]
        next_point = path[i]
        if is_neighbour(current, next_point):
            result.append(next_point)
        else:
            step_dir = (0, 0)
            if next_point[0] == current[0]:
                step_dir = (0, 1 if next_point[1] > current[1] else -1)
            else:
                step_dir = (1 if next_point[0] > current[0] else -1, 0)
            while current != next_point:
                current = (current[0] + step_dir[0], current[1] + step_dir[1])
                if is_free(current[0], current[1]):
                    result.append(current)
                else:
                    return []
    return result
