import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start] if grid[start[0]][start[1]] == '.' else []
    rows = len(grid)
    cols = len(grid[0])

    if not (0 <= start[0] < rows and 0 <= start[1] < cols and grid[start[0]][start[1]] == '.'):
        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols and grid[goal[0]][goal[1]] == '.'):
        return []

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def search(from_point, to_point, grid, rows, cols):
        frontier = [(manhattan(from_point, to_point), 0, from_point)]
        g_cost = {from_point: 0}
        came_from = {from_point: None}
        while frontier:
            f, g, current = heapq.heappop(frontier)
            if current in came_from and current != from_point and (current in g_cost and g > g_cost[current]):
                continue
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = current[0] + dx, current[1] + dy
                if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == '.':
                    new_g = g + 1
                    if (nx, ny) not in g_cost or new_g < g_cost[(nx, ny)]:
                        g_cost[(nx, ny)] = new_g
                        h = manhattan((nx, ny), to_point)
                        heapq.heappush(frontier, (new_g + h, new_g, (nx, ny)))
                        came_from[(nx, ny)] = current
            if current == to_point:
                return came_from, g_cost
        return came_from, g_cost

    forward_came_from, forward_g = search(start, goal, grid, rows, cols)
    backward_came_from, backward_g = search(goal, start, grid, rows, cols)

    meeting_points = set(forward_came_from).intersection(backward_came_from)
    if not meeting_points:
        return []

    best_meet = min(meeting_points, key=lambda p: forward_g.get(p, float('inf')) + backward_g.get(p, float('inf')))

    def reconstruct_path(came_from, start, end):
        path = []
        current = end
        while current != start:
            path.append(current)
            current = came_from.get(current)
            if current is None:
                return []
        path.append(start)
        return path[::-1]

    forward_path = reconstruct_path(forward_came_from, start, best_meet)
    backward_path = reconstruct_path(backward_came_from, goal, best_meet)

    if not forward_path or not backward_path:
        return []

    backward_path.reverse()
    return forward_path + backward_path[1:] if backward_path else forward_path
