import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start] if grid[start[0]][start[1]] == '.' else []

    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    if (not (0 <= start[0] < rows and 0 <= start[1] < cols) or
        not (0 <= goal[0] < rows and 0 <= goal[1] < cols) or
        grid[start[0]][start[1]] == '#' or
        grid[goal[0]][goal[1]] == '#'):
        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right
    parent = {}
    open_list = []
    heapq.heappush(open_list, (heuristic(start, goal), 0, start))

    while open_list:
        _, g, cell = heapq.heappop(open_list)

        if cell == goal:
            return reconstruct_path(parent, start, goal)

        if cell in parent or grid[cell[0]][cell[1]] == '#':
            continue

        parent[cell] = None

        for dx, dy in directions:
            if dx != 0 and dy == 0:  # horizontal move
                jump_cell = jump_horizontal(grid, cell, dx, dy, parent, g, goal)
            elif dy != 0 and dx == 0:  # vertical move
                jump_cell = jump_vertical(grid, cell, dx, dy, parent, g, goal)
            else:
                continue

            if jump_cell:
                new_g = g + manhattan_distance(cell, jump_cell)
                new_h = heuristic(jump_cell, goal)
                heapq.heappush(open_list, (new_g + new_h, new_g, jump_cell))
                parent[jump_cell] = cell

    return []

def heuristic(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])

def manhattan_distance(a, b):
    return heuristic(a, b)

def jump_horizontal(grid, current, dx, dy, parent, g, goal):
    row, col = current
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    next_cell = (row + dx, col + dy)

    if not (0 <= next_cell[0] < rows and 0 <= next_cell[1] < cols):
        return None
    if grid[next_cell[0]][next_cell[1]] == '#':
        return None

    if next_cell == goal:
        return next_cell

    # Check for vertical neighbors (up or down)
    up = (next_cell[0] - 1, next_cell[1])
    down = (next_cell[0] + 1, next_cell[1])
    if (0 <= up[0] < rows and 0 <= up[1] < cols and grid[up[0]][up[1]] == '.') or \
       (0 <= down[0] < rows and 0 <= down[1] < cols and grid[down[0]][down[1]] == '.'):
        return next_cell

    return jump_horizontal(grid, next_cell, dx, dy, parent, g, goal)

def jump_vertical(grid, current, dx, dy, parent, g, goal):
    row, col = current
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    next_cell = (row + dx, col + dy)

    if not (0 <= next_cell[0] < rows and 0 <= next_cell[1] < cols):
        return None
    if grid[next_cell[0]][next_cell[1]] == '#':
        return None

    if next_cell == goal:
        return next_cell

    # Check horizontal neighbors
    for dirx, diry in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        if dirx == 0 and diry != 0:
            continue
        if dirx == 0:
            jump = jump_horizontal(grid, next_cell, dirx, diry, parent, g, goal)
        else:
            jump = jump_vertical(grid, next_cell, dirx, diry, parent, g, goal)
        if jump:
            return jump

    return jump_vertical(grid, next_cell, dx, dy, parent, g, goal)

def reconstruct_path(parent, start, goal):
    path = [goal]
    while path[-1] != start:
        prev = parent.get(path[-1])
        if prev is None or prev in path:
            return []
        path.append(prev)
    path.reverse()
    return path
