import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start] if is_free(grid, start) else []

    if not is_free(grid, start) or not is_free(grid, goal):
        return []

    rows = len(grid)
    cols = len(grid[0])

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def is_free(grid, pos):
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[r]) and grid[r][c] == '.'

    def get_neighbors(pos):
        r, c = pos
        neighbors = [(r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)]
        return [n for n in neighbors if is_free(grid, n)]

    def search(from_pos, to_pos, get_f):
        open_heap = []
        heapq.heappush(open_heap, (get_f(from_pos, to_pos), 0, from_pos))
        g_cost = {from_pos: 0}
        parent = {}

        while open_heap:
            f, g, current = heapq.heappop(open_heap)
            if current in g_cost and g > g_cost[current]:
                continue
            for next_pos in get_neighbors(current):
                new_g = g + 1
                if next_pos not in g_cost or new_g < g_cost[next_pos]:
                    g_cost[next_pos] = new_g
                    f_next = new_g + get_f(next_pos, to_pos)
                    heapq.heappush(open_heap, (f_next, new_g, next_pos))
                    parent[next_pos] = current
        return g_cost, parent

    # Forward search from start, h is Manhattan to goal
    def forward_f(pos, to_pos):
        return 0 + manhattan(pos, to_pos)

    # Backward search from goal, h is Manhattan to start
    def backward_f(pos, to_pos):
        return 0 + manhattan(pos, to_pos)

    forward_g, forward_parent = search(start, goal, forward_f)
    backward_g, backward_parent = search(goal, start, backward_f)

    # Find meeting point
    meeting = None
    min_cost = float('inf')
    for pos in forward_g:
        if pos in backward_g and forward_g[pos] + backward_g[pos] < min_cost:
            meeting = pos
            min_cost = forward_g[pos] + backward_g[pos]

    if meeting is None:
        return []

    # Reconstruct path
    path = [meeting]
    while path[-1] != start:
        path.append(forward_parent[path[-1]])
    path.reverse()

    while path[-1] != goal:
        path.append(backward_parent[path[-1]])

    return path
