import heapq

def solve(grid, start, goal):
    if start == goal:
        if grid[start[0]][start[1]] == '#':
            return []
        return [start]
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    rows, cols = len(grid), len(grid[0])

    def get_neighbors(r, c):
        return [(r + dr, c + dc) for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)] if 0 <= r + dr < rows and 0 <= c + dc < cols and grid[r + dr][c + dc] == '.']

    parent = {}
    g = {start: 0}
    f = {start: heuristic(start, goal)}

    heap = [(f[start], start)]

    def heuristic(pos, goal):
        return abs(pos[0] - goal[0]) + abs(pos[1] - goal[1])

    def jump_horizontal(pos, direction):
        r, c = pos
        dr, dc = direction
        step = 1
        while True:
            r_jump = r + dr * step
            c_jump = c + dc * step
            if r_jump < 0 or r_jump >= rows or c_jump < 0 or c_jump >= cols or grid[r_jump][c_jump] == '#':
                return None
            if (r_jump, c_jump) == goal:
                return (r_jump, c_jump)
            # Check for forced neighbor vertically
            for d in [(-1, 0), (1, 0)]:
                nr, nc = r_jump + d[0], c_jump + d[1]
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                    if not (0 <= (r_jump - dr) < rows and 0 <= (c_jump - dc) < cols and grid[r_jump - dr][c_jump - dc] == '.'):
                        return (r_jump, c_jump)
            # Check if jumping vertically results in a jump point
            if jump_vertical((r_jump, c_jump), (1, 0)) or jump_vertical((r_jump, c_jump), (-1, 0)):
                return (r_jump, c_jump)
            step += 1

    def jump_vertical(pos, direction):
        r, c = pos
        dr, dc = direction
        step = 1
        while True:
            r_jump = r + dr * step
            c_jump = c + dc * step
            if r_jump < 0 or r_jump >= rows or grid[r_jump][c_jump] == '#':
                return None
            if (r_jump, c_jump) == goal:
                return (r_jump, c_jump)
            # Check if jumping horizontally results in a jump point
            if jump_horizontal((r_jump, c_jump), (0, 1)) or jump_horizontal((r_jump, c_jump), (0, -1)):
                return (r_jump, c_jump)
            step += 1

    while heap:
        (_, current) = heapq.heappop(heap)

        if current == goal:
            break

        for direction in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            next_r, next_c = current[0] + direction[0], current[1] + direction[1]
            if next_r < 0 or next_r >= rows or next_c < 0 or next_c >= cols or grid[next_r][next_c] == '#':
                continue

            if direction[1] != 0:
                jp = jump_horizontal(current, direction)
            else:
                jp = jump_vertical(current, direction)

            if not jp:
                continue

            new_g = g[current] + abs(jp[0] - current[0]) + abs(jp[1] - current[1])
            if jp not in g or new_g < g[jp]:
                g[jp] = new_g
                f[jp] = new_g + heuristic(jp, goal)
                parent[jp] = current
                heapq.heappush(heap, (f[jp], jp))

    if goal not in parent:
        return []

    path = []
    current = goal
    while current != start:
        path.append(current)
        current = parent[current]
    path.append(start)
    path.reverse()

    # Fill in the straight-line cells between jump points
    full_path = []
    for i in range(len(path) - 1):
        full_path.append(path[i])
        a, b = path[i], path[i + 1]
        dy = b[0] - a[0]
        dx = b[1] - a[1]
        step_y = 1 if dy > 0 else -1
        step_x = 1 if dx > 0 else -1
        for j in range(1, abs(dy) + 1):
            full_path.append((a[0] + step_y * j, a[1]))
        for j in range(1, abs(dx) + 1):
            full_path.append((a[0] + dy, a[1] + step_x * j))
    full_path.append(path[-1])

    return full_path
