        _, r, c = heapq.heappop(heap)
        if (r, c) == goal:
            return reconstruct_path(parent, start, goal)

        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:  # Horizontal and vertical jump directions
            next_point = jump(grid, r, c, dr, dc, goal, g, parent)
            if next_point:
                nr, nc = next_point
                new_g = g[(r, c)] + distance((r, c), (nr, nc))
                if (nr, nc) not in g or new_g < g.get((nr, nc), float('inf')):
                    g[(nr, nc)] = new_g
                    f[(nr, nc)] = new_g + heuristic((nr, nc), goal)
                    heapq.heappush(heap, (f[(nr, nc)], nr, nc))
                    parent[(nr, nc)] = (r, c)

    return []

def jump(grid, r, c, dr, dc, goal, g, parent):
    if not in_bounds(grid, r, c) or grid[r][c] == '#':
        return None

    if (r, c) == goal:
        return (r, c)

    # Move one step in the jump direction
    nr, nc = r + dr, c + dc
    if not in_bounds(grid, nr, nc) or grid[nr][nc] == '#':
        return None

    if dr == 0:  # Horizontal step
        # Check for forced vertical neighbor
        if in_bounds(grid, nr, c + 1) and grid[nr][c + 1] == '.' and in_bounds(grid, nr, c + 2) and grid[nr][c + 2] == '#':
            return (r, c)
        if in_bounds(grid, nr, c - 1) and grid[nr][c - 1] == '.' and in_bounds(grid, nr, c - 2) and grid[nr][c - 2] == '#':
            return (r, c)
        # Continue horizontal jump
        res = jump(grid, nr, nc, dr, dc, goal, g, parent)
        if res:
            return jump(grid, nr, nc, dr, dc, goal, g, parent)
    else:  # Vertical step
        # Check for forced horizontal neighbors
        if (jump(grid, nr, c + 1, 0, 1, goal, g, parent) or jump(grid, nr, c - 1, 0, -1, goal, g, parent)):
            return (r, c)
        # Continue vertical jump
        res = jump(grid, nr, nc, dr, dc, goal, g, parent)
        if res:
            return jump(grid, nr, nc, dr, dc, goal, g, parent)

    return None

def in_bounds(grid, r, c):
    return 0 <= r < len(grid) and 0 <= c < len(grid[0])

def is_free(grid, r, c):
    return in_bounds(grid, r, c) and grid[r][c] == '.'

def heuristic(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])

def distance(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])

def reconstruct_path(parent, start, goal):
    path = []
    current = goal
    while current != start:
        path.append(current)
        current = parent.get(current, None)
        if current is None:
            return []
    path.append(start)
    path.reverse()
    return path
