def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])
            and grid[start[0]][start[1]] == '.'):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])
            and grid[goal[0]][goal[1]] == '.'):
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def horizontal_jumps(r, c, step_x, parent):
        while True:
            c += step_x
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            # Check for forced neighbors
            if is_valid(r - 1, c) and not is_valid(r - 1, c - step_x):
                return (r, c)
            if is_valid(r + 1, c) and not is_valid(r + 1, c - step_x):
                return (r, c)
            yield (r, c)

    def vertical_jumps(r, c, step_y, parent):
        while True:
            r += step_y
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            # Check for forced neighbors
            if is_valid(r, c - 1) and not is_valid(r - step_y, c - 1):
                return (r, c)
            if is_valid(r, c + 1) and not is_valid(r - step_y, c + 1):
                return (r, c)
            # Check if any horizontal jump in this cell returns a jump point
            left = next(horizontal_jumps(r, c, -1, (r, c)), None)
            right = next(horizontal_jumps(r, c, 1, (r, c)), None)
            if left or right:
                return (r, c)
            yield (r, c)

    def jump(r, c, parent):
        dr = r - parent[0]
        dc = c - parent[1]
        if dr != 0:
            for (nr, nc) in vertical_jumps(r, c, 1 if dc > 0 else -1, parent):
                return (nr, nc)
        else:
            for (nr, nc) in horizontal_jumps(r, c, 1 if dc > 0 else -1, parent):
                return (nr, nc)
        return None

    def neighbors(r, c, parent):
        res = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                if (nr, nc) == goal:
                    res.append((nr, nc))
                else:
                    jp = jump(nr, nc, (r, c))
                    if is_valid(nr, nc) and jp:
                        res.append((nr, nc))
        return res

    came_from = {}
    g_score = {start: 0}
    f_score = {start: manhattan(start, goal)}
    heap = [(f_score[start], g_score[start], start)]

    heapq.heapify(heap)

    while heap:
        _, curr_g, curr = heapq.heappop(heap)
        if curr == goal:
            path = recover_path(came_from, start, curr)
            return path
        for nr, nc in neighbors(curr[0], curr[1], curr):
            new_g = curr_g + 1
            if (nr, nc) not in g_score or new_g < g_score[(nr, nc)]:
                came_from[(nr, nc)] = curr
                g_score[(nr, nc)] = new_g
                f_score[(nr, nc)] = new_g + manhattan((nr, nc), goal)
                heapq.heappush(heap, (f_score[(nr, nc)], new_g, (nr, nc)))

    return []

def recover_path(came_from, start, goal):
    path = []
    current = goal
    while current != start:
        path.append(current)
        current = came_from[current]
    path.append(start)
    path.reverse()
    return path
