                    priority = new_cost + manhattan(next_pos, goal)
                    heapq.heappush(forward_heap, (priority, new_cost, next_pos))

        # Backward step
        if backward_heap:
            f, cost, pos = heapq.heappop(backward_heap)
            if pos in forward_g:
                combined_cost = forward_g[pos] + backward_g[pos]
                if combined_cost < best_cost:
                    best_cost = combined_cost
                    best_meet = pos
            for next_pos in neighbors(pos):
                new_cost = cost + 1
                if next_pos not in backward_g or new_cost < backward_g[next_pos]:
                    backward_g[next_pos] = new_cost
                    backward_parent[next_pos] = pos
                    priority = new_cost + manhattan(next_pos, start)
                    heapq.heappush(backward_heap, (priority, new_cost, next_pos))

        if best_meet and best_cost < float('inf'):
            break

    if best_meet is None:
        return []

    return build_path(forward_parent, start, best_meet) + build_path(backward_parent, best_meet, goal)[1:][::-1]
