import heapq

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])

    def is_valid(pos):
        r, c = pos
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def horizontal_jump(pos, dir):
        r, c = pos
        dc = dir[1]
        while True:
            c += dc
            if not (0 <= c < cols):
                return None
            new_pos = (r, c)
            if new_pos == goal:
                return new_pos
            # Check if any cell below or above is a wall with the previous cell as free
            for dr in (-1, 1):
                nr = r + dr
                if 0 <= nr < rows and grid[nr][c] == '.':
                    if (0 <= c - dc < cols and grid[nr][c - dc] == '#') or (0 <= c + dc < cols and grid[nr][c + dc] == '#'):
                        return new_pos
            # Check if the next move is a wall
            if not is_valid((r, c + dc)):
                return None

    def vertical_jump(pos, dir):
        r, c = pos
        dr = dir[0]
        while True:
            r += dr
            if not (0 <= r < rows):
                return None
            new_pos = (r, c)
            if new_pos == goal:
                return new_pos
            # Check if a horizontal jump returns a jump point
            for dc in (-1, 1):
                jump = horizontal_jump(new_pos, (0, dc))
                if jump is not None:
                    return new_pos
            # Check if turning is blocked
            if not is_valid((r + dr, c - 1)) and not is_valid((r + dr, c + 1)):
                return None

    def get_jump_points(pos, direction):
        dr, dc = direction
        if dc != 0:
            return [horizontal_jump(pos, direction)]
        if dr != 0:
            return [vertical_jump(pos, direction)]
        return []

    open_set = []
    heapq.heappush(open_set, (manhattan(start, goal), manhattan(start, goal), start, None, 0))
    came_from = {}
    g_scores = {start: 0}

    while open_set:
        _, _, current, parent, g = heapq.heappop(open_set)
        if current == goal:
            break
        if current in came_from and came_from[current] == parent:
            continue
        came_from[current] = parent

        if parent is None:
            directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        else:
            pr, pc = parent
            cr, cc = current
            if pr == cr:
                directions = [(0, 1), (0, -1)]  # Horizontal move
            elif pc == cc:
                directions = [(-1, 0), (1, 0)]  # Vertical move

        for direction in directions:
            pos = (current[0] + direction[0], current[1] + direction[1])
            if not is_valid(pos):
                continue
            jump_points = get_jump_points(current, direction)
            for jp in jump_points:
                if jp is None:
                    continue
                new_g = g + 1
                if jp not in g_scores or g_scores[jp] > new_g:
                    g_scores[jp] = new_g
                    heapq.heappush(open_set, (
                        new_g + manhattan(jp, goal), manhattan(jp, goal), jp, current, new_g
                    ))

    if goal not in came_from:
        return []

    path = [goal]
    while path[-1] != start:
        path.append(came_from[path[-1]])
    path.reverse()

    res = [path[0]]
    for i in range(1, len(path)):
        dr, dc = path[i][0] - path[i-1][0], path[i][1] - path[i-1][1]
        while res[-1] != path[i]:
            r, c = res[-1]
            res.append((r + dr, c + dc))

    return res
