                    best_meeting = pos
                    continue
            if pos in forward_g and g_val > forward_g[pos]:
                continue
            forward_g[pos] = g_val
            for dr, dc in directions:
                nr, nc = pos[0] + dr, pos[1] + dc
                new_pos = (nr, nc)
                if not is_valid(grid, new_pos):
                    continue
                if new_pos in forward_g and forward_g[new_pos] <= g_val + 1:
                    continue
                new_g = g_val + 1
                heapq.heappush(forward_heap, (new_g + manhattan(new_pos, goal), new_pos, new_g))
                forward_parent[new_pos] = pos

        # Backward step
        if backward_heap:
            f, pos, g_val = heapq.heappop(backward_heap)
            if f >= best_meeting_cost:
                continue
            if pos in forward_g:
                if g_val + forward_g[pos] < best_meeting_cost:
                    best_meeting_cost = g_val + forward_g[pos]
                    best_meeting = pos
                    continue
            if pos in backward_g and g_val > backward_g[pos]:
