def solve(grid, start, goal):
    if start == goal:
        return [start] if is_free(grid, start) else []
    if not is_free(grid, start) or not is_free(grid, goal):
        return []

    rows = len(grid)
    cols = len(grid[0])

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def get_neighbors(pos):
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        neighbors = []
        for dr, dc in directions:
            nr, nc = pos[0] + dr, pos[1] + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                neighbors.append((nr, nc))
        return neighbors

    def is_free(grid, pos):
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def a_star(frontier, goal_pos, g_cost, parents, is_forward):
        if not frontier:
            return None, None
        f, cost, pos = heapq.heappop(frontier)
        if pos in g_cost or not is_free(grid, pos):
            return None, None
        g_cost[pos] = cost
        for neighbor in get_neighbors(pos):
            new_cost = cost + 1
            if neighbor not in g_cost or new_cost < g_cost[neighbor]:
                parents[neighbor] = pos
                h = manhattan(neighbor, goal_pos) if is_forward else manhattan(neighbor, start)
                heapq.heappush(frontier, (new_cost + h, new_cost, neighbor))
        return pos, new_cost

    forward_heap = [(manhattan(start, goal), 0, start)]
    backward_heap = [(manhattan(goal, start), 0, goal)]
    forward_g = {start: 0}
    backward_g = {goal: 0}
    forward_parents = {}
    backward_parents = {}
    best_meet_cost = float('inf')
    meet_pos = None

    while forward_heap and backward_heap:
        # Forward expansion
        pos, cost = a_star(forward_heap, goal, forward_g, forward_parents, True)
        if pos and pos in backward_g:
            total_cost = forward_g[pos] + backward_g[pos]
            if total_cost < best_meet_cost:
                best_meet_cost = total_cost
                meet_pos = pos
        elif pos is None:
            return []

        # Backward expansion
        pos, cost = a_star(backward_heap, start, backward_g, backward_parents, False)
        if pos and pos in forward_g:
            total_cost = forward_g[pos] + backward_g[pos]
            if total_cost < best_meet_cost:
                best_meet_cost = total_cost
                meet_pos = pos
        elif pos is None:
            return []

    if meet_pos is None:
        return []

    # Construct path from start to meet and from goal to meet
    def build_path(start_pos, meet, parents):
        path = []
        pos = meet
        while pos != start_pos:
            path.append(pos)
            pos = parents[pos]
        path.append(start_pos)
        return path[::-1]

    path1 = build_path(start, meet_pos, forward_parents)
    path2 = build_path(goal, meet_pos, backward_parents)
    path2.pop()  # Remove meet_pos to avoid duplication
    return path1 + path2
