        return 0 <= r < len(grid) and 0 <= c < len(grid[r]) and grid[r][c] == '.'

    def search(start, goal, is_forward):
        open_set = []
        heapq.heappush(open_set, (manhattan(start, goal), 0, start))
        came_from = {}
        g_cost = {start: 0}

        while open_set:
            _, g, current = heapq.heappop(open_set)
            if (is_forward and current in backward_g) or (not is_forward and current in forward_g):
                return current, came_from, g_cost

            for dr, dc in directions:
                nr, nc = current[0] + dr, current[1] + dc
                neighbor = (nr, nc)
                if is_free(grid, neighbor):
                    new_g = g + 1
                    if neighbor not in g_cost or new_g < g_cost[neighbor]:
                        g_cost[neighbor] = new_g
                        h = manhattan(neighbor, goal)
                        f = new_g + h
                        heapq.heappush(open_set, (f, new_g, neighbor))
                        came_from[neighbor] = current
        return None, None, None

    forward_open = []
    backward_open = []
    heapq.heappush(forward_open, (manhattan(start, goal), 0, start))
    heapq.heappush(backward_open, (manhattan(goal, start), 0, goal))

    forward_g = {start: 0}
    backward_g = {goal: 0}
    forward_came_from = {}
    backward_came_from = {}

    meeting_node = None

    while forward_open and backward_open:
        if meeting_node is not None:
            break

        # Forward expansion
        if forward_open:
            _, g, node = heapq.heappop(forward_open)
            if node in backward_g:
                meeting_node = node
                break
            forward_g[node] = g
            for dr, dc in directions:
                nr, nc = node[0] + dr, node[1] + dc
                neighbor = (nr, nc)
                if is_free(grid, neighbor) and (neighbor not in forward_g or g + 1 < forward_g[neighbor]):
                    forward_g[neighbor] = g + 1
                    h = manhattan(neighbor, goal)
                    f = forward_g[neighbor] + h
                    heapq.heappush(forward_open, (f, forward_g[neighbor], neighbor))
                    forward_came_from[neighbor] = node

        # Backward expansion
        if backward_open:
            _, g, node = heapq.heappop(backward_open)
            if node in forward_g:
                meeting_node = node
                break
            backward_g[node] = g
            for dr, dc in directions:
                nr, nc = node[0] + dr, node[1] + dc
                neighbor = (nr, nc)
                if is_free(grid, neighbor) and (neighbor not in backward_g or g + 1 < backward_g[neighbor]):
                    backward_g[neighbor] = g + 1
                    h = manhattan(neighbor, start)
                    f = backward_g[neighbor] + h
                    heapq.heappush(backward_open, (f, backward_g[neighbor], neighbor))
                    backward_came_from[neighbor] = node

        if forward_g and backward_g:
            lowest_forward_f = min(f for f, g, n in [(g + manhattan(n, goal), g, n) for n, g in forward_g.items()])
            lowest_backward_f = min(f for f, g, n in [(g + manhattan(n, start), g, n) for n, g in backward_g.items()])
            if lowest_forward_f >= lowest_backward_f:
                return []

    if meeting_node is None:
        return []

    # Reconstruct path from start to meeting node
    path = []
    current = meeting_node
    while current in forward_came_from and current != start:
        path.append(current)
        current = forward_came_from[current]
    path.append(start)
    path.reverse()

    # Reconstruct path from meeting node to goal
    current = meeting_node
    while current in backward_came_from and current != goal:
        current = backward_came_from[current]
        path.append(current)
    path.append(goal)

    if path[0] != start or path[-1] != goal or not all(is_free(grid, p) for p in path):
        return []

    return path
