        heapq.heappush(heap, (0, from_pos))
        g = {from_pos: 0}
        parent = {}
        if is_forward:
            other_g = {}
        else:
            other_g = set()

        while heap:
            f, current = heapq.heappop(heap)
            if current in other_g:
                return current, g, parent
            if not is_forward and current in g:
                continue
            if other_g and f > min(g[v] + manhattan(v, to_pos) for v in other_g):
                return None, None, None
            for dr, dc in directions:
                nr, nc = current[0] + dr, current[1] + dc
                neighbor = (nr, nc)
