                    new_g = g[current] + 1
                    if neighbor not in g or new_g < g[neighbor]:
                        g[neighbor] = new_g
                        h = manhattan(neighbor, to_pos)
                        heapq.heappush(heap, (new_g + h, neighbor))
                        parent[neighbor] = current
        return None, None, None

    current1, g1, parent1 = search(start, goal, is_forward=True)
    if not current1:
        return []

    current2, g2, parent2 = search(goal, start, is_forward=False)
    if not current2:
        return []

    path1 = [current1]
    while current1 in parent1:
