import heapq

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0])

    def is_wall(r, c):
        return r < 0 or c < 0 or r >= rows or c >= cols or grid[r][c] == '#'

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def heappop_with_check(heap, g_dict):
        while heap:
            f, g, pos = heapq.heappop(heap)
            if pos not in g_dict:
                return f, g, pos
        return None, None, None

    def expand(heap, is_forward, g_dict, parent, other_g, start, goal):
        f, g, pos = heappop_with_check(heap, g_dict)
        if f is None:
            return None
        if pos in other_g:
            return pos
        r, c = pos
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if not is_wall(nr, nc) and (nr, nc) not in g_dict:
                ng = g + 1
                new_pos = (nr, nc)
                if is_forward:
                    nf = ng + manhattan(new_pos, goal)
                else:
                    nf = ng + manhattan(new_pos, start)
                heapq.heappush(heap, (nf, ng, new_pos))
                g_dict[new_pos] = ng
                parent[new_pos] = pos
        return None

    if start == goal and not is_wall(*start):
        return [start]
    if is_wall(*start) or is_wall(*goal):
        return []

    forward_heap = []
    backward_heap = []
    heapq.heappush(forward_heap, (manhattan(start, goal), 0, start))
    heapq.heappush(backward_heap, (manhattan(goal, start), 0, goal))

    forward_g = {start: 0}
    backward_g = {goal: 0}
    forward_parent = {start: None}
    backward_parent = {goal: None}

    meeting = None

    # Ensure balanced expansion by alternating forward and backward
    for _ in range(2 * (rows + cols + 4)):
        meeting = expand(forward_heap, True, forward_g, forward_parent, backward_g, start, goal)
        if meeting:
            break
        meeting = expand(backward_heap, False, backward_g, backward_parent, forward_g, start, goal)
        if meeting:
            break

    if not meeting:
        return []

    def build_path(from_parent, start, end):
        path = []
        curr = end
        while curr != start:
            path.append(curr)
            curr = from_parent[curr]
        path.append(start)
        return path[::-1]

    forward_path = build_path(forward_parent, start, meeting)
    backward_path = build_path(backward_parent, goal, meeting)
    return forward_path + backward_path[1:]
