import heapq

def solve(grid, start, goal):
    if start == goal:
        if is_free(grid, start):
            return [start]
        return []

    if not (is_free(grid, start) and is_free(grid, goal)):
        return []

    def is_free(grid, cell):
        row, col = cell
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def neighbors(cell):
        row, col = cell
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            new_cell = (row + dr, col + dc)
            if is_free(grid, new_cell):
                yield new_cell

    def search(start, goal, is_forward):
        open_list = []
        g = {start: 0}
        f = {start: manhattan(start, goal)}
        parent = {}
        heapq.heappush(open_list, (f[start], start))

        while open_list:
            current_f, current = heapq.heappop(open_list)
            if current in g and g[current] < current_f - manhattan(current, goal if is_forward else start):
                continue

            if is_forward:
                g_val = forward_g.get(current, float('inf'))
                if current_f > g_val:
                    continue
                if current in backward_g:
                    return current, g[current]
                forward_g[current] = g[current]
                forward_parent[current] = parent.get(current)
            else:
                g_val = backward_g.get(current, float('inf'))
                if current_f > g_val:
                    continue
                if current in forward_g:
                    return current, g[current]
                backward_g[current] = g[current]
                backward_parent[current] = parent.get(current)

            for next_cell in neighbors(current):
                new_g = g[current] + 1
                if next_cell not in g or new_g < g[next_cell]:
                    g[next_cell] = new_g
                    h = manhattan(next_cell, goal if is_forward else start)
                    f[next_cell] = new_g + h
                    heapq.heappush(open_list, (f[next_cell], next_cell))

        return None, float('inf')

    forward_g = {start: 0}
    forward_parent = {}
    backward_g = {goal: 0}
    backward_parent = {}

    meeting_point = None
    best_cost = float('inf')
    i = 0
    best_forward_f = float('inf')
    best_backward_f = float('inf')

    while best_forward_f + best_backward_f < best_cost:
        if i % 2 == 0:
            meeting, cost = search(start, goal, True)
            if meeting is None:
                return []
            best_forward_f = min(best_forward_f, cost)
        else:
            meeting, cost = search(goal, start, False)
            if meeting is None:
                return []
            best_backward_f = min(best_backward_f, cost)
        if meeting:
            meeting_point = meeting
            best_cost = cost + backward_g.get(meeting_point, float('inf'))
            break
        i += 1

    if not meeting_point:
        return []

    def reconstruct_path():
        path = []
        current = meeting_point
        while current in backward_parent:
            path.append(current)
            current = backward_parent[current]
            if current is None or current == start:
                break
        path.reverse()
        if current != start:
            current = start
        while current in forward_parent:
            path.append(current)
            current = forward_parent[current]
            if current is None or current == goal:
