import heapq

def solve(grid, start, goal):
    if start == goal:
        if not is_free(start):
            return []
        return [start]

    rows = len(grid)
    cols = len(grid[0])

    def in_bounds(pos):
        r, c = pos
        return 0 <= r < rows and 0 <= c < cols

    def is_free(pos):
        r, c = pos
        return grid[r][c] == '.' if in_bounds(pos) else False

    def manhattan(pos):
        return abs(pos[0] - goal[0]) + abs(pos[1] - goal[1])

    def get_neighbors(pos):
        r, c = pos
        return [(r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)]

    def jump_horizontal(pos, dx, parent):
        r, c = pos
        new_pos = (r, c + dx)
        if not is_free(new_pos):
            return None

        if new_pos == goal:
            return new_pos

        up = (r - 1, c + dx)
        down = (r + 1, c + dx)
        backtrack = (r, c - dx)
        if is_free(up) and not is_free((r - 1, c - dx)):
            return new_pos
        if is_free(down) and not is_free((r + 1, c - dx)):
            return new_pos

        next_jump = jump_horizontal(new_pos, dx, pos)
        return next_jump if next_jump else None

    def jump_vertical(pos, dy, parent):
        r, c = pos
        new_pos = (r + dy, c)
        if not is_free(new_pos):
            return None

        if new_pos == goal:
            return new_pos

        left = (r + dy, c - 1)
        right = (r + dy, c + 1)
        backtrack = (r - dy, c)
        if is_free(left) and not is_free((r - dy, c - 1)):
            return new_pos
        if is_free(right) and not is_free((r - dy, c + 1)):
            return new_pos

        jump_left = jump_horizontal(new_pos, -1, new_pos)
        jump_right = jump_horizontal(new_pos, 1, new_pos)
        if jump_left or jump_right:
            return new_pos
        else:
            next_jump = jump_vertical(new_pos, dy, pos)
            return next_jump if next_jump else None

    def length_between(a, b):
        r1, c1 = a
        r2, c2 = b
        return abs(r1 - r2) + abs(c1 - c2)

    def reconstruct_path(parent_map, start, goal):
        if goal not in parent_map:
            return []
        path = [goal]
        current = goal
        while current != start:
            current = parent_map[current]
            path.append(current)
        path.reverse()
        return fill_path(path)

    def fill_path(path):
        filled = [path[0]]
        for i in range(1, len(path)):
            p0, p1 = filled[-1], path[i]
            dr = p1[0] - p0[0]
            dc = p1[1] - p0[1]
            dr_sign = 1 if dr > 0 else -1
            dc_sign = 1 if dc > 0 else -1
            for j in range(1, max(abs(dr), abs(dc))):
                filled.append((p0[0] + dr_sign * j, p0[1] + dc_sign * j))
            filled.append(p1)
        return filled

    def jump_point_search():
        if not is_free(start) or not is_free(goal):
            return []
        visited = set()
        parent = {}
        pq = [(manhattan(start), 0, start, None)]

        while pq:
            _, g, pos, prev = heapq.heappop(pq)
            if pos in visited:
                continue
            if pos == goal:
                return reconstruct_path(parent, start, goal)
            visited.add(pos)

            r, c = pos
            # Horizontal jumps left and right
            if prev is None or (prev[0] != r and prev[1] < c):
                next_pos = jump_horizontal(pos, 1, pos)
                if next_pos and next_pos not in visited:
                    parent[next_pos] = pos
                    heapq.heappush(pq, (manhattan(next_pos) + g + length_between(pos, next_pos), g + length_between(pos, next_pos), next_pos, pos))
            if prev is None or (prev[0] != r and prev[1] > c):
                next_pos = jump_horizontal(pos, -1, pos)
                if next_pos and next_pos not in visited:
                    parent[next_pos] = pos
                    heapq.heappush(pq, (manhattan(next_pos) + g + length_between(pos, next_pos), g + length_between(pos, next_pos), next_pos, pos))

            # Vertical jumps up and down
            if prev is None or (prev[1] != c and prev[0] < r):
                next_pos = jump_vertical(pos, 1, pos)
                if next_pos and next_pos not in visited:
                    parent[next_pos] = pos
                    heapq.heappush(pq, (manhattan(next_pos) + g + length_between(pos, next_pos), g + length_between(pos, next_pos), next_pos, pos))
            if prev is None or (prev[1] != c and prev[0] > r):
                next_pos = jump_vertical(pos, -1, pos)
                if next_pos and next_pos not in visited:
                    parent[next_pos] = pos
                    heapq.heappush(pq, (manhattan(next_pos) + g + length_between(pos, next_pos), g + length_between(pos, next_pos), next_pos, pos))

        return []

    return jump_point_search()
