    backward_heap = [(manhattan(goal, start), goal)]
    forward_seen = {start}
    backward_seen = {goal}
    meet = None

    while forward_heap and backward_heap and not (forward_seen & backward_seen):
        # Forward step
        if forward_heap:
            f, pos = heapq.heappop(forward_heap)
            if forward_g[pos] < f or pos in backward_seen:
                continue
            for n in neighbors(pos):
