                    heapq.heappush(forward_heap, (new_g + manhattan(n, goal), n))
                    forward_parent[n] = pos
                    forward_seen.add(n)

        # Backward step
        if backward_heap:
            f, pos = heapq.heappop(backward_heap)
            if backward_g[pos] < f or pos in forward_seen:
                continue
            for n in neighbors(pos):
                new_g = backward_g[pos] + 1
