            f, cost, pos, p = heapq.heappop(heap)
            if pos in visited:
                continue
            visited.add(pos)
            if pos == to_pos:
                return pos, g[pos], parent
            for n in neighbors(pos):
                new_cost = cost + 1
                if n not in g or new_cost < g[n]:
                    g[n] = new_cost
                    priority = new_cost + heur(n, to_pos)
                    heapq.heappush(heap, (priority, new_cost, n, pos))
                    parent[n] = pos
        return None, float('inf'), {}

    def reconstruct_path(parent1, meeting, parent2):
        path = []
        current = meeting
        while current is not None:
            path.append(current)
            current = parent1[current]
        path = path[::-1]
        current = parent2.get(meeting)
        while current is not None:
            path.append(current)
            current = parent2[current]
        return path

