            next_node = (curr[0] + d[0], curr[1] + d[1])
            if 0 <= next_node[0] < len(grid) and 0 <= next_node[1] < len(grid[0]) and grid[next_node[0]][next_node[1]] != '#':
                new_g = g[curr] + 1
                if next_node not in g or new_g < g[next_node]:
                    g[next_node] = new_g
                    parents[next_node] = curr
                    heapq.heappush(frontier, (new_g + manhattan(next_node, goal), next_node))
        return frontier, g, parents

    def reconstruct_path(parents1, path1, parents2, path2, meet):
        path = [meet]
        curr = parents1.get(meet, None)
        while curr:
            path.insert(0, curr)
            curr = parents1.get(curr, None)
        curr = parents2.get(meet, None)
        while curr:
            path.append(curr)
            curr = parents2.get(curr, None)
        return path

    dirs = [(-1,0), (1,0), (0,-1), (0,1)]

    frontier_start = []
    frontier_goal = []
    heapq.heappush(frontier_start, (manhattan(start, goal), start))
    heapq.heappush(frontier_goal, (manhattan(goal, start), goal))
    g_start = {start: 0}
    g_goal = {goal: 0}
    parents_start = {}
    parents_goal = {}

    best_meet_cost = float('inf')
    meeting_cell = None

    while frontier_start and frontier_goal:
        frontier_start, g_start, parents_start = a_star(frontier_start, g_start, parents_start, start, goal, grid, dirs)
        for node in g_start:
            if node in g_goal:
                cost = g_start[node] + g_goal[node]
                if cost < best_meet_cost:
                    best_meet_cost = cost
                    meeting_cell = node

        if best_meet_cost < float('inf'):
            break

        frontier_goal, g_goal, parents_goal = a_star(frontier_goal, g_goal, parents_goal, goal, start, grid, dirs)
        for node in g_goal:
            if node in g_start:
                cost = g_start[node] + g_goal[node]
                if cost < best_meet_cost:
                    best_meet_cost = cost
                    meeting_cell = node

        if best_meet_cost < float('inf'):
            break

    if meeting_cell is None:
        return []

    return reconstruct_path(parents_start, [], parents_goal, [], meeting_cell)
