        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        neighbors = []
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == '.':
                neighbors.append((nr, nc))
        return neighbors

    # Initialize forward and backward searches
    forward_g = {start: 0}
    backward_g = {goal: 0}
    forward_heap = [(manhattan(start, goal), 0, start)]
    backward_heap = [(manhattan(goal, start), 0, goal)]
    forward_came_from = {start: None}
    backward_came_from = {goal: None}

    best_f = float('inf')

    while forward_heap and backward_heap and min(forward_heap[0][0], backward_heap[0][0]) < best_f:
        # Forward search
        if forward_heap:
            f, g, pos = heapq.heappop(forward_heap)
            if pos in backward_g:
                best_f = min(best_f, g + backward_g[pos])
            if pos not in forward_g or g < forward_g.get(pos, float('inf')):
                forward_g[pos] = g
                for neighbor in get_neighbors(pos):
                    if neighbor not in forward_g or g + 1 < forward_g.get(neighbor, float('inf')):
                        forward_came_from[neighbor] = pos
                        new_f = g + 1 + manhattan(neighbor, goal)
                        heapq.heappush(forward_heap, (new_f, g + 1, neighbor))

        if forward_heap and forward_heap[0][0] >= best_f:
            break

        # Backward search
        if backward_heap:
            f, g, pos = heapq.heappop(backward_heap)
            if pos in forward_g:
                best_f = min(best_f, g + forward_g[pos])
            if pos not in backward_g or g < backward_g.get(pos, float('inf')):
                backward_g[pos] = g
                for neighbor in get_neighbors(pos):
                    if neighbor not in backward_g or g + 1 < backward_g.get(neighbor, float('inf')):
                        backward_came_from[neighbor] = pos
                        new_f = g + 1 + manhattan(neighbor, start)
                        heapq.heappush(backward_heap, (new_f, g + 1, neighbor))

        if backward_heap and backward_heap[0][0] >= best_f:
            break

    meeting_nodes = set(forward_g.keys()) & set(backward_g.keys())
    if not meeting_nodes:
        return []

    # Construct the path
    meeting = next(iter(meeting_nodes))  # pick any meeting point
    path = [meeting]
    while path[-1] != start:
        path.append(forward_came_from[path[-1]])
    path.reverse()
    curr = meeting
    while curr != goal:
        curr = backward_came_from[curr]
        path.append(curr)
    return path
