        r, c = pos
        while True:
            r += dy
            if not (0 <= r < rows):
                return None
            if grid[r][c] == '#':
                return None
            new_pos = (r, c)
            if new_pos == goal:
                return new_pos
            if dy != 0 and (grid[r - dy][c] == '#' or grid[r + dy][c] == '#'):
                return new_pos
            if (r, c - dx) != pos and grid[r][c - dx] == '.' or (r, c + dx) != pos and grid[r][c + dx] == '.':
                return new_pos
            if grid[r][c] == '#':
                return None

    def jump_vertical(pos, dx, dy):
        r, c = pos
        while True:
            c += dx
            if not (0 <= c < cols):
                return None
            if grid[r][c] == '#':
                return None
            new_pos = (r, c)
            if new_pos == goal:
                return new_pos
            if jump_horizontal(new_pos, 1, 0) or jump_horizontal(new_pos, -1, 0):
                return new_pos

    while heap:
        f, g, pos = heapq.heappop(heap)
        if pos == goal:
            path = []
            while pos in parent:
                path.append(pos)
                pos = parent[pos]
            path.append(start)
            path.reverse()
            return path
        if pos in visited:
            continue
        visited.add(pos)
        for dx, dy in directions:
            if dx == 0:  # vertical jump
                res = jump_vertical(pos, dy, dx)
            else:  # horizontal jump
                res = jump_horizontal(pos, dx, dy)
            if res:
                new_g = g + heuristic(pos, res)
                if res not in visited:
