           (not is_valid(jump_r + 1, jump_c) and is_valid(jump_r, jump_c - 1)):
            return (jump_r, jump_c)
        if (not is_valid(jump_r - 1, jump_c) and is_valid(jump_r, jump_c + 1)) or \
           (not is_valid(jump_r + 1, jump_c) and is_valid(jump_r, jump_c + 1)):
            return (jump_r, jump_c)
    else:
