        if dc == 0:
            return None

        while True:
            r, c = r + dr, c + dc
            if is_wall(r, c):
                return None
            for dy in (-1, 1):
                if not is_wall(r, c + dy) and not is_wall(r - dy, c + dy):
                    return (r, c)
            if (r, c) == goal:
                return (r, c)

    def jump_vertical(pos, direction):
        r, c = pos
        dr, dc = (1, 0) if direction == 'down' else (-1, 0)
        if dr == 0:
            return None

        while True:
            r, c = r + dr, c + dc
            if is_wall(r, c):
                return None
            for dx in (-1, 1):
                if not is_wall(r + dx, c) and not is_wall(r + dr + dx, c):
                    return (r, c)
            if (r, c) == goal:
                return (r, c)

    def heuristic(p):
        return manhattan(p, goal)

    visited = set()
    heap = [(heuristic(start), 0, start, None)]

