        if pos == goal:
            path = [pos]
            while parent:
                path.append(parent)
                parent = parent_map.get(parent)
            return path[::-1]
        if pos in visited:
            continue
        visited.add(pos)
        parent_map[pos] = parent

        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            new_pos = (pos[0] + dx, pos[1] + dy)
            if not is_wall(*new_pos):
                if dx != 0:
                    jump_result = jump_vertical(pos, 'down' if dx == 1 else 'up')
                else:
                    jump_result = jump_horizontal(pos, 'right' if dy == 1 else 'left')
                if jump_result:
