        directions = [(0, -1, "left"), (0, 1, "right"), (-1, 0, "up"), (1, 0, "down")]
        path_points = []
        for dr, dc, _ in directions:
            nr, nc = r + dr, c + dc
            if not is_valid(nr, nc):
                continue
            if (nr, nc) == goal:
                path_points.append((nr, nc))
                continue
            if (nr, nc, parent) in visited:
                continue
            visited.add((nr, nc, parent))
            if dr == 0:  # Horizontal
                result = jump_horizontal(r, c, dr, dc, parent)
            else:  # Vertical
                result = jump_vertical(r, c, dr, dc, parent)
            if result:
                new_cell, _, new_parent = result
                path_points.append(new_cell)

        for new_cell in path_points:
            new_g = manhattan(start, new_cell)
            heapq.heappush(heap, (manhattan(new_cell, goal) + new_g, new_g, new_cell, (r, c)))

    path_map = {}

    while heap:
        f, g, cell, parent = heapq.heappop(heap)
        if cell in visited:
            continue
        visited.add(cell)
        path_map[cell] = parent
        if cell == goal:
            path = []
            while cell:
                path.append(cell)
                cell = path_map.get(cell)
            return list(reversed(path))
        jump(*cell, path_map.get(cell))

    return []

