    return None

def is_wall_above_or_below(grid, r, c, dr):
    for dir in (1, -1):
        if is_free(grid, r + dir, c) and not is_free(grid, r + dir, c - 1) or not is_free(grid, r + dir, c + 1):
            return True
    return False

def jump_vertical(grid, r, c, dr, dc):
    while 0 <= r + dr < len(grid):
        r += dr
        curr = (r, c)
        if curr == goal:
            return curr
        if any(jump_horizontal(grid, r, c, 0, dc2) is not None for dc2 in (1, -1)):
            return curr
    return None

def reconstruct_path(came_from, goal):
    path = [goal]
    curr = goal
    while curr in came_from:
        curr = came_from[curr]
        path.insert(0, curr)
    return path
