    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right
    parent = {}
    g_cost = {start: 0}
    h = manhattan_distance(start, goal)
    heap = [(g_cost[start] + h, g_cost[start], start)]

    def in_bounds(pos):
        return 0 <= pos[0] < rows and 0 <= pos[1] < cols

    def is_free(pos):
        return in_bounds(pos) and grid[pos[0]][pos[1]] == '.'

    def manhattan_distance(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def jump_horizontal(pos, dx, dy):
        r, c = pos
        while True:
            c += dx
            new_pos = (r, c)
            if not in_bounds(new_pos) or grid[new_pos[0]][new_pos[1]] == '#':
                return None
            if new_pos == goal:
                return new_pos
            # Check for vertical forced neighbor
            for dr in [-1, 1]:
                check = (r + dr, c)
                if is_free(check):
                    prev = (r + dr, c - dx)
                    if not is_free(prev):
                        return new_pos
            if (r, c+1) in g_cost or (r, c-1) in g_cost or (r+1, c) in g_cost or (r-1, c) in g_cost:
                return new_pos

    def jump_vertical(pos, dx, dy):
        r, c = pos
        while True:
            r += dy
            new_pos = (r, c)
            if not in_bounds(new_pos) or grid[new_pos[0]][new_pos[1]] == '#':
                return None
            if new_pos == goal:
                return new_pos
            # Check for horizontal jump
            for dc in [-1, 1]:
                res = jump_horizontal(new_pos, dc, 0)
                if res:
                    return new_pos
            if (r+1, c) in g_cost or (r-1, c) in g_cost or (r, c+1) in g_cost or (r, c-1) in g_cost:
                return new_pos

    while heap:
        f, g, pos = heapq.heappop(heap)
        if pos == goal:
            break
        r, c = pos
        for i, (dr, dc) in enumerate(directions):
            if i % 2 == 0:  # Vertical directions
                if dc == 0:
                    result = jump_vertical(pos, dc, dr)
                else:
                    result = jump_vertical(pos, dr, dc)
            else:  # Horizontal directions
                result = jump_horizontal(pos, dc, 0) if dc != 0 else jump_horizontal(pos, 0, dr)
            if result is not None and result not in g_cost:
                new_g = g + manhattan_distance(pos, result)
                g_cost[result] = new_g
                h = manhattan_distance(result, goal)
                heapq.heappush(heap, (new_g + h, new_g, result))
                parent[result] = pos

    if goal not in parent:
        return []

    # Reconstruct path
    path = [goal]
    current = goal
    while current != start:
        current = parent[current]
        path.append(current)
    path.reverse()

    # Fill in the straight cells between jump points
    result_path = [start]
    for i in range(1, len(path)):
        dx = path[i][0] - path[i-1][0]
        dy = path[i][1] - path[i-1][1]
        x, y = result_path[-1]
        steps = max(abs(dx), abs(dy))
        dx //= steps
        dy //= steps
        for _ in range(steps - 1):
            x += dx
            y += dy
            if is_free((x, y)):
                result_path.append((x, y))
        result_path.append(path[i])
    return [p for p in result_path if is_free(p)]
