import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]
    if not is_free(grid, start) or not is_free(grid, goal):
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def is_free(grid, pos):
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[r]) and grid[r][c] == '.'

    def get_neighbors(pos, dr, dc):
        r, c = pos
        if dc == 0:  # Vertical (up/down)
            while True:
                r += dr
                if not is_free(grid, (r, c)):
                    return None
                if (r, c) == goal:
                    return (r, c)
                # Check for forced vertical neighbor
                if is_free(grid, (r+1, c)) and not is_free(grid, (r+1 + dr, c)):
                    return (r, c)
                if is_free(grid, (r-1, c)) and not is_free(grid, (r-1 + dr, c)):
                    return (r, c)
        else:  # Horizontal (left/right)
            while True:
                c += dc
                if not is_free(grid, (r, c)):
                    return None
                if (r, c) == goal:
                    return (r, c)
                # Check for forced horizontal neighbor
                if is_free(grid, (r, c+1)) and not is_free(grid, (r, c+2)):
                    return (r, c)
                if is_free(grid, (r, c-1)) and not is_free(grid, (r, c-2)):
                    return (r, c)

    def jump(start, dir):
        r, c = start
        dr, dc = dir
        if dc == 0:
            # Vertical
            res = get_neighbors((r, c), dr, 0)
        else:
            # Horizontal
            res = get_neighbors((r, c), 0, dc)
        return res

    def get_jump_points(current, g, parent):
        r, c = current
        jump_points = []
        for dr, dc in directions:
            if dr == 0 or dc == 0:
                next_pos = jump(current, (dr, dc))
                if next_pos:
                    new_g = g + manhattan(current, next_pos)
                    # Compute straight-line path to add in return phase
                    points = [(r, c)]
                    x, y = r + dr, c + dc
                    while (x, y) != next_pos:
                        points.append((x, y))
                        x += dr
                        y += dc
                    points.append(next_pos)
                    heapq.heappush(jump_points, (new_g + manhattan(next_pos, goal), new_g, next_pos, points, (r, c)))
        return jump_points

    came_from = {}
    g_score = {start: 0}
    f_score = {start: manhattan(start, goal)}
    heap = [(f_score[start], g_score[start], start, [], None)]  # (f, g, pos, path, parent)
    visited = set()

    while heap:
        f, g, pos, path, parent = heapq.heappop(heap)
        if pos in visited:
            continue
        if pos == goal:
            full_path = []
            if path:
                for seg in path:
                    full_path.extend(seg)
            elif parent:
                full_path.append(pos)
                p = parent
                while p in came_from:
                    full_path.append(p)
                    p = came_from[p]
            else:
                full_path.append(pos)
            full_path.reverse()
            return full_path
        visited.add(pos)
        jump_list = get_jump_points(pos, g, parent)
        for new_f, new_g, next_pos, segment, _ in jump_list:
            if next_pos not in visited:
                g_score[next_pos] = new_g
                f_score[next_pos] = new_f
                came_from[next_pos] = pos
                heapq.heappush(heap, (f_score[next_pos], g_score[next_pos], next_pos, segment, pos))
    return []
