            jump_h, jump_c, h_steps = jump_horizontal(r, c, -1, came_from, g, (r, c))
            if jump_h is not None:
                return jump_h, jump_c, steps + h_steps
            if is_blocked(r + 1, c) or is_blocked(r - 1, c):
                if (r, c) not in came_from or came_from[(r, c)] != parent:
                    came_from[(r, c)] = parent
                    return r, c, steps
            if is_blocked(r, c + 1) or is_blocked(r, c - 1):
                if (r, c) not in came_from or came_from[(r, c)] != parent:
                    came_from[(r, c)] = parent
                    return r, c, steps

    came_from = {}
    open_set = []
    heapq.heappush(open_set, (0, start))
    g_score = {start: 0}
    f_score = {start: manhattan(start, goal)}

    while open_set:
        current_f, current = heapq.heappop(open_set)
        if current == goal:
            return reconstruct_path(came_from, current)
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            if dr == 0:
                jump_r, jump_c, jump_steps = jump_horizontal(current[0], current[1], dc, came_from, g_score[current], current)
            else:
                jump_r, jump_c, jump_steps = jump_vertical(current[0], current[1], dr, came_from, g_score[current], current)
            if jump_r is not None and (jump_r, jump_c) != current:
                new_g = g_score[current] + jump_steps
                if (jump_r, jump_c) not in g_score or new_g < g_score[(jump_r, jump_c)]:
                    came_from[(jump_r, jump_c)] = current
                    g_score[(jump_r, jump_c)] = new_g
                    f_score[(jump_r, jump_c)] = new_g + manhattan((jump_r, jump_c), goal)
                    heapq.heappush(open_set, (f_score[(jump_r, jump_c)], (jump_r, jump_c)))

