import heapq

def solve(grid, start, goal):
    if not grid or not grid[0]:
        return []
    rows, cols = len(grid), len(grid[0])
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def heuristic(r, c):
        return abs(r - goal[0]) + abs(c - goal[1])

    def jump_horizontal(r, c, dr):
        if not is_valid(r, c):
            return None
        while True:
            steps = 1
            nr, nc = r + 2 * dr, c
            if not is_valid(nr, nc):
                return None
            while is_valid(r + dr, c) and not (r + dr == goal[0] and c == goal[1]):
                r += dr
                steps += 1
                if is_valid(r, c + 1) and not is_valid(r, c + 2):
                    return (r, c)
                if is_valid(r, c - 1) and not is_valid(r, c - 2):
                    return (r, c)
            if (r + dr, c) == goal:
                return (r + dr, c)
            if is_valid(r, c + 1) and not is_valid(r, c + 2):
                return (r, c)
            if is_valid(r, c - 1) and not is_valid(r, c - 2):
                return (r, c)
            if is_valid(r + dr, c):
                return (r + dr, c)
            return None

    def jump_vertical(r, c, dc):
        if not is_valid(r, c):
            return None
        while True:
            steps = 1
            nr, nc = r, c + 2 * dc
            if not is_valid(nr, nc):
                return None
            while is_valid(r, c + dc) and not (r == goal[0] and c + dc == goal[1]):
                c += dc
                steps += 1
                jp = jump_horizontal(r, c, 1)
                if jp:
                    return (r, c)
                jp = jump_horizontal(r, c, -1)
                if jp:
                    return (r, c)
            if (r, c + dc) == goal:
                return (r, c + dc)
            jp = jump_horizontal(r, c, 1)
            if jp:
                return (r, c)
            jp = jump_horizontal(r, c, -1)
            if jp:
                return (r, c)
            if is_valid(r, c + dc):
                return (r, c + dc)
            return None

    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right
    open_list = [(heuristic(*start), 0, start, None)]
    closed = set()
    parent = {}

    while open_list:
        f, g, pos, prev = heapq.heappop(open_list)
        if pos in closed:
            continue
        if pos == goal:
            break
        closed.add(pos)
        pr, pc = pos
        if prev:
            prv_r, prv_c = prev
            move_r = pr - prv_r
            move_c = pc - prv_c
            if move_r != 0:
                if move_r == 1:
                    jp = jump_vertical(pr, pc, 1) if move_c == 1 else jump_vertical(pr, pc, -1)
                else:
                    jp = jump_vertical(pr-1, pc, 1) if move_c == 1 else jump_vertical(pr-1, pc, -1)
            else:
                if move_c == 1:
                    jp = jump_horizontal(pr, pc, 1) if move_r == 0 else jump_horizontal(pr, pc-1, move_r)
                else:
                    jp = jump_horizontal(pr, pc, -1) if move_r == 0 else jump_horizontal(pr, pc+1, move_r)
            if isinstance(jp, tuple):
                if jp not in closed:
                    heapq.heappush(open_list, (heuristic(*jp) + g + manhattan(pos, jp), g + manhattan(pos, jp), jp, pos))
                    parent[jp] = pos
        for dr, dc in dirs:
            nr, nc = pr + dr, pc + dc
            if is_valid(nr, nc) and (nr, nc) not in closed:
                if (prv_r, prv_c) == (pr - dr, pc - dc):
                    continue  # prevent preferences in search
                if (pr + 2 * dr, pc + 2 * dc) == goal:
                    parent[goal] = pos
                    break
                if grid[pr + dr][pc + dc] == '.':
                    next_pos = (pr + dr, pc + dc)
                    if move_r != 0 or move_c != 0:
                        if move_r == dr:
                            jp = jump_horizontal(pr + dr, pc + dc, move_c)
                        elif move_c == dc:
                            jp = jump_horizontal(pr + dr, pc + dc, move_r)
                        else:
                            continue
                    else:
                        if move_r == dr:
                            jp = jump_vertical(pr + dr, pc + dc, move_c)
                        elif move_c == dc:
                            jp = jump_vertical(pr + dr, pc + dc, move_r)
                        else:
                            continue
                    if isinstance(jp, tuple):
                        parent[jp] = pos
                        parent[next_pos] = pos
                        if jp not in closed:
                            heapq.heappush(open_list, (heuristic(*jp) + g + manhattan(pos, jp), g + manhattan(pos, jp), jp, pos))
    path = []
    current = goal
    while current and current in parent:
        path.append(current)
        current = parent.get(current)
    if current != start or not path:
        return []
    path = path[::-1]
    if path[0] != start:
        path.insert(0, start)
    return path

def manhattan(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])
