import heapq

def solve(grid, start, goal):
    if (
        not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])) or
        not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])) or
        grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#'
    ):
        return []

    if start == goal:
        return [start]

    height, width = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    def is_valid(r, c):
        return 0 <= r < height and 0 <= c < width and grid[r][c] == '.'

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def jump_horizontal(r, c, dr, dc, parent):
        if not is_valid(r, c):
            return None
        if (r, c) == goal:
            return (r, c)
        # Check for forced neighbors (up or down)
        for dd in (-1, 1):
            nr, nc = r + dd, c
            if 0 <= nr < height and 0 <= nc < width:
                if is_valid(nr, nc) and not is_valid(r - dr, c - dc) and not is_valid(r + dr, c + dc):
                    return (r, c)
        # Continue jumping
        if jump_vertical(r + dr, c + dc, dr, dc, parent):
            return (r, c)
        return jump_horizontal(r + dr, c + dc, dr, dc, parent)

    def jump_vertical(r, c, dr, dc, parent):
        if not is_valid(r, c):
            return None
        if (r, c) == goal:
            return (r, c)
        # Perform horizontal jumps in both directions
        left = jump_horizontal(r, c - 1, 0, -1, (r, c)) if c > 0 else None
        right = jump_horizontal(r, c + 1, 0, 1, (r, c)) if c < width - 1 else None
        if (left or right):
            return (r, c)
        # Continue vertical jump
        return jump_vertical(r + dr, c + dc, dr, dc, parent)

    heap = []
    heapq.heappush(heap, (manhattan(start, goal), 0, start, None))
    came_from = {}

    while heap:
        _, g, current, parent = heapq.heappop(heap)
        if current == goal:
            break
        if current in came_from:
            continue
        came_from[current] = parent
        for dr, dc in directions:
            r, c = current
            if (dr == 0 or dc == 0) and (r + dr, c + dc) not in came_from:
                if (dr == 0 and dc != 0):
                    jumped = jump_horizontal(r, c + dc, dr, dc, current)
                else:
                    jumped = jump_vertical(r, c + dr, dr, dc, current)
                if jumped is not None:
                    nr, nc = jumped
                    heapq.heappush(heap, (manhattan(jumped, goal) + g + abs(nr - r) + abs(nc - c), g + abs(nr - r) + abs(nc - c), jumped, current))

    if goal not in came_from:
        return []

    path = []
    step = goal
    while step:
        path.append(step)
        step = came_from[step]
    path.reverse()

    return path
