    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    heap = [(manhattan(start, goal), 0, start, None)]
    came_from = {}
    g_cost = {start: 0}

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def jump_horizontal(x, y, dx, parent):
        while is_valid(x, y):
            steps = 1
            next_x, next_y = x + dx, y
            while is_valid(next_x, next_y):
                steps += 1
                x = next_x
                y = next_y
                next_x = x + dx
                next_y = y
                if (x, y) == goal:
                    return (x, y), steps
                if is_valid(x + 1, y) is False and is_valid(x - 1, y) is False:
                    continue
                if is_valid(x + 1, y):
                    if not is_valid(x + 1, y - 1) and not is_valid(x + 1, y + 1):
                        return (x, y), steps
                if is_valid(x - 1, y):
                    if not is_valid(x - 1, y - 1) and not is_valid(x - 1, y + 1):
                        return (x, y), steps
                if not is_valid(x + dx, y) or not is_valid(x + dx * 2, y + dy * 2):
                    continue
        return None, steps

    def jump_vertical(x, y, dy, parent):
        while is_valid(x, y):
            steps = 1
            next_x, next_y = x, y + dy
            while is_valid(next_x, next_y):
                steps += 1
                x = next_x
                y = next_y
                next_x = x
                next_y = y + dy
                if (x, y) == goal:
                    return (x, y), steps
                l, _ = jump_horizontal(x, y - 1, -1, (x, y))
                r, _ = jump_horizontal(x, y + 1, 1, (x, y))
                if l or r:
                    return (x, y), steps
        return None, steps

    while heap:
        f, g, curr, parent = heapq.heappop(heap)
        if curr == goal:
            break
        if curr in came_from and came_from[curr] == parent:
            continue
        came_from[curr] = parent
        dx, dy = 0, 0
        if parent:
            pr, pc = parent
            if curr[0] == pr:
                dy = 1 if curr[1] > pr else -1
            else:
                dx = 1 if curr[0] > pr else -1
        for d in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            if d[0] == dx and d[1] == dy:
                continue
            x, y = curr
            nx, ny = x + d[0], y + d[1]
            if is_valid(nx, ny) and (nx, ny) not in came_from or g + 1 < g_cost.get((nx, ny), float('inf')):
                if d[1] != 0:  # horizontal
                    jump_point, steps = jump_horizontal(nx, ny, d[1], curr)
                else:          # vertical
                    jump_point, steps = jump_vertical(nx, ny, d[0], curr)
                if jump_point:
                    if jump_point not in g_cost or g + steps < g_cost[jump_point]:
                        g_cost[jump_point] = g + steps
                        heapq.heappush(heap, (g + steps + manhattan(jump_point, goal), g + steps, jump_point, curr))

    if curr != goal:
        return []

    # Reconstruct path
    path = []
    node = goal
    prev = came_from.get(node)
    while node:
        path.append(node)
        node = prev
        prev = came_from.get(node)
    path.reverse()

    def interpolate(a, b):
        res = [a]
        dx = b[0] - a[0]
        dy = b[1] - a[1]
        if abs(dx) > 0:
            step = 1 if dx > 0 else -1
            for i in range(1, abs(dx)):
                res.append((a[0] + step * i, a[1]))
        elif abs(dy) > 0:
            step = 1 if dy > 0 else -1
            for i in range(1, abs(dy)):
                res.append((a[0], a[1] + step * i))
        return res

    full_path = []
    for i in range(len(path) - 1):
        full_path += interpolate(path[i], path[i+1])
    full_path.append(path[-1])

    return full_path
