        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def jump_horizontal(r, c, dr, dc, parent):
        while is_valid(r, c):
            if (r, c) == goal:
                return (r, c)
            if dc != 0 and (not is_valid(r + 1, c) or not is_valid(r - 1, c)):
                return (r, c)
            r += dr
            c += dc
        return None

    def jump_vertical(r, c, dr, dc, parent):
        while is_valid(r, c):
            if (r, c) == goal:
                return (r, c)
            hr = jump_horizontal(r, c, -1 if parent[0] > r else 1, 0, (r, c))
            hl = jump_horizontal(r, c, 1 if parent[0] < r else -1, 0, (r, c))
            if hr or hl:
                return (r, c)
            r += dr
            c += dc
        return None

    def jump(r, c, dr, dc, parent):
        if dc == 0:  # vertical
            return jump_vertical(r, c, dr, dc, parent)
        else:  # horizontal
            return jump_horizontal(r, c, dr, dc, parent)

    def get_neighbors(r, c):
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        jump_points = []
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                j = jump(nr, nc, dr, dc, (r, c))
                if j:
                    jump_points.append(j)
        return jump_points

    visited = set()
    heap = [(manhattan(start, goal), 0, start, None)]
    parent_map = {}

    while heap:
        f, g, (r, c), parent = heapq.heappop(heap)
        if (r, c) == goal:
            path = []
            while (r, c) != start:
                path.append((r, c))
                r, c = parent_map[(r, c)]
            path.append(start)
            return path[::-1]
        if (r, c) in visited:
            continue
        visited.add((r, c))
        for nr, nc in get_neighbors(r, c):
            if (nr, nc) not in visited:
                parent_map[(nr, nc)] = (r, c)
                heapq.heappush(heap, (manhattan((nr, nc), goal) + g + 1, g + 1, (nr, nc), (r, c)))
    return []
