        r, c = point
        dr, dc = dir
        new_r, new_c = r + dr, c + dc
        if not is_free(grid, new_r, new_c):
            return None

        if (new_r, new_c) == goal:
            return (new_r, new_c)

        # Check for forced vertical neighbor
        if dr != 0:
            if (is_free(grid, new_r, new_c - 1) and not is_free(grid, r, c - 1)) or \
               (is_free(grid, new_r, new_c + 1) and not is_free(grid, r, c + 1)):
                return (new_r, new_c)
        else:
            # Check for forced horizontal neighbor using horizontal jump
            if dr == 0:
                for d in [(1, 0), (-1, 0)]:
                    j = jump((new_r, new_c), d)
                    if j is not None and (j == goal or (new_r, new_c) != start):
                        return (new_r, new_c)

        if jump((new_r, new_c), dir) is not None:
            return jump((new_r, new_c), dir)
        return None

    def horizontal_jump(cell, direction):
        r, c = cell
        dr, dc = direction
        step = 1
        while True:
            r += dr * step
            c += dc * step
            if not is_free(grid, r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            if is_free(grid, r, c + (1 if dc == 1 else -1)) and not is_free(grid, r - dr * step, c - dc * step):
                return (r, c)
            if is_free(grid, r + 1, c) or is_free(grid, r - 1, c):
                j = jump((r, c), (0, 1 if dc == 1 else -1))
                if j is not None:
                    return (r, c)
            step += 1

    def vertical_jump(cell, direction):
        r, c = cell
        dr, dc = direction
        step = 1
        while True:
            r += dr * step
            c += dc * step
            if not is_free(grid, r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            # Check for forced horizontal neighbor
            if is_free(grid, r, c + 1) and not is_free(grid, r, c):
                return (r, c)
            if is_free(grid, r, c - 1) and not is_free(grid, r, c):
                return (r, c)
            if is_free(grid, r, c - 1):
                j = horizontal_jump((r, c - 1), (0, -1))
                if j is not None:
                    return (r, c)
            if is_free(grid, r, c + 1):
                j = horizontal_jump((r, c + 1), (0, 1))
                if j is not None:
                    return (r, c)
            step += 1

    def heuristic(cell):
        return manhattan(cell, goal)

    def get_neighbors(current):
        r, c = current
        neighbors = []
        for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if not is_free(grid, nr, nc):
                continue
            jp = jump((nr, nc), (dr, dc))
            if jp is not None:
                idx = 0
                while (r + dr * idx, c + dc * idx) != jp:
                    idx += 1
                neighbors.append((jp, idx))
        return neighbors

    came_from = {}
    cost = {}
    start_g = 0
    start_f = start_g + heuristic(start)
    heap = [(start_f, start_g, start, None)]

    while heap:
        f, g, current, parent = heapq.heappop(heap)
        if current == goal:
            return reconstruct_path(start, current, came_from)
        if current in cost and cost[current] < g:
            continue
        cost[current] = g
        came_from[current] = parent
        for (next_cell, steps) in get_neighbors(current):
            if next_cell not in cost:
                new_g = g + steps
                new_f = new_g + heuristic(next_cell)
                heapq.heappush(heap, (new_f, new_g, next_cell, current))

    return []

def reconstruct_path(start, goal, came_from):
    path = [goal]
    current = goal
    while current != start:
        prev = came_from.get(current)
        if prev is None:
            return [start]
        fr1, fc1 = prev
        fr2, fc2 = current
        dr = fr2 - fr1
        dc = fc2 - fc1
        step = 1
        while prev != current:
            next_p = (fr1 + dr * step, fc1 + dc * step)
            path.append(next_p)
            step += 1
        current = prev
    path.reverse()
    return path
