            down = vertical_jump(r, c, 1)
            up = vertical_jump(r, c, -1)
            if down or up:
                return result
            c += dc
        return []

    def jump(r, c, parent_dir):
        result = []
        if parent_dir[0] != 0:
            result = vertical_jump(r, c, parent_dir[0])
        else:
            result = horizontal_jump(r, c, parent_dir[1])
        return result

    visited = set()
    heap = [(manhattan(start), 0, start, None)]
    parent = {}
    while heap:
        _, g, pos, dir = heapq.heappop(heap)
        if pos == goal:
