import heapq

def solve(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])
    if not (0 <= start[0] < rows and 0 <= start[1] < cols and 0 <= goal[0] < rows and 0 <= goal[1] < cols):
        return []

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal:
        return [start]

    def is_wall(r, c):
        return not (0 <= r < rows and 0 <= c < cols) or grid[r][c] == '#'

    def is_goal(r, c):
        return (r, c) == goal

    def get_direction(r1, c1, r2, c2):
        if r1 < r2:
            return (1, 0)  # down
        elif r1 > r2:
            return (-1, 0)  # up
        elif c1 < c2:
            return (0, 1)  # right
        else:
            return (0, -1)  # left

    def horizontal_jump(r, c, dr):
        while True:
            c += 1 if dr == (0, 1) else -1
            if is_wall(r, c):
                return None
            if is_goal(r, c):
                return (r, c)
            if is_wall(r - 1, c) or is_wall(r + 1, c):
                return (r, c)
            if is_wall(r, c + 1) and dr == (0, 1) or is_wall(r, c - 1) and dr == (0, -1):
                return (r, c)

    def vertical_jump(r, c, dc):
        while True:
            r += 1 if dc == (1, 0) else -1
            if is_wall(r, c):
                return None
            if is_goal(r, c):
                return (r, c)
            # Check horizontal jumps in both directions
            for dir in [(0, 1), (0, -1)]:
                jump = horizontal_jump(r, c, dir)
                if jump:
                    return (r, c)

    def jump(r, c, prev_dr, prev_dc):
        dr, dc = get_direction(r, c, *goal)
        # Horizontal jump
        if dr == 0:
            res = horizontal_jump(r, c, (0, dc))
        # Vertical jump
        else:
            res = vertical_jump(r, c, (dr, 0))
        return res

    def neighbors(r, c, came_from=None):
        neighbors = []
        for dr, dc in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nr, nc = r + dr, c + dc
            if not is_wall(nr, nc) and (nr, nc) != came_from:
                next_jump = jump(nr, nc, dr, dc)
                if next_jump:
                    neighbors.append((nr, nc))
        return neighbors

    came_from = {}
    open_set = []
    heapq.heappush(open_set, (0 + abs(goal[0] - start[0]) + abs(goal[1] - start[1]), 0, start, None))
    g_score = {start: 0}

    while open_set:
        f, g, (r, c), parent = heapq.heappop(open_set)
        if (r, c) == goal:
            # Reconstruct path
            path = [goal]
            while (r, c) != start:
                r, c = came_from[(r, c)]
                path.append((r, c))
            return list(reversed(path))
        for nr, nc in neighbors(r, c, parent):
            if is_wall(nr, nc):
                continue
            tentative_g = g + 1
            if (nr, nc) not in g_score or tentative_g < g_score[(nr, nc)]:
                g_score[(nr, nc)] = tentative_g
                came_from[(nr, nc)] = (r, c)
                f = tentative_g + abs(goal[0] - nr) + abs(goal[1] - nc)
                heapq.heappush(open_set, (f, tentative_g, (nr, nc), (r, c)))

    return []
