    def heuristic_search(front, goal, is_wall, g, parent, other_g, forward):
        if not front:
            return False
        cost, node = heapq.heappop(front)
        r, c = node
        if node in other_g:
            return True
        if g[node] < cost:
            return False
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_wall(nr, nc):
                continue
            new_cost = g[node] + 1
            if (nr, nc) not in g or new_cost < g[(nr, nc)]:
                g[(nr, nc)] = new_cost
                h = manhattan((nr, nc), goal)
                f = new_cost + h
                heapq.heappush(front, (f, (nr, nc)))
                parent[(nr, nc)] = node
        return False

    def reconstruct_path(start, goal, parent1, parent2):
        path = []
        current = goal
        while current != start:
            path.append(current)
            current = parent1[current]
        path.append(start)
        path.reverse()
        current = path[-1]
        while current != goal:
            next_node = parent2[current]
            path.append(next_node)
            current = next_node
        return path

    if start == goal:
        return [start] if grid[start[0]][start[1]] == '.' or grid[start[0]][start[1]] == 'S' else []

    if is_wall(*start) or is_wall(*goal):
        return []

    forward_heap = []
    backward_heap = []
    forward_g = {}
    backward_g = {}
    forward_parent = {}
    backward_parent = {}

    forward_g[start] = 0
    backward_g[goal] = 0
    heapq.heappush(forward_heap, (manhattan(start, goal), start))
    heapq.heappush(backward_heap, (manhattan(goal, start), goal))

    while forward_heap and backward_heap:
        if heuristic_search(forward_heap, goal, is_wall, forward_g, forward_parent, backward_g, True):
            return reconstruct_path(start, goal, forward_parent, backward_parent)
        if heuristic_search(backward_heap, start, is_wall, backward_g, backward_parent, forward_g, False):
            return reconstruct_path(start, goal, forward_parent, backward_parent)

    return []
