import heapq

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and grid[start[0]][start[1]] == '.'):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0]) and grid[goal[0]][goal[1]] == '.'):
        return []
    if start == goal:
        return [start]

    def is_wall(r, c):
        return not (0 <= r < len(grid) and 0 <= c < len(grid[r])) or grid[r][c] == '#'

    def heuristic(r, c):
        return abs(r - goal[0]) + abs(c - goal[1])

    def jump_horizontal(current, dir_r, dir_c):
        r, c = current
        g = 0
        while True:
            r += dir_r
            c += dir_c
            g += 1
            if is_wall(r, c):
                return None
            if (r, c) == goal:
                return (r, c), g, current
            if not is_wall(r - 1, c) or not is_wall(r + 1, c):
                return (r, c), g, current

    def jump_vertical(current, dir_r, dir_c):
        r, c = current
        g = 0
        while True:
            r += dir_r
            c += dir_c
            g += 1
            if is_wall(r, c):
                return None
            if (r, c) == goal:
                return (r, c), g, current
            for d in (-1, 1):
                res = jump_horizontal((r, c), 0, d)
                res2 = jump_horizontal((r, c), 0, -d)
                if res and res[0] is not None or res2 and res2[0] is not None:
                    return (r, c), g, current

    def get_moves(current, parent):
        r, c = current
        pr, pc = parent
        if pr == r:
            # horizontal move
            if pc < c:
                res = jump_horizontal(current, 0, 1)
            else:
                res = jump_horizontal(current, 0, -1)
        else:
            # vertical move
            if pc < c:
                res = jump_vertical(current, 1, 0)
            elif pc > c:
                res = jump_vertical(current, -1, 0)
        if res and res[0] is not None:
            yield res
        if not parent and can_step(current, 0, -1):
            if res := jump_horizontal(current, 0, -1):
                if res[0] is not None:
                    yield res
        if not parent and can_step(current, 0, 1):
            if res := jump_horizontal(current, 0, 1):
                if res[0] is not None:
                    yield res
        if not parent and can_step(current, -1, 0):
            if res := jump_vertical(current, -1, 0):
                if res[0] is not None:
                    yield res
        if not parent and can_step(current, 1, 0):
            if res := jump_vertical(current, 1, 0):
                if res[0] is not None:
                    yield res

    def can_step(r, c, dr, dc):
        if is_wall(r + dr, c + dc):
            return False
        if is_wall(r + dr + dr, c + dc + dc):
            return False
        if is_wall(r + dr, c + dc + dc) or is_wall(r + dr + dr, c + dc):
            return True
        match (dr, dc):
            case (0, 1) | (0, -1):
                if not is_wall(r + 1, c + dc) or not is_wall(r - 1, c + dc):
                    return True
            case (1, 0) | (-1, 0):
                if not is_wall(r + dr, c + 1) or not is_wall(r + dr, c - 1):
                    return True
        return False

    visited = set()
    heap = [(heuristic(*start), 0, start, None)]
    path_map = {}
    path_map[start] = None

    while heap:
        f, g, current, parent = heapq.heapop(heap)
        if current in visited:
            continue
        visited.add(current)
        if current == goal:
            path = [current]
            prev = path_map.get(current)
            while prev:
                path.append(prev)
                prev = path_map.get(prev)
            return path[::-1]
        for jump_point, jump_g, jump_parent in get_moves(current, parent):
            if jump_point not in visited:
                path_map[jump_point] = current
                heapq.heappush(heap, (g + jump_g + heuristic(*jump_point), g + jump_g, jump_point, current))

    return []
