    rows = len(grid)
    cols = len(grid[0])
    g_score = {}
    came_from = {}
    open_heap = []

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def jump_horizontal(r, c, dr, dc, parent, g):
        while True:
            next_r, next_c = r + dr, c + dc
            if not is_valid(next_r, next_c):
                return None
            new_g = g + 1
            if (next_r, next_c) == goal:
                return (next_r, next_c, new_g, (r, c))
            if (next_r + 1, next_c) in g_score and next_r + 1 in range(rows):
                if grid[next_r + 1][next_c] == '.' and next_r - 1 in range(rows) and grid[next_r - 1][next_c] == '#':
                    return (next_r, next_c, new_g, (r, c))
            if (next_r - 1, next_c) in g_score and next_r - 1 in range(rows):
                if grid[next_r - 1][next_c] == '.' and next_r + 1 in range(rows) and grid[next_r + 1][next_c] == '#':
                    return (next_r, next_c, new_g, (r, c))
            r, c = next_r, next_c
            g = new_g
            if (r, c) in parent_map and parent_map[(r, c)] != (r - dr, c - dc):
                return (r, c, g, (r - dr, c - dc))

    def jump_vertical(r, c, dr, dc, parent, g):
        while True:
            next_r, next_c = r + dr, c + dc
            if not is_valid(next_r, next_c):
                return None
            new_g = g + 1
            if (next_r, next_c) == goal:
                return (next_r, next_c, new_g, (r, c))
            jump1 = jump_horizontal(next_r, next_c, 0, 1, parent, 1)
            jump2 = jump_horizontal(next_r, next_c, 0, -1, parent, 1)
            if jump1 or jump2:
                return (next_r, next_c, new_g, (r, c))
            r, c = next_r, next_c
            g = new_g

    def get_neighbors(r, c, parent):
        neighbors = []
        for dir_r, dir_c in [(-1,0), (1,0), (0,-1), (0,1)]:
            if is_valid(r + dir_r, c + dir_c) and (r + dir_r, c + dir_c) != parent:
                neighbors.append((r + dir_r, c + dir_c))
        return neighbors

    parent_map = {}
    g_score[start] = 0
    f_score = {start: manhattan(start, goal)}
    heapq.heappush(open_heap, (f_score[start], g_score[start], start))

    while open_heap:
        _, curr_g, current = heapq.heappop(open_heap)

        if current == goal:
            break

        if current in g_score and g_score[current] < curr_g:
            continue

        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            next_r, next_c = current[0] + dr, current[1] + dc
            if is_valid(next_r, next_c):
                if (next_r, next_c) == parent_map.get(current, (-1, -1)):
                    continue

                if dr == 0 or dc == 0:  # Horizontal or vertical move
                    if dr != 0:
                        j = jump_vertical(current[0], current[1], dr, dc, parent_map[current], curr_g)
                    else:
                        j = jump_horizontal(current[0], current[1], dr, dc, parent_map[current], curr_g)
                else:
                    j = jump_horizontal(current[0], current[1], dr, dc, parent_map[current], curr_g)

                if j is None:
                    continue
                j_r, j_c, j_g, j_parent = j

                g_new = curr_g + (abs(j_r - current[0]) + abs(j_c - current[1]))

                if (j_r, j_c) not in g_score or g_new < g_score[(j_r, j_c)]:
                    g_score[(j_r, j_c)] = g_new
                    f_new = g_new + manhattan((j_r, j_c), goal)
                    f_score[(j_r, j_c)] = f_new
                    heapq.heappush(open_heap, (f_new, g_new, (j_r, j_c)))
                    parent_map[(j_r, j_c)] = current

    if current != goal:
        return []

    path = []
    while current:
        path.append(current)
        current = parent_map.get(current)
    path.reverse()

    # Interpolate straight cells between jump points
    expanded_path = []
    for i in range(len(path) - 1):
        r1, c1 = path[i]
        r2, c2 = path[i + 1]
        dr = (r2 - r1) // abs(r2 - r1) if r1 != r2 else 0
        dc = (c2 - c1) // abs(c2 - c1) if c1 != c2 else 0
        expanded_path.append((r1, c1))
        r, c = r1 + dr, c1 + dc
        while (r, c) != (r2, c2):
            expanded_path.append((r, c))
            r += dr
            c += dc
    expanded_path.append((r2, c2))

    return expanded_path if all(grid[r][c] == '.' for r, c in expanded_path) else []
