            if is_free(grid, next_pos) and next_pos not in g_dict:
                new_g = g + 1
                if next_pos in g_dict and g_dict[next_pos] <= new_g:
                    continue
                g_dict[next_pos] = new_g
                parent_dict[next_pos] = curr
                heapq.heappush(frontier, (ffunc(next_pos, goal_pos), next_pos))
