        for current_search, goal_pos, g_dict, parent_dict, other_g, other_heap in [
            (forward_heap, goal, forward_g, forward_parent, backward_g, backward_heap),
            (backward_heap, start, backward_g, backward_parent, forward_g, forward_heap)
        ]:
            if not current_search:
                return []
            result = heuristic_search(current_search, lambda p, goal: g_dict[p] + manhattan(p, goal), g_dict, parent_dict, other_g, goal_pos)
            if result is not None:
                meeting_pos, total_cost = result
                if total_cost < best_meeting_cost:
                    best_meeting = meeting_pos
                    best_meeting_cost = total_cost
                return build_path(meeting_pos, forward_parent, backward_parent)
