import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]
    if not is_valid(grid, start[0], start[1]) or not is_valid(grid, goal[0], goal[1]):
        return []

    rows, cols = len(grid), len(grid[0])

    def neighbors(r, c):
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                yield (nr, nc)

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def search_forward():
        nonlocal forward_heap, forward_g, forward_parent, best_meet_g
        if not forward_heap:
            return False
        g, f, node = heapq.heappop(forward_heap)
        if forward_g[node] < g:  # Already found a better path
            return True
        if node in backward_g:
            best_meet_g = min(best_meet_g, g + backward_g[node])
        for next_node in neighbors(node[0], node[1]):
            new_g = g + 1
            if new_g < forward_g.get(next_node, float('inf')):
                forward_g[next_node] = new_g
                forward_parent[next_node] = node
                f = new_g + manhattan(next_node, goal)
                heapq.heappush(forward_heap, (new_g, f, next_node))
        return True

    def search_backward():
        nonlocal backward_heap, backward_g, backward_parent, best_meet_g
        if not backward_heap:
            return False
        g, f, node = heapq.heappop(backward_heap)
        if backward_g[node] < g:
            return True
        if node in forward_g:
            best_meet_g = min(best_meet_g, g + forward_g[node])
        for next_node in neighbors(node[0], node[1]):
            new_g = g + 1
            if new_g < backward_g.get(next_node, float('inf')):
                backward_g[next_node] = new_g
                backward_parent[next_node] = node
                f = new_g + manhattan(next_node, start)
                heapq.heappush(backward_heap, (new_g, f, next_node))
        return True

    def is_valid(grid, r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    forward_heap = []
    backward_heap = []

    forward_g = {start: 0}
    backward_g = {goal: 0}

    forward_parent = {}
    backward_parent = {}

    best_meet_g = float('inf')

    heapq.heappush(forward_heap, (0, manhattan(start, goal), start))
    heapq.heappush(backward_heap, (0, manhattan(goal, start), goal))

    while forward_heap or backward_heap:
        if not search_forward() or not search_backward():  # One heap is exhausted or no better path
            return []

        for h in [forward_heap, backward_heap]:
            if not h:
                return []

        forward_f = forward_heap[0][1] if forward_heap else float('inf')
        backward_f = backward_heap[0][1] if backward_heap else float('inf')

        if min(forward_f, backward_f) >= best_meet_g:
            for meet in forward_g:
                if meet in backward_g:
                    total_g = forward_g[meet] + backward_g[meet]
                    if total_g == best_meet_g:
                        meet_node = meet
                        break
            path = []
            curr = meet_node
            while curr in forward_parent:
                path.append(curr)
                curr = forward_parent[curr]
            path.reverse()
            curr = meet_node
            while curr in backward_parent:
                curr = backward_parent[curr]
                path.append(curr)
            path.append(start)
            path.reverse()
            return path

    return []

