import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]
    if not is_free(grid, start) or not is_free(grid, goal):
        return []

    rows, cols = len(grid), len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols

    def is_free(grid, pos):
        r, c = pos
        return is_valid(r, c) and grid[r][c] == '.'

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def a_star(start, goal):
        heap = [(manhattan(start, goal), 0, start)]
        came_from = {start: None}
        g_score = {start: 0}

        while heap:
            _, cost, current = heapq.heappop(heap)
            if current == goal:
                break
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = current[0] + dr, current[1] + dc
                neighbor = (nr, nc)
                if is_valid(nr, nc) and grid[nr][nc] == '.' and is_free(grid, neighbor):
                    new_cost = cost + 1
                    if neighbor not in g_score or new_cost < g_score[neighbor]:
                        g_score[neighbor] = new_cost
                        priority = new_cost + manhattan(neighbor, goal)
                        heapq.heappush(heap, (priority, new_cost, neighbor))
                        came_from[neighbor] = current
        return g_score, came_from

    g_forward, came_from_forward = a_star(start, goal)
    g_backward, came_from_backward = a_star(goal, start)

    if goal not in g_forward or start not in g_backward:
        return []

    forward_path = reconstruct_path(came_from_forward, start, goal)
    backward_path = reconstruct_path(came_from_backward, goal, start)
    backward_path.reverse()
    return forward_path + backward_path


def reconstruct_path(came_from, start, goal):
    current = goal
    path = []
    while current != start:
        path.append(current)
        current = came_from[current]
    path.append(start)
    path.reverse()
    return path
