            if pos in g and g[pos] < f - manhattan(pos, back):
                continue
            if pos in g and g[pos] > f - manhattan(pos, back):
                continue
            if pos in g and g[pos] == cost:
                if pos in g:
                    if g[pos] < cost:
                        continue
                    if g[pos] == cost:
                        meet = pos
                        return (meet, g, parent)
                else:
                    g[pos] = cost
                    if forward:
                        directions = [(-1,0), (1,0), (0,-1), (0,1)]
                    else:
                        directions = [(1,0), (-1,0), (0,1), (0,-1)]
                    for dy, dx in directions:
