import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]
    if not is_free(grid, *start) or not is_free(grid, *goal):
        return []

    return bidirectional_astar(grid, start, goal)

def is_free(grid, r, c):
    return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

def manhattan(p1, p2):
    return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

def get_neighbors(r, c):
    return [(r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)]

def bidirectional_astar(grid, start, goal):
    forward = {'heap': [], 'g': {}, 'parent': {}, 'start': start, 'goal': goal}
    backward = {'heap': [], 'g': {}, 'parent': {}, 'start': goal, 'goal': start}

    for side in [forward, backward]:
        heapq.heappush(side['heap'], (manhattan(side['start'], side['goal']), 0, side['start']))
        side['g'][side['start']] = 0

    best_cost = float('inf')
    while forward['heap'] and backward['heap']:
        # Alternate expansion between forward and backward
        for i in [0, 1]:
            if i == 0:
                if forward['heap'][0][0] >= best_cost:
                    break
                # Expand from forward
                side = forward
            else:
                if backward['heap'][0][0] >= best_cost:
                    break
                # Expand from backward
                side = backward

            f, g, loc = heapq.heappop(side['heap'])
            if loc in side['g'] and side['g'].get(loc, float('inf')) < g:
                continue
            if loc in (forward['g'] if side == backward else backward['g']):
                return build_path(forward['parent'], backward['parent'], loc, start, goal)
            for nr, nc in get_neighbors(*loc):
                if not is_free(grid, nr, nc):
                    continue
                new_g = (side['g'][loc] if loc in side['g'] else g) + 1
                if (nr, nc) in side['g'] and side['g'][(nr, nc)] <= new_g:
                    continue
                new_f = new_g + manhattan((nr, nc), side['goal'])
                if new_f < best_cost:
                    side['g'][(nr, nc)] = new_g
                    heapq.heappush(side['heap'], (new_f, new_g, (nr, nc)))
                    side['parent'][(nr, nc)] = loc
                    if (nr, nc) in (forward['g'] if side == backward else backward['g']):
                        return build_path(forward['parent'], backward['parent'], (nr, nc), start, goal)
        else:
            continue
        break
    return []

def build_path(fwd_parent, bwd_parent, mid, start, goal):
    path = []
    current = mid
    while current != start:
        path.append(current)
        current = fwd_parent[current]
    path.append(start)
    current = mid
    while current != goal:
        current = bwd_parent[current]
        path.append(current)
    return path[::-1]
