        r, c = pos
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:  # Up, Down, Left, Right
            nr, nc = r + dr, c + dc
            if 0 <= nr < height and 0 <= nc < width and grid[nr][nc] == '.':
                yield (nr, nc)

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def is_free(grid, r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def a_star(start, goal, forward=True):
        if forward:
            cost = lambda g, pos: g + manhattan(pos, goal)
        else:
            cost = lambda g, pos: g + manhattan(pos, start)

        def search(from_pos, to_pos):
            heap = [(cost(0, from_pos), 0, from_pos)]
            visited = {from_pos: 0}
            parent = {}

            while heap:
                f, g, pos = heapq.heappop(heap)
                if pos in visited and visited[pos] < g:
                    continue
                if pos == to_pos or any(visited[h] <= g for h in visited if cost(g - visited[h], h) < cost(0, h)):
                    return g, parent, visited
                for n in neighbors(pos):
                    new_g = g + 1
                    if n not in visited or new_g < visited[n]:
                        visited[n] = new_g
                        heapq.heappush(heap, (cost(new_g, n), new_g, n))
                        parent[n] = pos
            return float('inf'), {}, visited

        g, parents, visited = search(start, goal)
        return g, parents, visited

    forward_g, forward_parent, forward_visited = a_star(start, goal, True)
    backward_g, backward_parent, backward_visited = a_star(goal, start, False)

    # Find best meeting point
    meeting = None
    for cell in forward_visited:
        if cell in backward_visited:
            total = forward_visited[cell] + backward_visited[cell]
            if meeting is None or total < meeting[0]:
                meeting = (total, cell)

    if meeting is None:
        return []

    _, meet = meeting

    # Reconstruct path
    path = []
    curr = meet
    while curr != start:
        path.append(curr)
        curr = forward_parent[curr]
    path.reverse()
    path = [start] + path

    curr = meet
    while curr != goal:
        curr = backward_parent[curr]
        path.append(curr)
    path.append(goal)

    return path
