    backward_parent = {}

    heapq.heappush(forward_heap, (manhattan(start, goal), 0, start))
    heapq.heappush(backward_heap, (manhattan(goal, start), 0, goal))

    min_cost = float('inf')
    meeting_node = None

    while forward_heap or backward_heap:
        cost, node = search_step(forward_heap, forward_g, forward_parent, backward_g, start, goal)
        if cost < min_cost and node:
            min_cost = cost
            meeting_node = node
        if cost >= min_cost or min_cost == float('inf'):
            cost, node = search_step(backward_heap, backward_g, backward_parent, forward_g, goal, start)
            if cost < min_cost and node:
                min_cost = cost
                meeting_node = node
            if cost >= min_cost or min_cost == float('inf'):
                break

    if meeting_node is None or meeting_node not in forward_g or meeting_node not in backward_g:
        return []

    path = []
    curr = meeting_node
    while curr in forward_parent:
        path.append(curr)
        curr = forward_parent[curr]
    path = path[::-1]
    curr = meeting_node
    while curr in backward_parent:
        curr = backward_parent[curr]
        if curr != meeting_node:
            path.append(curr)
    path.append(start)

    return path if path[-1] == start else []
