        return abs(r - goal[0]) + abs(c - goal[1])

    def jump(r, c, dr, dc):
        if is_wall(r, c):
            return None
        if (r, c) == goal:
            return (r, c)
        step = {
            'dr': dr, 'dc': dc, 'prev': (-dc, dr) if dr and dc else (0, 0),
            'next': (dc, -dr) if dr and dc else (0, 0), 'jumped': 1
        }

        while True:
            nr, nc = r + dr, c + dc
            if is_wall(nr, nc):
                return None
            r, c = nr, nc
            step['jumped'] += 1
            pd, prd = step['prev']
            nd, nrd = step['next']
            if not is_wall(r + pd, c + prd) or not is_wall(r + nd, c + nrd):
                return (r, c)

    open_set = [(manhattan(*start), 0, start, None)]
    came_from = {}
    g_score = {start: 0}

    while open_set:
        f, g, current, parent = heapq.heappop(open_set)
        if current == goal:
            path = [current]
            while parent is not None:
                path.append(parent)
                parent = came_from.get(parent)
            return path[::-1]
        if current in came_from:
            continue
        came_from[current] = parent
        r, c = current
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            step = 1
            if parent is not None:
                pr, pc = parent
                if (pr == r and abs(pc - c) > 0 and dr == 0 and (c + dc - pc) == 0) or \
                   (pc == c and abs(pr - r) > 0 and dc == 0 and (r + dr - pr) == 0):
                    # Continue from parent in the same direction
                    pass
                else:
                    continue
            jumped = jump(r, c, dr, dc)
            if jumped is None:
                continue
            nr, nc = jumped
            if is_wall(nr, nc):
                continue
            if (nr, nc) in g_score and g_score[(nr, nc)] <= g + step:
                continue
            g_score[(nr, nc)] = g + step
            heapq.heappush(open_set, (g + step + manhattan(nr, nc), g + step, (nr, nc), current))
    return []
