            if next_cell and next_cell not in g_scores:
                next_g = g + manhattan(next_cell, curr)
                g_scores[next_cell] = next_g
                heapq.heappush(heap, (next_g + manhattan(next_cell, goal), next_g, next_cell))
                came_from[next_cell] = curr

