    for dr in (1, -1):
        if is_free(grid, r + dr, c) and (
            not is_valid_cell(grid, r + dr, c - 1) or 
            not is_valid_cell(grid, r + dr, c + 1)
        ):
            return True
    return False

def is_valid_cell(grid, r, c):
