def jump_horizontal(grid, r, c, dr, dc, goal):
    while 0 <= c + dc < len(grid[0]):
        c += dc
        curr = (r, c)
        if curr == goal:
            return curr
        if is_wall_above_or_below(grid, r, c):
            return curr
    return None

def jump_vertical(grid, r, c, dr, dc, goal):
    while 0 <= r + dr < len(grid):
        r += dr
        curr = (r, c)
        if curr == goal:
            return curr
        if any(jump_horizontal(grid, r, c, 0, dc2, goal) for dc2 in (1, -1)):
            return curr
    return None

def reconstruct_path(came_from, goal):
    path = [goal]
    curr = goal
    while curr in came_from:
        curr = came_from[curr]
        path.insert(0, curr)
    return path
