import heapq

def solve(grid, start, goal):
    if start == goal:
        r, c = start
        if 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.':
            return [start]
        return []

    rows = len(grid)
    cols = len(grid[0])

    def manhattan(pos):
        return abs(pos[0] - goal[0]) + abs(pos[1] - goal[1])

    def is_free(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def is_forced_vertical(r, c, dr):
        back_r, back_c = r - dr, c
        if not is_free(back_r, back_c):
            return True
        return is_free(r + 1, c) or is_free(r - 1, c)

    def is_forced_horizontal(r, c, dc):
        back_r, back_c = r, c - dc
        if not is_free(back_r, back_c):
            return True
        return is_free(r, c + 1) or is_free(r, c - 1)

    def jump_horizontal(r, c, d):
        while True:
            next_r, next_c = r, c + d
            if not is_free(next_r, next_c):
                return None
            if (next_r, next_c) == goal:
                return (next_r, next_c)
            if is_forced_vertical(next_r, next_c, 0):
                return (next_r, next_c)
            r, c = next_r, next_c

    def jump_vertical(r, c, d):
        while True:
            next_r, next_c = r + d, c
            if not is_free(next_r, next_c):
                return None
            if (next_r, next_c) == goal:
                return (next_r, next_c)
            if jump_horizontal(next_r, next_c, 1) or jump_horizontal(next_r, next_c, -1):
                return (next_r, next_c)
            r, c = next_r, next_c

    def jump(r, c, dr, dc):
        if dr != 0:
            return jump_vertical(r, c, dr)
        if dc != 0:
            return jump_horizontal(r, c, dc)
        return None

    came_from = {}
    cost = {}
    frontier = [(manhattan(start), 0, start)]
    visited = set()

    while frontier:
        _, g, current = heapq.heappop(frontier)
        if current == goal:
            break
        if current in visited:
            continue
        visited.add(current)
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            found = jump(current[0], current[1], dr, dc)
            if found is not None and found not in visited:
                new_g = g + abs(found[0] - current[0]) + abs(found[1] - current[1])
                if found not in cost or new_g < cost[found]:
                    cost[found] = new_g
                    came_from[found] = current
                    heapq.heappush(frontier, (new_g + manhattan(found), new_g, found))

    if goal not in came_from:
        return []

    path = []
    current = goal
