    def jump_horizontal(pos, dx, dy):
        r, c = pos
        while True:
            c += dx
            new_pos = (r, c)
            if not in_bounds(new_pos) or grid[new_pos[0]][new_pos[1]] == '#':
                return None
            if new_pos == goal:
                return new_pos
            # Check for vertical forced neighbor
            for dr in [-1, 1]:
                check = (r + dr, c)
                if is_free(check):
                    prev = (r + dr, c - dx)
                    if not is_free(prev):
                        return new_pos
            res = jump_horizontal(new_pos, dx, 0)
            if res:
                if res == goal:
                    return res
                elif any(grid[n[0]][n[1]] == '#' for n in [(res[0] + 1, res[1]), (res[0] - 1, res[1])]):
                    return res

    def jump_vertical(pos, dx, dy):
        r, c = pos
        while True:
            r += dy
            new_pos = (r, c)
            if not in_bounds(new_pos) or grid[new_pos[0]][new_pos[1]] == '#':
                return None
            if new_pos == goal:
                return new_pos
            # Check for horizontal jump
            for dc in [-1, 1]:
                res = jump_horizontal(new_pos, dc, 0)
                if res:
                    return new_pos

    def heuristic(pos):
        return manhattan_distance(pos, goal)

    while heap:
        f, g, pos = heapq.heappop(heap)
        if pos == goal:
            break
        for dr, dc in directions:
            next_pos = (pos[0] + dr, pos[1] + dc)
            if in_bounds(next_pos) and is_free(next_pos) and next_pos not in g_cost:
                jump_result = None
                if dc == 0:
