                else:
                    jump_result = jump_horizontal(pos, dc, 0)
                if jump_result:
                    new_g = g + manhattan_distance(pos, jump_result)
                    g_cost[jump_result] = new_g
                    new_f = new_g + heuristic(jump_result)
                    heapq.heappush(heap, (new_f, new_g, jump_result))
                    parent[jump_result] = pos

    if goal not in parent:
        return []

    # Reconstruct path
    path = [goal]
    current = goal
    while current != start:
        current = parent[current]
        path.append(current)
    path.reverse()

    # Fill in the straight-line cells between consecutive jump points
    result_path = []
    for i in range(len(path) - 1):
        dx = path[i + 1][0] - path[i][0]
        dy = path[i + 1][1] - path[i][1]
        steps = max(abs(dx), abs(dy))
        dr = dx // steps if dx else 0
        dc = dy // steps if dy else 0
        result_path.append(path[i])
        current = path[i]
        for _ in range(steps - 1):
            current = (current[0] + dr, current[1] + dc)
            if is_free(current):
                result_path.append(current)
    result_path.append(path[-1])
    return [p for p in result_path if is_free(p)]
