                if abs(move_r) == 1:
                    jp = jump_vertical(pr, pc, jdir)
                else:
                    jp = jump_vertical(pr - 1, pc, jdir)
            else:
                jdir = 1 if move_c >= 0 else -1
                if move_c == 1:
                    jp = jump_horizontal(pr, pc, jdir)
                else:
                    jp = jump_horizontal(pr, pc, -jdir)
            if isinstance(jp, tuple) and jp not in closed:
                heapq.heappush(open_list, (heuristic(*jp) + g + manhattan(pos, jp), g + manhattan(pos, jp), jp, pos))
                parent[jp] = pos
        else:
            for dr, dc in dirs:
                nr, nc = pr + dr, pc + dc
                if is_valid(nr, nc) and (nr, nc) not in closed:
                    if (pr + 2 * dr, pc + 2 * dc) == goal:
                        parent[goal] = pos
                        break
                    if (dr == 0):
                        jp = jump_horizontal(pr, pc, dc)
                    else:
                        jp = jump_vertical(pr, pc, dr)
                    if isinstance(jp, tuple) and jp not in closed:
                        heapq.heappush(open_list, (heuristic(*jp) + g + manhattan(pos, jp), g + manhattan(pos, jp), jp, pos))
                        parent[jp] = pos
    path = []
    current = goal
    while current and current in parent:
        path.append(current)
        current = parent[current]
    if current != start or not path:
        return []
    path.reverse()
    if path[0] != start:
        path.insert(0, start)
    return path
