                if j:
                    jump_points.append(j)
        return jump_points

    visited = set()
    heap = [(manhattan(start, goal), 0, start, None)]
    parent_map = {}

    while heap:
        f, g, (r, c), parent = heapq.heappop(heap)
        if (r, c) in visited:
            continue
        if (r, c) == goal:
            path = []
            while (r, c) != start:
                path.append((r, c))
                r, c = parent_map.get((r, c), (None, None))
                if r is None:
                    break
            if path and path[-1] == goal:
                path.append(start)
                path.reverse()
                return path
            return [goal] if (r, c) == goal else []
        visited.add((r, c))
        for nr, nc in get_neighbors(r, c):
            if (nr, nc) not in visited and is_valid(nr, nc):
                parent_map[(nr, nc)] = (r, c)
                heapq.heappush(heap, (manhattan((nr, nc), goal) + g + 1, g + 1, (nr, nc), (r, c)))
