            result.append((r, c))
            if (r, c) == goal:
                return result
            if (0 <= r - 1 < rows and grid[r - 1][c] == '#') or (0 <= r + 1 < rows and grid[r + 1][c] == '#'):
                break
            c += dc
        return result

    def vertical_jump(r, c, dr):
        result = []
        while 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.':
            result.append((r, c))
            if (r, c) == goal:
                return result
            if (0 <= c - 1 < cols and grid[r][c - 1] == '#') or (0 <= c + 1 < cols and grid[r][c + 1] == '#'):
                break
            r += dr
        return result

    def jump(r, c, dr, dc):
        if dr != 0:
            return vertical_jump(r, c, dr)
        else:
            return horizontal_jump(r, c, dc)

    visited = set()
    heap = [(manhattan(start), 0, start, None)]
    parent = {}

    while heap:
        _, g, pos, dir = heapq.heappop(heap)
        if pos == goal:
            break
        if pos in visited:
            continue
        visited.add(pos)
        if dir is not None:
            dr, dc = dir
            new_r, new_c = pos[0] + dr, pos[1] + dc
            jump_result = jump(new_r, new_c, dr, dc)
            for p in jump_result:
                if p not in visited and grid[p[0]][p[1]] == '.':
                    parent[p] = pos
                    delta = abs(p[0] - pos[0]) + abs(p[1] - pos[1])
                    heapq.heappush(heap, (g + delta + manhattan(p), g + delta, p, (p[0] - pos[0], p[1] - pos[1])))
        else:
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                new_r, new_c = pos[0] + dr, pos[1] + dc
                if 0 <= new_r < rows and 0 <= new_c < cols and grid[new_r][new_c] == '.':
                    parent[(new_r, new_c)] = pos
                    heapq.heappush(heap, (1 + manhattan((new_r, new_c)), 1, (new_r, new_c), (dr, dc)))

    if goal not in parent and start != goal:
        return []

    path = []
    current = goal
    while current != start:
        path.append(current)
        current = parent[current]
    path.append(start)
