                return (r, c, steps)

    def jump_vertical(pos, dir):
        r, c = pos
        dr, dc = (1, 0) if dir == 'D' else (-1, 0)
        steps = 0
        while True:
            r += dr
            c += dc
            steps += 1
            if not (0 <= r < rows and 0 <= c < cols):
                return None
            if (r, c) == goal:
