            if is_wall(r, c):
                return None
            for horiz_dir in ('L', 'R'):
                jump_result = jump_horizontal((r, c), horiz_dir)
                if jump_result:
                    return jump_result

    open_set = [(manhattan(start, goal), 0, start, None)]
    heapq.heapify(open_set)
    came_from = {}
    g_score = {start: 0}

    while open_set:
        f, g, pos, parent = heapq.heappop(open_set)
        if pos in came_from:
            continue
        came_from[pos] = parent
        if pos == goal:
            break
        for (dr, dc, dir, jump_func) in [
            ( (+1, 0), 'D', jump_vertical ),
            ( (-1, 0), 'U', jump_vertical ),
            ( (0, +1), 'R', jump_horizontal ),
            ( (0, -1), 'L', jump_horizontal ),
        ]:
            next_r, next_c = pos[0] + dr[0], pos[1] + dr[1]
            if not (0 <= next_r < rows and 0 <= next_c < cols):
                continue
            jump_result = jump_func( (pos[0], pos[1]), dir )
            if jump_result is None:
                continue
            jump_pos, jump_steps = jump_result[0:2]
            if jump_pos in came_from:
                continue
            new_g = g + jump_steps
            heapq.heappush(open_set, (new_g + manhattan(jump_pos, goal), new_g, jump_pos, pos))
            g_score[jump_pos] = new_g

    if goal not in came_from:
        return []

    path = []
    current = goal
    while current:
        path.append(current)
