import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]

    rows = len(grid)
    cols = len(grid[0])

    if not (0 <= start[0] < rows and 0 <= start[1] < cols and grid[start[0]][start[1]] == '.'):
        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols and grid[goal[0]][goal[1]] == '.'):
        return []

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def get_neighbors(pos):
        r, c = pos
        neighbors = []
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                neighbors.append((nr, nc))
        return neighbors

    def search(frontier, start, other_g, other_heap, g_dict, parents, goal):
        while frontier:
            f, cost, pos = heapq.heappop(frontier)
            if pos in other_g:
                path1 = [pos]
                while pos in parents:
                    pos = parents[pos]
                    path1.append(pos)
                if pos == start:
                    return path1[::-1]
                path2 = []
                while pos in other_parents:
                    pos = other_parents[pos]
                    path2.append(pos)
                if pos == goal:
                    path2.append(pos)
                return path1 + path2

            if pos in g_dict and g_dict[pos] < cost:
                continue

            for neighbor in get_neighbors(pos):
                new_cost = cost + 1
                if neighbor not in g_dict or g_dict[neighbor] > new_cost:
                    g_dict[neighbor] = new_cost
                    h = heuristic(neighbor, goal)
                    heapq.heappush(frontier, (new_cost + h, new_cost, neighbor))
                    parents[neighbor] = pos
        return None

    forward_heap = [(heuristic(start, goal), 0, start)]
    backward_heap = [(heuristic(goal, start), 0, goal)]
    forward_g = {start: 0}
    backward_g = {goal: 0}
    forward_parents = {}
    backward_parents = {}

    best_f = [float("inf")]
    best_forward_g = [float("inf")]
    best_backward_g = [float("inf")]

    def check_meet():
        if forward_g and backward_g:
            forward_min_f = min((g + heuristic(pos, goal) for pos, g in forward_g.items()), default=float("inf"))
            backward_min_f = min((g + heuristic(pos, start) for pos, g in backward_g.items()), default=float("inf"))
            total_f = forward_min_f + backward_min_f
            if total_f >= best_forward_g[0] + best_backward_g[0]:
                return True
        return False

    forward_heap_dup = forward_heap.copy()
    heapq.heapify(forward_heap_dup)
    backward_heap_dup = backward_heap.copy()
    heapq.heapify(backward_heap_dup)
    forward_g_dup = forward_g.copy()
    backward_g_dup = backward_g.copy()

    while forward_heap and backward_heap:
        if check_meet():
            break
        path_starttojoint = search(forward_heap, start, backward_g, backward_heap_dup, forward_g, forward_parents, goal)
        if path_starttojoint:
            best_forward_g[0] = forward_g[start]
            best_backward_g[0] = backward_g[goal]
            for p in path_starttojoint:
                best_forward_g[0] = min(best_forward_g[0], forward_g.get(p, float("inf")))
                best_backward_g[0] = min(best_backward_g[0], backward_g.get(p, float("inf")))
        if path_starttojoint and not check_meet():
            forward_heap = forward_heap_dup
            forward_g = forward_g_dup.copy()
            forward_parents = {}
            return path_starttojoint

        if check_meet():
            break
        path_backbackward = search(backward_heap, goal, forward_g, forward_heap_dup, backward_g, backward_parents, start)
        if path_backbackward:
            best_forward_g[0] = forward_g[start]
            best_backward_g[0] = backward_g[goal]
            for p in path_backbackward:
                best_forward_g[0] = min(best_forward_g[0], forward_g.get(p, float("inf")))
                best_backward_g[0] = min(best_backward_g[0], backward_g.get(p, float("inf")))
        if path_backbackward and not check_meet():
            backward_heap = backward_heap_dup
            backward_g = backward_g_dup.copy()
            backward_parents = {}
            return path_backbackward

    path_starttojoint = search(forward_heap, start, backward_g, backward_heap, forward_g, forward_parents, goal)
    return path_starttojoint
