import heapq

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    heap = [(0, 0, start, None)]
    came_from = {}
    g_cost = {start: 0}

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def jump_horizontal(x, y, dx, parent):
        steps = 0
        new_x, new_y = x, y
        while is_valid(new_x, new_y):
            steps += 1
            next_x = new_x + dx
            if not is_valid(next_x, new_y):
                return None, steps
            if (new_x, new_y) == goal:
                return (new_x, new_y), steps
            if is_valid(new_x + 1, new_y - 1) == False and is_valid(new_x + 1, new_y + 1) == False:
                return (new_x, new_y), steps
            if is_valid(new_x - 1, new_y - 1) == False and is_valid(new_x - 1, new_y + 1) == False:
                return (new_x, new_y), steps
            if is_valid(new_x, new_y - 1) and jump_vertical(new_x, new_y - 1, -1, (new_x, new_y))[0] is not None:
                return (new_x, new_y), steps
            if is_valid(new_x, new_y + 1) and jump_vertical(new_x, new_y + 1, 1, (new_x, new_y))[0] is not None:
                return (new_x, new_y), steps
            new_x += dx
        return None, steps

    def jump_vertical(x, y, dy, parent):
        steps = 0
        new_x, new_y = x, y
        while is_valid(new_x, new_y):
            steps += 1
            next_y = new_y + dy
            if not is_valid(new_x, next_y):
                return None, steps
            if (new_x, new_y) == goal:
                return (new_x, new_y), steps
            if is_valid(new_x - 1, new_y - dy) == False and is_valid(new_x + 1, new_y - dy) == False:
                return (new_x, new_y), steps
            if is_valid(new_x - 1, new_y) and jump_horizontal(new_x - 1, new_y, -1, (new_x, new_y))[0] is not None:
                return (new_x, new_y), steps
            if is_valid(new_x + 1, new_y) and jump_horizontal(new_x + 1, new_y, 1, (new_x, new_y))[0] is not None:
                return (new_x, new_y), steps
            new_y += dy
        return None, steps

    while heap:
        f, g, curr, parent = heapq.heappop(heap)
        if curr == goal:
            break
        if curr in came_from and came_from[curr] == parent:
            continue
        came_from[curr] = parent
        dx, dy = 0, 0
        if parent:
            pr, pc = parent
            if curr[0] == pr:
                dy = 1 if curr[1] > pr else -1
            else:
                dx = 1 if curr[0] > pr else -1
        for d in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            if d[0] == dx and d[1] == dy:
                continue
            x, y = curr
            nx, ny = x + d[0], y + d[1]
            if is_valid(nx, ny) and (nx, ny) not in came_from or g + 1 < g_cost.get((nx, ny), float('inf')):
                if d[1] != 0:  # horizontal
                    jump_point, steps = jump_horizontal(nx, ny, d[1], curr)
                else:          # vertical
                    jump_point, steps = jump_vertical(nx, ny, d[0], curr)
                if jump_point:
                    if jump_point not in g_cost or g + steps < g_cost[jump_point]:
                        g_cost[jump_point] = g + steps
                        heapq.heappush(heap, (g + steps + manhattan(jump_point, goal), g + steps, jump_point, curr))

    if curr != goal:
        return []

    # Reconstruct path
    path = []
    node = goal
    prev = came_from.get(node)
    while node:
        path.append(node)
        node = prev
        prev = came_from.get(node)
    path.reverse()

    def interpolate(a, b):
        res = [a]
        dx = b[0] - a[0]
        dy = b[1] - a[1]
        if abs(dx) > 0:
            step = 1 if dx > 0 else -1
            for i in range(1, abs(dx)):
                res.append((a[0] + step * i, a[1]))
        elif abs(dy) > 0:
            step = 1 if dy > 0 else -1
            for i in range(1, abs(dy)):
                res.append((a[0], a[1] + step * i))
        return res

    full_path = []
    for i in range(len(path) - 1):
        full_path += interpolate(path[i], path[i+1])
    full_path.append(path[-1])

    return full_path
