import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start] if is_free(grid, *start) else []
    if not is_free(grid, *start) or not is_free(grid, *goal):
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # right, down, left, up

    def is_free(grid, r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def jump(point, dir):
        r, c = point
        dr, dc = dir
        steps = 0
        while True:
            r += dr
            c += dc
            steps += 1
            if not is_free(grid, r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            # Check for forced neighbors
            if dr != 0:
                # Left or right movement
                if (is_free(grid, r - 1, c) and not is_free(grid, r - 1 - dr, c)) or \
                   (is_free(grid, r + 1, c) and not is_free(grid, r + 1 - dr, c)):
                    return (r, c)
            else:
                # Up or down movement
                for d in [(0, 1), (0, -1)]:
                    ndr, ndc = d
                    nr, nc = r, c
                    while is_free(grid, nr + ndr, nc + ndc):
                        nr += ndr
                        nc += ndc
                    if (nr + ndr, nc + ndc) == goal:
                        return (r, c)
                    if not is_free(grid, nr + ndr, nc + ndc):
                        return (r, c)
            if jump((r, c), dir) is not None:
                return jump((r, c), dir)
            if not is_free(grid, r + dr, c + dc):
                return None

    def get_neighbors(current):
        neighbors = []
        r, c = current
        for (dr, dc) in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if not is_free(grid, nr, nc):
                continue
            j = jump((nr, nc), (dr, dc))
            if j is not None:
                steps = 0
                (jr, jc) = (nr, nc)
                while (jr, jc) != j:
                    jr += dr
                    jc += dc
                    steps += 1
                    if not is_free(grid, jr, jc):
                        break
                if is_free(grid, *j):
                    neighbors.append((j, steps + 1))
        return neighbors

    def heuristic(cell):
        return manhattan(cell, goal)

    def reconstruct_path(start, goal, came_from):
        path = [goal]
        current = goal
        while current != start:
            prev = came_from[current]
            if prev is None:
                return []
            prev_row, prev_col = prev
            curr_row, curr_col = current
            dr = curr_row - prev_row
            dc = curr_col - prev_col
            step = 1
            while prev != current:
                next_p = (prev_row + dr * step, prev_col + dc * step)
                path.append(next_p)
                step += 1
                current = next_p
        path.reverse()
        return path

    came_from = {}
    cost = {}
    heap = [(heuristic(start), 0, start, None)]

    while heap:
        f, g, current, parent = heapq.heappop(heap)
        if current == goal:
            return reconstruct_path(start, current, came_from)
        if current in cost and cost[current] < g:
            continue
        cost[current] = g
        came_from[current] = parent
        for (next_cell, steps) in get_neighbors(current):
            if next_cell not in cost:
                new_g = g + steps
                new_f = new_g + heuristic(next_cell)
                heapq.heappush(heap, (new_f, new_g, next_cell, current))

    return []
