def solve(grid, start, goal):
    if start == goal:
        if is_free(grid, start):
            return [start]
        return []

    if not is_free(grid, start) or not is_free(grid, goal):
        return []

    rows, cols = len(grid), len(grid[0])

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def is_free(grid, pos):
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def jump_horizontal(pos, direction):
        r, c = pos
        dr, dc = direction
        while True:
            r += dr
            c += dc
            if not (0 <= r < rows and 0 <= c < cols):
                return None
            if grid[r][c] == '#':
                return None
            new_pos = (r, c)
            if new_pos == goal:
                return new_pos
            # Check if there is a forced vertical neighbor (wall one step back)
            if dr == -1:
                up = (r - 1, c)
                down = (r + 1, c)
            else:
                up = (r + 1, c)
                down = (r - 1, c)
            if is_free(grid, new_pos) and ((is_free(grid, up) and grid[r - dr][c] == '#') or (is_free(grid, down) and grid[r - dr][c] == '#')):
                return new_pos

    def jump_vertical(pos, direction):
        r, c = pos
        dr, dc = direction
        while True:
            r += dr
            c += dc
            if not (0 <= r < rows and 0 <= c < cols):
                return None
            if grid[r][c] == '#':
                return None
            new_pos = (r, c)
            if new_pos == goal:
                return new_pos
            # Check horizontal jumps from current pos with left and right directions
            if jump_horizontal(new_pos, (-1, 0)) is not None or jump_horizontal(new_pos, (1, 0)) is not None:
                return new_pos

    def jump(pos, direction):
        if direction in [(0, 1), (0, -1)]:
            return jump_horizontal(pos, direction)
        else:
            return jump_vertical(pos, direction)

    def path_reconstruction(prev, start, goal):
        path = []
        current = goal
        while current:
            path.append(current)
            current = prev.get(current)
        path.reverse()
        return path

    def fill_path(path):
        if not path:
            return []
        filled_path = [path[0]]
        for i in range(1, len(path)):
            r1, c1 = filled_path[-1]
            r2, c2 = path[i]
            while not (r1 == r2 and c1 == c2):
                if r1 < r2:
                    r1 += 1
                elif r1 > r2:
                    r1 -= 1
                elif c1 < c2:
                    c1 += 1
                else:
                    c1 -= 1
                filled_path.append((r1, c1))
        return filled_path

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    open_set = []
    heapq.heappush(open_set, (manhattan(start, goal), 0, start, None))  # (f, g, pos, parent)
    parent = {}

    while open_set:
        _, g, pos, prev_pos = heapq.heappop(open_set)
        if pos == goal:
            path = path_reconstruction(parent, start, pos)
            return fill_path(path)
        for direction in directions:
            dr, dc = direction
            next_cell = (pos[0] + dr, pos[1] + dc)
            if not (0 <= next_cell[0] < rows and 0 <= next_cell[1] < cols):
                continue
            if grid[next_cell[0]][next_cell[1]] == '#':
                continue
            if next_cell in parent and parent[next_cell] == pos:
                continue
            jumped = jump(next_cell, direction)
            if jumped:
                if jumped not in parent:
                    parent[jumped] = pos
                    heapq.heappush(open_set, (g + manhattan(jumped, goal), g + 1, jumped, pos))
    return []
