                    g_forward[(nr, nc)] = g + 1
                    parent_forward[(nr, nc)] = current
                    heapq.heappush(forward_heap, (g_forward[(nr, nc)] + h((nr, nc), goal), (nr, nc), g + 1))

        if backward_heap:
            f, current, g = heapq.heappop(backward_heap)
            if current in backward_visited:
                continue
            backward_visited.add(current)
            if current in g_forward:
