                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in g_backward:
                    g_backward[(nr, nc)] = g + 1
                    parent_backward[(nr, nc)] = current
                    heapq.heappush(backward_heap, (g_backward[(nr, nc)] + h((nr, nc), start), (nr, nc), g + 1))

    return []

def is_free(grid, pos):
    r, c = pos
    return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

def join_paths(join_point, parent_forward, parent_backward):
    path_forward = [join_point]
    current = join_point
    while current in parent_forward:
        current = parent_forward[current]
        path_forward.append(current)
    path_backward = []
    current = join_point
    while current in parent_backward:
        current = parent_backward[current]
        path_backward.append(current)
    return path_forward[::-1] + path_backward

def is_valid_path(grid, path):
    for (r, c) in path:
        if not (0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'):
            return False
    return True
