        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def heuristic_search(frontier, ffunc, g_dict, parent_dict, other_g, goal_pos):
        if not frontier:
            return None
        while frontier:
            cost, curr = heapq.heappop(frontier)
            g = g_dict[curr]
            if curr in other_g:
                return (curr, g + other_g[curr])
            for dr, dc in directions:
                next_pos = (curr[0]+dr, curr[1]+dc)
                if is_free(grid, next_pos) and next_pos not in g_dict:
                    new_g = g + 1
                    g_dict[next_pos] = new_g
                    parent_dict[next_pos] = curr
                    heapq.heappush(frontier, (ffunc(next_pos, goal_pos), next_pos))
        return None

    forward_g = {start: 0}
    forward_parent = {}
    forward_heap = [(manhattan(start, goal), start)]

    backward_g = {goal: 0}
    backward_parent = {}
    backward_heap = [(manhattan(goal, start), goal)]

    best_meeting_cost = float('inf')
    best_meeting = None

    while forward_heap and backward_heap and forward_g and backward_g:
        for current_search, goal_pos, g_dict, parent_dict, other_g, other_heap in [
            (forward_heap, goal, forward_g, forward_parent, backward_g, backward_heap),
            (backward_heap, start, backward_g, backward_parent, forward_g, forward_heap)
        ]:
            result = heuristic_search(current_search, lambda p, gpos: g_dict.get(p, float('inf')) + manhattan(p, gpos), g_dict, parent_dict, other_g, goal_pos)
            if result is not None:
                meeting_pos, total_cost = result
                if total_cost < best_meeting_cost:
                    best_meeting = meeting_pos
                    best_meeting_cost = total_cost
                return build_path(meeting_pos, forward_parent, backward_parent)
    return []

def build_path(meet, forward_parent, backward_parent):
    path = []
    curr = meet
    while curr in forward_parent:
        path.append(curr)
        curr = forward_parent[curr]
    path.reverse()
    while curr in backward_parent:
        curr = backward_parent[curr]
        path.append(curr)
    return path
