        if not frontier:
            return None
        f, cost, pos = heapq.heappop(frontier)
        if pos in other_g:
            return (f + other_g[pos], pos, parent, g)
        if pos in g and cost > g[pos]:
            return None
        g[pos] = cost
        for dr, dc in directions:
            nr, nc = pos[0] + dr, pos[1] + dc
            npos = (nr, nc)
            if is_valid(grid, npos) and npos not in g:
                new_cost = cost + 1
                h = manhattan(npos, goal)
                new_f = new_cost + h
                heapq.heappush(frontier, (new_f, new_cost, npos))
                parent[npos] = pos
        return None

    def reconstruct(g1, p1, meet, g2, p2):
        path1, path2 = [meet], [meet]
        while meet in p1:
            meet = p1[meet]
            path1.insert(0, meet)
        meet = p2[meet]
        while meet in p2:
            meet = p2[meet]
            path2.append(meet)
        return path1 + path2

    forward_heap = [(manhattan(start, goal), 0, start)]
    backward_heap = [(manhattan(start, goal), 0, goal)]
    g_forward, g_backward = {start: 0}, {goal: 0}
    parent_forward, parent_backward = {}, {}
    best_meeting_cost = float('inf')
    best_meet_pos = None

    while forward_heap or backward_heap:
        result = search(forward_heap, goal, g_forward, parent_forward, g_backward, True)
        if result:
            cost, meet, p, g = result
            if cost < best_meeting_cost:
                best_meeting_cost = cost
                best_meet_pos = meet
                forward_heap = []
                backward_heap = []
                break
        if forward_heap:
            result = search(backward_heap, start, g_backward, parent_backward, g_forward, False)
            if result:
                cost, meet, p, g = result
                if cost < best_meeting_cost:
                    best_meeting_cost = cost
                    best_meet_pos = meet
                    forward_heap = []
                    backward_heap = []
                    break
        if not forward_heap or not backward_heap:
            break

    if not best_meet_pos:
        return []

