import heapq

def solve(grid, start, goal):
    if start == goal:
        if grid[start[0]][start[1]] == '#':
            return []
        return [start]

    rows = len(grid)
    cols = len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def get_neighbors(point):
        r, c = point
        neighbors = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                neighbors.append((nr, nc))
        return neighbors

    def a_star_search(direction, start, goal, heuristic):
        open_heap = []
        closed = set()
        g = {}
        parent = {}

        if direction == 'forward':
            origin, target = start, goal
            heapq.heappush(open_heap, (heuristic(start, goal), start, 0))
        else:
            origin, target = goal, start
            heapq.heappush(open_heap, (heuristic(goal, start), goal, 0))

        g[origin] = 0

        while open_heap:
            f, current, cost = heapq.heappop(open_heap)
            if current in closed:
                continue
            closed.add(current)

            if current == target:
                break

            for neighbor in get_neighbors(current):
                new_cost = cost + 1
                if neighbor not in g or new_cost < g[neighbor]:
                    g[neighbor] = new_cost
                    f_neighbor = new_cost + heuristic(neighbor, target)
                    heapq.heappush(open_heap, (f_neighbor, neighbor, new_cost))
                    parent[neighbor] = current

        return closed, parent, g

    def reconstruct_path(parent1, parent2, meeting_point):
        path1 = []
        current = meeting_point
        while current in parent1:
            path1.append(current)
            current = parent1[current]
        if current != start:
            return None
        path1.reverse()
        path2 = []
        current = meeting_point
        while current in parent2:
            path2.append(current)
            current = parent2[current]
        if current != goal:
            return None
        return path1 + path2

    closed1, parent1, g1 = a_star_search('forward', start, goal, manhattan)
    if start not in g1:
        return []
    closed2, parent2, g2 = a_star_search('backward', goal, start, manhattan)
    if goal not in g2:
        return []

    best_meeting = None
    best_meeting_cost = float('inf')

    for node in g1:
        if node in g2:
            total_cost = g1[node] + g2[node]
            if total_cost < best_meeting_cost:
                best_meeting = node
                best_meeting_cost = total_cost

    if best_meeting is None:
        return []

    final_path = reconstruct_path(parent1, parent2, best_meeting)
    if not final_path or final_path[0] != start or final_path[-1] != goal:
        return []

    return final_path
