        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def jump_horizontal(r, c, dr, dc, parent, g):
        while True:
            next_r, next_c = r + dr, c + dc
            if not is_valid(next_r, next_c):
                return None
            new_g = g + 1
            if (next_r, next_c) == goal:
                return (next_r, next_c, new_g)
            above = is_valid(next_r - 1, next_c) and grid[next_r - 1][next_c] == '.'
            below = is_valid(next_r + 1, next_c) and grid[next_r + 1][next_c] == '.'
            if above and not is_valid(next_r - 2, next_c):
                return (next_r, next_c, new_g)
            if below and not is_valid(next_r + 2, next_c):
                return (next_r, next_c, new_g)
            r, c = next_r, next_c
            g = new_g

    def jump_vertical(r, c, dr, dc, parent, g):
        while True:
            next_r, next_c = r + dr, c + dc
            if not is_valid(next_r, next_c):
                return None
            new_g = g + 1
            if (next_r, next_c) == goal:
                return (next_r, next_c, new_g)
            left = jump_horizontal(next_r, next_c, 0, -1, (next_r - dr, next_c - dc), 1)
            right = jump_horizontal(next_r, next_c, 0, 1, (next_r - dr, next_c - dc), 1)
            if left or right:
                return (next_r, next_c, new_g)
            r, c = next_r, next_c
            g = new_g

    while open_heap:
        f, g, current = heapq.heappop(open_heap)

        if current == goal:
            break

        if g > g_score.get(current, float('inf')):
            continue

        r, c = current
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            next_r, next_c = r + dr, c + dc
            if is_valid(next_r, next_c) and (next_r, next_c) != came_from.get(current, (-1, -1)):
                if (dr == -1 or dr == 1):  # Moving vertically
                    jump_result = jump_vertical(r, c, dr, dc, current, g)
                else:  # Moving horizontally
                    jump_result = jump_horizontal(r, c, dr, dc, current, g)

                if jump_result:
                    jump_r, jump_c, jump_g = jump_result
                    if (jump_r, jump_c) not in g_score or jump_g < g_score.get((jump_r, jump_c), float('inf')):
                        g_score[(jump_r, jump_c)] = jump_g
                        f = jump_g + manhattan((jump_r, jump_c), goal)
                        heapq.heappush(open_heap, (f, jump_g, (jump_r, jump_c)))
                        came_from[(jump_r, jump_c)] = current

    if current != goal:
        return []

    path = []
    while current:
        path.append(current)
        current = came_from.get(current)
    path.reverse()

    expanded_path = []
    for i in range(len(path) - 1):
        r1, c1 = path[i]
        r2, c2 = path[i + 1]
        dr = (r2 - r1) // abs(r2 - r1) if r1 != r2 else 0
        dc = (c2 - c1) // abs(c2 - c1) if c1 != c2 else 0
        r, c = r1, c1
        while (r, c) != (r2, c2):
            expanded_path.append((r, c))
            r += dr
            c += dc
    expanded_path.append((r2, c2))

    return expanded_path if all(grid[r][c] == '.' for r, c in expanded_path) else []
