import heapq

def solve(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])
    if not (0 <= start[0] < rows and 0 <= start[1] < cols and 0 <= goal[0] < rows and 0 <= goal[1] < cols):
        return []

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal:
        return [start]

    def is_wall(r, c):
        return not (0 <= r < rows and 0 <= c < cols) or grid[r][c] == '#'

    def is_goal(r, c):
        return (r, c) == goal

    def move(r, c, dr, dc):
        return not is_wall(r + dr, c + dc), (r + dr, c + dc)

    def horizontal_jump(r, c, dr, dc):
        nr, nc = r, c
        while True:
            nr += dc
            nc += dr
            if is_wall(nr, nc):
                return None
            if is_goal(nr, nc):
                return (nr, nc)
            if not is_wall(nr, nc - 1) or not is_wall(nr, nc + 1):  # has open vertical
                return (nr, nc)

    def vertical_jump(r, c, dr, dc):
        nr, nc = r, c
        while True:
            nr += dr
            nc += dc
            if is_wall(nr, nc):
                return None
            if is_goal(nr, nc):
                return (nr, nc)
            # Check left and right for horizontal jump
            if horizontal_jump(nr, nc - 1, -1, 0) or horizontal_jump(nr, nc + 1, 1, 0):
                return (nr, nc)

    def jump(r, c, dr, dc):
        nr, nc = r + dr, c + dc
        if is_wall(nr, nc):
            return None
        if is_goal(nr, nc):
            return (nr, nc)
        # Vertical jump
        if dr != 0:
            if (not is_wall(nr, nc - 1) and (is_wall(r, nc - 1) or is_wall(nr, nc - 1 - dr))) or \
               (not is_wall(nr, nc + 1) and (is_wall(r, nc + 1) or is_wall(nr, nc + 1 - dr))):
                return (nr, nc)
            next_jump = vertical_jump(r, c, dr, dc)
            if next_jump:
                return next_jump
        # Horizontal jump
        else:
            if (not is_wall(nr - 1, nc) and (is_wall(r - 1, c) or is_wall(nr - 1, nc))) or \
               (not is_wall(nr + 1, nc) and (is_wall(r + 1, c) or is_wall(nr + 1, nc))):
                return (nr, nc)
            next_jump = horizontal_jump(r, c, dr, dc)
            if next_jump:
                return next_jump
        return None

    def get_neighbors(r, c, came_from_dr, came_from_dc):
        directions = [(1, 0, 'down'), (-1, 0, 'up'), (0, 1, 'right'), (0, -1, 'left')]
        neighbors = []
        for dr, dc, _ in directions:
            if (dr, dc) == (-came_from_dr, -came_from_dc):
                continue  # Skip the reverse of the came_from direction
            next_jump = jump(r, c, dr, dc)
            while next_jump:
                neighbors.append(next_jump)
                temp_r, temp_c = next_jump
                next_jump = jump(temp_r, temp_c, dr, dc)
        return neighbors

    came_from = {}
    open_set = []
    g_score = {start: 0}

    heapq.heappush(open_set, (0 + abs(goal[0] - start[0]) + abs(goal[1] - start[1]), 0, start, 0, 0))

    while open_set:
        f, g, (r, c), came_from_dr, came_from_dc = heapq.heappop(open_set)
        if (r, c) == goal:
            # Reconstruct path
            path = [goal]
            curr = goal
            while curr != start:
                curr = came_from[curr]
                path.append(curr)
            return list(reversed(path))

        for nr, nc in get_neighbors(r, c, came_from_dr, came_from_dc):
            if is_wall(nr, nc):
                continue
            tentative_g = g + 1
            if (nr, nc) not in g_score or tentative_g < g_score[(nr, nc)]:
                g_score[(nr, nc)] = tentative_g
                came_from[(nr, nc)] = (r, c)
                f = tentative_g + abs(goal[0] - nr) + abs(goal[1] - nc)
                dr, dc = get_direction(r, c, nr, nc)
                heapq.heappush(open_set, (f, tentative_g, (nr, nc), dr, dc))

    return []

def get_direction(r1, c1, r2, c2):
    if r1 < r2:
        return (1, 0)
    elif r1 > r2:
        return (-1, 0)
    elif c1 < c2:
        return (0, 1)
    else:
        return (0, -1)
