        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step(pos):
        r, c = pos
        neighbors = [(r+1, c), (r-1, c), (r, c+1), (r, c-1)]
        return [n for n in neighbors if not is_wall(n)]

    def build_path(from_parent, to_parent, meet):
        path1 = []
        pos = meet
        while pos in from_parent:
            path1.append(pos)
            pos = from_parent[pos]
        path1.reverse()
        path2 = []
        pos = meet
        while pos in to_parent:
            path2.append(pos)
            pos = to_parent[pos]
        return [start] + path1 + path2

    if start == goal and not is_wall(start):
        return [start]
    if is_wall(start) or is_wall(goal):
        return []

    g_start = {start: 0}
    parent_start = {}
    open_start = [(manhattan(start, goal) + g_start[start], g_start[start], start)]

    g_goal = {goal: 0}
    parent_goal = {}
    open_goal = [(manhattan(goal, start) + g_goal[goal], g_goal[goal], goal)]

    best_meet = None
    best_meet_cost = float('inf')

    while open_start and open_goal:
        # Forward step
        if open_start:
            f, g, node = heapq.heappop(open_start)
            if min(f for f in map(lambda x: x[0], open_start)) if open_start else float('inf') >= best_meet_cost:
                continue
            if node in g_goal:
                total = g + g_goal[node]
                if total < best_meet_cost:
                    best_meet_cost = total
                    best_meet = node
            for next_node in step(node):
                if is_wall(next_node):
                    continue
                new_g = g + 1
                if next_node not in g_start or new_g < g_start[next_node]:
                    g_start[next_node] = new_g
                    parent_start[next_node] = node
                    heapq.heappush(open_start, (new_g + manhattan(next_node, goal), new_g, next_node))

        # Backward step
        if open_goal:
            f, g, node = heapq.heappop(open_goal)
            if min(f for f in map(lambda x: x[0], open_goal)) if open_goal else float('inf') >= best_meet_cost:
                continue
            if node in g_start:
                total = g + g_start[node]
                if total < best_meet_cost:
                    best_meet_cost = total
                    best_meet = node
            for next_node in step(node):
                if is_wall(next_node):
                    continue
                new_g = g + 1
                if next_node not in g_goal or new_g < g_goal[next_node]:
                    g_goal[next_node] = new_g
                    parent_goal[next_node] = node
                    heapq.heappush(open_goal, (new_g + manhattan(next_node, start), new_g, next_node))

