            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                yield nr, nc

    def is_free(grid, pos):
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def heuristic_search(from_pos, to_pos, neighbor_func, h_func):
        open_heap = []
        heapq.heappush(open_heap, (h_func(from_pos, to_pos), from_pos))
        g_cost = {from_pos: 0}
        parent = {}

        while open_heap:
            f, current = heapq.heappop(open_heap)
            if current in g_cost and f > g_cost[current]:
                continue

            for next_pos in neighbor_func(current):
                new_g = g_cost[current] + 1
                if next_pos not in g_cost or new_g < g_cost[next_pos]:
                    g_cost[next_pos] = new_g
                    heapq.heappush(open_heap, (new_g + h_func(next_pos, to_pos), next_pos))
                    parent[next_pos] = current
        return g_cost, parent

    g_start, parents_start = heuristic_search(start, goal, neighbors, manhattan)
    g_goal, parents_goal = heuristic_search(goal, start, neighbors, manhattan)

    best_meeting_cost = float('inf')
    best_meet = None

    for cell in g_start:
        if cell in g_goal and g_start[cell] + g_goal[cell] < best_meeting_cost:
            best_meeting_cost = g_start[cell] + g_goal[cell]
            best_meet = cell

    if not best_meet:
        return []

    path_start = [best_meet]
    while path_start[-1] != start:
        path_start.append(parents_start[path_start[-1]])
    path_start.reverse()

    path_goal = [best_meet]
