                neighbor = (nr, nc)
                if is_valid(nr, nc) and grid[nr][nc] == '.' and is_free(grid, neighbor):
                    if neighbor in (came_from if forward else came_from) and g_score[current] + 1 >= g_score.get(neighbor, float('inf')):
                        continue
                    g_score[neighbor] = g_score[current] + 1
                    priority = g_score[neighbor] + manhattan(neighbor, goal if forward else start)
                    heapq.heappush(heap, (priority, g_score[neighbor], neighbor))
                    came_from[neighbor] = current
        return g_score, came_from

    g_forward, came_from_forward = a_star(start, goal, forward=True)
    g_backward, came_from_backward = a_star(goal, start, forward=False)

    if goal not in g_forward or start not in g_backward:
        return []

    forward_path = reconstruct_path(came_from_forward, start, goal)
    backward_path = reconstruct_path(came_from_backward, goal, start)
    backward_path.reverse()
    return forward_path + backward_path


def reconstruct_path(came_from, start, goal):
    current = goal
    path = []
    while current != start:
        path.append(current)
        if current not in came_from:
            return []
        current = came_from[current]
    path.append(start)
    path.reverse()
    return path
