import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start] if is_free(grid, *start) else []

    if not is_free(grid, *start) or not is_free(grid, *goal):
        return []

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def get_neighbors(r, c):
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        result = []
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_free(grid, nr, nc):
                result.append((nr, nc))
        return result

    def is_free(grid, r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def search(from_node, to_node, forward_dir=True):
        open_set = []
        heapq.heappush(open_set, (0, from_node))
        g_cost = {from_node: 0}
        parent = {}

        while open_set:
            _, current = heapq.heappop(open_set)

            if current in g_cost and (forward_dir and current == to_node or not forward_dir and current == from_node):
                break

            for neighbor in get_neighbors(*current):
                if neighbor in g_cost:
                    if g_cost[neighbor] <= g_cost[current] + 1:
                        continue
                new_g = g_cost[current] + 1
                if neighbor not in g_cost or new_g < g_cost[neighbor]:
                    g_cost[neighbor] = new_g
                    h = heuristic(neighbor, to_node)
                    heapq.heappush(open_set, (new_g + h, neighbor))
                    parent[neighbor] = current
        return g_cost, parent

    forward_g, forward_parents = search(start, goal, forward_dir=True)
    backward_g, backward_parents = search(goal, start, forward_dir=False)

    def find_intersection():
        min_total = float('inf')
        intersection = None
        for node in forward_g:
            if node in backward_g:
                total_cost = forward_g[node] + backward_g[node]
                if total_cost < min_total:
                    min_total = total_cost
                    intersection = node
        return intersection, min_total

    intersect, min_total = find_intersection()
    if intersect is None:
        return []

    def build_path(start_node, end_node, parents):
        path = []
        current = end_node
        while current != start_node:
            path.append(current)
            current = parents[current]
        path.append(start_node)
        return path[::-1]

    forward_path = build_path(start, intersect, forward_parents)
    backward_path = build_path(goal, intersect, backward_parents)
    return forward_path + backward_path[1:]
