        neighbors = []
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                neighbors.append((nr, nc))
        return neighbors

    def heuristic_search(from_pos, to_pos):
        queue = []
        visited = set()
        parent = {}
        g = {}

        start_pos = from_pos
        heapq.heappush(queue, (manhattan(start_pos, to_pos), start_pos))
        g[start_pos] = 0

        while queue:
            f, current = heapq.heappop(queue)
            if current in visited:
                continue
            visited.add(current)
            for neighbor in get_neighbors(current):
                new_g = g[current] + 1
                if neighbor not in g or new_g < g[neighbor]:
                    g[neighbor] = new_g
                    parent[neighbor] = current
                    heapq.heappush(queue, (new_g + manhattan(neighbor, to_pos), neighbor))
            yield current, parent, g, f

    forward = heuristic_search(start, goal)
    backward = heuristic_search(goal, start)

    forward_closed = {}
    backward_closed = {}

    while True:
        try:
            current_f, parent_f, g_f, _ = next(forward)
            forward_closed[current_f] = parent_f
            if current_f in backward_closed:
                return build_path(start, current_f, parent_f, current_f, backward_closed, goal)
        except StopIteration:
            pass

        try:
            current_b, parent_b, g_b, _ = next(backward)
            backward_closed[current_b] = parent_b
            if current_b in forward_closed:
                return build_path(start, current_b, forward_closed, current_b, parent_b, goal)
        except StopIteration:
            pass

def build_path(start, meet, f_parent, meet, b_parent, goal):
    path = [meet]
    while path[-1] != start:
        path.append(f_parent[path[-1]])
    path.reverse()
    node = meet
    while node != goal:
        node = b_parent[node]
        path.append(node)
    return path
