import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start] if is_free(grid, start[0], start[1]) else []
    if not is_free(grid, start[0], start[1]) or not is_free(grid, goal[0], goal[1]):
        return []

    height = len(grid)
    width = len(grid[0])

    def neighbors(pos):
        r, c = pos
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:  # Up, Down, Left, Right
            nr, nc = r + dr, c + dc
            if 0 <= nr < height and 0 <= nc < width and grid[nr][nc] == '.':
                yield (nr, nc)

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def is_free(grid, r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def a_star(start, goal, forward=True):
        if forward:
            cost_func = lambda g, pos: g + manhattan(pos, goal)
        else:
            cost_func = lambda g, pos: g + manhattan(pos, start)

        def search(from_pos, to_pos):
            heap = [(cost_func(0, from_pos), 0, from_pos)]
            visited = {from_pos: 0}
            parent = {}

            while heap:
                f, g, pos = heapq.heappop(heap)
                if pos == to_pos:
                    return g, parent, visited
                if pos in visited and visited[pos] < g:
                    continue
                for n in neighbors(pos):
                    new_g = g + 1
                    if n not in visited or new_g < visited[n]:
                        visited[n] = new_g
                        heapq.heappush(heap, (cost_func(new_g, n), new_g, n))
                        parent[n] = pos
            return float('inf'), {}, visited

        g, parents, visited = search(start, goal)
        return g, parents, visited

    forward_g, forward_parent, forward_visited = a_star(start, goal, True)
    if forward_g < float('inf'):
        return reconstruct_path(start, goal, forward_parent)

    backward_g, backward_parent, backward_visited = a_star(goal, start, False)
    if backward_g < float('inf'):
        return reconstruct_path(start, goal, backward_parent)

    # Bidirectional search
    forward_heap = [(manhattan(start, goal), 0, start)]
    backward_heap = [(manhattan(goal, start), 0, goal)]
    forward_visited = {start: 0}
    backward_visited = {goal: 0}
    forward_parent = {}
    backward_parent = {}
    best_f = float('inf')
    best_meet_cost = float('inf')
    meeting_point = None

    while forward_heap and backward_heap and forward_heap[0][0] + backward_heap[0][0] < best_meet_cost:
        dir = len(forward_heap) < len(backward_heap)
        if dir:
            # Expand forward
            f, g, pos = heapq.heappop(forward_heap)
            if f >= best_f:
                continue
            if pos in backward_visited:
                meet_cost = g + backward_visited[pos]
                if meet_cost < best_meet_cost:
                    best_meet_cost = meet_cost
                    meeting_point = pos
            if g > forward_visited[pos]:
                continue
            for n in neighbors(pos):
                if n not in forward_visited or forward_visited[n] > g + 1:
                    new_g = g + 1
                    forward_visited[n] = new_g
                    forward_parent[n] = pos
                    heapq.heappush(forward_heap, (new_g + manhattan(n, goal), new_g, n))
        else:
            # Expand backward
            f, g, pos = heapq.heappop(backward_heap)
            if f >= best_f:
                continue
            if pos in forward_visited:
                meet_cost = g + forward_visited[pos]
                if meet_cost < best_meet_cost:
                    best_meet_cost = meet_cost
                    meeting_point = pos
            if g > backward_visited[pos]:
                continue
            for n in neighbors(pos):
                if n not in backward_visited or backward_visited[n] > g + 1:
                    new_g = g + 1
                    backward_visited[n] = new_g
                    backward_parent[n] = pos
                    heapq.heappush(backward_heap, (new_g + manhattan(n, start), new_g, n))

        for p in forward_visited:
            if p in backward_visited:
                cost = forward_visited[p] + backward_visited[p]
                if cost < best_meet_cost:
                    best_meet_cost = cost
                    meeting_point = p

        if best_meet_cost < float('inf'):
            best_f = best_meet_cost

    if meeting_point is None:
        return []

    # Reconstruct path
    part1 = []
    curr = meeting_point
    while curr != start:
        part1.append(curr)
        curr = forward_parent[curr]
    part1.reverse()
    path = [start] + part1

    curr = meeting_point
    while curr != goal:
        curr = backward_parent[curr]
        path.append(curr)
    path.append(goal)

    return path

def reconstruct_path(start, goal, parent):
    path = [goal]
    curr = goal
    while curr != start:
        curr = parent.get(curr)
        if curr is None:
            return []
        path.append(curr)
    path.reverse()
    return path
