        if dr == 0 or dc == 0:
            if (dr != 0 and (not is_free(grid, row + 1, col) or not is_free(grid, row - 1, col))) or \
               (dc != 0 and (not is_free(grid, row, col + 1) or not is_free(grid, row, col - 1))):
                return (row, col)
