            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                yield (nr, nc)

    # Forward search
    open_f = [(heuristic(start, goal), 0, start)]
    came_from_f = {}
    cost_f = {start: 0}

    # Backward search
    open_b = [(heuristic(goal, start), 0, goal)]
    came_from_b = {}
    cost_b = {goal: 0}

    def expand(heap, came_from, cost, target_cost, target, other_cost):
        if not heap:
            return None
        _, g, u = heapq.heappop(heap)
        for v in neighbors(u):
            if v not in cost or g + 1 < cost[v]:
                cost[v] = g + 1
                f = g + 1 + heuristic(v, target)
                heapq.heappush(heap, (f, g + 1, v))
                came_from[v] = u
            if v in other_cost:
                return g + 1 + other_cost[v]
        return None

    meet_cost = float('inf')
    meet_at = None
    while open_f and open_b and open_f[0][0] < meet_cost and open_b[0][0] < meet_cost:
        # Forward expansion
        new_cost = expand(open_f, came_from_f, cost_f, cost_b, goal, cost_b)
        if new_cost is not None and new_cost < meet_cost:
            meet_cost = new_cost
            meet_at = [k for k in cost_f if k in cost_b and cost_f[k] + cost_b[k] == meet_cost][0]
        if open_f and open_b and open_f[0][0] >= meet_cost and open_b[0][0] >= meet_cost:
            break
        # Backward expansion
        new_cost = expand(open_b, came_from_b, cost_b, cost_f, start, cost_f)
