            meet_cost = new_cost
            meet_at = [k for k in cost_f if k in cost_b and cost_f[k] + cost_b[k] == meet_cost][0]
        if open_f[0][0] >= meet_cost and open_b[0][0] >= meet_cost:
            break

    if meet_at is None:
        return []

    # Reconstruct path
    path = []
    curr = meet_at
    while curr in came_from_f:
        path.append(curr)
        curr = came_from_f[curr]
    path.reverse()
    curr = meet_at
    while curr != goal:
        path.append(curr)
        curr = came_from_b[curr]
    if path[0] == start and path[-1] == goal:
