import heapq

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    def in_bounds(pos):
        r, c = pos
        return 0 <= r < rows and 0 <= c < cols

    def is_free(pos):
        r, c = pos
        return in_bounds(pos) and grid[r][c] == '.'

    def manhattan(p1, p2):
        r1, c1 = p1
        r2, c2 = p2
        return abs(r1 - r2) + abs(c1 - c2)

    def horizontal_jump(pos, dir_r, dir_c, parent):
        r, c = pos
        while True:
            next_pos = (r + dir_r, c + dir_c)
            if not in_bounds(next_pos):
                return None
            next_r, next_c = next_pos
            if grid[next_r][next_c] == '#':
                return None
            # Check if next is goal
            if next_pos == goal:
                return next_pos
            # Check forced vertical neighbor
            up = (next_r - 1, next_c)
            down = (next_r + 1, next_c)
            if not is_free((next_r - parent[0], next_c - parent[1])) and (
                (up != parent and in_bounds(up) and grid[next_r - 1][next_c] == '#') or
                (down != parent and in_bounds(down) and grid[next_r + 1][next_c] == '#')):
                return next_pos
            r, c = next_pos

    def vertical_jump(pos, dir_r, dir_c, parent):
        r, c = pos
        while True:
            next_pos = (r + dir_r, c + dir_c)
            if not in_bounds(next_pos):
                return None
            next_r, next_c = next_pos
            if grid[next_r][next_c] == '#':
                return None
            # Check if next is goal
            if next_pos == goal:
                return next_pos
            # Check horizontal jump from next
            left = horizontal_jump(next_pos, 0, -1, parent)
            right = horizontal_jump(next_pos, 0, 1, parent)
            if left or right:
                return next_pos
            r, c = next_pos

    def reconstruct_path(came_from, current):
        path = [current]
        while current in came_from:
            current = came_from[current]
            path.insert(0, current)
        return path

    if start == goal and is_free(start):
        return [start]
    if not is_free(start) or not is_free(goal):
        return []

    open_set = []
    heapq.heappush(open_set, (manhattan(start, goal), start))
    came_from = {}
    g = {start: 0}

    while open_set:
        _, current = heapq.heappop(open_set)
        if current == goal:
            return reconstruct_path(came_from, current)

        # Directions: up, down, left, right
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for dr, dc in directions:
            # Determine parent direction for jump
            parent_dir = (-dr, -dc)
            if dr == 0:
                # Horizontal jump
                jp = horizontal_jump(current, dr, dc, parent_dir)
            else:
                # Vertical jump
                jp = vertical_jump(current, dr, dc, parent_dir)
            if jp:
                new_cost = g[current] + 1
                if jp not in g or new_cost < g[jp]:
                    g[jp] = new_cost
                    f = new_cost + manhattan(jp, goal)
                    heapq.heappush(open_set, (f, jp))
                    came_from[jp] = current

    return []
