        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def horizontal_jump(r, c, direction, parent):
        if not is_valid(r, c):
            return None
        if (r, c) == goal:
            return (r, c)
        dr = 0
        dc = 1 if direction == 'right' else -1
        steps = 1

        while True:
            r += dr
            c += dc
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            has_forced = False
            for dr2 in (-1, 1):
                if 0 <= r + dr2 < rows and is_valid(r + dr2, c) and not is_valid(r, c - dc):
                    has_forced = True
                    break
            if has_forced:
                return (r, c), steps
            steps += 1

    def vertical_jump(r, c, direction, parent):
        if not is_valid(r, c):
            return None
        if (r, c) == goal:
            return (r, c)
        dr = 1 if direction == 'down' else -1
        dc = 0
        steps = 1

        while True:
            r += dr
            c += dc
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            # Check if any horizontal jump returns a jump point
            j_right = horizontal_jump(r, c, 'right', (r, c))
            if j_right and j_right[0]:
                return (r, c), steps
            j_left = horizontal_jump(r, c, 'left', (r, c))
            if j_left and j_left[0]:
                return (r, c), steps
            steps += 1

    def heuristic(r, c):
        return abs(r - goal[0]) + abs(c - goal[1])

    def neighbors(r, c):
        points = []
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            jump = horizontal_jump if dc != 0 else vertical_jump
            result = jump(r, c, 'right' if dc > 0 else 'left' if dc < 0 else 'down' if dr > 0 else 'up', (r, c))
            if result and result[0]:
                jump_point, step_count = result
                if is_valid(*jump_point):
                    points.append((jump_point, step_count))
        return points

    came_from = {}
    g_score = {start: 0}
    open_set = [(0 + heuristic(*start), start, g_score[start])]

    while open_set:
        _, current, current_g = heapq.heappop(open_set)
        if current == goal:
            break
        for neighbor, step in neighbors(*current):
            tentative_g = g_score[current] + step
            if neighbor not in g_score or tentative_g < g_score[neighbor]:
                g_score[neighbor] = tentative_g
                f = tentative_g + heuristic(*neighbor)
                heapq.heappush(open_set, (f, neighbor, tentative_g))
                came_from[neighbor] = current

    if goal not in came_from:
        return []

    path = [goal]
    while path[-1] != start:
        path.append(came_from[path[-1]])
    path.reverse()
    return path
