        while is_valid(r, c + step):
            c += step
            for dr in [-1, 1]:
                if is_valid(r + dr, c) and not is_valid(r + dr, c - step):
                    return (r, c)
            if (r, c) == goal:
                return (r, c)
        return None

    def vertical_jump(r, c, dirc):
        step = 1 if dirc == 'down' else -1
        while is_valid(r + step, c):
            r += step
            if (r, c) == goal:
                return (r, c)
            for dc in [-1, 1]:
                res = horizontal_jump(r, c, 'right' if dc == 1 else 'left')
                if res:
                    return (r, c)
        return None

    def heuristic(r, c):
        return abs(r - goal[0]) + abs(c - goal[1])

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    heap = [(heuristic(start[0], start[1]), 0, start, None)]
    visited = set()
    parent_map = {}
    g_values = {start: 0}

    while heap:
        f, g, curr, parent = heapq.heappop(heap)
        if curr in visited:
            continue
        visited.add(curr)
        parent_map[curr] = parent
        if curr == goal:
            break

        for direction in ['left', 'right', 'up', 'down']:
            if direction == 'left' or direction == 'right':
                step = -1 if direction == 'left' else 1
                new_r, new_c = curr[0], curr[1] + step
                if is_valid(new_r, new_c):
                    jump_point = horizontal_jump(new_r, new_c, direction)
            else:
                step = -1 if direction == 'up' else 1
                new_r, new_c = curr[0] + step, curr[1]
                if is_valid(new_r, new_c):
                    jump_point = vertical_jump(new_r, new_c, direction)
            if jump_point and jump_point not in g_values:
                new_g = g + 1
                while curr != jump_point:
                    if curr == None or curr not in parent_map or parent_map[curr] != curr:
                        break
                    curr = parent_map[curr]
                else:
                    g_values[jump_point] = new_g
                    heapq.heappush(heap, (new_g + heuristic(jump_point[0], jump_point[1]), new_g, jump_point, curr))

    if goal not in parent_map:
        return []

    path = []
    curr = goal
    while curr is not None:
        path.append(curr)
        curr = parent_map[curr]
    path.reverse()

    # Interpolate straight cells between jump points
    full_path = []
    for i in range(len(path) - 1):
        start_r, start_c = path[i]
        end_r, end_c = path[i + 1]
        dr = end_r - start_r
        dc = end_c - start_c
        if dr != 0:
            step = 1 if dr > 0 else -1
            for r in range(start_r, end_r, step):
                full_path.append((r, start_c))
        if dc != 0:
            step = 1 if dc > 0 else -1
            for c in range(start_c, end_c, step):
                full_path.append((end_r, c))
        full_path.append((end_r, end_c))

    full_path.remove(path[0])
    full_path.insert(0, path[0])
    return full_path if path[0] == start else []
