import heapq

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0])
    if not (0 <= start[0] < rows and 0 <= start[1] < cols and 0 <= goal[0] < rows and 0 <= goal[1] < cols):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def jump_horizontal(pos, d):
        r, c = pos
        dr, dc = 0, 1 if d == 'right' else 0, -1
        while True:
            c += dc
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return r, c
            if dc == 1 and (is_valid(r - 1, c) and not is_valid(r - 1, c - 1) or
                            is_valid(r + 1, c) and not is_valid(r + 1, c - 1)):
                return r, c
            if dc == -1 and (is_valid(r - 1, c) and not is_valid(r - 1, c + 1) or
                             is_valid(r + 1, c) and not is_valid(r + 1, c + 1)):
                return r, c
            c -= dc

    def jump_vertical(pos, d):
        r, c = pos
        dr, dc = 1 if d == 'down' else -1, 0
        while True:
            r += dr
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return r, c
            left = (r, c - 1) if is_valid(r, c - 1) and not is_valid(r, c - 2) else None
            right = (r, c + 1) if is_valid(r, c + 1) and not is_valid(r, c + 2) else None
            if left or right:
                return r, c
            r -= dr

    def get_neighbors(pos):
        neighbors = []
        r, c = pos
        for dr, dc, direction, jump_func in [(0, 1, 'right', jump_horizontal),
                                             (0, -1, 'left', jump_horizontal),
                                             (1, 0, 'down', jump_vertical),
                                             (-1, 0, 'up', jump_vertical)]:
            new_pos = (r + dr, c + dc)
            if is_valid(new_pos[0], new_pos[1]):
                jump_pos = jump_func(new_pos, direction)
                if jump_pos and (jump_pos == goal or jump_pos != new_pos):
                    neighbors.append(jump_pos)
        return neighbors

    heap = [(manhattan(start, goal), 0, start, None)]
    visited = set()

    parent = {}
    g_scores = {start: 0}

    while heap:
        f, g, pos, prev = heapq.heappop(heap)
        if pos in visited:
            continue
        visited.add(pos)
        if pos == goal:
            return reconstruct_path(start, goal, parent)
        for neighbor in get_neighbors(pos):
            new_g = g + manhattan(pos, neighbor)
            if neighbor not in visited and is_valid(neighbor[0], neighbor[1]):
                parent[neighbor] = pos
                g_scores[neighbor] = new_g
                heapq.heappush(heap, (new_g + manhattan(neighbor, goal), new_g, neighbor, pos))

    return []

def reconstruct_path(start, goal, parent):
    if goal not in parent:
        return []
    path = []
    current = goal
    while current != start:
        path.append(current)
        current = parent[current]
    path.append(start)
    return path[::-1]
