from typing import List, Tuple, Dict, Set, Optional

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    def manhattan(a: Tuple[int, int], b: Tuple[int, int]) -> int:
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def is_valid(pos: Tuple[int, int]) -> bool:
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def search():
        nonlocal forward_g, backward_g, forward_heap, backward_heap

        if forward_heap:
            f_f, f_pos = heapq.heappop(forward_heap)
            if f_pos in backward_g:
                return f_pos
            if f_pos in forward_g:
                return None
            forward_g[f_pos] = f_f - manhattan(f_pos, goal)
            forward_parent[f_pos] = None
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                next_r, next_c = f_pos[0] + dr, f_pos[1] + dc
                next_pos = (next_r, next_c)
                if is_valid(next_pos) and next_pos not in forward_g:
                    new_g = forward_g[f_pos] + 1
                    h = manhattan(next_pos, goal)
                    f = new_g + h
                    heapq.heappush(forward_heap, (f, next_pos))
                    forward_g[next_pos] = new_g
                    forward_parent[next_pos] = f_pos
        if backward_heap:
            b_f, b_pos = heapq.heappop(backward_heap)
            if b_pos in forward_g:
                return b_pos
            if b_pos in backward_g:
                return None
            backward_g[b_pos] = b_f - manhattan(b_pos, start)
            backward_parent[b_pos] = None
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                next_r, next_c = b_pos[0] + dr, b_pos[1] + dc
                next_pos = (next_r, next_c)
                if is_valid(next_pos) and next_pos not in backward_g:
                    new_g = backward_g[b_pos] + 1
                    h = manhattan(next_pos, start)
                    f = new_g + h
                    heapq.heappush(backward_heap, (f, next_pos))
                    backward_g[next_pos] = new_g
                    backward_parent[next_pos] = b_pos
        if forward_heap and backward_heap:
            min_f = min(forward_heap[0][0], backward_heap[0][0])
            min_meeting_cost = float('inf')
            for pos in forward_g:
                if pos in backward_g:
                    cost = forward_g[pos] + backward_g[pos]
                    min_meeting_cost = min(min_meeting_cost, cost)
            if min_f >= min_meeting_cost:
                return None
        return None

    def build_path(meet_point: Tuple[int, int]) -> Optional[List[Tuple[int, int]]]:
        forward_path = []
        pos = meet_point
        while pos != start:
            forward_path.append(pos)
            pos = forward_parent[pos]
        forward_path.append(start)
        forward_path.reverse()

        backward_path = []
        pos = meet_point
        while pos != goal:
            backward_path.append(pos)
            pos = backward_parent[pos]
        backward_path.append(goal)

        return forward_path + backward_path

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    forward_g: Dict[Tuple[int, int], int] = {}
    backward_g: Dict[Tuple[int, int], int] = {}
    forward_parent: Dict[Tuple[int, int], Optional[Tuple[int, int]]] = {}
    backward_parent: Dict[Tuple[int, int], Optional[Tuple[int, int]]] = {}
    forward_heap = [(manhattan(start, goal), start)]
    backward_heap = [(manhattan(goal, start), goal)]

    while forward_heap and backward_heap:
        meeting = search()
        if meeting is None:
            return []
        elif meeting in forward_g:
            return build_path(meeting)

    return []
