            for nr, nc in [(1, 0), (-1, 0)]:
                if is_free(r + nr, c + nc) and not is_free(r + nr - dr, c + nc - dc):
                    return (r, c)
            if (r, c) == goal:
                return (r, c)

    def jump_vertical(r, c, dr, dc):
        while True:
            r += dr
            c += dc
            if not is_free(r, c):
                return None
            for ndc in [-1, 1]:
                if jump_horizontal(r, c, 0, ndc) is not None:
                    return (r, c)
            if (r, c) == goal:
                return (r, c)

    while open_set:
        f, g, current = heapq.heappop(open_set)
        if current in visited:
