        if current == goal:
            path = [current]
            while current in came_from:
                current = came_from[current]
                path.append(current)
            return path[::-1]
        visited.add(current)

        for dir_dr, dir_dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            new_r, new_c = current[0] + dir_dr, current[1] + dir_dc
            if is_free(new_r, new_c):
                if dir_dc == 0:
                    jumped = jump_vertical(current[0], current[1], dir_dr, dir_dc)
                else:
                    jumped = jump_horizontal(current[0], current[1], dir_dr, dir_dc)
                if jumped:
                    new_g = g + distance(current, jumped)
                    if jumped not in g_score or new_g < g_score[jumped]:
                        g_score[jumped] = new_g
                        came_from[jumped] = current
                        heapq.heappush(open_set, (new_g + manhattan(jumped, goal), new_g, jumped))

