import heapq

def solve(grid, start, goal):
    if not grid or not grid[0]:
        return []
    if start == goal:
        if grid[start[0]][start[1]] == '.':
            return [start]
        else:
            return []
    if not is_free(grid, *start) or not is_free(grid, *goal):
        return []

    rows, cols = len(grid), len(grid[0])

    def is_free(grid, r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def manhattan(r1, c1, r2, c2):
        return abs(r1 - r2) + abs(c1 - c2)

    directions = {
        'left': (0, -1),
        'right': (0, 1),
        'up': (-1, 0),
        'down': (1, 0)
    }

    def is_goal(r, c):
        return (r, c) == goal

    def jump_horizontal(r, c, dy):
        dr, dc = (0, dy)
        while True:
            c += dc
            if not is_free(grid, r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            if (is_free(grid, r - 1, c) and not is_free(grid, r - 1, c - dc)) or \
               (is_free(grid, r + 1, c) and not is_free(grid, r + 1, c - dc)):
                return (r, c)
            if c == start[1] and r == start[0]:
                return None

    def jump_vertical(r, c, dx):
        dr, dc = (dx, 0)
        while True:
            r += dr
            if not is_free(grid, r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            for d in [-1, 1]:
                if is_free(grid, r, c + d) and not is_free(grid, r - dr, c + d):
                    return (r, c)
            if r == start[0] and c == start[1]:
                return None

    def neighbors(r, c, parent):
        for direction, (dr, dc) in directions.items():
            if (dr == 0 and dc == -1 and parent not in [(r, c + 1), (r, c - 1)]):
                jump = jump_horizontal(r, c, dc)
                if jump:
                    yield jump
            elif (dr == 0 and dc == 1 and parent not in [(r, c + 1), (r, c - 1)]):
                jump = jump_horizontal(r, c, dc)
                if jump:
                    yield jump
            elif (dr == -1 and dc == 0 and parent not in [(r + 1, c), (r - 1, c)]):
                jump = jump_vertical(r, c, dr)
                if jump:
                    yield jump
            elif (dr == 1 and dc == 0 and parent not in [(r + 1, c), (r - 1, c)]):
                jump = jump_vertical(r, c, dr)
                if jump:
                    yield jump

    visited = set()
    parent_map = {}
    heap = []
    heapq.heappush(heap, (manhattan(*start, *goal), 0, start, None))
    found = False
    goal_node = None

    while heap:
        _, g, (r, c), parent = heapq.heappop(heap)
        if (r, c) == goal:
            found = True
            goal_node = (r, c, parent)
            break
        if (r, c) in visited:
            continue
        visited.add((r, c))
        for jump_point in neighbors(r, c, parent):
            if jump_point is None:
                continue
            nr, nc = jump_point
            if (nr, nc) not in visited:
                parent_map[(nr, nc)] = (r, c)
                new_g = g + abs(r - nr) + abs(c - nc)
                h = manhattan(nr, nc, *goal)
                f = new_g + h
                heapq.heappush(heap, (f, new_g, (nr, nc), (r, c)))

    if not found:
        return []

    path = []
    curr = goal_node
    while curr:
        path.append(curr[0])
        curr = parent_map.get(curr[0], None)
    path.reverse()

    def fill_path(from_point, to_point):
        r1, c1 = from_point
        r2, c2 = to_point
        if r1 == r2:
            for c in range(min(c1, c2), max(c1, c2) + 1):
                if not (r1, c1) == (r1, c) and not (r1, c) == (r1, c2):
                    yield (r1, c)
        else:
            for r in range(min(r1, r2), max(r1, r2) + 1):
                if not (r1, c1) == (r, c1) and not (r, c1) == (r2, c1):
                    yield (r, c1)

    full_path = [start]
    for i in range(1, len(path)):
        from_point = path[i - 1]
        to_point = path[i]
        for cell in fill_path(from_point, to_point):
            full_path.append(cell)
        full_path.append(to_point)

    return full_path if full_path[-1] == goal else []
