        for v in neighbors(u):
            if v not in cost or g_current + 1 < cost[v]:
                cost[v] = g_current + 1
                f = g_current + 1 + heuristic(v, target)
                heapq.heappush(heap, (f, g_current + 1, v))
                came_from[v] = u
