import heapq

def solve(grid, start, goal):
    if start == goal:
        # Check if cell is free
        if grid[start[0]][start[1]] == '.':
            return [start]
        else:
            return []

    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def heuristic_search(front, back, start, goal):
        g = {}
        heap = []
        path = {}

        pos = start
        cost = 0
        g[pos] = cost
        heapq.heappush(heap, (cost + manhattan(pos, goal), cost, pos))

        while heap:
            f, g_val, node = heapq.heappop(heap)
            if node in path:
                continue
            path[node] = None

            if node in back[1]:
                return node, path, back[1], back[2]

            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = node[0] + dr, node[1] + dc
                next_pos = (nr, nc)
                if is_valid(nr, nc) and next_pos not in g:
                    next_cost = g_val + 1
                    g[next_pos] = next_cost
                    heapq.heappush(heap, (next_cost + manhattan(next_pos, goal), next_cost, next_pos))
                    path[next_pos] = node

        return None, path, back[1], back[2]

    def reconstruct_path(path1, path2, meet):
        def build_path(p, start, end):
            res = []
            cur = end
            while cur is not None and cur in p:
                res.append(cur)
                cur = p[cur]
            if cur != start:
                return None
            return list(reversed(res))

        p1 = build_path(path1, start, meet)
        p2 = build_path(path2, goal, meet)

        if p1 is None or p2 is None:
            return None

        return p1[:-1] + list(reversed(p2))

    forward_data = {start: 0}
    backward_data = {goal: 0}
    forward_path = {start: None}
    backward_path = {goal: None}

    f_heap = [(0 + manhattan(start, goal), 0, start)]
    b_heap = [(0 + manhattan(goal, start), 0, goal)]

    best_meeting_cost = float('inf')
    best_path = None

    while f_heap and b_heap:
        f_cost = f_heap[0][0]
        b_cost = b_heap[0][0]
        combined_cost = f_cost + b_cost

        if combined_cost >= best_meeting_cost:
            break

        meeting, f_path, b_dict, b_cost_dict = heuristic_search((f_heap, forward_data), (b_dict, b_path, b_cost_dict), start, goal)
        if meeting:
            path = reconstruct_path(f_path, backward_path, meeting)
            if path and all(grid[cell[0]][cell[1]] == '.' for cell in path):
                return path
        else:
            meeting, b_path, f_dict, f_cost_dict = heuristic_search((b_heap, backward_data), (f_dict, f_path, f_cost_dict), goal, start)
            if meeting:
                path = reconstruct_path(backward_path, f_path, meeting)
                if path and all(grid[cell[0]][cell[1]] == '.' for cell in path):
                    return path

    return []
