        if 0 <= r < len(grid) and 0 <= c < len(grid[r]) and grid[r][c] == '.':
            return [start]
        else:
            return []
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])) or grid[start[0]][start[1]] == '#':
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])) or grid[goal[0]][goal[1]] == '#':
        return []

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def neighbors(pos):
        r, c = pos
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == '.':
                yield (nr, nc)

    def heuristic_search(start, goal, forward=True):
        heap = []
        heapq.heappush(heap, (manhattan(start, goal), start))
        g = {start: 0}
        parent = {}

        while heap:
            f, curr = heapq.heappop(heap)
            if forward:
                sides[0].append(curr)
                if curr in g_others[0]:
                    return curr
            else:
                sides[1].append(curr)
                if curr in g_others[1]:
                    return curr

            for next in neighbors(curr):
                cost = g[curr] + 1
                if next not in g or cost < g[next]:
                    g[next] = cost
                    heapq.heappush(heap, (cost + manhattan(next, goal), next))
                    parent[next] = curr

        return None

    def reconstruct_path(pos1, pos2, parent1, parent2):
        path = [pos1]
        while path[-1] != meeting:
            path.append(parent1[path[-1]])
        path.reverse()
        path2 = [pos2]
        while path2[-1] != meeting:
            path2.append(parent2[path2[-1]])
        path.reverse()
        return path + path2[1:]

    sides = [[start], [goal]]
    g1 = {start: 0}
    g2 = {goal: 0}
    parent1 = {start: None}
    parent2 = {goal: None}
    g_others = [{goal}, {start}]
    meeting = None

    for _ in range(10000):
        for i in [0, 1]:
            new_heap = []
            if i == 0:
                next_node = sides[0][-1]
                new = heuristic_search(next_node, goal, forward=True)
                g_others[0].update(g2)
                current_g = g1
                current_parent = parent1
            else:
                next_node = sides[1][-1]
                new = heuristic_search(next_node, start, forward=False)
                g_others[1].update(g1)
                current_g = g2
                current_parent = parent2

            if new is not None:
                meeting = new
                break

        if meeting is not None:
            path = reconstruct_path(start, goal, parent1, parent2)
            if all(0 <= cell[0] < len(grid) and 0 <= cell[1] < len(grid[0]) and grid[cell[0]][cell[1]] == '.' for cell in path):
                return path
            else:
                break

    return []
