    def is_free(grid, pos):
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[r]) and grid[r][c] == '.'

    def neighbors(pos):
        r, c = pos
        return [(nr, nc) for nr, nc in [(r-1,c), (r+1,c), (r,c-1), (r,c+1)] if is_free(grid, (nr, nc))]

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def a_star(start_pos, goal_pos):
        open_list = [(manhattan(start_pos, goal_pos), 0, start_pos)]
        heapq.heapify(open_list)
        came_from = {}
        g_cost = {start_pos: 0}

        while open_list:
            f, cost, current = heapq.heappop(open_list)
            if current == goal_pos:
                return g_cost[current], came_from

            for next_pos in neighbors(current):
                new_g = g_cost[current] + 1
                if next_pos not in g_cost or new_g < g_cost[next_pos]:
                    g_cost[next_pos] = new_g
                    heapq.heappush(open_list, (new_g + manhattan(next_pos, goal_pos), new_g, next_pos))
                    came_from[next_pos] = current
        return float('inf'), {}

    def reconstruct_path(came_from, start, goal):
        curr = goal
        path = []
        while curr != start:
            if curr not in came_from:
                return []
            path.append(curr)
            curr = came_from[curr]
        path.append(start)
        return path[::-1]

    def bidirectional_a_star(start_pos, goal_pos):
        g_start = {start_pos: 0}
        came_from_start = {start_pos: None}
        g_goal = {goal_pos: 0}
        came_from_goal = {goal_pos: None}

        open_start = [(manhattan(start_pos, goal_pos), 0, start_pos)]
        open_goal = [(manhattan(goal_pos, start_pos), 0, goal_pos)]

        while open_start and open_goal:
            f1, cost1, curr1 = heapq.heappop(open_start)
            if curr1 in g_goal:
                path1 = [curr1]
                while path1[0] != start_pos:
                    path1.insert(0, came_from_start[path1[0]])
                path2 = [curr1]
                while path2[-1] != goal_pos:
                    path2.append(came_from_goal[path2[-1]])
                return path1 + path2[1:]

            for next_pos in neighbors(curr1):
                new_g = g_start[curr1] + 1
                if next_pos not in g_start or new_g < g_start[next_pos]:
                    g_start[next_pos] = new_g
                    came_from_start[next_pos] = curr1
                    heapq.heappush(open_start, (new_g + manhattan(next_pos, goal_pos), new_g, next_pos))

            f2, cost2, curr2 = heapq.heappop(open_goal)
            if curr2 in g_start:
                path1 = [curr2]
                while path1[0] != start_pos:
                    path1.insert(0, came_from_start[path1[0]])
                path2 = [curr2]
                while path2[-1] != goal_pos:
                    path2.append(came_from_goal[path2[-1]])
                return path1 + path2[1:]

            for next_pos in neighbors(curr2):
                new_g = g_goal[curr2] + 1
                if next_pos not in g_goal or new_g < g_goal[next_pos]:
                    g_goal[next_pos] = new_g
                    came_from_goal[next_pos] = curr2
                    heapq.heappush(open_goal, (new_g + manhattan(next_pos, start_pos), new_g, next_pos))

            if f1 > g_goal[curr1] and f2 > g_start[curr2]:
                return []

    path = bidirectional_a_star(start, goal)
    return path if is_free(grid, start) and is_free(grid, goal) else []
