import heapq

def solve(grid, start, goal):
    if not grid or not grid[0]:
        return []
    rows, cols = len(grid), len(grid[0])

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def horizontal_jump(r, c, direction, parent):
        if not is_valid(r, c):
            return None
        if (r, c) == goal:
            return (r, c)
        dr = 0
        dc = 1 if direction == 'right' else -1
        steps = 1

        while True:
            r += dr
            c += dc
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            has_forced = False
            for dr2 in (-1, 1):
                nr, nc = r + dr2, c
                if is_valid(nr, nc) and not is_valid(r, c - dc):
                    has_forced = True
                    break
            if has_forced:
                return (r, c)
            steps += 1

    def vertical_jump(r, c, direction, parent):
        if not is_valid(r, c):
            return None
        if (r, c) == goal:
            return (r, c)
        dr = 1 if direction == 'down' else -1
        dc = 0
        steps = 1

        while True:
            r += dr
            c += dc
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            j_right = horizontal_jump(r, c, 'right', (r, c)) if is_valid(r, c + 1) else None
            if j_right is not None:
                return (r, c)
            j_left = horizontal_jump(r, c, 'left', (r, c)) if is_valid(r, c - 1) else None
            if j_left is not None:
                return (r, c)
            steps += 1

    def heuristic(r, c):
        return abs(r - goal[0]) + abs(c - goal[1])

    def neighbors(r, c):
        points = []
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            if dr == 0 and dc != 0:
                jump = horizontal_jump if dc > 0 else horizontal_jump
                direction = 'right' if dc > 0 else 'left'
                result = jump(r, c, direction, (r, c))
            else:
                jump = vertical_jump if dr > 0 else vertical_jump
                direction = 'down' if dr > 0 else 'up'
                result = jump(r, c, direction, (r, c))
            if result and result == goal:
                points.append((goal, 1))
            elif result is not None:
                points.append((result, 1))
        return points

    came_from = {}
    g_score = {start: 0}
    open_set = [(0 + heuristic(*start), start, g_score[start])]

    while open_set:
        _, current, current_g = heapq.heappop(open_set)
        if current == goal:
            break
        for neighbor, step in neighbors(*current):
            tentative_g = g_score[current] + step
            if neighbor not in g_score or tentative_g < g_score[neighbor]:
                g_score[neighbor] = tentative_g
                f = tentative_g + heuristic(*neighbor)
                heapq.heappush(open_set, (f, neighbor, tentative_g))
                came_from[neighbor] = current

    if goal not in came_from:
        return []

    path = [goal]
    while path[-1] != start:
        path.append(came_from[path[-1]])
    path.reverse()
    return path
