import heapq

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0])
    if not (0 <= start[0] < rows and 0 <= start[1] < cols and 0 <= goal[0] < rows and 0 <= goal[1] < cols):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def jump_horizontal(pos, direction):
        r, c = pos
        dc = 1 if direction == 'right' else -1
        while True:
            c += dc
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return r, c
            if grid[r - 1][c] == '#' or grid[r + 1][c] == '#':
                return r, c
            prev_is_wall = not is_valid(r, c - dc)
            if is_valid(r - 1, c) and not is_valid(r - 1, c - dc) and prev_is_wall:
                return r, c
            if is_valid(r + 1, c) and not is_valid(r + 1, c - dc) and prev_is_wall:
                return r, c

    def jump_vertical(pos, direction):
        r, c = pos
        dr = 1 if direction == 'down' else -1
        while True:
            r += dr
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return r, c
            if grid[r][c - 1] == '#' or grid[r][c + 1] == '#':
                return r, c
            prev_is_wall = not is_valid(r - dr, c)
            if is_valid(r, c - 1) and not is_valid(r - dr, c - 1) and prev_is_wall:
                return r, c
            if is_valid(r, c + 1) and not is_valid(r - dr, c + 1) and prev_is_wall:
                return r, c

    def get_neighbors(pos):
        r, c = pos
        neighbors = []
        for dr, dc, direction, jump_func in [(0, 1, 'right', jump_horizontal), 
                                             (0, -1, 'left', jump_horizontal),
                                             (1, 0, 'down', jump_vertical),
                                             (-1, 0, 'up', jump_vertical)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                jump_pos = jump_func((nr, nc), direction)
                if jump_pos:
                    neighbors.append(jump_pos)
        return neighbors

    def reconstruct_path(parent):
        path = []
        node = goal
        while node is not None:
            path.append(node)
            node = parent[node]
        return path[::-1]

    heap = [(manhattan(start, goal), 0, start, None)]
    visited = set()
    parent = {}
    g = {start: 0}

    while heap:
        f, cost, current, from_ = heapq.heappop(heap)
        if current == goal:
            return reconstruct_path(parent)
        if current in visited:
            continue
        visited.add(current)
        parent[current] = from_

        for next_ in get_neighbors(current):
            if not is_valid(next_[0], next_[1]):
                continue
            new_cost = cost + manhattan(current, next_)
            if next_ not in visited and (next_ not in g or new_cost < g[next_]):
                g[next_] = new_cost
                heapq.heappush(heap, (new_cost + manhattan(next_, goal), new_cost, next_, current))

    return []
