def solve(grid, start, goal):
    if start == goal:
        # Check if the cell is free
        if (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and grid[start[0]][start[1]] == '.'):
            return [start]
        else:
            return []

    rows = len(grid)
    cols = len(grid[0])

    if not (0 <= start[0] < rows and 0 <= start[1] < cols and grid[start[0]][start[1]] == '.'):
        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols and grid[goal[0]][goal[1]] == '.'):
        return []

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # Right, Down, Left, Up
    came_from = {}
    g_score = {start: 0}
    heap = [(manhattan(start, goal), 0, start, None)]

    def is_wall(r, c):
        return r < 0 or c < 0 or r >= rows or c >= cols or grid[r][c] == '#'

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def jump_horizontal(x, y, dx):
        while not is_wall(x, y):
            if (x, y) == goal:
                return (x, y)
            if (not is_wall(x + dx, y)):
                if not is_wall(x, y + 1) and is_wall(x + dx, y + 1):
                    return (x, y)
                elif not is_wall(x, y - 1) and is_wall(x + dx, y - 1):
                    return (x, y)
            x += dx
        return None

    def jump_vertical(x, y, dy):
        while not is_wall(x, y):
            if (x, y) == goal:
                return (x, y)
            if not is_wall(x + 1, y) and isinstance(jump_horizontal(x + 1, y, 1), tuple):
                return (x, y)
            if not is_wall(x - 1, y) and isinstance(jump_horizontal(x - 1, y, 1), tuple):
                return (x, y)
            if not is_wall(x + 1, y) and isinstance(jump_horizontal(x + 1, y, -1), tuple):
                return (x, y)
            if not is_wall(x - 1, y) and isinstance(jump_horizontal(x - 1, y, -1), tuple):
                return (x, y)
            x += dy
        return None

    def jump(x, y, dx, dy):
        while not is_wall(x, y):
            if (x, y) == goal:
                return (x, y)
            if dy == 0:
                next_point = jump_horizontal(x, y, dx)
            else:
                next_point = jump_vertical(x, y, dy)
            if next_point:
                return next_point
            x += dx
            y += dy
        return None

    while heap:
        f, g, current, parent = heapq.heappop(heap)
        if current in came_from:
            continue
        came_from[current] = parent
        if current == goal:
            break
        for dx, dy in directions:
            nx = current[0] + dx
            ny = current[1] + dy
            if not is_wall(nx, ny) and (nx, ny) not in came_from:
                jump_result = jump(nx, ny, dx, dy)
                if jump_result:
                    new_g = g_score[current] + abs(jump_result[0] - current[0]) + abs(jump_result[1] - current[1])
                    if jump_result not in g_score or new_g < g_score[jump_result]:
                        g_score[jump_result] = new_g
                        h = manhattan(jump_result, goal)
                        heapq.heappush(heap, (new_g + h, new_g, jump_result, current))

    if goal not in came_from:
        return []

    path = []
    current = goal
    while current:
        path.append(current)
        current = came_from.get(current)
    path.reverse()

    full_path = []
    for i in range(len(path) - 1):
        x1, y1 = path[i]
        x2, y2 = path[i + 1]
        dx = x2 - x1
        dy = y2 - y1

        if dx != 0:
            step = 1 if dx > 0 else -1
            for k in range(x1 + step, x2, step):
                full_path.append((k, y1))
        if dy != 0:
            step = 1 if dy > 0 else -1
            for k in range(y1 + step, y2, step):
                full_path.append((x1, k))
    full_path = [path[0]] + full_path + [path[-1]]

    final_path = []
    for p in full_path:
        if grid[p[0]][p[1]] == '.':
            final_path.append(p)
    return final_path
