import heapq

def solve(grid, start, goal):
    if not grid or not grid[0]:
        return []
    if start == goal:
        if grid[start[0]][start[1]] == '.':
            return [start]
        else:
            return []
    if not is_free(grid, *start) or not is_free(grid, *goal):
        return []

