    def is_free(grid, r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def manhattan(r1, c1, r2, c2):
        return abs(r1 - r2) + abs(c1 - c2)

    def is_goal(r, c):
        return (r, c) == goal

    def jump_horizontal(r, c, dc):
        while True:
            c += dc
            if not is_free(grid, r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            if (is_free(grid, r - 1, c) and not is_free(grid, r - 1, c - dc)) or \
               (is_free(grid, r + 1, c) and not is_free(grid, r + 1, c - dc)):
                return (r, c)

    def jump_vertical(r, c, dr):
        while True:
            r += dr
            if not is_free(grid, r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            for d in [-1, 1]:
                if is_free(grid, r, c + d) and not is_free(grid, r - dr, c + d):
                    return (r, c)

    directions = {
        'left': (0, -1),
        'right': (0, 1),
        'up': (-1, 0),
        'down': (1, 0)
    }

    def neighbors(r, c, pr, pc):
        for direction, (dr, dc) in directions.items():
            nr, nc = r + dr, c + dc
            if not (0 <= nr < rows and 0 <= nc < cols) or not is_free(grid, nr, nc):
                continue
            # Only search if this is a new direction or not directly backtracking
            if dr == 0:  # Horizontal
                if dc > 0:  # Right
                    if not (r == pr and c == pc and dc < 0):
                        jump = jump_horizontal(r, c, dc)
                        if jump:
                            yield jump
                else:  # Left
                    if not (r == pr and c == pc and dc > 0):
                        jump = jump_horizontal(r, c, dc)
                        if jump:
                            yield jump
            else:  # Vertical
                if dr > 0:  # Down
                    if not (r == pr and c == pc and dr < 0):
                        jump = jump_vertical(r, c, dr)
                        if jump:
                            yield jump
                else:  # Up
                    if not (r == pr and c == pc and dr > 0):
                        jump = jump_vertical(r, c, dr)
                        if jump:
                            yield jump

    visited = set()
    parent_map = {}
    heap = []
    heapq.heappush(heap, (manhattan(*start, *goal), 0, start, None))
    found = False

    while heap:
        _, g, (r, c), parent = heapq.heappop(heap)
        if (r, c) == goal:
            found = True
            break
        if (r, c) in visited:
            continue
        visited.add((r, c))
        if parent is not None:
            pr, pc = parent
        else:
            pr, pc = -1, -1  # Dummy out-of-bound parent
        for jump_point in neighbors(r, c, pr, pc):
            if jump_point is None:
                continue
            nr, nc = jump_point
            if (nr, nc) not in visited:
                parent_map[(nr, nc)] = (r, c)
                new_g = g + abs(nr - r) + abs(nc - c)
                h = manhattan(nr, nc, *goal)
                f = new_g + h
                heapq.heappush(heap, (f, new_g, (nr, nc), (r, c)))

    if not found:
        return []

    path = []
    curr = goal
    while curr is not None:
        path.append(curr)
        curr = parent_map.get(curr, None)
    path.reverse()

    full_path = [start]
    for i in range(1, len(path)):
        r1, c1 = path[i - 1]
        r2, c2 = path[i]
        if r1 == r2:
            for c in range(min(c1, c2), max(c1, c2) + 1):
                full_path.append((r1, c))
        else:
            for r in range(min(r1, r2), max(r1, r2) + 1):
                full_path.append((r, c1))
        full_path.pop()  # Removes the last point (already in path)

    return path if path[-1] == goal else []
