def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Check for invalid starting or ending points
    if grid[start[0]][start[1]] != '.' or grid[goal[0]][goal[1]] != '.':
        return []
    if start == goal:
        return [start]

    # Test if a location is within bounds and is walkable
    def is_open(x, y):
        return 0 <= x < rows and 0 <= y < cols and grid[x][y] == '.'

    # Jump in horizontal direction, stopping at boundaries or interesting junctions
    def go_horizontal(x, y, step):
        while True:
            y2 = y + step
            if not is_open(x, y2):
                return None
            if (x, y2) == goal:
                return (x, y2)
            if is_open(x + 1, y2) and not is_open(x + 1, y2 - step):
                return (x, y2)
            if is_open(x - 1, y2) and not is_open(x - 1, y2 - step):
                return (x, y2)
            y = y2

    # Jump in vertical direction, stopping at boundaries or if horizontal jump from there identifies something worth it
    def go_vertical(x, y, step):
        while True:
            x2 = x + step
            if not is_open(x2, y):
                return None
            if (x2, y) == goal:
                return (x2, y)
            if go_horizontal(x2, y, 1) is not None or go_horizontal(x2, y, -1) is not None:
                return (x2, y)
            x = x2

    # Heuristic to estimate distance to goal for A* search
    def estimate(x, y):
        return abs(x - goal[0]) + abs(y - goal[1])

    # A* setup
    priority = [(estimate(*start), 0, start)]
    cost_so_far = {start: 0}
    came_from = {start: None}
    visited = set()

    while priority:
        _, dist, current = heapq.heappop(priority)
        if current in visited:
            continue
        if current == goal:
            # Reconstruct the path from goal back to start
            path = []
            while current is not None:
                path.append(current)
                current = came_from[current]
            path.reverse()
            # Expand the path into each cell between jump points
            smooth_path = [path[0]]
            for i in range(1, len(path)):
                p1 = path[i - 1]
                p2 = path[i]
                while p1 != p2:
                    dx = 1 if p2[0] > p1[0] else -1 if p2[0] < p1[0] else 0
                    dy = 1 if p2[1] > p1[1] else -1 if p2[1] < p1[1] else 0
                    p1 = (p1[0] + dx, p1[1] + dy)
                    smooth_path.append(p1)
