def solve(grid, start, goal):
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def jump_right(r, c):
        while True:
            next_c = c + 1
            if not is_valid(r, next_c):
                return None
            if (r, next_c) == goal:
                return (r, next_c)
            if (is_valid(r - 1, next_c) and not is_valid(r - 1, c)) or \
               (is_valid(r + 1, next_c) and not is_valid(r + 1, c)):
                return (r, next_c)
            c = next_c

    def jump_left(r, c):
        while True:
            next_c = c - 1
            if not is_valid(r, next_c):
                return None
            if (r, next_c) == goal:
                return (r, next_c)
            if (is_valid(r - 1, next_c) and not is_valid(r - 1, c)) or \
               (is_valid(r + 1, next_c) and not is_valid(r + 1, c)):
                return (r, next_c)
            c = next_c

    def jump_down(r, c):
        while True:
            next_r = r + 1
            if not is_valid(next_r, c):
                return None
            if (next_r, c) == goal:
                return (next_r, c)
            left = jump_left(next_r, c)
            right = jump_right(next_r, c)
            if left is not None or right is not None:
                return (next_r, c)
            r = next_r

    def jump_up(r, c):
        while True:
            next_r = r - 1
            if not is_valid(next_r, c):
                return None
            if (next_r, c) == goal:
                return (next_r, c)
            left = jump_left(next_r, c)
            right = jump_right(next_r, c)
            if left is not None or right is not None:
                return (next_r, c)
            r = next_r

    def heuristic(pos):
        return abs(pos[0] - goal[0]) + abs(pos[1] - goal[1])

    priority = [(heuristic(start), 0, start)]
    heapq.heapify(priority)
    best_cost = {start: 0}
    trace = {start: None}
    visited = set()

    while priority:
        f, g, pos = heapq.heappop(priority)
        if pos in visited:
            continue
        if pos == goal:
            path = []
            current = pos
            while current:
                path.append(current)
                current = trace[current]
            path.reverse()
            expanded = [path[0]]
            for i in range(1, len(path)):
                x, y = path[i - 1]
                tx, ty = path[i]
                while x != tx or y != ty:
                    if tx > x:
                        x += 1
                    elif tx < x:
                        x -= 1
                    if ty > y:
                        y += 1
                    elif ty < y:
                        y -= 1
                    expanded.append((x, y))
            return expanded

        visited.add(pos)
        r, c = pos
        steps = [jump_right(r, c), jump_left(r, c), jump_down(r, c), jump_up(r, c)]
        for neighbor in steps:
            if not neighbor or neighbor in visited:
                continue
            new_g = g + 1
            if neighbor not in best_cost or best_cost[neighbor] > new_g:
