import heapq


def solve(grid, start, goal):
    # Adaptation of Jump Point Search for 4-connected grids, focusing on performance
    # by leveraging directional information to prune unnecessary node expansions.
    rows, cols = len(grid), len(grid[0])
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    def is_open(r, c):
        # Check if a given cell is within bounds and unblocked
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def extend_right(r, c):
        # Extend rightward as long as we can
        while True:
            next_c = c + 1
            if not is_open(r, next_c):
                break
            if (r, next_c) == goal:
                return (r, next_c)
            if any(is_open(r + dr, next_c) and not is_open(r + dr, c) for dr in (-1, 1)):
                return (r, next_c)
            c = next_c
        return None

    def extend_left(r, c):
        # Extend leftward as long as we can
        while True:
            next_c = c - 1
            if not is_open(r, next_c):
                break
            if (r, next_c) == goal:
                return (r, next_c)
            if any(is_open(r + dr, next_c) and not is_open(r + dr, c) for dr in (-1, 1)):
                return (r, next_c)
            c = next_c
        return None

    def extend_down(r, c):
        # Extend downward as long as we can
        while True:
            next_r = r + 1
            if not is_open(next_r, c):
                break
            if (next_r, c) == goal:
                return (next_r, c)
            right = extend_right(next_r, c)
            left = extend_left(next_r, c)
            if right is not None or left is not None:
                return (next_r, c)
            r = next_r
        return None

    def extend_up(r, c):
        # Extend upward as long as we can
        while True:
            next_r = r - 1
            if not is_open(next_r, c):
                break
            if (next_r, c) == goal:
                return (next_r, c)
            right = extend_right(next_r, c)
            left = extend_left(next_r, c)
            if right is not None or left is not None:
                return (next_r, c)
            r = next_r
        return None

    def heuristic(cell):
        # Manhattan distance to the goal
        return abs(cell[0] - goal[0]) + abs(cell[1] - goal[1])

    priority_queue = [(heuristic(start), 0, start)]
    best_cost = {start: 0}
    predecessors = {start: None}
    visited = set()

    while priority_queue:
        f, g, point = heapq.heappop(priority_queue)
        if point in visited:
            continue
        if point == goal:
            # Reconstruct the path from start to goal
            path = []
            while point is not None:
                path.append(point)
                point = predecessors[point]
            path.reverse()
            output_path = [path[0]]
            # Expand jumps into individual steps
            for i in range(1, len(path)):
                px, py = path[i - 1]
                nx, ny = path[i]
                while (px, py) != (nx, ny):
                    if nx > px:
                        px += 1
                    elif nx < px:
                        px -= 1
                    elif ny > py:
                        py += 1
                    elif ny < py:
                        py -= 1
                    output_path.append((px, py))
            return output_path
        visited.add(point)
        x, y = point
        neighbors = []
        if jump := extend_right(x, y):
            neighbors.append(jump)
        if jump := extend_left(x, y):
            neighbors.append(jump)
        if jump := extend_down(x, y):
            neighbors.append(jump)
        if jump := extend_up(x, y):
            neighbors.append(jump)
        for nx, ny in neighbors:
            if nx is None or (nx, ny) in visited:
                continue
            new_cost = g + abs(nx - x) + abs(ny - y)
            if new_cost < best_cost.get((nx, ny), float('inf')):
                best_cost[(nx, ny)] = new_cost
                predecessors[(nx, ny)] = point
                heapq.heappush(priority_queue, (new_cost + heuristic((nx, ny)), new_cost, (nx, ny)))
    return []
