import heapq


def solve(grid, start, goal):
    """Jump point search for 4-connected grids. This implementation finds a valid path from start to goal using
    a best-first search approach (A* variant), with heuristic-based path expansion and pruning using jump point
    identification to reduce node exploration. The returned path is from start to goal, with each step being a
    direct orthogonal move (up, down, left, right)."""

    rows, cols = len(grid), len(grid[0])
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    def is_valid(r, c):
        """Check if a cell (r, c) is in bounds and is a free space in the grid."""
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def horizontal_identify(x, y, step_x):
        """Perform a horizontal jump from (x, y), in direction step_x (1 for right, -1 for left). Stopping conditions:
        if the end is a wall, or if any diagonal neighbor is blocked and adjacent one is free (indicative of a
        potential detour that needs to be explored)."""
        while True:
            y_new = y + step_x
            if not is_valid(x, y_new):
                return None
            if (x, y_new) == goal:
                return (x, y_new)
            # Check for any vertical neighbors that create forced moves
            if is_valid(x - 1, y_new) and not is_valid(x - 1, y):
                return (x, y_new)
            if is_valid(x + 1, y_new) and not is_valid(x + 1, y):
                return (x, y_new)
            y, y_new = y_new, y_new + step_x  # Move one step further to continue the jump

    def vertical_identify(x, y, step_x):
        """Perform a vertical jump from (x, y), in direction step_x (1 for down, -1 for up). Stopping conditions:
        if any horizontal jump identifies a forced move in x direction at the newly found point, implying a
        jump point. This helps reduce exploration while ensuring correctness."""
        while True:
            x_new = x + step_x
            if not is_valid(x_new, y):
                return None
            if (x_new, y) == goal:
                return (x_new, y)
            # If either horizontal jump around the current cell returns a valid point, we stop
            if horizontal_identify(x_new, y, 1) is not None or horizontal_identify(x_new, y, -1) is not None:
                return (x_new, y)
            x, x_new = x_new, x_new + step_x

    def heur(pos):
        """Manhattan distance from current cell to goal. Used to guide the search."""
        return abs(pos[0] - goal[0]) + abs(pos[1] - goal[1])

    frontier = [(heur(start), 0, start)]  # (f_score, g_score, cell)
    best_cost = {start: 0}
    predecessors = {start: None}
    final_set = set()

    while frontier:
        _, current_cost, current = heapq.heappop(frontier)
        if current in final_set:
            continue
        if current == goal:
            # Reconstruct the path from goal back to start
            reconstructed = []
            while current is not None:
                reconstructed.append(current)
                current = predecessors[current]
            reconstructed.reverse()

            expanded_path = [reconstructed[0]]
            for i in range(len(reconstructed) - 1):
                path_x, path_y = reconstructed[i]
                dest_x, dest_y = reconstructed[i + 1]
                # Fill in intermediate steps between each node in the path
                while (path_x, path_y) != (dest_x, dest_y):
                    path_x += 1 if dest_x > path_x else -1 if dest_x < path_x else 0
                    path_y += 1 if dest_y > path_y else -1 if dest_y < path_y else 0
                    expanded_path.append((path_x, path_y))
            return expanded_path

        final_set.add(current)
        x, y = current
        # Identify jump points in each of four directions and expand them
        neighbors = [horizontal_identify(x, y, 1), horizontal_identify(x, y, -1),
                     vertical_identify(x, y, 1), vertical_identify(x, y, -1)]

        for neighbor in neighbors:
            if neighbor is not None and neighbor not in final_set:
                new_cost = current_cost + abs(neighbor[0] - x) + abs(neighbor[1] - y)
                if new_cost < best_cost.get(neighbor, float('inf')):
                    best_cost[neighbor] = new_cost
                    predecessors[neighbor] = current
                    heapq.heappush(frontier, (new_cost + heur(neighbor), new_cost, neighbor))
    return []
