        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_free(nr, nc):
                yield nr, nc

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    if start == goal and is_free(*start):
        return [start]
    if not is_free(*start) or not is_free(*goal):
