                reverse_cost[neighbor] = new_dist
                heapq.heappush(reverse_queue, (new_dist + estimate(neighbor, start), new_dist, neighbor))
                reverse_links[neighbor] = pos2

    # No path found
    return []

def _connect_paths(forward, backward, meet, start, goal):
    # Reconstruct path from start to meeting point
    path_start = [meet]
    while path_start[-1] != start:
        path_start.append(forward[path_start[-1]])
    path_start.reverse()

    # Reconstruct path from meeting point to goal
    path_end = [meet]
    while path_end[-1] != goal:
        path_end.append(backward[path_end[-1]])

    # Combine both paths
    return path_start + path_end[1:]
