import heapq

def solve(grid, start, goal):
    height, width = len(grid), len(grid[0])

    # If start and goal are the same and it's a free cell, return it as the path
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]

    # If either start or goal is a wall, no solution is possible
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    # Define Manhattan distance for heuristics
    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    # Forward search state
    cost_forward = {start: 0}
    forward_path = {}
    forward_frontier = [(0 + manhattan(start, goal), start)]

    # Backward search state
    cost_backward = {goal: 0}
    backward_path = {}
    backward_frontier = [(0 + manhattan(goal, start), goal)]

    # To track best meeting point and combined cost
    best_meet = None
    min_total_cost = float('inf')

    # Perform dual-directional search
    while forward_frontier and backward_frontier:
        # Forward step: Expand from start
        _, current = heapq.heappop(forward_frontier)
        if current in cost_backward:
            # Possible meeting node found
            total_cost = cost_forward[current] + cost_backward[current]
            if total_cost < min_total_cost:
                min_total_cost = total_cost
                best_meet = current

        # Explore neighbors and update forward paths
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = current[0] + dr, current[1] + dc
            if 0 <= nr < height and 0 <= nc < width and grid[nr][nc] == '.':
                new_cost = cost_forward[current] + 1
                if (nr, nc) not in cost_forward or new_cost < cost_forward[(nr, nc)]:
                    cost_forward[(nr, nc)] = new_cost
                    forward_path[(nr, nc)] = current
                    heapq.heappush(forward_frontier, (new_cost + manhattan((nr, nc), goal), (nr, nc)))

        # Backward step: Expand from goal
        _, current = heapq.heappop(backward_frontier)
        if current in cost_forward:
            # Possible meeting node found
            total_cost = cost_forward[current] + cost_backward[current]
            if total_cost < min_total_cost:
                min_total_cost = total_cost
                best_meet = current

        # Explore neighbors and update backward paths
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = current[0] + dr, current[1] + dc
            if 0 <= nr < height and 0 <= nc < width and grid[nr][nc] == '.':
                new_cost = cost_backward[current] + 1
                if (nr, nc) not in cost_backward or new_cost < cost_backward[(nr, nc)]:
                    cost_backward[(nr, nc)] = new_cost
                    backward_path[(nr, nc)] = current
                    heapq.heappush(backward_frontier, (new_cost + manhattan((nr, nc), start), (nr, nc)))

        # Early stopping when best meeting point's cost is less or equal to the best remaining in frontiers
        if best_meet is not None and all(cost_forward[n[0]] + cost_backward[n[0]] >= min_total_cost for n in forward_frontier + backward_frontier):
            break

    # If no meeting point found, return empty path
    if best_meet is None:
        return []

    # Reconstruct full path from start to goal through the meeting point
    def reconstruct_path(meet_node):
        # Build path from start to meeting node
        path_start = [meet_node]
        while path_start[-1] != start:
            path_start.append(forward_path[path_start[-1]])
        path_start.reverse()

        # Build path from meeting node to goal
        path_goal = [meet_node]
        while path_goal[-1] != goal:
            path_goal.append(backward_path[path_goal[-1]])

        # Combine the two paths and remove the duplicate meeting node
        return path_start + path_goal[1:]

    return reconstruct_path(best_meet)
