import heapq


def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def move_right(r, c):
        while True:
            c += 1
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            if (is_valid(r - 1, c) and not is_valid(r - 1, c - 1)) or (is_valid(r + 1, c) and not is_valid(r + 1, c - 1)):
                return (r, c)

    def move_left(r, c):
        while True:
            c -= 1
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            if (is_valid(r - 1, c) and not is_valid(r - 1, c + 1)) or (is_valid(r + 1, c) and not is_valid(r + 1, c + 1)):
                return (r, c)

    def move_down(r, c):
        while True:
            r += 1
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            right_result = move_right(r, c)
            left_result = move_left(r, c)
            if right_result is not None or left_result is not None:
                return (r, c)

    def move_up(r, c):
        while True:
            r -= 1
            if not is_valid(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            right_result = move_right(r, c)
            left_result = move_left(r, c)
            if right_result is not None or left_result is not None:
                return (r, c)

    def heuristic(r, c):
        return abs(r - goal[0]) + abs(c - goal[1])

    open_queue = [(heuristic(*start), 0, start)]
    min_cost = {start: 0}
    predecessors = {start: None}
    visited = set()

    while open_queue:
        est_total, cost, pos = heapq.heappop(open_queue)
        if pos in visited:
            continue
        if pos == goal:
            path = []
            while pos is not None:
                path.append(pos)
                pos = predecessors.get(pos, None)
            path.reverse()
            final_path = [path[0]]
            x1, y1 = path[0]
            for (x2, y2) in path[1:]:
                while (x1, y1) != (x2, y2):
                    if x2 > x1:
                        x1 += 1
                    elif x2 < x1:
                        x1 -= 1
                    if y2 > y1:
                        y1 += 1
                    elif y2 < y1:
                        y1 -= 1
                    final_path.append((x1, y1))
            return final_path
        visited.add(pos)
        r, c = pos
        directions = [move_right(r, c), move_left(r, c), move_down(r, c), move_up(r, c)]
        for next_pos in directions:
            if next_pos is None or next_pos in visited:
                continue
            nr, nc = next_pos
            new_cost = cost + abs(nr - r) + abs(nc - c)
            if new_cost < min_cost.get(next_pos, float('inf')):
                min_cost[next_pos] = new_cost
                predecessors[next_pos] = pos
                heapq.heappush(open_queue, (new_cost + heuristic(nr, nc), new_cost, next_pos))

    return []
