import heapq

def solve(grid, source, target):
    rows, cols = len(grid), len(grid[0])

    if source == target:
        if grid[source[0]][source[1]] == '.':
            return [source]
        else:
            return []

    if grid[source[0]][source[1]] == '#' or grid[target[0]][target[1]] == '#':
        return []

    def distance(pos1, pos2):
        return abs(pos1[0] - pos2[0]) + abs(pos1[1] - pos2[1])

    # Heuristic-guided search from a point
    def explore(start, end, cost_map, queue, origin_map):
        def get_moves(coord):
            r, c = coord
            moves = [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]
            return [m for m in moves if 0 <= m[0] < rows and 0 <= m[1] < cols and grid[m[0]][m[1]] == '.']

        heuristic = {pos: cost_map.get(pos, float('inf')) + distance(pos, end) for pos in cost_map}
        heapq.heapify(heuristic)

        while heuristic:
            _, pos = heapq.heappop(heuristic)
            if cost_map[pos] < cost_map.get(pos, float('inf')):
                for move in get_moves(pos):
                    updated = cost_map[pos] + 1
                    if updated < cost_map.get(move, float('inf')):
                        cost_map[move] = updated
                        origin_map[move] = pos
                        heapq.heappush(heuristic, (cost_map[move] + distance(move, end), move))
        return

    # Forward and backward cost maps and origins
    cost_from_start = {source: 0}
    cost_from_target = {target: 0}
    path_from_start = {}
    path_from_target = {}
    frontier_start = [(distance(source, target), source)]
    frontier_target = [(distance(target, source), target)]

    meeting_point = None
    lowest_total = float('inf')

    while frontier_start and frontier_target:
        # Explore from start
        _, loc = heapq.heappop(frontier_start)
        if loc in cost_from_target and cost_from_start[loc] + cost_from_target[loc] < lowest_total:
