        return []
    if start == goal:
        return [start]

    def in_bounds(r, c):
        return 0 <= r < rows and 0 <= c < cols

    def is_free(r, c):
        return in_bounds(r, c) and grid[r][c] == '.'

    def jump_horizontal(r, c, direction):
        if not is_free(r, c + direction):
            return None
        if (r, c + direction) == goal:
            return (r, c + direction)
        r_above = is_free(r - 1, c + direction)
        r_below = is_free(r + 1, c + direction)
        c_left = is_free(r, c)
        if (not r_above and is_free(r - 1, c)) or (not r_below and is_free(r + 1, c)):
            return (r, c + direction)
        return jump_horizontal(r, c + direction, direction)

    def jump_vertical(r, c, direction):
        if not is_free(r + direction, c):
            return None
        if (r + direction, c) == goal:
            return (r + direction, c)
        if jump_horizontal(r + direction, c, 1) or jump_horizontal(r + direction, c, -1):
            return (r + direction, c)
        return jump_vertical(r + direction, c, direction)

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def heuristic(p):
        return dist(p, goal)

    frontier = [(heuristic(start), 0, start)]
    came_from = {start: None}
    best_scores = {start: 0}
