import heapq


def solve(grid, start, goal):
    """Finds a path in a grid from start to goal using a best-first search with jump point pruning.
    Only 4-connected movements are allowed (up, down, left, right)."""
    rows = len(grid)
    cols = len(grid[0])

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    def is_open(r, c):
        """Determine whether position (r, c) is within the grid and accessible."""
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def distance(p1, p2):
        """Manhattan distance between two points."""
        r1, c1 = p1
        r2, c2 = p2
        return abs(r1 - r2) + abs(c1 - c2)

    def jump_horizontal(r, c, step_c, step_r, dir_r):
        """Jump horizontally in one direction, stopping at a forced stop or the goal."""
        while True:
            c += step_c
            r += step_r
            if not is_open(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            # Forced neighbor: a wall behind (r, c) in either diagonal that opens at (r, c)
            if (step_r > 0) and (
                (not is_open(r - 1, c) and is_open(r - 1, c - step_c)) or 
                (not is_open(r + 1, c) and is_open(r + 1, c - step_c)) or 
                (r, c) == goal
            ):
                return (r, c)
            if (step_r < 0) and (
                (not is_open(r + 1, c) and is_open(r + 1, c - step_c)) or 
                (not is_open(r - 1, c) and is_open(r - 1, c - step_c))
            ):
                return (r, c)

    def jump_vertical(r, c, dir_r):
        """Jump vertically in one direction, stopping at a forced stop or the goal."""
        r += dir_r
        c += 0
        while True:
            if not is_open(r, c):
                return None
            if (r, c) == goal:
                return (r, c)
            # Jump horizontally from the new position to find forced stops
            for dc in [1, -1]:
                if jump_horizontal(r, c, dc, 0, 0) is not None:
                    return (r, c)
            r += dir_r

    open_list = [(distance(start, goal), 0, start)]
    cost_best = {start: 0}
    backtracking = {start: None}
    closed_set = set()

    while open_list:
        f_score, g_score, current = heapq.heappop(open_list)
        if current in closed_set:
            continue
        if current == goal:
            # Reconstruct path
            path = []
            while current is not None:
                path.append(current)
                current = backtracking[current]
            path.reverse()
            # Expand the path to include every step
            full_path = [path[0]]
            for i in range(len(path) - 1):
                r1, c1 = path[i]
                r2, c2 = path[i + 1]
                while (r1, c1) != (r2, c2):
                    r1 += 1 if r2 > r1 else -1 if r2 < r1 else 0
                    c1 += 1 if c2 > c1 else -1 if c2 < c1 else 0
                    full_path.append((r1, c1))
            return full_path
        closed_set.add(current)

        r, c = current
        directions = [
            jump_horizontal(r, c, 1, 0, 1),
            jump_horizontal(r, c, -1, 0, -1),
            jump_vertical(r, c, 1),
            jump_vertical(r, c, -1)
        ]
        for neighbor in directions:
            if neighbor is None or neighbor in closed_set:
                continue
            n_r, n_c = neighbor
            new_g = g_score + distance((r, c), (n_r, n_c))
            if new_g < cost_best.get(neighbor, float('inf')):
                cost_best[neighbor] = new_g
                backtracking[neighbor] = current
                total_h = new_g + distance(neighbor, goal)
                heapq.heappush(open_list, (total_h, new_g, neighbor))

    return []
