    best_meet = None
    lowest_combined_cost = float('inf')

    while forward_heap and backward_heap:
        if forward_heap:
            _, curr = heapq.heappop(forward_heap)
            if curr in backward_cost:
                current_total = forward_cost[curr] + backward_cost[curr]
                if current_total < lowest_combined_cost:
